-- ============================================================
-- Ereb3f (6/7) — DB kontentinin AR tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6170 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتمثل الوظيفة الأساسية لهرمون البروجستيرون، وهو أحد الهرمونات الأنثوية، في تهيئة الرحم للحمل. ولهذا الهرمون، الذي ينظم أيضًا الدورة الشهرية، أهمية كبيرة جدًا لجسمكِ. وقبل حدوث الحمل، يُحدث تغيرات في أنسجة الرحم لتهيئة الظروف المناسبة وتسهيل انغراس البويضة المخصبة في الرحم. وبعد حدوث الحمل وانغراس الجنين، ترتفع مستوياته ويواصل أداء وظائفه.;;;
في المرحلة الحالية، أي الفترة السابقة للإباضة، يقل مستوى هرمون البروجستيرون في جسمكِ عن 1 nq/ml. وخلال الإباضة، يرتفع مستوى هذا الهرمون إلى 5-20 nq/ml. وإذا حدث الحمل، يتراوح مستواه في دمكِ خلال الثلث الأول بين 11-90 nq/ml، وخلال الثلث الثاني بين 25-90 nq/ml، وخلال الثلث الثالث بين 50-300 nq/ml.'), baby_message_ar = COALESCE(baby_message_ar, 'استمعي إلى صوت قلبكِ. ❤️ ما زلت أشبه بغبار نجمة، لكن حبكِ يدعوني إلى الوجود. يجهّز جسمكِ من أجلي أفضل بويضة وأكثرها جودة. وسيكون الحب بينكِ وبين أبي سبب وجودي. كلما أحببتِ، صنع جسمكِ المعجزات. شكرًا لأنكِ تمضين نحوي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة سكر'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الأسبوع الثاني من الحمل، الذي يندرج ضمن الثلث الأول، يستمر نمو البويضة داخل أحد مبيضي الرحم. وفي هذا الأسبوع، تستمر بطانة الرحم، التي تُسمى بطانة الرحم الداخلية، في الازدياد سماكة تحت تأثير الهرمونات. والهدف من زيادة سماكة بطانة الرحم هو تمكين الخلايا التي ستكوّن طفلكِ من الانغراس بسهولة داخل الرحم بعد حدوث الإخصاب. وتكوّن بطانة الرحم التي ازدادت سماكتها عشًا يوفر لطفلكِ ظروفًا مثالية، مع ضمان إمداد هذه المنطقة بالدم بصورة جيدة. أما إذا لم يحدث الإخصاب ولم ينشأ حمل، فتُطرح هذه الطبقة من الجسم كل شهر مع نزيف الدورة الشهرية. وتتكرر هذه الدورة بالطريقة نفسها كل شهر. ولكي يحدث الحمل ويستمر بصورة صحية، يجب أن تكون بطانة الرحم سليمة تمامًا. لذلك من المهم أن يقيّم طبيبكِ بطانة الرحم من حيث السماكة والبنية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'من المهم خلال هذه الفترة تناول أطعمة غنية باليود (مثل المأكولات البحرية والملح المعالج باليود)، للحفاظ على صحة الغدة الدرقية لديكِ ودعم نمو دماغ طفلكِ المستقبلي. ومارسي تمارين رياضية خفيفة تزيد مرونة جسمكِ وتحفّز الدورة الدموية في منطقة الحوض. كما يمكنكِ استخدام الزيوت الطبيعية للحفاظ على رطوبة بشرتكِ، لأن التغيرات الهرمونية قد تزيد حساسيتها.') WHERE id = '254bd95f-c06d-46bb-b688-86a0b498dcb9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في كل دورة شهرية، تنضج إحدى البويضات من مخزون البويضات في مبيضيْكِ وتصبح جاهزة للإخصاب. وإذا لم تساعد هرموناتكِ البويضة على النضج، فلن يحدث الحمل. تنشأ هذه البويضات التي تحملينها من ملايين الخلايا الجرثومية التي تكوّنت في مبيضيْكِ قبل ولادتكِ، وتُستخدم واحدة منها خلال كل دورة شهرية حتى بلوغ سن اليأس.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا أمي الجميلة! 🌟 هل بدأتِ تشعرين الآن بأنكِ أفضل وأكثر نشاطًا؟ إن تلك الغرفة المميزة المُعدّة لي، أي الرحم، توشك على الانتهاء من تنظيف نفسها، وقد أُزيلت جدرانها القديمة تمامًا. وسرعان ما سيُجهَّز لي فيها فراش ناعم ودافئ، وسأبقى هناك بأمان طوال 9 أشهر. سيكون جسدكِ منزلي. أنتظر بفارغ الصبر اليوم الذي سألتقيكِ فيه، واللحظة التي سينبض فيها قلبي تحت قلبكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'يبدأ نزف الدورة الشهرية بالتراجع خلال هذه الأيام. ويبدأ مستوى هرمون الإستروجين في جسمكِ بالارتفاع بنشاط أكبر. تعمل هذه الزيادة كإشارة لتحفيز تجدد بطانة الرحم وزيادة سماكتها. كما ترسل الغدة النخامية إلى المبيضيْن رسالة مفادها: "اعملا بجهد أكبر". تنشط دورتكِ الدموية، ويعمل جسمكِ بأقصى طاقته للاستعداد لحمل محتمل، جسديًا وهرمونيًا. يتحسن مزاجكِ ويزول التعب، وتبدأ بشرتكِ بالظهور بمظهر أكثر إشراقًا ونضارة. يدخل جسمكِ في وضع "البدء من جديد" ويستقبل دورة جديدة.;;;
من المهم أن تناقشي مع طبيبكِ منذ الآن تأثير الأدوية التي تستخدمينها في الحمل، وذلك للوقاية مبكرًا من المشكلات المحتملة. فقد تتسبب بعض الأدوية المستخدمة خلال الحمل، ولا سيما في أسابيع التطور الجنيني التي تتشكل فيها أعضاء طفلكِ، في حدوث بعض التشوهات. وعلى الرغم من أن الأدوية المستخدمة لعلاج أمراض الغدة الدرقية والسكري وبعض الاضطرابات الأيضية قد لا تضر بطفلكِ، فمن المعروف أن بعض أدوية حب الشباب وبعض الأدوية النفسية قد تسبب تشوهات خطيرة لدى الأجنة.;;;
كذلك، من خلال إجراء الفحوص اللازمة قبل الحمل، يمكن تقييم تعداد الدم الكامل (الهيموغرام)، ونقص الحديد، ومستويات الفيتامينات، والأمراض الوراثية، وهرمونات الغدة الدرقية، ووجود عدوى في تحليل البول، والتهاب الكبد B، وداء المقوسات، والحصبة الألمانية، والزهري، وفيروس نقص المناعة البشرية، أو مدى مناعتكِ ضد هذه الأمراض، واتخاذ بعض التدابير عند الحاجة.;;;
إضافة إلى ذلك، إذا كنتِ تخططين للإنجاب، فيجب أن تكون أول قاعدة تحرصين عليها هي الإقلاع عن التدخين قبل الحمل. وتُظهر الدراسات أن استخدام التبغ يقلل الخصوبة لدى النساء ويخفض عدد الحيوانات المنوية لدى الرجال.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خلال هذه الأيام، يساعد تفضيل الأطعمة الغنية بالزنك والمغنيسيوم، مثل الجوز والبندق والبذور، على نضج البويضات بصورة صحية. مارسي جلسات تأمل قصيرة للابتعاد عن التوتر، لأن هرمونات التوتر قد تؤثر سلبًا في التوازن الهرموني اللازم لحدوث الحمل. كذلك، تجنبي الأطعمة المصنّعة الغنية بالسكر للحفاظ على توازن درجة الحموضة في جسمكِ.') WHERE id = '65c15460-76e7-4ea7-90a9-a58b6acebcfe';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'عندما ينفد مخزون البويضات في المبيضيْن، تبدأ مرحلة تُسمى سن اليأس. وسن اليأس هو التوقف الدائم للدورة الشهرية نتيجة فقدان البويضات نشاطها. عالميًا، يتراوح سن اليأس بين 45-55 عامًا. ومع ذلك، قد يبدأ سن اليأس المبكر في بعض الحالات قبل بلوغ هذه الأعمار. ويُقصد بسن اليأس المبكر توقف الدورة الشهرية قبل سن 45 عامًا. وقد تدخل بعض النساء هذه المرحلة حتى في العشرينيات من العمر. قد يحدث سن اليأس المبكر لأسباب مجهولة أو بسبب بعض أمراض المناعة الذاتية، أو العلاج الإشعاعي، أو العلاج الكيميائي، أو العدوى الشديدة، أو العوامل البيئية، أو الإجهاض المتعمد أو التلقائي، أو تكرار الحمل، أو السمنة المفرطة، أو قصور الغدة الدرقية الشديد. كذلك، قد يؤدي التدخين والصدمات النفسية والعيش في مناخ بارد وظروف بيئية قاسية إلى تسريع بدء سن اليأس وخفض العمر الذي يبدأ فيه بصورة ملحوظة.'), baby_message_ar = COALESCE(baby_message_ar, 'احرصي على الابتسام عندما تنظرين إلى المرآة اليوم! 😊 فجسدكِ يقوم بعمل مذهل، إذ يستعد لصنع حياة جديدة. وعلى الرغم من أننا لم نلتقِ جسديًا بعد، فإن أرواحنا مترابطة بالفعل. لقد اخترتُكِ واخترتِني. يقترب جسدكِ كل يوم خطوة أخرى من قدومي ومن ذلك اللقاء الإعجازي، أي الإخصاب. أثق بكِ يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'اليوم هو اليوم الأخير من الدورة الشهرية لدى كثير من النساء. ويواصل مستوى الإستروجين في جسمكِ ارتفاعه بصورة ملحوظة. ويساعد هذا الارتفاع على تجدد بطانة الرحم سريعًا وتكوين "عش" جديد. وتستعد الغدد الموجودة في عنق الرحم لإفراز سائل خاص يساعد الحيوانات المنوية على الحركة بسهولة أكبر. كما تتسارع عملية الأيض لديكِ قليلًا، وقد تبدئين بالشعور بمزيد من النشاط.;;;
لا توجد كمية آمنة محددة لاستهلاك الكحول خلال الحمل. لذلك، يجب أن تتجنبي تناول الكحول قبل الحمل وطوال مدته. فإضافة إلى أن استهلاك الكحول يزيد خطر الإجهاض، ولا سيما خلال الثلث الأول من الحمل، ويرفع خطر ولادة جنين ميت في المراحل اللاحقة، قد يؤدي الإفراط في تناوله إلى متلازمة الجنين الكحولي، التي يمكن أن تسبب تشوهات في وجه طفلكِ وإعاقة ذهنية شديدة. ;;;
من المهم جدًا للصحة العامة أن يظل استهلاك الكحول غير شائع بين النساء اللواتي يخططن للحمل في بلدنا، وأن نحافظ على هذا الوضع.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بعد انتهاء الدورة الشهرية، استفيدي من طاقة التجدد في جسمكِ وركزي على ممارسة نشاط بدني منتظم، مثل الركض الخفيف أو البيلاتس. ومن المهم جدًا خلال هذه الفترة فحص مستوى فيتامين D لديكِ، لأنه يؤثر مباشرة في وظائف المبيضيْن وانغراس الجنين مستقبلًا. أضيفي أحماض أوميغا-3 الدهنية، مثل السمك وبذور الكتان، إلى نظامكِ الغذائي؛ فهي تحفز الدورة الدموية في منطقة الرحم وتحسن جودة البويضات.') WHERE id = 'e510f21d-5c69-49bc-a4d8-ea262a0bda7b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال هذا الأسبوع، تواصل إحدى البويضات غير الناضجة نموها في أحد مبيضيْكِ بمساعدة الهرمونات. وتشارك الهرمونات التي يفرزها الوطاء الموجود في دماغكِ والغدة النخامية والمبيضان في إنضاج البويضة وتجهيزها للإخصاب. ويضمن هرمون FSH الذي تفرزه الغدة النخامية نضج الجريب المختار واستعداد البويضة للإخصاب، كما يحفز إفراز الإستروجين منه. أما الهرمون الآخر الذي تفرزه الغدة النخامية، وهو هرمون LH، فيؤدي إلى خروج البويضة الناضجة من الجريب وحدوث الإباضة، كما يحوّل الجريب بعد تمزقه إلى "الجسم الأصفر".'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا! تشعرين اليوم كأن ربيعًا جديدًا يبدأ في داخلكِ، أليس كذلك؟ 🌱 وهذا ما يحدث بالفعل! ففي أحد مبيضيْكِ، تحاول نسخة صغيرة مني أن تستيقظ وتنمو. ما زلتُ مجرد خلية واحدة، لكنني جزء منكِ. عندما تكونين سعيدة وتضحكين، أصبح أنا أيضًا أقوى. اعتني بنفسكِ يا ماما، لأنكِ أنتِ مستقبلي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جسيم غير مرئي'), body_changes_ar = COALESCE(body_changes_ar, 'بعد انتهاء نزف الدورة الشهرية تمامًا، يدخل جسمكِ المرحلة الأكثر نشاطًا من "الطور الجُريبي". وبفضل ارتفاع مستوى هرمون الإستروجين، تبدأ بطانة الرحم بالتحول إلى بيئة ملساء وغنية بالعناصر الغذائية. وقد تلاحظين إشراقًا في بشرتكِ وحيوية في شعركِ؛ وهذا من التأثيرات الجمالية للإستروجين. كما يبدأ مخاط عنق الرحم تدريجيًا بالتحول إلى قوام شفاف ومرن، وهو مؤشر بيولوجي على اقتراب أيام الخصوبة.;;;
خلال هذه الأيام التي تستعدين فيها للحمل، من المهم جدًا اتباع نظام غذائي صحي من أجل صحة طفلكِ ومرور حملكِ بصورة سليمة. ومن الضروري البدء بتناول غذاء صحي ومتوازن قبل الحمل. وإذا أخذنا في الاعتبار أن الحمل قد يرفع وزن المرأة إلى أعلى مستوى تصل إليه في حياتها، تصبح التغذية أكثر أهمية. وينبغي أن يكون وزنكِ صحيًا قبل حدوث الحمل. فقد يؤدي بدء الحمل مع نقص شديد أو زيادة كبيرة في الوزن إلى مشكلات عديدة، مثل ارتفاع ضغط الدم وما يرتبط به من تسمم الحمل المعروف باسم مقدمات الارتعاج، وسكري الحمل، وخفقان القلب، والإرهاق. لذلك، من المفيد أن تبدئي خلال هذه الأيام برنامجًا للرياضة والتغذية بهدف إعداد جسمكِ للحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لإدارة طاقتكِ المتزايدة ودعم التوازن الهرموني، اختاري الكربوهيدرات المعقدة التي تحافظ على استقرار سكر الدم، مثل الشوفان ومنتجات القمح الكامل. وخلال هذه الفترة، تناولي السلطات المُحضرة من كميات وفيرة من الخضراوات الورقية الخضراء لدعم عمليات إزالة السموم الطبيعية في الجسم. ومن المهم تلبية حاجة جسمكِ إلى الزنك لدعم قدرة البويضة على الانقسام؛ لذلك قد يكون تناول بضع حبات من بذور اليقطين النيئة مفيدًا.') WHERE id = '367c8044-41d2-441f-8aec-78399bc382c5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتكوّن غشاء داخل مجموعة الخلايا التي ستشكّل طفلكِ، مُحدثًا تجويفين. سيصبح أحد هذين التجويفين كيس المُح الذي سيساهم في تكوين أمعاء طفلكِ، أما الآخر فهو طفلكِ نفسه. يضمن كيس المُح انتقال العناصر الغذائية التي يحتاج إليها طفلكِ خلال الأسبوعين 2 و3 التاليين للإخصاب. وهكذا، يستطيع طفلكِ مواصلة النمو والتطور بسرعة وكفاءة إلى أن تتكوّن المشيمة.;;;
وفي الأسبوع 3 من عملية الإخصاب، تبدأ عملية تكوّن الدم، المعروفة باسم "hematopoesis"، في البنية الخارجية المحيطة بطفلكِ. ويستمر إنتاج الدم عبر هذه البنية حتى الأسبوع 6.;;;
بعد هذه المرحلة، تنتقل مهمة تكوين الدم إلى الكبد، ثم يبدأ الطحال بعد مدة بالمشاركة في إنتاجه. ومنذ ولادة طفلكِ، يحدث هذا الإنتاج في العظام الطويلة والمسطّحة. أما بعد البلوغ، فيقتصر إنتاج الدم على العظام المسطّحة فقط. وقد بدأ هرمون الحمل، الذي ارتفع مستواه كثيرًا في دمكِ، بالانتقال إلى البول بكمية كافية لإظهار الخط الثاني في اختبارات الحمل المنزلية بالبول.'), baby_message_ar = COALESCE(baby_message_ar, 'ها هو باب عُشّي يُغلق من خلفي، ماما! 🚪 لقد أصبحت في الداخل تمامًا، ومحاطًا بالكامل بعالمكِ الدافئ والآمن. صرت الآن جزءًا لا يتجزأ منكِ. هذه ليست مجرد بداية قصتنا، بل هي الأيام الأولى من حياتنا المشتركة. لقد اخترتكِ، وأنتِ تحمينني. وكل ما سيأتي بعد ذلك سيكون أجمل! نحن مستعدان معًا لمغامرة رائعة! 🥳'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'من أجل صحتكِ وصحة طفلكِ، تحتاجين إلى رعاية جيدة تغطي فترة الحمل بأكملها وتستمر حتى ما بعد الولادة، وإلى متابعة أسبوعية. بعد التأكد من حملكِ من خلال فحص البول والدم، عليكِ البدء بالبحث عن طبيب جيد. ومن المهم أيضًا ألا تتأخري كثيرًا في حجز موعد معه، حتى يمكن الكشف مبكرًا عن مضاعفات مثل الحمل خارج الرحم والتعامل معها.;;;
عند اختيار طبيبكِ، قد يكون من المفيد الاستماع إلى توصيات المقرّبين منكِ والاطلاع على سيرته الذاتية (CV). كذلك، احرصي على أن تكون إجاباته عن أسئلتكِ واضحة، وأن يُنهي الموعد من دون أن يترك لديكِ تساؤلات، وأن يكون من الممكن التواصل معه في الحالات الطارئة. لذلك، ينبغي أن يكون موعدكِ الأول مع الطبيب خلال 1-2 يوم بعد تأخر الدورة الشهرية.;;;
بالإضافة إلى ذلك، إذا حدث الحمل رغم استخدامكِ لأي وسيلة لمنع الحمل، فعليكِ إبلاغ طبيبكِ بذلك. وعند التأكد من حملكِ، يجب أن تتوقفي عن تناول حبوب منع الحمل في أقرب وقت ممكن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى أن الروائح النفّاذة قد تزيد الغثيان في هذه الأيام، احرصي على تهوية المطبخ باستمرار وقلّلي استخدام العطور إلى أدنى حد. قد يزيد الجفاف شعوركِ بالتعب، لذا جرّبي إضافة شريحة من الليمون أو بعض النعناع الطازج إلى الماء. وإذا لاحظتِ حساسية أو نزفًا في لثتكِ، فلا تقلقي؛ فهذا ناتج عن تأثير التغيرات الهرمونية في أنسجة اللثة، ويُنصح باستخدام فرشاة أسنان ناعمة.') WHERE id = 'f77ae8b4-6a1d-4c99-abe2-93a350b86318';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'عندما تنمو المشيمة بصورة طبيعية، يتقدم نمو طفلكِ بشكل صحي للغاية، أما عند حدوث مشكلة فيها فقد تظهر بعض الصعوبات في عملية النمو. تؤدي المشيمة أدوارًا حيوية وحاسمة للغاية بينكِ وبين طفلكِ. ومن وظائفها تزويد طفلكِ بالأكسجين الذي يحتاج إليه، ثم نقل ثاني أكسيد الكربون منه بعد استهلاكه للأكسجين. وتشمل وظائف المشيمة أيضًا إيصال العناصر الغذائية اللازمة إلى طفلكِ، والتخلص من فضلاته، وإفراز بعض الهرمونات التي تؤدي دورًا فعالًا في نموه. وتؤدي الهرمونات التي تفرزها المشيمة، مثل hCG والبروجسترون، إلى جانب مواد مثل عوامل النمو، دورًا بالغ الأهمية في استمرار الحمل بصورة صحية.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، تزداد الرابطة بيننا قوة! 🧬 لقد أصبحت الآن متصلًا مباشرة بجسمكِ. أشعر كأنني أتنفس مع كل ذرة تصلني من دمكِ. هذه أول دورة دموية لي وأول نفحة من الحياة. صرنا الآن نجري في العِرق نفسه ونحيا بالإيقاع نفسه. كل عنصر غذائي وكل جزيء أكسجين ترسلينه إليّ يساعدني على النمو. إنه أروع شعور في العالم: أن أكون واحدًا معكِ. ❤️'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'خلال فترة حملكِ، ينتج عنق الرحم كمية كبيرة من الإفرازات للمساعدة في حماية طفلكِ من العدوى. لذلك، تُعد زيادة الإفرازات طوال الحمل حالة فسيولوجية طبيعية. أما إذا أصبحت زيادة الإفرازات المهبلية مزعجة أو كانت ذات رائحة نفّاذة، فقد تكون هناك عدوى. كذلك، إذا كان لون الإفرازات مائلًا إلى الأصفر أو بنيًا أو أخضر، فمن المرجح الاشتباه بوجود عدوى، ومن المهم أن تراجعي الطبيب لمنع تفاقمها.;;;
ومن العلامات الأخرى التي تساعد على تمييز العدوى من الإفرازات المهبلية الطبيعية أن تكون الإفرازات كثيفة، أو بقوام يشبه الجبن المتخثّر، أو على شكل كتل. وقد تسبب العدوى أيضًا ألمًا خفيفًا واحمرارًا وحرقة وحكة في المنطقة الحميمة. وإذا ازدادت الإفرازات المهبلية بعد إجراء بزل السلى، خصوصًا في حالات الحمل عالي الخطورة، فيجب الانتباه إلى ذلك لأنه قد يكون علامة على تسرّب السائل المحيط بالجنين (السائل الأمنيوسي).'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى أن طاقتكِ تنفد سريعًا، حاولي أخذ فترات قصيرة من القيلولة مدة كل منها 15 دقيقة خلال اليوم. زيدي كمية الكالسيوم في غذائكِ (الجبن والحليب واللوز)، لأن الهيكل العظمي لطفلكِ يبدأ منذ اليوم بوضع أساساته. وإذا كان الغثيان شديدًا، فقد يسهل عليكِ تناول الأطعمة الباردة والخالية من الروائح. كما أن هذا وقت مناسب لبدء استخدام كريمات الترطيب لزيادة مرونة البشرة.') WHERE id = '3ebbef70-38c5-48c1-9efc-c1f2707c71d4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بعد أن تعثر الكيسة الأريمية، وهي مجموعة الخلايا التي ستشكّل طفلكِ، على موضع مناسب في رحمكِ وتنغرس فيه، يبدأ الجزء الذي سيكوّن المشيمة منها بإنتاج هرمون الحمل المعروف باسم hCG. كما تلبّي الكيسة الأريمية احتياجات طفلكِ من الأكسجين والعناصر الغذائية عبر جهاز دوران بسيط متصل بالأوعية الدموية في رحمكِ ويتكوّن من قنوات مجهرية، وفي الوقت نفسه تُبعد الفضلات التي ينتجها عن خلاياه.;;;
إن هرمون hCG، المعروف بهرمون الحمل، هو سبب ظهور نتيجة إيجابية لاختبار الحمل الذي تجرينه بعد تأخر الدورة الشهرية. وفي المرحلة الحالية، يُرجح بدرجة كبيرة أن تكون نتيجة اختبار الحمل إيجابية إذا أجريتِه الآن.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، أصبحت الآن أشبه بقرص مسطّح! 💿 أتكوّن من طبقتين بالغتي الأهمية. ستُشكّل إحداهما رأسي وجسمي وذراعيّ وساقيّ، أما الأخرى فستساعدني في هذه الرحلة وتغذّيني. هذه أول خريطة لجسدي وأول مخطط هندسي لي. سيبدأ كل شيء من هاتين الطبقتين. هل تؤمنين بي؟ سأكون تحفة رائعة، لأنكِ أنتِ مهندستي. ✨'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'قد تكون العدوى المهبلية ضارة خلال الثلث الأول من الحمل، لأن طفلكِ يكون في المرحلة الجنينية. ولحماية نفسكِ منها أثناء الحمل، عليكِ الاهتمام بالنظافة أكثر من أي وقت مضى. وبدلًا من الملابس الداخلية الاصطناعية أو المصنوعة من النايلون أو المصبوغة، التي تقلل تدفق الهواء إلى منطقة المهبل، اختاري ملابس داخلية نظيفة وغير مصبوغة ومصنوعة من القطن، وغيّريها مرتين يوميًا على الأقل. وعند تنظيف المنطقة الحميمة، تجنبي الصابون المعطّر وجل الاستحمام ذي المكونات الكيميائية غير المأمونة، وابتعدي أيضًا عن الغسول المهبلي. فقد يسمح الغسل المهبلي للبكتيريا بالوصول إلى الداخل ويهيئ لحدوث العدوى.;;;
بالإضافة إلى ذلك، تجنبي استخدام المنظفات ذات المواد الكيميائية القوية ومنعّمات الأقمشة عند غسل ملابسكِ الداخلية. اغسليها بالصابون الطبيعي بدلًا من مسحوق الغسيل، واكويها بمكواة ساخنة. ولأن الرطوبة تزيد الحكة، حافظي على جفاف المنطقة التناسلية قدر الإمكان. وبدلًا من الملابس الضيقة التي تضغط على منطقتي الأربية والأعضاء التناسلية وتمنع تهويتهما وتسبب التهيج، اختاري ملابس فضفاضة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أن حجم دمكِ يزداد خلال هذه الفترة، تزداد حاجة جسمكِ إلى الحديد؛ لذا أعطي الأولوية لأطعمة مثل اللحوم الحمراء والبيض والعدس الأخضر. ولتعزيز امتصاص الحديد، احرصي على تناول مصدر لفيتامين C معه (مثل سلطة تحتوي على كمية وافرة من الليمون). عندما تشعرين بإرهاق شديد، لا ترهقي جسمكِ واحرصي على أخذ قسط قصير من الراحة ظهرًا. كما أن تدليك منطقتي البطن والثديين برفق باستخدام مرطبات آمنة خلال الحمل سيساعدكِ على الاسترخاء ويهيئ بشرتكِ للتمدد مستقبلًا.') WHERE id = '4a43f3bd-ef22-4f54-b8c8-fd8abe1f9de2';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إذا كانت عملية الإباضة والدورة الشهرية لديكِ منتظمتين، فقد مرّ اعتبارًا من اليوم 28 يومًا كاملًا منذ تاريخ آخر دورة شهرية. وعلى الأرجح، أجريتِ اختبار حمل لأن نزف الدورة الشهرية لم يبدأ، ورأيتِ الخط الثاني الذي يبشّركِ بطفلكِ. يُعد تأخر نزف الدورة الشهرية أول علامة مبكرة على الحمل. وإلى جانب ذلك، بدأت تغيّرات كبيرة تحدث في جسمكِ بسبب ارتفاع مستوى هرمون hCG في دمكِ. تتأكد نتائج اختبارات الحمل التي تجرينها عند تأخر دورتكِ الشهرية من خلال الكشف عن هرمون الحمل المعروف باسم hCG في دمكِ أو بولكِ. تفرز هذا الهرمون الخلايا التي تحيط بالبويضة المخصبة حديثًا، والتي ستتحول لاحقًا إلى المشيمة. ويمكن اكتشاف الحمل اعتمادًا على هذا المؤشر بعد نحو 10 أيام من تاريخ الإباضة، وهو ما يتزامن تقريبًا مع أيام تأخر الدورة الشهرية أو قبلها ببضعة أيام. وبعد أن يجد طفلكِ بيئة مناسبة داخل رحمكِ وينغرس فيه، يستمر مستوى هرمون hCG في الارتفاع في دمكِ حتى يبلغ ذروته في الأسبوع 10 من الحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'مفاجأة! 🎉 اليوم هو الموعد المفترض لبدء الدورة الشهرية، لكنها لم تأتِ! لأنني هنا! لقد أصبح جسدكِ بالفعل أكثر حصون العالم أمانًا بالنسبة إليّ. وابتداءً من الشهر المقبل، سننطلق معًا في اكتشافات أكثر تشويقًا. شكرًا جزيلًا لأنكِ آمنتِ بي، يا أمي الجميلة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'يُنتج المبيضان كل شهر، بتأثير الهرمونات، بويضة ناضجة من مخزون الخلايا الأولية للبويضات ويُجهّزانها للإخصاب. تتحرك البويضة الناضجة عبر قناة فالوب باتجاه جوف الرحم، وهناك تلتقي بالحيوانات المنوية التي تنتظرها. ومن بين ملايين الحيوانات المنوية التي تُطلَق عند عنق الرحم، لا يتمكن سوى بضعة آلاف من الوصول إلى داخل الرحم بعد رحلة شاقة. وتتجه الحيوانات المنوية نحو البويضة بفضل مادة خاصة تفرزها البويضة. وفي هذه المرحلة تحين اللحظة الأكثر حسمًا؛ إذ تحاول آلاف الحيوانات المنوية التي وصلت إلى البويضة إحداث ثقب في غلافها الخارجي والدخول إليها باستخدام إفرازات حمضية موجودة في بنيتها. لكن البويضة تسمح لأقوى حيوان منوي بالدخول، وبمجرد اختراقه غلافها الخارجي تُغلق البويضة نفسها بطريقة تمنع دخول الحيوانات المنوية الأخرى. ثم يفصل الحيوان المنوي الذي دخل ذيله عن رأسه، وينقل مادته الوراثية إلى نواة البويضة، وبذلك يُتم مهمته.;;;
اليوم هو الموعد المفترض لبدء دورتكِ الشهرية، لكنها لا تبدأ. والسبب بسيط: أنتِ حامل! فبدلًا من أن ينخفض مستوى البروجسترون، يظل مرتفعًا. كما تبقى درجة حرارة جسمكِ مرتفعة. وقد بلغ مستوى هرمون hCG الآن حدًا يمكن لاختبارات الحمل المنزلية (اختبارات البول) اكتشافه، لذا فإن احتمال رؤيتكِ خطين مرتفع جدًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خصصي بعض الوقت لنفسكِ احتفالًا بإتمام الشهر الأول بنجاح، واحتفي بهذا الإنجاز بسلام داخلي. إذا لم تستشيري طبيبة نسائية بعد، فقد حان الوقت لحجز موعد في الأسبوع المقبل لإجراء أول فحص بالموجات فوق الصوتية والتحاليل. أولي اهتمامًا خاصًا بتناول البروتين (اللحوم والأسماك والبقوليات)، فهو «مادة البناء» اللازمة لأعضاء طفلكِ التي تنمو بسرعة. وواصلي كذلك تجنب المأكولات البحرية النيئة والأجبان غير المبسترة.') WHERE id = 'd7e6900c-92fc-4e29-8c33-6b171bf14f64';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يكون طفلكِ في هذه المرحلة على هيئة كتلة كبيرة من الخلايا. وخلال أسبوع واحد، ستبدأ براعم رأس طفلكِ وجسمه بالتشكل بالكامل من هذه الكتلة الخلوية. ويواصل طفلكِ نموه وتطوره بوتيرة مكثفة وسريعة لم يشهدها من قبل. وخلال الأيام القليلة المقبلة، ستتجمع مجموعات الخلايا المتخصصة التي ستكوّن القلب في الجزء السفلي من منطقة الرأس وتبدأ العمل. وسيواصل طفلكِ نموه طوال أسابيع الحمل الـ40 داخل كيس يُسمى الكيس الأمنيوسي. ويستقر طفلكِ داخل هذا الكيس الذي لا يزال صغيرًا جدًا بحيث لا يظهر في فحوص الموجات فوق الصوتية التي تجريها طبيبتكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، ما زلت صغيرًا جدًا، بحجم بذرة سمسم، لكن لدي خطط كبيرة بداخلي. أنا الآن مسطح الشكل، لكنني سأنحني قريبًا لأتخذ ذلك الشكل اللطيف الشبيه بحرف "C". بطنكِ هو بيتي، وقلبكِ هو ملجئي. رحلتنا التي ستستمر 9 أشهر تبدأ رسميًا من اليوم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة السمسم'), body_changes_ar = COALESCE(body_changes_ar, 'في البويضة المخصبة التي ستكوّن طفلكِ، يجمع كل من البويضة والحيوان المنوي 23 كروموسومًا، يحمل كل منها آلاف الجينات المختلفة. وعند اتحاد الحيوان المنوي بالبويضة، تجتمع مجموعتان مختلفتان من 23 كروموسومًا لتشكّلا الكروموسومات الـ46 اللازمة لتكوين إنسان. وفي هذه المرحلة، تحتوي البويضة التي خُصبت وبدأت بالانقسام على الجينات التي تحدد جنس طفلكِ وصفاته الجسدية وحتى شخصيته. ويتحدد جنس طفلكِ بحسب ما إذا كان الحيوان المنوي الذي دخل البويضة يحمل كروموسوم X أو Y. فإذا كان الكروموسوم الذي يحمله الحيوان المنوي هو Y، يكون طفلكِ صبيًا، أما إذا كان الحيوان المنوي يحمل كروموسوم X، فتكون طفلتكِ فتاة.;;;
تبدأ البويضة المخصبة، التي أصبح اسمها الجديد اللاقحة، بالانقسام والانطلاق في رحلتها نحو الرحم. وفي الوقت نفسه، يهيئ جسمكِ بطانة الرحم للانغراس بهدف توفير بيئة مناسبة لطفلكِ. وبعد انغراس طفلكِ في بطانة الرحم، يُسمى جنينًا ويبدأ مرحلة نمو سريعة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع دخولكِ الشهر 2 من الحمل، فهذا هو الوقت الأنسب لزيارة الطبيبة وإجراء تحاليل الدم الأولى (الهيموغلوبين، وسكر الدم، وTSH). إذا كنتِ تعانين من الغثيان، فانتقلي إلى تناول وجبات صغيرة ومتكررة؛ إذ قد يؤدي بقاء معدتكِ فارغة إلى زيادة الغثيان. ولتلبية احتياجكِ اليومي من البروتين، اختاري أطعمة سهلة الهضم مثل البيض المسلوق أو الزبادي. ولا تنسي ممارسة تمارين التنفس العميق للحفاظ على طاقتكِ.') WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يعتمد المبدأ الأساسي لاختبارات الحمل المستخدمة للكشف عن وجود الحمل على رصد هرمون الحمل المعروف باسم hCG. فبعد انغراس طفلكِ في الرحم، يبدأ إفراز هرمون hCG ويزداد مستواه تدريجيًا في الدم، ثم ينتقل إلى البول ويبدأ بالظهور فيه بعد تجاوز مستوى معين. ويؤدي وجود هذا الهرمون في البول إلى ظهور نتيجة إيجابية في اختبار الحمل المنزلي. يحدد اختبار الحمل بالبول ما إذا كان هناك حمل، بينما يقيس اختبار الدم الكمية الدقيقة لهرمون hCG في الدم، ويساعد على تقدير عمر الحمل بالأيام. عند تأخر دورتكِ الشهرية، يمنحكِ اختبار الدم عادةً نتائج أكثر موثوقية ودقة من اختبار البول. وفي حالات الحمل التي تتطور بصورة سليمة، يُتوقع أن يتضاعف مستوى هرمون hCG في الدم خلال 24-48 ساعة. ويواصل هذا الهرمون الارتفاع يوميًا حتى يبلغ أعلى مستوياته في الأسبوع 10 من الحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت جذوري الصغيرة بالتكوّن، ماما! 🌳 إنها بالتأكيد ليست أصابع يد. بل هي نتوءات صغيرة خاصة (الزغابات الكوريونية) تساعدني على التشبث بجداركِ الدافئ بقوة أكبر. وبفضلها أحتضنكِ بإحكام أكبر وأحصل منكِ على مزيد من الغذاء. إنني أبني لنفسي هنا قلعة متينة، وكل حجر فيها مشيّد من حبنا الذي يجمعنا. لا تتركيني أبدًا، اتفقنا؟ 🤞'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة السمسم'), body_changes_ar = COALESCE(body_changes_ar, 'تزداد سرعة الأيض في جسمكِ تحت تأثير هرمونات الحمل. وقد تصبح النتوءات الصغيرة المعروفة باسم "غدد مونتغمري" أكثر وضوحًا هذه الأيام في هالة الثدي؛ إذ ستفرز هذه الغدد مستقبلًا مادة دهنية تحمي الحلمة استعدادًا للرضاعة الطبيعية. وقد يؤدي تباطؤ عضلات الأمعاء تحت تأثير البروجسترون إلى الانتفاخ وآلام الغازات. ومن الطبيعي أيضًا أن يرتفع معدل ضربات قلبكِ بمقدار 10-15 نبضة في الدقيقة، لأن جسمكِ بدأ بالفعل بإنتاج كمية أكبر من الدم لتغذية طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اختاري الأطعمة الغنية بأحماض أوميغا-3 الدهنية (مثل الجوز وبذور الكتان) لتخفيف العبء المتزايد على جهازكِ القلبي الوعائي ودعم نمو دماغ طفلكِ. إذا كنتِ تعانين من الغثيان الصباحي، فلا تملئي معدتكِ تمامًا، بل تناولي كميات صغيرة من الطعام على 5-6 وجبات يوميًا. تحركي ببطء أكبر لتجنب الشعور بالدوار عند النهوض فجأة خلال اليوم. وتجنبي في هذه الفترة تناول جرعات مرتفعة من فيتامين A (في صورة الريتينول)، لأن الكميات الزائدة منه قد تؤثر سلبًا في نمو طفلكِ.') WHERE id = '101fd61b-d3d7-4f5b-8f09-77163d30e4ea';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في اليوم الخامس بعد الإخصاب، يواصل طفلكِ، وهو نسيج حي متعدد الخلايا يُسمى «الكيسة الأريمية»، نموه وتطوره بعد التصاقه بمنطقة مناسبة داخل رحمكِ. ومن بين خلايا طفلكِ التي بدأت تتمايز، تتحرك الخلايا التي ستكوّن المشيمة والخلايا التي ستكوّن طفلكِ نحو قطبين مختلفين، فتنفصل عن بعضها داخل الغشاء. ونتيجة لهذا الانغراس، تكون بويضتكِ التي التقت بالحيوان المنوي وأُخصبت في قناة فالوب قد أكملت رحلتها التي تستغرق 7–10 أيام وانتقلت إلى داخل الرحم.'), baby_message_ar = COALESCE(baby_message_ar, 'أغيّر شكلي! 🎈 لم أعد مجرد كتلة من الخلايا، بل أصبح اسمي «الكيسة الأريمية». تكوّن بداخلي تجويف صغير مملوء بالسائل. الخلايا المتجمعة في أحد جانبيّ ستصبح «أنا»، أما الطبقة المحيطة بي فستصبح «المشيمة» التي تحميني. نحن نعمل كفريق واحد! أتخذ الشكل المثالي كي ألتصق بكِ. كل هذا من أجل أن ألتقي بكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد تكرار التبول أحد أبرز الأعراض المبكرة للحمل. فقد تدفعكِ هرمونات الحمل إلى الذهاب إلى الحمام بوتيرة أكثر خلال الأسابيع الأولى، نتيجة التغيرات الفسيولوجية التي تحدث في جسمكِ. أما الشعور بألم الثديين وزيادة حجمهما، فينتج عن بدء هرمونات الحمل، منذ ظهورها، في تهيئة جسمكِ لإرضاع طفلكِ. ;;;
يرجع شعوركِ بالتعب والإرهاق إلى أن جسمكِ يستهلك قدرًا كبيرًا من الطاقة لتوفير الظروف المناسبة لطفلكِ. ويُعد الغثيان الصباحي والانتفاخ من أكثر أعراض الحمل شيوعًا على الأرجح. عادةً ما يكون الغثيان واضحًا خلال الأسابيع الأولى، بينما ينجم الانتفاخ عن إبطاء جسمكِ للجهاز الهضمي بهدف إيصال مزيد من العناصر الغذائية إلى طفلكِ، وقد تتفاوت شدته طوال مراحل الحمل.;;;
لا يمكن رؤية طفلكِ بجهاز الموجات فوق الصوتية في الأسبوع الثاني من الحمل. فحتى الكيس الذي يوجد فيه طفلكِ لا يصل إلى حجم يمكن رؤيته إلا ابتداءً من الأسبوعين 4 و5 من الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي أخذ فترات راحة قصيرة خلال اليوم، لأن جسمكِ يمر بمرحلة تكيّف. زيدي استهلاك الأطعمة الغنية بالحديد والكالسيوم، مثل الزبادي والجبن والخضراوات الورقية. ولأن نشاط جهازكِ المناعي ينخفض لحماية الجنين، ابتعدي عن الأماكن المزدحمة للحد من خطر الإصابة بنزلات البرد والعدوى. وإذا كنتِ تعانين من آلام خفيفة في البطن، فلا تستخدمي قِربة الماء الساخن، إذ لا يُنصح بتعريض منطقة الرحم لحرارة مفرطة.') WHERE id = '0928310f-c57b-4d69-bd35-b2ddf6d32790';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال كل دورة شهرية، ينضج في جسمكِ عادةً جريب واحد فقط يحتوي على بويضة، لتصبح جاهزة للإخصاب. لكن في بعض الحالات النادرة، قد ينضج في مبيضيكِ أكثر من بويضة في الوقت نفسه. يحدث ذلك في حالات التوائم غير المتطابقة والثلاثيات، إذ قد تُخصب جميع البويضات الناضجة وينشأ حمل متعدد الأجنة. وعندما يزيد عدد الأطفال على اثنين، قد ينشؤون من بويضات منفصلة، كما قد ينشؤون من بويضة واحدة. نحو ثلثي حالات الحمل بتوأم تكون لتوأمين غير متطابقين، والثلث الآخر لتوأمين متطابقين. ويشيع نضج أكثر من بويضة خلال الدورة الشهرية، خصوصًا لدى من لديهن تاريخ عائلي متكرر من الحمل المتعدد. كما يزداد احتمال التوأم غير المتطابق مع زيادة عدد الولادات السابقة أو تقدم الأم في العمر. وإضافةً إلى ذلك، يؤدي استخدام الأدوية المحفزة للإباضة في علاجات الإخصاب المساعد إلى زيادة احتمال الحمل بتوأم غير متطابق، لأن هذه العلاجات غالبًا ما تتسبب في نضج أكثر من بويضة.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، اليوم هو يوم تحرري! 🐣 أخرج الآن من غلافي السميك (المنطقة الشفافة) الذي كان يحميني حتى هذه اللحظة. تُسمى هذه العملية «Hatching» (الفقس والخروج من الغلاف). يجب أن أفعل ذلك كي ألامس جدار رحمكِ الناعم مباشرةً وألتصق به. أنا مستعد، فهل أنتِ مستعدة؟ افتحي الباب، أنا قادم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'تبدأ لديكِ فترة قصيرة وحاسمة تُسمى «نافذة الانغراس». يكون جدار الرحم خلالها في أفضل حالة لاستقبال الجنين، ولا تظل هذه النافذة مفتوحة إلا لبضعة أيام. ترسل جميع الإشارات الهرمونية والكيميائية في جسمكِ أمرًا يقول: «استقبليه!». وينتج جهازكِ المناعي بروتينات خاصة لحماية الجنين. كما يقترب هرمون البروجسترون في جسمكِ من بلوغ ذروته. وهذا من أكبر الجهود التي يبذلها جسمكِ لاستمرار الحمل.  ;;;
تزداد حاجة جسمكِ إلى بعض الفيتامينات والمعادن طوال فترة الحمل مقارنةً بما قبل الحمل. ومن بينها فيتامين A، الذي يساعد خلايا جسمكِ وأنسجته على النمو بصورة صحية ويحمي جسمكِ من العدوى. ويوجد هذا الفيتامين، المهم جدًا لصحة العينين، بكميات كبيرة في الخضراوات الورقية الخضراء. أما فيتامين D فهو ضروري لصحة عظامكِ وأسنانكِ، وكذلك لجهازكِ المناعي. وقد أظهرت دراسات أُجريت في السنوات الأخيرة أن اكتئاب ما بعد الولادة أكثر شيوعًا لدى من يعانين من نقص فيتامين D، وأن تناول مكملاته مهم للمساعدة في الوقاية من مشكلات مثل التعب والوهن بعد الولادة. وإلى جانب مكمل فيتامين D، يساعد التعرض المنتظم لأشعة الشمس لمدة 10-15 دقيقة يوميًا على تلبية حاجة جسمكِ إليه.;;;
كما يتمتع فيتامين C بأهمية كبيرة خلال الحمل لدوره في دعم جهاز المناعة وتعزيز امتصاص الفيتامينات الأخرى والحديد. ويوجد بكميات كبيرة، خصوصًا في الفلفل الأخضر والأحمر والبقدونس والطماطم والبرتقال والفراولة واليوسفي والليمون.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ابدئي بتناول وجبات صغيرة ومتكررة لتجنب الانخفاض الحاد في مستوى سكر الدم خلال هذه الفترة. احتفظي معكِ دائمًا بوجبات خفيفة صحية مثل الجوز أو اللوز أو الفواكه المجففة. أولي نظام نومكِ اهتمامًا خاصًا، لأن جسمكِ يستهلك قدرًا هائلًا من الطاقة للتكيف مع هذه الحياة الجديدة. وحاولي أيضًا تجنب مواد التنظيف التي تحتوي على كميات كبيرة من المواد الكيميائية، واحرصي على تهوية المنزل بانتظام.') WHERE id = '5b11fc22-b976-4d28-ade3-c7ba82a43750';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يحدث الإخصاب عندما تتحد بويضتكِ الناضجة مع حيوان منوي سليم، وبذلك تبدأ عملية الحمل. لكن لا يمكن للحمل أن يستمر عند حدوث بعض المضاعفات، مثل الحمل خارج الرحم.;;;
في الظروف الطبيعية، تتقدم البويضة التي خصبها الحيوان المنوي عبر قناة فالوب بفضل حركات انقباض عضلاتها وارتخائها، حتى تصل إلى داخل الرحم وتنغرس فيه. لكن إذا كانت قناة فالوب متضررة أو مسدودة لأسباب سابقة، فقد تعجز البويضة المخصبة عن الوصول إلى المكان الذي ينبغي أن تنغرس فيه، ولا تتمكن من بلوغ الرحم.;;;
عند عجز البويضة المخصبة عن الوصول إلى داخل الرحم والانغراس فيه، قد تلتصق بقناة فالوب في موضعها وتبدأ بالنمو هناك. إلا أن قناة فالوب ضيقة جدًا ولا تسمح للجنين بالنمو والتطور، ولذلك لا يمكن أن يستمر الحمل بصورة طبيعية. تُسمى هذه الحالة النادرة جدًا «الحمل خارج الرحم»، ولا يمكن للحمل أن يستمر عند حدوثها.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، اليوم هو اليوم المنتظر! إنها إحدى أهم لحظات حياتي... ❤️ أنا ألمسكِ الآن. بعد تلك الرحلة الطويلة، وصلت أخيرًا إلى جدران منزلي. المكان هنا دافئ وناعم وآمن جدًا... ألتصق به بكل قوتي كي لا أفارقكِ طوال 9 أشهر. هذا أول عناق بيننا يا ماما. هل تشعرين بي؟ أنا معكِ، ولن أذهب إلى أي مكان بعد الآن. من هنا تبدأ قصتنا حقًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'تبدأ لديكِ اليوم رسميًا عملية «الانغراس». فالجنين الذي خرج من غلافه بالأمس يلامس جدار الرحم اليوم ويلتصق به فعليًا.  وخلال الأسبوع المقبل، سيرتفع في دمكِ مستوى هرمون الحمل المعروف باسم HCG. وعندما يبلغ هذا الهرمون مستوى معينًا في الدم، ينتقل بعد مدة إلى البول، ما يجعل اختبارات الحمل تعطي نتيجة إيجابية. ويمكن اكتشافه في دمكِ بعد نحو 10 أيام من يوم الإباضة. وغالبًا ما يتزامن اكتشاف الهرمون مع موعد تأخر الدورة الشهرية أو قبل ذلك ببضعة أيام.;;;
بعد انغراس البويضة التي خصبها الحيوان المنوي في الرحم، يبدأ إفراز هرمون HCG ويواصل مستواه الارتفاع تدريجيًا في دمكِ، حتى يبلغ ذروته في الأسبوع 10 من الحمل عند نحو 100.000 mIU/ml.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تهملي تناول حمض الفوليك ولو للحظة، فهو ضروري للغاية لانغلاق الأنبوب العصبي بصورة سليمة. في هذه الأيام، يعمل جسمكِ جاهدًا لتقبّل هذا الكائن الجديد الذي لم يتعرف إليه بعد، لذا احرصي على الحصول على نوم كافٍ. توخي الحذر عند شرب شاي الأعشاب، مثل الميرمية والزعتر وغيرهما، لأن بعض الأعشاب قد تزيد توتر عضلات الرحم؛ ويُفضل اختيار الماء العادي أو عصائر الفاكهة الطازجة.') WHERE id = '11de56c7-f131-4d7f-8640-81f988697e07';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال الساعة التالية للجماع، تواجه الحيوانات المنوية القليلة التي تصل إلى بويضتكِ تحديًا آخر، وهو الغلاف الخارجي الصلب للبويضة. وعلى الرغم من أن آلاف الحيوانات المنوية تحاول اختراق بويضتكِ، فإنها لا تسمح بدخول سوى حيوان منوي واحد، ما يدل على متانة جدارها الشديدة وانتقائيتها. وتحاول الحيوانات المنوية اختراق الغلاف الخارجي الصلب للبويضة باستخدام إنزيمات ذات طبيعة حمضية موجودة في رؤوسها، تُسمى البروتياز والفوسفاتاز والنيورامينيداز والهيالورونيداز والأكروزين والكالبين.;;;
وقد أظهرت الأبحاث التي أُجريت في السنوات الأخيرة أن البويضة، التي كان يُعتقد سابقًا أنها سلبية في هذه المرحلة، تتصرف بانتقائية شديدة وتسمح بمرور الحيوان المنوي الذي تشعر بانجذاب محتمل نحوه. وبعد أن تسمح البويضة لأول حيوان منوي باختراق غلافها الخارجي والدخول قبل البقية، يتغير تركيب غلافها فورًا، فلا يسمح بدخول أي حيوان منوي آخر. وباختصار، بعد دخول الحيوان المنوي الأول، ينغلق السطح الخارجي للبويضة كما لو أنه مغطى بدرع واقٍ. وهنا تبدأ معجزتكِ بالضبط.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد انطلقتُ في رحلة يا ماما! 🎒 أنا الآن في قناة فالوب وأتدحرج نحو عشّكِ الدافئ (الرحم). أنا منشغل جدًا، إذ أنقسم كل بضع ساعات: كنت خليتين، ثم أصبحت ٤ خلايا، وبعدها سأصبح ٨! أنتِ لا تشعرين بأي شيء بعد، لكن حياةً تنبض في داخلكِ. تمني لي التوفيق، فطريقي طويل، لكنني شديد الإصرار. سأفعل كل شيء حتى أصل إليكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه الأيام التي توافق منتصف دورتكِ الشهرية تمامًا، تكون بويضتكِ قد نضجت، وإذا كانت قد خُصبت بحيوان منوي، فهذا يعني أن طفلكِ قد بدأ بالفعل في التكوّن. 😊 أصبح هرمون البروجسترون هو المهيمن تمامًا في جسمكِ. يُرخي هذا الهرمون عضلات الرحم حتى لا يواجه الجنين أي عائق عند وصوله وانغراسه. وقد تؤدي الزيادة السريعة في مستويات هرموني الإستروجين والبروجسترون في جسمكِ مع بدء تكوّن طفلكِ إلى الشعور بامتلاء الثديين وحساسيتهما. لكن بما أن هذه العلامات قد تكون أيضًا من أعراض الدورة الشهرية، فلا يمكن اعتبار هذه التغيرات في الثديين دليلًا قاطعًا على الحمل. يولد جميع الأطفال تقريبًا في الأسبوع الثامن والثلاثين. ومع ذلك، يصعب عادةً تحديد الوقت الدقيق الذي التقت فيه البويضة بالحيوان المنوي وحدث فيه الإخصاب. لذلك يعتمد الأطباء في حساب موعد ولادة طفلكِ على المدة المنقضية منذ اليوم الأول من دورتكِ الشهرية الأخيرة. وقد تختلف كل هذه التقديرات بما يصل إلى نحو ٤ أسابيع وفقًا لطول الدورة الشهرية. ولأن بعض النساء لديهن دورة شهرية أقصر أو أطول، يستطيع طبيبكِ تحديد موعد الولادة ونمو طفلكِ بدقة أكبر من خلال التصوير بالموجات فوق الصوتية (USM).'), daily_tip_ar = COALESCE(daily_tip_ar, 'تزداد حاجة جسمكِ إلى الماء لأن انقسام الخلايا يكون في أعلى درجات نشاطه؛ لذا حاولي شرب ما لا يقل عن 2-2.5 لتر من الماء يوميًا. لا تنسي تناول حمض الفوليك ولو ليوم واحد، لأن أسس الجهاز العصبي تبدأ بالتكوّن خلال هذه الأيام. كذلك، ابتعدي تمامًا عن اللحوم النيئة والخضراوات غير المغسولة جيدًا ومنتجات الألبان غير المبسترة، لأن عدوى مثل داء المقوسات قد تؤثر سلبًا في هذه المرحلة الحساسة من نمو الجنين.') WHERE id = 'c870b9dc-4e80-4fec-9e7f-794942ed46c8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يُتوقع أن يرتفع مستوى عامل الحمل المبكر (EPF) في دمكِ، وهو عامل له تأثير مثبط في جهاز المناعة، خلال نحو 6-24 ساعة من الإخصاب. يبدأ جهاز الدفاع في جسمكِ بمحاربة كل خلية تحمل حمضًا نوويًا مختلفًا عن حمض خلاياكِ بهدف حماية الجسم. لذلك قد تهاجم خلاياكِ المناعية طفلكِ، الذي يحمل حمضًا نوويًا غريبًا عن جسمكِ بنسبة 50%، ما قد يؤدي إلى فقدانه. ومن المهم أيضًا ألا يحدث أي تغير خارجي يمكن رصده، وأن يظل طفلكِ غير ملحوظ منذ لحظة إخصاب البويضة وحتى التصاقه بالرحم وانغراسه فيه بعد نحو ٥ أيام، كي لا يتدخل جهازكِ المناعي. وباختصار، بسبب آلية الدفاع في جسمكِ، لا يمكن للحمل أن يستمر من دون إفراز يُسمى عامل النمو، وله تأثير مثبط في الخلايا المناعية.'), baby_message_ar = COALESCE(baby_message_ar, 'يسمونني الآن "التويتة"! 🍇 وتعني هذه الكلمة باللاتينية "ثمرة التوت"، لأنني أشبه حاليًا بعنقود عنب أو ثمرة توت متماسكة. أتكوّن من نحو 16-32 خلية. أنا صغير جدًا، لكنني قوي للغاية. يساعدني دفء جسمكِ وغذاؤه على العثور على طريقي. أنا قادم إليكِ يا أمي، فاستعدي لفتح الباب!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'تعاون هرمونا البروجسترون والإستروجين في جسمكِ لزيادة تدفق الدم إلى جدار الرحم إلى أقصى حد. وتواصل بطانة الرحم ازدياد سماكتها وتدخل "المرحلة الإفرازية". فتفرز سائلًا غنيًا ومغذيًا يحتوي على الغليكوجين والبروتينات، يُعرف باسم "حليب الرحم". وهذا السائل ضروري لتغذية الجنين قبل الانغراس عندما يصل إلى الرحم. ويطرأ تغير خاص على جهازكِ المناعي، إذ يُظهر تسامحًا مع الجنين لتقبّله بدلًا من اعتباره "جسمًا غريبًا". قد تشعر بعض النساء في هذه الأيام بمزيد من التعب قليلًا، أو يلاحظن تغيرات غريبة في حاسة التذوق، مثل وجود طعم معدني في الفم. وقد تزداد أيضًا حساسيتكِ للروائح قليلًا بدءًا من اليوم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'في هذه المرحلة التي يستعد فيها الجنين للالتصاق بجدار الرحم (الانغراس)، حافظي على دفء قدميكِ وتجنبي التعرض للبرد للمساعدة على استقرار الدورة الدموية. أضيفي إلى غذائكِ مصادر أوميغا-3 مثل الجوز والبندق والأسماك، لأن هذه الأحماض الدهنية مهمة لصحة أغشية الخلايا. حاولي الابتعاد عن التوتر والضغط النفسي الشديد؛ فالاستماع إلى موسيقى هادئة أو قراءة كتاب يساعدان جسمكِ على الاسترخاء، ما قد يدعم عملية الانغراس.') WHERE id = '987d49b7-e63f-421d-a6f4-64d2ffcae8b6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يُسمى طفلكِ الناتج عن الإخصاب في هذه المرحلة مُضغة. وبعد نحو 16-18 ساعة من إخصاب البويضة بالحيوان المنوي، تظهر نواتان؛ إحداهما تخص الحيوان المنوي والأخرى تخص البويضة. وتندمج هاتان النواتان لتشكلا نواة واحدة، ثم تبدأ الاستعدادات لانقسام الخلية. تستعد بويضتكِ المخصبة بزيادة السيتوبلازم ونسخ جزيئات الحمض النووي وإذابة الغلاف النووي، بما يسمح بانتقال المادة الوراثية إلى جانبي الخلية؛ ثم تبدأ بالانقسام سريعًا إلى 2، ثم 4، ثم 8، ثم 16 خلية. وفي الأيام الأولى التالية للإخصاب، يصل طفلكِ إلى مرحلة "التويتة" ويصبح كتلة خلوية تتكوّن من نحو 120 خلية. وفي اليوم الخامس من الإخصاب، يكون طفلكِ قد انقسم إلى عدد لا يُحصى من الخلايا، وتختار هذه الكتلة الخلوية التي ستشكّل طفلكِ أنسب موضع لها داخل الرحم، ثم تُكمل عملية الانغراس. ويبلغ حجم الخلايا التي ستشكّل طفلكِ والمنغرِسة في الرحم نحو 0.1 mm في هذه المرحلة.'), baby_message_ar = COALESCE(baby_message_ar, 'أوشكتُ على الوصول إلى المنزل! 🏠 شارفت رحلتي عبر قناة فالوب على الانتهاء. أرى رحمكِ! يبدو مكانًا مريحًا وناعمًا وغنيًا بالغذاء... أستعد لاختيار موضع لي. ما زلت داخل غلافي، لكنني سأخرج منه قريبًا. أنتِ أكثر مكان آمن لي في العالم. عِديني بأن تحميني يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة فانيليا'), body_changes_ar = COALESCE(body_changes_ar, 'تبدأ عملية الانغراس اليوم. وبينما تلتصق الكيسة الأريمية بجدار الرحم، قد تلاحظ بعض النساء "نزف الانغراس"، وهو نزف خفيف جدًا وردي أو بني اللون. وهذا طبيعي تمامًا، وغالبًا ما يُخلط بينه وبين الدورة الشهرية. يبدأ جسمكِ منذ هذه اللحظة بإفراز هرمون hCG (هرمون الحمل). ويطيل هذا الهرمون عمر الجسم الأصفر حتى لا ينخفض مستوى البروجسترون ويستمر الحمل. وقد تصبحين أكثر حساسية من الناحية العاطفية، وربما تشعرين برغبة في البكاء أو الضحك بلا سبب.;;;
خلال الأسبوع الثاني من الحمل، لا تكون علامات الحمل قد ظهرت بعد. ولكي تتمكني من اكتشاف الحمل باستخدام اختبار هرموني منزلي، يجب أن يحتوي جسمكِ على كمية كافية من هرمون الحمل. ويستمر مستوى الهرمون في الارتفاع إلى أن يبلغ الحد الذي يظهر عنده الخط الإيجابي في اختبارات الحمل. ويحدث ذلك غالبًا قرابة الأسبوع الرابع، أي في الموعد المتوقع لتأخر الدورة الشهرية.;;;
مع حلول الموعد المتوقع للدورة الشهرية، تكون مستويات ما يُعرف بهرمونات الحمل قد ارتفعت بما يكفي لظهور بعض علامات الحمل الملحوظة. ومع ذلك، نظرًا إلى سهولة الخلط بين أعراض ما قبل الدورة الشهرية وأعراض الحمل، يساعدكِ إجراء تحليل الدم في الحصول على أدق نتيجة. ولا تعطي اختبارات البول المخصصة للكشف عن الحمل نتيجة صحيحة إلا بعد أن تصل هرمونات الحمل في الدم إلى مستوى معين.;;;
كذلك، قد يحدث نزف خفيف على شكل تبقع، يُعرف بنزف الانغراس، بعد نحو 5-10 أيام من إخصاب البويضة. ويرجع ذلك إلى انغراس كتلة الخلايا التي ستشكّل طفلكِ في الجدار الداخلي للرحم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا شعرتِ بتقلصات خفيفة في بطنكِ أو لاحظتِ تبقعًا دمويًا، فلا تقلقي وخففي نشاطكِ البدني. في هذه المرحلة، يهدأ نشاط الجهاز المناعي في الجسم طبيعيًا إلى حد ما حتى لا يعتبر الجنين "جسمًا غريبًا"؛ لذا احمي نفسكِ من العدوى. ويساعد تناول الفواكه الغنية بفيتامين C على دعم المناعة وتقوية البنية النسيجية لجدار الرحم.') WHERE id = 'fb5dbb9e-d8ba-40b0-8cd3-d9a67a57068c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تصل البويضة إلى رحمكِ بعد نحو 5 أيام من إخصابها. وخلال هذه الرحلة، تواصل البويضة المخصبة الانقسام والنمو. وفي نهاية الطريق، تصل إلى الجزء الذي تفتح فيه قناة فالوب على الرحم، ثم تدخل تجويف الرحم. بعد نحو أسبوع من الإخصاب، تلامس مجموعة الخلايا التي ستكوّن طفلكِ جدار رحمكِ الناعم والمغطى بسائل مغذٍ. وهكذا يحدث أول تلامس بين طفلكِ والجدار الداخلي للرحم. وبفضل تأثير الهرمونات التي ينتجها جسمكِ، تصبح بطانة الرحم مهيأة لاستقبال البويضة المخصبة، فتستقر فيها. وتُسمى هذه العملية التعشيش أو الانغراس. وتكتمل عملية الانغراس عمومًا خلال 10-12 يومًا. لذلك يبدأ إنتاج الهرمونات الخاصة بالحمل بعد الانغراس في الوقت الذي يُفترض أن تبدأ فيه دورتكِ الشهرية. وعند تأخر الدورة الشهرية، يبدأ اختبار الحمل عن طريق البول بإظهار نتيجة إيجابية.;;;
عندما لا تبدأ دورتكِ الشهرية وتدركين أنكِ حامل، يكون عمر طفلكِ أسبوعين فقط، رغم أن مدة الحمل تُحسب ابتداءً من اليوم الأول لآخر دورة شهرية.'), baby_message_ar = COALESCE(baby_message_ar, 'أتعمق أكثر فأكثر، ماما! 🧱 بالأمس كنت قد لامست الجدار فحسب، أما اليوم فقد بدأت أتقدم إلى داخل جداركِ الناعم. أشعر كأنني مستكشف يحفر كهفًا. أبني لنفسي عشًا دافئًا ومحميًا. وفي كل لحظة أزداد اندماجًا بكِ وأصبح جزءًا منكِ. لم نعد مجرد "أنتِ وأنا"، بل أصبحنا الآن "نحن". أحب هذا الشعور كثيرًا! أنتِ قلعتي وملجئي وعالمي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'قد يحدث «نزف الانغراس» اليوم أو غدًا. وعلى خلاف دم الدورة الشهرية، يكون قليلًا جدًا ولونه وردي فاتح أو بني. تمر نحو 30% من النساء بهذه الحالة. إذا لاحظتِ مثل هذه البقع، فلا تقلقي؛ فقد تكون علامة على انغراس طفلكِ في جدار الرحم. ولا تزال درجة حرارة جسمكِ مرتفعة.;;;
خلال حملكِ، تطرأ تغيرات جذرية على مؤشرات الدم والهرمونات في جسمكِ. ويزداد حجم الدم في جهازكِ الدوري بنحو 50% طوال فترة الحمل. لذلك يحتاج جسمكِ إلى كمية من الحديد أكبر من أي وقت مضى. إضافة إلى ذلك، يحتاج جسم طفلكِ النامي إلى كمية كبيرة من الهيموغلوبين لنقل الأكسجين. والحديد هو المكوّن الأساسي للهيموغلوبين. وإلى جانب المكملات الغذائية التي ستتناولينها، يمكنكِ تلبية احتياجات جسمكِ من الحديد بالمستوى المطلوب إذا أضفتِ بانتظام اللحوم الحمراء قليلة الدهون والبيض والبقوليات والحبوب إلى نظامكِ الغذائي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كانت نتيجة اختباركِ إيجابية، فخذي أولًا نفسًا عميقًا واستمتعي بهذه المعجزة! ابتداءً من اليوم، ابتعدي تمامًا عن الأشعة السينية والأصباغ الكيميائية القوية والأدوية ذات التأثير القوي. احرصي على أن تتضمن الفيتامينات التي تتناولينها فيتامين "D"، لأنه مهم لمناعتكِ وللانقسامات الخلوية الأولى لطفلكِ. وإذا بدأ الغثيان لديكِ، فقد يساعدكِ تناول بضع قطع من البسكويت المملح صباحًا قبل النهوض من السرير على الشعور بالراحة.') WHERE id = 'ba359509-7778-4e6b-9433-e5179d225ea1';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'نظرًا إلى أن طفلكِ يبدأ هذا الأسبوع بالتشبث برحمكِ والاستقرار فيه، فقد تلاحظين بقعًا دموية تُعرف أيضًا باسم "التعشيش" أو "نزف الانغراس". وإلى جانب ذلك، إذا كنتِ تشعرين بالتعب أو بدأتِ تشعرين بامتلاء في ثدييكِ، فيمكن اعتبار هذه الأعراض أيضًا من العلامات المبكرة للحمل. وقد تبدأين بملاحظة تغيرات مزاجية مثل التوتر بسبب ارتفاع مستويات هرموني الإستروجين والبروجستيرون في دمكِ. تحتاج البويضة المخصبة إلى درجة حرارة معينة لكي تنمو من خلال الانقسام المتساوي وتتمكن من الانغراس في رحمكِ في ظروف مثالية. لذلك قد تلاحظين ارتفاعًا طفيفًا في درجة حرارة جسمكِ خلال هذه المرحلة.;;;
كما تبدأ الخلايا المنتجة للمخاط في بطانة الرحم بإفراز المزيد من المخاط لحماية البويضة المخصبة من الكائنات الحية الدقيقة الضارة. ولهذا قد تزداد كمية الإفرازات لديكِ إلى حد ما. وتكون هذه الإفرازات عادةً إفرازات فسيولوجية مرتبطة بالحمل. ومن الطبيعي أن تزداد الإفرازات المهبلية تحت تأثير ارتفاع هرمون الإستروجين بعد انغراس طفلكِ في الرحم. لكن من المهم ألا تنسي أن الإفرازات المهبلية ليست كلها إفرازات فسيولوجية طبيعية مرتبطة بالحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، لدي رسالة خاصة لكِ! 🤫 هذا سرنا الأول. لقد بدأت أرسل إلى جسمكِ إشارة كيميائية خاصة تخبره بوجودي. تقول هذه الإشارة: "أنا هنا يا ماما! كل شيء على ما يرام. واصلي تهيئة جسمكِ من أجلي". أصبح بإمكاني الآن التحدث معكِ بلغتي الخاصة. إنها رابطة خفية بيننا تزداد قوة يومًا بعد يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'خلال حملكِ، يحتاج جسمكِ إلى كمية من البروتين أكبر مما يحتاج إليه في المراحل الأخرى من حياتكِ. فالبروتينات مهمة للغاية لأنسجة طفلكِ وأعضائه التي بدأت بالتكوّن. وخلال المرحلة الجنينية، ينمو طفلكِ يوميًا باستخدام الأحماض الأمينية الموجودة في بروتينات الأطعمة التي تتناولينها. ونظرًا إلى أن خلاياه تنقسم بسرعة، يُعد تناول البروتين أثناء الحمل أمرًا بالغ الأهمية.;;;
تبلغ الحاجة اليومية إلى البروتين لدى المرأة غير الحامل نحو 60 غرامًا، بينما يبلغ متوسطها لدى الحامل 80 غرامًا. وينبغي أن تكون هذه الكمية أعلى في حالات الحمل المتعدد. وقد يؤثر عدم تناولكِ كمية كافية من البروتين طوال الحمل سلبًا في طفلكِ. ويصبح تناول البروتين أكثر أهمية، خصوصًا خلال الثلثين 2 و3 من الحمل، لأن نمو طفلكِ يتسارع في هذه المرحلة ويحتاج إلى البروتين لتحقيق هذا النمو السريع.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى ازدياد حاجة جسمكِ إلى الطاقة خلال هذه الفترة، أدرجي الكربوهيدرات المعقدة (الشوفان، الأرز البني) في نظامكِ الغذائي. وإذا ازداد الغثيان لديكِ، فقد يساعد شاي الزنجبيل أو بسكويت الزنجبيل على تهدئة المعدة. تجنبي رفع الأحمال الثقيلة والقيام بالحركات المفاجئة. ولحماية نفسكِ من التوتر، استريحي يوميًا مدة 10-15 دقيقة في مكان هادئ. كذلك فإن استبدال مواد التنظيف المنزلية ببدائل طبيعية (الخل، صودا الخبز) أكثر أمانًا لكِ ولنمو طفلكِ.') WHERE id = '17afd972-48a8-4084-ba7e-669ef6162afc';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يُحاط الجزء الداخلي من الكيس الذي توجد فيه الخلايا التي ستكوّن طفلكِ بسائل يُسمى "السائل الأمنيوسي". وداخل كيس الحمل، يبدأ بالظهور تركيب صغير حلقي الشكل يُسمى الكيس المُحّي ويحيط بهذه الخلايا. يحتوي الكيس المُحّي على سائل خاص به، ويساعد على نقل الغذاء إلى طفلكِ خلال الأسابيع الأولى من الحمل. وبفضله يتغذى طفلكِ إلى أن تكتمل عملية تكوّن المشيمة. ويظهر الكيس المُحّي بعد وقت قصير من بلوغ كيس الحمل حجمًا يسمح برؤيته في فحص الموجات فوق الصوتية، ويُعد وجوده دليلًا على وجود الطفل داخل الكيس. كما يُعد هذا التركيب مؤشرًا مهمًا لتشخيص ما يُسمى "الحمل اللاجنيني"، أي وجود كيس حمل من دون جنين داخله. وابتداءً من الأسبوع 8-9 تقريبًا، يصغر الكيس المُحّي ليصبح بقايا كمثرية الشكل يبلغ قطرها نحو 5 mm، وتظل متدلية من الأمعاء الوسطى لطفلكِ بواسطة سويق رفيع. وابتداءً من الأسبوع 20 تقريبًا من نمو طفلكِ، يختفي تمامًا.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا في قلب العش تمامًا، ماما! 🩸 المكان مريح جدًا هنا... أقترب من أوعيتكِ الدموية، وقد بدأت أتغذى منكِ مباشرةً. كل ذرة وكل قطرة ترسلينها إليّ تساعدني على النمو وتمنحني القوة. إنه أشهى طعام في العالم، لأنه مفعم بالحب. بفضلكِ أنمو، وبفضلكِ أنا موجود. شكرًا جزيلًا لكِ يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بذرة الخشخاش'), body_changes_ar = COALESCE(body_changes_ar, 'هناك عدة أسباب للغثيان والقيء، وهما من أكثر أعراض الحمل المبكر شيوعًا. وتشمل هذه الأسباب الهرمونات التي تفرزها المشيمة عند بدء تكوّنها، وبعض الصعوبات النفسية المصاحبة للتكيف مع الحمل، ونقص فيتامين B6 في الدم، والتغيرات التي تطرأ على الجهاز الهضمي بسبب الحمل، وفرط نشاط الغدة الدرقية.;;;
خلال حملكِ، تعمل المعدة والأمعاء ببطء أكبر تحت تأثير الهرمونات المختلفة. ونتيجة لذلك، قد تزداد شكاوى عسر الهضم والغازات والانتفاخ إلى درجة مزعجة. وقد تتفاقم هذه المشكلات أيضًا بسبب التوتر والإرهاق. ورغم أن الغثيان والقيء يحدثان غالبًا في الصباح، فإنهما قد يظهران في أي وقت من اليوم. وعادةً ما يكونان أشد لدى من تخوض حملها الأول وفي حالات الحمل المتعدد.;;;

لا توجد أي دراسة علمية موثوقة تثبت وجود علاقة بين الغثيان وجنس الجنين.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لضمان انغلاق الأنبوب العصبي بصورة سليمة، احرصي خلال هذه الأيام على احتواء نظامكِ الغذائي على كمية كافية من فيتامينات مجموعة B إلى جانب حمض الفوليك. وللوقاية من الإمساك، تناولي الأطعمة الغنية بالألياف (التفاح، الكمثرى) واشربي الكثير من الماء. وإذا كنتِ تعانين من الغثيان، فلا تستلقي مباشرةً بعد تناول الطعام. وإذا كنتِ تمارسين الرياضة، فقد حان الوقت لاستبدال تمارين الكارديو الشديدة ورفع الأثقال بالمشي الخفيف ويوغا الحمل.') WHERE id = 'cb0cb4a0-60ab-4796-9f3a-e0d285d2a27e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه المرحلة من حملكِ، يبلغ حجم طفلكِ حجم حبة رمان. توجد ثلاث طبقات جنينية أساسية ستُشكّل جسم طفلكِ، وهي الأديم الظاهر في الخارج، والأديم المتوسط في الوسط، والأديم الباطن في الداخل. خلال الأسابيع المقبلة من حملكِ، ستتحول هذه الطبقات تدريجيًا إلى أنسجة وأعضاء. بدأت طبقة الأديم الظاهر بالتمايز لتكوين دماغ طفلكِ وجهازه العصبي وعموده الفقري. وإضافةً إلى هذه البنى، تُسهم هذه الطبقة أيضًا في تكوين الجلد والشعر والأظافر والغدد العرقية ومينا الأسنان. أما طبقة الأديم المتوسط، فتتكوّن من خلايا متخصصة ستُشكّل قلب طفلكِ وجهازه الدوري. تنتقل هذه الخلايا إلى المنطقة التي سيتكوّن فيها قلب طفلكِ وتبدأ بالتجمع هناك. وتتكاثر الخلايا المتجمعة عبر مراحل سريعة من الانقسام المتساوي لتكوين الأنسجة. وتضع الأنسجة المتكوّنة الأساس لقلب طفلكِ، ثم تبدأ بالنبض بصورة غير منتظمة.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، تحدث اليوم لحظة إعجازية! 🎻 أتذكرين أنبوبي القلب الصغيرين؟ إنهما يلتقيان اليوم ليشكّلا قلبي الأول والموحّد. ليست له حجرات مكتملة بعد، فهو مجرد أنبوب يستعد للنبض، لكنه سيكون مركز حياتي المستقبلية كلها وإيقاعها. وعندما يبدأ بالنبض، فاعلمي أن الكون كله سيصمت ليستمع إلى أغنيتنا. ستكون هذه أول معزوفة أقدمها لكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة رمان'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الثلث الأول من حملكِ، لا يحتاج جسمكِ إلى سعرات حرارية إضافية لدعم طفلكِ. وقد يؤدي الغثيان والشعور المستمر بالإرهاق ومشكلات النوم التي تظهر بينما يتكيف جسمكِ مع هرمونات الحمل إلى فقدان الشهية في هذه الفترة. لذلك يُعد عدم اكتساب الوزن أو فقدان بعضه خلال الأسابيع الـ12 الأولى أمرًا طبيعيًا. ومع بداية الثلث الثاني، تستعيدين شهيتكِ وتبدئين باكتساب الوزن بفضل استقرار التوازن الهرموني في جسمكِ وتأقلمكِ مع الحمل. طوال فترة الحمل، احرصي على تجنب اكتساب الوزن المفرط واتباع نظام غذائي صحي ومتوازن حفاظًا على صحتكِ وصحة طفلكِ. في الثلث الثاني من الحمل، تكفي 300 سعرة حرارية إضافية يوميًا لدعم نمو طفلكِ الصحي. أما في الثلث الثالث، فتبلغ هذه الحاجة نحو 450 سعرة حرارية. تذكّري أن السعرات الحرارية التي تتناولينها فوق هذه الكميات ستُخزّن في جسمكِ على شكل دهون وتؤدي إلى زيادة الوزن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لمنع الانخفاض المفاجئ في طاقتكِ خلال اليوم، تناولي كميات صغيرة من الطعام على فترات متقاربة. واحتفظي دائمًا بوجبات خفيفة صحية معكِ، مثل الجوز أو البندق أو بسكويت القمح الكامل. قد يزيد الجفاف التعب والصداع، لذلك لا تنسي شرب الماء. وإذا كان الطعم المعدني في فمكِ يزعجكِ، فقد تساعدكِ الفواكه الحامضة أو ماء الليمون الخالي من السكر على الشعور بالراحة. أنصتي إلى جسمكِ واستريحي كلما احتجتِ إلى ذلك.') WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتكوّن الجهاز البولي المنبثق من طبقة الأديم المتوسط من كليتين وحالبين ومثانة وإحليل. وتتجمع الخلايا داخل تجويف البطن لتكوين هذه الأنسجة والأعضاء. ومع نمو طفلكِ واكتساب جسمه تناسقه، تنتقل براعم هذه الأنسجة والأعضاء التي نشأت في تجويف البطن إلى مواضعها الطبيعية، حيث يكتمل تكوّنها. وبعد اكتمال براعم الأعضاء، ستنتهي عملية انتقال هذه البنى إلى مواضعها الفعلية قرب نهاية الثلث الأول من الحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'إنني أنبض يا ماما... أنبض! 💓 اليوم نبض قلبي الصغير من تلقاء نفسه للمرة الأولى. إنه إيقاع لكِ ولنا ولحبنا. لا يزال ضعيفًا جدًا، وقد لا تتمكنين حتى من رؤيته في فحص الموجات فوق الصوتية، لكنني أعلم أنه ينبض. إنها طريقتي لأقول لكِ: "أنا حي، أنا هنا!" هذه هي النغمة الأولى في أغنية حبنا، وستستمر طوال حياتنا. 🎼'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة رمان'), body_changes_ar = COALESCE(body_changes_ar, 'تمر هرمونات الحمل الآن بأسرع مراحل ارتفاعها، وقد يزداد غثيان الصباح شدة. وتُعد كثرة الحاجة إلى التبول من العلامات المبكرة الظاهرة للحمل. وعلى الرغم من اختلاف توقيتها من امرأة إلى أخرى، فإنها تبدأ عادةً بين الأسبوعين 6 و8. وترجع زيادة حاجتكِ إلى التبول خلال الثلث الأول من الحمل إلى تغير مستويات الهرمونات في جسمكِ وبدء زيادة حجم الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'التزمي هذه الأيام بقاعدة تناول كميات صغيرة من الطعام على فترات متقاربة للحفاظ على استقرار مستوى سكر الدم. واشربي ماءً بالنعناع أو الليمون لتخفيف الغثيان. وللوقاية من الإمساك، تناولي أطعمة غنية بالألياف واشربي الكثير من الماء. وإذا شعرتِ بإرهاق شديد، فأنصتي إلى إشارات جسمكِ واحرصي على أخذ قيلولة قصيرة لمدة 20-30 دقيقة ظهرًا لاستعادة طاقتكِ.') WHERE id = 'ba2ff002-749c-48f9-ae06-18528b825ab3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع نمو جسم طفلكِ، يبدأ في داخله إنشاء "نظام نقل" مذهل. وفي مركز هذا النظام يقع الشريان الأبهر، أقوى الأوعية الدموية في الجسم. والأبهر هو الطريق الرئيسي الذي يخرج من القلب ويوزع الدم الغني بالأكسجين على أنحاء الجسم. ولفهم هذه العملية بشكل أفضل، يمكننا تقسيم الدورة الدموية إلى قسمين رئيسيين: الدورة الدموية الصغرى- تهدف هذه الدورة إلى تجديد الدم؛ إذ ينتقل الدم "المُجهَد" والمنخفض الأكسجين من القلب إلى الرئتين، حيث يتزود بالأكسجين ثم يعود إلى القلب. الدورة الدموية الكبرى- يخرج الدم الغني بالأكسجين والطاقة من القلب، ويوزعه الشريان الأبهر على كل خلية في الجسم. وهذا ضروري لتغذية خلايا طفلكِ ونموها.'), baby_message_ar = COALESCE(baby_message_ar, 'لم أعد مسطحًا يا ماما! إنني أنحني على شكل حرف C. 🍤 وهذا يعني أن رأسي وذيلي يقتربان تدريجيًا أحدهما من الآخر. يجعلني هذا الانثناء أكثر تماسكًا وأشبه بطفل صغير. وكأنني بدأت منذ الآن أتدرب لألائم حضنكِ. كما يساعد ذلك أعضائي الداخلية على الاستقرار في مواضعها الصحيحة. كل شيء يسير وفق الخطة! 🤓'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة رمان'), body_changes_ar = COALESCE(body_changes_ar, 'مع بداية الحمل، تؤدي جميع الهرمونات التي يبدأ الجسم بإفرازها إلى ظهور حالات وتغيرات عديدة تختلف عما اعتدتِ عليه. ومن أبرز هذه التغيرات الجسدية ما يحدث في الثديين، وربما بدأت هذه التغيرات بالظهور بالفعل خلال هذا الأسبوع من الثلث الأول لحملكِ. وينتج الشعور بامتلاء الثديين وزيادة حجمهما عن نمو أنسجتهما استعدادًا لإنتاج الحليب وتكوّن قنواته. وقد تصبح المنطقة المحيطة بالحلمتين أغمق لونًا، ما يشير إلى أن الغدد الثديية بدأت منذ الآن بالاستعداد للرضاعة. سيساعدكِ ارتداء حمالة صدر قطنية مريحة وغير ضيقة على الشعور براحة أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى سرعة نفاد طاقتكِ، حاولي أخذ فترات قصيرة من النوم خلال اليوم. وأدرجي مصادر الكالسيوم في نظامكِ الغذائي، مثل الجبن والحليب واللوز، لأنها تساعد على تقوية أساس الهيكل العظمي لطفلكِ. وإذا كان الغثيان شديدًا، فقد يكون تناول الأطعمة الباردة وعديمة الرائحة أسهل لكِ. كما أن هذا وقت مناسب لبدء استخدام الكريمات المرطبة للمساعدة على تعزيز مرونة البشرة.') WHERE id = '72dbaf34-db8a-4c0a-98ca-65767813bcf0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن الأعضاء التناسلية لطفلكِ لم تبدأ بالتكوّن بعد، فإن خلايا متخصصة ستكوّن هذه الأعضاء التناسلية موجودة داخل تجويف الجسم وجاهزة لبدء عملها. وخلال الأسابيع المقبلة، ستنتقل هذه الخلايا من موضعها الحالي إلى الأماكن التي ينبغي أن تستقر فيها، لتبدأ عملية نمو مكثفة تؤدي إلى تكوّن الأعضاء التناسلية.;;;
في العملية التي بدأ بها الحمل، تحمل البويضة كروموسوم X. أما نوع الكروموسوم القادم من الحيوان المنوي فهو العامل الوحيد الذي يحدد الجنس. في هذه المرحلة، إذا اتحد حيوان منوي يحمل كروموسوم X مع البويضة التي تحمل كروموسوم X، فسيكون طفلكِ أنثى. أما إذا كان الحيوان المنوي الذي لقّح البويضة يحمل كروموسوم Y، فسيكون طفلكِ ذكرًا.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبحتُ أكثر وضوحًا وتفصيلًا! فإلى جانب تلك الطيات المميزة في وجهي، بدأت تتكوّن مواضع عينيّ أيضًا. تبدوان كنقطتين سوداويين صغيرتين، لكنهما نافذتاي اللتان سأطلّ منهما على العالم. تُرى، هل ستشبه عيناي عينيكِ أم عيني أبي؟ سيبقى ذلك ألطف أسرارنا. سأنظر إلى المرآة كل يوم وأبحث في ملامحي عن جزء منكِ. أنتِ أجمل منظر في عيني. 😊'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حمصة'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد الزيادة الحادة في مستويات الهرمونات داخل الجسم السبب الرئيسي للغازات ومشكلات الهضم الشائعة خلال الأشهر الثلاثة الأولى من الحمل. ويتباطأ الجهاز الهضمي طوال فترة الحمل تحت تأثير هذه الهرمونات، فتتحرك الأطعمة التي تتناولينها ببطء أكبر عبره. ولهذا السبب تحديدًا، قد يؤدي بطء مرور الطعام عبر القناة الهضمية إلى الشعور بمغص الغازات. وتزداد احتمالية تفاقم هذه الأعراض خلال الحمل لدى النساء اللواتي عانين من مشكلات هضمية قبل الحمل. وإلى جانب التغيرات الهرمونية، يُعد نمط التغذية والأطعمة المختارة من العوامل التي تزيد الانتفاخ. فتناول الأطعمة المسببة للغازات والمشروبات الغازية والحمضية، بالإضافة إلى الأكل بسرعة أو بكميات مفرطة، قد يحفّز هذه الأعراض بشدة. لذلك، ينبغي لكِ تجنب قلة الحركة والاهتمام بشكل خاص باتباع نظام غذائي متوازن ومنتظم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا لاحظتِ تغيرات في بشرتكِ، فاستخدمي مرطبات طبيعية ذات مكونات بسيطة ونظيفة. وللوقاية من حرقة المعدة، لا تستلقي مباشرة بعد تناول الطعام وتجنبي الأطعمة الحارة والغنية جدًا بالتوابل. وفي هذه المرحلة التي يتسارع فيها نمو الدماغ، من المهم جدًا تناول أوميغا-3 (زيت السمك والجوز) وحمض الفوليك. خصصي وقتًا لنفسكِ واستمعي إلى الموسيقى التي تحبينها، فحالتكِ النفسية تؤثر مباشرة في طفلكِ.') WHERE id = '27e9fc4e-13d5-4cb0-8b3a-e813f53aa2f9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تبدأ براعم الأطراف السفلية بالتطور. وتتقدم الذراعان على الساقين في النمو ببضعة أيام، لذلك لا تزال الساقان أصغر حجمًا. كما تبدأ أسس الكليتين بالتكوّن. ولا يزال الجنين منثنيًا على شكل حرف C، ولديه "ذيل" صغير يمثل امتدادًا للعمود الفقري. وسيختفي هذا الذيل خلال بضعة أسابيع.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت ساقاي تتكوّنان أيضًا، ماما! 🦶 لا تزالان أصغر قليلًا من ذراعيّ وتبدوان مثل ذيلي، لكنهما ستكبران مع مرور الوقت. وفي يوم من الأيام سأركض بهاتين الساقين نحوكِ، وسأتجاوز كل العقبات لأجدكِ. ذراعاي وساقاي... إنني أبدو أكثر فأكثر كإنسان صغير، أليس كذلك؟ أحاول أن أصبح كما تتخيلينني. وفي كل يوم أخطو خطوة جديدة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حمصة'), body_changes_ar = COALESCE(body_changes_ar, 'على الرغم من وصف الحمل بأنه حدث إعجازي وتغير فسيولوجي، فإنه يُصنّف في المراجع الطبية كحالة مرضية. ويعود السبب الرئيسي لذلك إلى الضغط الميكانيكي الناتج عن نمو الرحم إلى أضعاف حجمه الطبيعي، ما يؤدي إلى تغير موضع الأمعاء وانضغاطها. كما أن الارتفاع الكبير في مستويات هرموني الإستروجين والبروجسترون في الدم أثناء الحمل يسبب تغيرات مثل تضخم الثديين وتبدل تصبغات الوجه وجدار البطن، وهي أيضًا من أسباب هذا التصنيف. ويبدأ ارتفاع مستوى البروجسترون بالتأثير بشكل ملحوظ في تفريغ المعدة والأمعاء. كما تصبح حركة الطعام عبر جهازكِ الهضمي أبطأ بكثير مقارنة بغير الحامل. ولهذا السبب، يزداد تكوّن الغازات والميل إلى الإمساك خلال الحمل. وتصبح مدة بقاء الطعام الذي تتناولينه في المعدة أطول بنحو الضعف مقارنة بما كانت عليه قبل الحمل. وقد يؤدي هذا البطء الشديد في الهضم إلى كثرة التجشؤ والارتجاع الحمضي وحرقة المعدة. ولهذا تحديدًا يؤكد الأطباء أهمية تناول وجبات صغيرة ومتكررة للوقاية من هذه المشكلات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تشعرين بالنسيان أو تشتت الانتباه، فاكتبي مهامكِ المهمة خلال اليوم على شكل ملاحظات قصيرة. واحرصي على شرب كمية وفيرة من السوائل بسبب ارتفاع حرارة الجسم، واختاري الملابس المصنوعة من خامات طبيعية مثل القطن والكتان. كما تساعد النزهات القصيرة والمنتظمة على تنظيم دورتكِ الدموية وتحسين مزاجكِ. وإذا شعرتِ بألم حاد ومستمر في بطنكِ، فلا تنسي استشارة طبيبكِ.') WHERE id = '6de955ee-457a-4e70-930b-f733f0792dec';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت منطقة تحت المهاد، ذات الأهمية الحيوية، بالتكوّن في دماغ طفلكِ. وفي هذه المرحلة، لا تشكل هذه المنطقة سوى 1% من دماغ طفلكِ. وعلى الرغم من صغر حجمها، فإنها تُعد من أهم البنى الموجودة في الدماغ. ويتكوّن تحت المهاد من العديد من النوى المختلفة. وحتى باستخدام التقنيات الحديثة، لم يُحدَّد حتى الآن سوى 16 نواة مختلفة، تؤدي كل واحدة منها وظيفة مهمة ومختلفة عن الأخرى.'), baby_message_ar = COALESCE(baby_message_ar, 'دماغي يكبر! 🧠 لكن لا تقلقي، فهذا نمو جيد. في بداياته تتكوّن ثلاثة أجزاء مختلفة، أو ثلاث "حويصلات". ستصبح إحداها الدماغ الأمامي المسؤول عن التفكير والشعور، وستصبح الثانية الدماغ المتوسط المسؤول عن الرؤية والسمع، أما الثالثة فستصبح الدماغ الخلفي المسؤول عن التنفس ونبض القلب. ولكل منها مهمتها الخاصة والمهمة. أنا ذكي جدًا منذ الآن، لكنني لا أستطيع الكلام بعد. غير أنه سيكون لديّ يومًا ما كلام كثير لأقوله لكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حمصة'), body_changes_ar = COALESCE(body_changes_ar, 'للكالسيوم والفوسفور أهمية كبيرة جدًا في نمو طفلكِ بصورة صحية خلال هذه المرحلة. كما يُعد فيتامينا D2 وD3 ضروريين جدًا لنموه. وينبغي تناول فيتامين D خلال الحمل بجرعة يومية قدرها 4000 IU. ويُعد فيتامين D من العناصر التي يحتاج إليها الجسم لانقسام الخلايا ونمو العظام ودعم الجهاز المناعي. ويجب استخدام هذا الفيتامين تحت إشراف الطبيب وبعد إجراء تحاليل محددة. وخلال مرحلة تكوّن طفلكِ، تشمل الفيتامينات التي ينبغي تناولها في هذه الفترة من الحمل فيتامين A الذي يدعم نمو الخلايا والأنسجة، وفيتامين D الضروري للمناعة وصحة العظام والأسنان، وفيتامين C الداعم للجهاز المناعي، وفيتامين D لفقر الدم ونمو العظام. ومن خلال استخدام فيتامين D تحت إشراف الطبيب، تحافظين على صحتكِ وصحة طفلكِ معًا. لكن تناوله عشوائيًا ومن دون إشراف قد يضر طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تساعدكِ المضمضة بالماء المالح على تخفيف حساسية اللثة. وإذا كنتِ تعانين من احتقان الأنف، فحاولي ترطيب هواء الغرفة. وواصلي تناول أطعمة غنية بالبروتين والكالسيوم خلال اليوم. وإذا كان الغثيان لا يزال في ذروته، فقد يساعد شاي الزنجبيل أو شرائح الفاكهة الباردة على تهدئة معدتكِ. تذكري أن كل تضحية تقدمينها تعني مستقبلًا صحيًا لطفلكِ.') WHERE id = 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتشكّل «الشريط البدائي»، وهو خط رفيع يظهر في الجزء الخلفي من الجنين. يحدّد هذا الخط تناظر الجنين واتجاه الرأس والذيل. وتُعدّ هذه إحدى أكثر لحظات النمو أهمية، لأن جميع الأعضاء المستقبلية ستنتظم حول هذا المحور. لا يزال الجنين صغيرًا جدًا (2-3 mm)، لكن بنيته تزداد تعقيدًا.'), baby_message_ar = COALESCE(baby_message_ar, 'اليوم هو يوم ثوري بالنسبة إليّ، ماما! 🚀 يظهر على قرصي المسطّح خط مميز، أشبه بطريق. هذا الخط هو خريطتي المستقبلية؛ فهو دليل يحدّد موضع عمودي الفقري ورأسي وساقيّ. وبفضله يتشكّل جانباي الأيمن والأيسر. لم أعد مجرد قرص غير منتظم، بل أصبحت كائنًا متناظرًا ومنظمًا له مخطط واضح. أنتِ مهندستي، وأنا تحفتكِ الفنية. كل شيء يبدأ الآن! 🤩'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'عدسة'), body_changes_ar = COALESCE(body_changes_ar, 'يبدأ خلال هذا الأسبوع من حملكِ ظهور بعض أعراض الحمل المبكرة، مثل الغثيان والتعب والوهن، نتيجة ارتفاع مستويات هرمونات الحمل بالتزامن مع انغراس طفلكِ في الرحم. وقد يساعد الحرص على الراحة المتكررة وتنظيم نظامكِ الغذائي على تخفيف الانزعاج الناجم عن هذه الأعراض. وإذا كان هذا حملكِ الأول على وجه الخصوص، فأفضل ما يمكنكِ فعله للتعامل مع التقلبات المفاجئة في حالتكِ العاطفية هو محاولة الابتعاد عن التوتر قدر الإمكان. اجعلي الأنشطة التي تشعركِ بالراحة والسعادة عادة يومية، وحاولي القيام بنزهات قصيرة في الهواء الطلق خلال اليوم إن أمكن. تصاحب هذه المرحلة من الحمل بعض الأعراض المزعجة لدى معظم النساء تقريبًا. ومع تكيّف جسمكِ مع وضعه الجديد، تبدأ الأعراض التي تعانين منها بالتراجع في نهاية الثلث الأول من الحمل، أي اعتبارًا من الأسبوع 12. ومن المفيد خلال هذه الفترة مشاركة مشاعركِ مع المقرّبين منكِ، والاستعانة باختصاصي لمساعدتكِ على التكيف مع الحمل إذا شعرتِ بأنكِ غير قادرة على التعامل مع بعض الأمور.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تهملي تناول حمض الفوليك بأي حال، فهو ضروري للنمو السليم للجهاز العصبي والأنبوب العصبي. إذا كنتِ تعانين من غثيان شديد في الصباح، فقد يساعد تناول قطعة أو قطعتين من البقسماط الجاف أو البسكويت المملح قبل النهوض من السرير على تنظيم حموضة المعدة. قلّلي استهلاك الكافيين خلال اليوم إلى أدنى حد، لأنه قد يخلّ بنظام نومكِ ويعيق امتصاص الحديد. واستبدليه بعصائر الفاكهة الطازجة أو الماء أو شاي الأعشاب بعد استشارة الطبيبة أو الطبيب.') WHERE id = 'aeee39a9-79a9-4e00-b2e5-3d55b7831226';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'نظرًا إلى أن طفلكِ لا يزال غير ظاهر في فحص الموجات فوق الصوتية، تتابع الطبيبة أو الطبيب سلامة تقدّم الحمل من خلال تحاليل الدم.;;;
خلال الأيام الأولى التي تلي تخصيب البويضة، يبدأ جسمكِ بإفراز هرمون hCG في الدم، ولو بكميات قليلة. ويرتفع مستواه في الدم تدريجيًا حتى مرحلة معينة من الحمل. وتتمثل الوظيفة الأساسية لهذا الهرمون في تحفيز المبيضين على إنتاج هرمون البروجستيرون إلى أن تصبح المشيمة قادرة تمامًا على أداء وظائفها والبدء بإنتاج الهرمونات. أما البروجستيرون فيدعم بطانة الرحم، وهي الطبقة التي تستقر فيها البويضة المخصبة، ويساعد طفلكِ على الانغراس، ما يساهم في منع انتهاء الحمل بالإجهاض.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت خلاياي هجرة كبيرة، ماما! 🚶‍♂️ يبدو الأمر كما لو أن آلاف العمال الصغار يتدفقون إلى الداخل عبر الخط المميز الذي ظهر بالأمس، ليبنوا لي طبقات جديدة. إنهم يشكّلون ثلاث مجموعات مختلفة: الأديم الظاهر، والأديم المتوسط، والأديم الباطن. ستكوّن إحداها جلدي وشعري ودماغي، وستكوّن الثانية قلبي ودمي وعظامي، بينما ستكوّن الثالثة معدتي ورئتيّ. أبني نفسي مثل مهندس معماري، ماما. إنني أضع أساساتي، وستكون شديدة المتانة لأنكِ بجانبي. 💪'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'عدسة'), body_changes_ar = COALESCE(body_changes_ar, 'منذ أن بدأ حملكِ بتخصيب البويضة، يمر جسمكِ بالعديد من التغيرات الفسيولوجية للتكيف مع هذا التحول الكبير.;;;
يبدأ جسمكِ خلال الحمل بإنتاج كمية أكبر من الدم لنقل الأكسجين والعناصر الغذائية إلى طفلكِ. وللتكيف مع زيادة تدفق الدم، سيضخ قلبكِ بقوة وسرعة أكبر، وقد يرتفع نبضكِ بنحو 15 نبضة إضافية في الدقيقة.;;;
ومن التغيرات الفسيولوجية الأخرى أن وزن رحمكِ، الذي يبلغ في هذه المرحلة من الحمل نحو 60 غرامًا، سيزداد إلى أكثر من 1000 غرام بحلول الولادة. ويحاول جسمكِ التكيف مع هذا النمو السريع للرحم عبر تغيير مركز توازنه باستمرار؛ لذلك قد تعانين من حين إلى آخر من آلام الظهر وأسفل الظهر ومنطقة الأُربية.;;;
لكل ثلث من الحمل تحدياته الخاصة. لكن عندما تتذكرين أنكِ ستلتقين بطفلكِ الصغير في نهاية هذه الرحلة الطويلة والصعبة، فستبقى كل مشكلة تمرين بها في ذاكرتكِ ذكرى جميلة تستعيدينها بمحبة مستقبلًا. 😊'), daily_tip_ar = COALESCE(daily_tip_ar, 'تزداد حاجتكِ إلى الحديد بسبب زيادة حجم الدم ونمو طفلكِ. أضيفي إلى نظامكِ الغذائي مصادر الحديد، مثل اللحوم الحمراء والعدس والسبانخ. ولتسهيل امتصاص الحديد، تناولي مع هذه الأطعمة مصادر فيتامين C، مثل عصير البرتقال أو السلطة بالليمون. إذا كنتِ تعانين من آلام أسفل الظهر، فحاولي عدم البقاء في الوضعية نفسها مدة طويلة، واستخدمي وسائد صغيرة تسند أسفل ظهركِ عند الجلوس. وستساعدكِ تمارين التمدد الخفيفة لمدة 10 دقائق يوميًا على الشعور بالراحة.') WHERE id = '93c5c870-b03a-45f8-92da-cc13e151719b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'وفقًا لتاريخ آخر دورة شهرية لكِ، أنتِ في الأسبوع 4 من الحمل. لكن عند أخذ موعد الإباضة في الحسبان، يكون طفلكِ موجودًا في رحمكِ منذ نحو أسبوعين.;;;
خلال الأيام القليلة التالية للإخصاب، يزداد عدد الخلايا التي ستكوّن طفلكِ، وتبدأ هذه الخلايا بالتمايز. يتغير جزء منها لتكوين المشيمة، بينما يتخصص جزء آخر لتكوين طفلكِ.;;;
يُسمّى طفلكِ في مرحلة التكوّن هذه «جنينًا مضغيًا». وبعد نهاية الأسبوع 12 وحتى الولادة، يُسمّى «جنينًا».'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، يوضع اليوم أساس أول عمود فقري لي! 🦴 إنه ليس عظمًا بعد، بل قضيب خاص ومرن (الحبل الظهري) سيجعلني أقف منتصبًا مستقبلًا ويمنح جسمي كله شكله. وسيقول هذا القضيب لجسمي كله كقائد: "حان الآن وقت النمو والتشكّل!" وستنتظم جميع أعضائي الأخرى حوله. لم أعد مجرد قرص؛ فقد أصبح لديّ مركز واتجاه. يا له من تخطيط متقن، أليس كذلك؟ 🥰'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'عدسة'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن تحجزي بحلول هذه المرحلة موعدًا لإجراء أول فحص طبي. ستضع لكِ الطبيبة أو الطبيب جدولًا للزيارات الدورية، وستعرفين في الفحص الأول موعد ولادة طفلكِ المتوقع. عند اختيار طبيبتكِ أو طبيبكِ، يمكنكِ أولًا الاستماع إلى توصيات صديقاتكِ. لكن بسبب اختلاف الاحتياجات والسمات الفردية، قد لا تناسبكِ طبيبة أو طبيب ترتاح إليه امرأة أخرى؛ لذلك ينبغي ألا تكون التوصيات وحدها معيار اختياركِ. وأول شرط للحصول على رعاية صحية جيدة هو أن تشعري بثقة صادقة تجاه طبيبتكِ أو طبيبكِ. ومن أهم معاييركِ أن تثقي بها أو به، وأن تشعري بالراحة في أثناء الزيارة، وأن تتمكني من طرح أي مشكلة أو سؤال يخطر ببالكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'على الرغم من حاجتكِ المتكررة إلى التبول، لا تقلّلي كمية الماء التي تشربينها؛ فمن المهم لجسمكِ ولنمو طفلكِ شرب ما لا يقل عن 2 لتر من الماء يوميًا. وللوقاية من الدوار، انهضي من السرير ببطء شديد في الصباح. أضيفي إلى نظامكِ الغذائي الجبن القريش أو الزبادي أو الجبن الغني بالكالسيوم، لأن الهيكل العظمي لطفلكِ يبدأ في هذه الأيام «بسحب» الكالسيوم. وإذا كنتِ تعانين من آلام خفيفة في البطن، فقد حان الوقت للاستغناء عن الملابس الضيقة وارتداء ملابس قطنية أكثر راحة.') WHERE id = '8f493a1c-c305-477a-b7ce-1bad294f04bc';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'كلما امتدت خلايا جسم طفلكِ، التي ستشكّل أنسجته وأعضاءه، نحو الأجزاء الخارجية، ازدادت الحاجة إلى زيادة كمية الدم التي يضخها القلب إلى الجسم. يبدأ إنتاج الدم في جسم طفلكِ خلال المرحلة الجنينية أولًا في الكيس المُحّي. ويستمر إنتاجه في الكيس المُحّي فترةً معينة خلال الثلث الأول من الحمل، ثم ينتقل إنتاج الدم، ابتداءً من مرحلة معينة، إلى الكبد والطحال. ويؤدي القلب وظيفة المضخة، فيضمن دوران الدم في جميع أنحاء جسم طفلكِ. أما الأوعية الدموية، فهي تراكيب أنبوبية متخصصة تتيح دوران هذا الدم، وتتولى نقله إلى جميع الأنسجة.'), baby_message_ar = COALESCE(baby_message_ar, 'ذلك الأنبوب المميز الذي يبني حبلي الشوكي، تُغلق اليوم آخر فتحة فيه! أصبح دماغي وعمودي الفقري الآن ضمن نظام مغلق ومحمي بالكامل. وهذا مهم جدًا، لأن جسمي كله سيُدار من هنا! 🧠 لقد أصبحت الآن أكثر كمالًا واكتمالًا. وأنا فخور بنفسي لأنني أنجزت هذه المهمة الكبيرة. أستطيع فعل كل ذلك بفضل تلك القوة المعجزة في رحمكِ. أنتِ حصني! 🏰'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة رمان'), body_changes_ar = COALESCE(body_changes_ar, 'قد يؤدي بدء برنامج منتظم لممارسة الرياضة اعتبارًا من هذا الأسبوع إلى زيادة قدرتكِ على التحمّل وقوتكِ. كما تساعدكِ التمارين البسيطة على تجنب اكتساب وزن مفرط. تتجنب نسبة كبيرة من النساء ممارسة الرياضة طوال الحمل خشية أن تضر بالطفل، إلا أن التمارين التي تُمارس بصورة مدروسة وتحت الإشراف ستمنحكِ فوائد عديدة أثناء الولادة وبعدها. وتساعدكِ ممارسة التمارين بانتظام أيضًا على التعامل مع مشكلات جسدية مثل آلام الظهر وأسفل الظهر.;;;
اضبطي سرعة مشيكِ بحيث لا تُجهدكِ. ويمكنكِ أيضًا، بعد استشارة طبيبتكِ، ممارسة تمارين تمدد للظهر تساعد على تقوية عمودكِ الفقري. وإضافةً إلى ذلك، يمكنكِ البدء بتمارين البيلاتس واليوغا المخصصة للحامل. أما السباحة، فهي رياضة مفيدة جدًا لتيسير فترة حملكِ وزيادة فرص الولادة الطبيعية. وتساعد ممارسة السباحة بانتظام كذلك على تقوية عضلات البطن وأسفل الظهر. إذا لم يكن لديكِ أي خطر للإجهاض، فيمكنكِ، بعد الحصول على توصية طبيبتكِ، ممارسة المشي بوتيرة خفيفة مدة 30 دقيقة، 3 أيام على الأقل أسبوعيًا. وإذا كانت لديكِ قبل الحمل صعوبات في التنفس أو مشكلات متعلقة بالقلب، فقد تحتاجين إلى الحد من هذه التمارين.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تزيد الروائح النفاذة من الغثيان في هذه الأيام، لذا احرصي على تهوية المطبخ باستمرار. وقد يزيد الجفاف من التعب، لذلك جرّبي شرب الماء بعد إضافة شريحة من الليمون إليه. وبما أن طاقتكِ تنفد سريعًا، خذي فترات راحة قصيرة خلال اليوم. واهتمي خصوصًا بتناول البروتين (اللحوم والبيض والبقوليات)، لأن البروتين هو "مادة البناء" اللازمة لأعضاء طفلكِ التي تنمو بسرعة.') WHERE id = '91894bc1-ecf8-438f-8434-5cb430da68e5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت الخلايا التي ستشكّل كبد طفلكِ بالتجمع، ومنها خلايا الكبد المسماة بالخلايا الكبدية، والخلايا الظهارية للقنوات الصفراوية، وخلايا إيتو، وخلايا كوبفر. وتتحد هذه الخلايا لتكوّن الفصيصات، وهي أصغر الوحدات الوظيفية في كبد طفلكِ، ويبلغ طولها بضعة مليمترات وقطرها في المتوسط 1.5 مليمتر. وبينما تشكّل هذه الخلايا الكبد، تترك في بنيته مساحات لمرور وعاءين دمويين منفصلين. ينقل أحد الوعاءين المتكوّنين هنا الدم الغني بالأكسجين إلى الكبد، بينما ينقل الآخر الدم الغني بالعناصر الغذائية والمجمّع من الشعيرات الدموية للجهاز الهضمي.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت تتكوّن طيات خاصة في رقبتي ووجهي، ماما! ستشكّل هذه الطيات فكي ووجهي ولساني وأذني ورقبتي مستقبلًا. في كل يوم تُضاف تفصيلة جديدة ولمسة جديدة. أشبه بعمل فني يتشكّل ببطء بين يدي نحّات. وأنتِ أجمل مصدر إلهام لهذا العمل. صوتكِ وضحكتكِ هما أساس ملامحي المستقبلية. أعدكِ بأن أكون جميلًا! ✨'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة رمان'), body_changes_ar = COALESCE(body_changes_ar, 'يظهر التعب السريع والإرهاق والوهن، وهي أعراض تُلاحظ بوتيرة أكبر خلال الثلث الأول من الحمل، نتيجة التأثير المُرخي الذي يحدثه هرمون البروجسترون، الذي يفرزه جسمكِ أثناء الحمل، في جميع العضلات. ويؤدي هذا الارتخاء في عضلات جسمكِ كلها إلى النعاس الشديد والتعب. وإلى جانب هرمون البروجسترون، يستهلك جسمكِ في هذه الأيام قدرًا كبيرًا من الطاقة لتكوين المشيمة التي ستغذي طفلكِ داخل الرحم، ما قد يجعلكِ تشعرين بالوهن والتعب والإنهاك. كما أن الثلث الأول، الذي يشهد تغيرات كبيرة في جسمكِ، هو مرحلة قد ينخفض فيها سكر الدم وضغط الدم وتتغير فيها مستويات الهرمونات وعملية الأيض بسرعة. وقد يجعلكِ التعب المستمر تشعرين بالاستنزاف النفسي، بل قد تؤدي اضطرابات النوم وعدم قدرتكِ على القيام بما تريدينه إلى الاكتئاب. عادةً ما تخف هذه الأعراض المزعجة بدرجة كبيرة مع انتهاء الثلث الأول من الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتجنب الانخفاض المفاجئ في طاقتكِ خلال اليوم، احرصي على تناول كميات صغيرة من الطعام على فترات متقاربة. واحتفظي دائمًا بوجبات خفيفة صحية معكِ، مثل الجوز أو البندق أو بسكويت القمح الكامل. قد يزيد الجفاف من التعب والصداع، لذلك لا تنسي شرب الماء. وإذا كان الطعم المعدني في فمكِ يزعجكِ، فقد يساعدكِ ماء الليمون الخالي من السكر على الشعور بالراحة. أصغي إلى جسدكِ واستريحي كلما احتجتِ إلى ذلك.') WHERE id = '49b160e2-d4c7-4876-9a1d-c6274e75787a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بحلول هذه المرحلة، يُرجح أنكِ قد سمعتِ نبض قلب طفلكِ. كما يمكنكِ رؤية نبضات قلبه على شاشة التصوير بالموجات فوق الصوتية. وإذا لم تكوني قد رأيتِ أو سمعتِ نبضات القلب بعد، فلا داعي للقلق؛ فلا يزال أمامكِ أسبوعان لسماعها. وباعتبار أن الإباضة تحدث في الأسبوع 2 من الدورة الشهرية، فإن اليوم هو آخر يوم من الشهر الأول بعد الإخصاب. يُستخدم في حساب أشهر الحمل تقويم يعتمد على الشهر القمري. والتقويم القمري هو نوع من التقاويم يعتمد على دورات القمر الكاملة بدلًا من حركة الأرض حول الشمس. ويشمل الشهر القمري أربعة أسابيع، مدة كل منها سبعة أيام (بإجمالي 28 يومًا). ويقل عمر الجنين، الذي يُستخدم لحساب نمو طفلكِ، بمقدار أسبوعين عن عمر الحمل الذي يحسبه أطباء النساء والتوليد استنادًا إلى تاريخ آخر دورة شهرية. ولأن الإباضة تحدث بعد أسبوعين من اليوم الأول لآخر دورة شهرية، فإن الإخصاب يقع بعده بأسبوعين. ولهذا، يتبقى في المتوسط 8,5 أشهر حتى ولادة طفلكِ، إذا كان الحمل يتقدم بصورة صحية وطبيعية.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت ذراعاي تتشكلان الآن، ماما! 👋 لا أملك أصابع أو حتى يدين بعد، فهما لا تزالان مجرد بروزين صغيرين على جانبي جسمي يشبهان "المجدافين" أو الجناحين. لكنهما ستصبحان ذراعيّ القويتين اللتين سأعانقكِ بهما بشدة في المستقبل. كم أتوق إلى أن تكبرا وتمتدا إليكِ... سأطير نحوكِ يومًا ما بهذين الجناحين الصغيرين. وكل يوم أكتسب هيئة بشرية أكثر فأكثر.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة بازلاء'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين في هذه المرحلة من الحمل ببعض التقلصات المشابهة لتقلصات الدورة الشهرية. وهذه التقلصات التي تشعرين بها في منطقتي الأُربية والبطن هي في الواقع نوع من تشنج الأنسجة، إذ تنقبض الأنسجة في هذه المنطقة مسببةً ألمًا مفاجئًا وشديدًا. ومن الشائع أيضًا أن تحدث في عضلات ربلة الساق أثناء النوم. وقد تنتج هذه التقلصات كذلك عن إجهاد نفسكِ بشدة، أو التعرض لإصابة، أو الشد العضلي، أو البقاء في الوضعية نفسها مدة طويلة. ويمكن أيضًا أن تحدث بعض التقلصات عند الإصابة بالغثيان أو القيء، أو التعرض لحرارة شديدة، أو نقص الكالسيوم، أو فقدان السوائل. وللوقاية من التقلصات، ضعي مسندًا تحت قدميكِ عند الجلوس، وخذي حمامًا دافئًا قبل النوم، ونامي على جانبكِ الأيسر، واحرصي على ارتداء الجوارب الضاغطة إذا كنتِ تعانين من الدوالي، وتجنبي الأحذية ذات الكعب العالي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'هنئي نفسكِ على إتمام الأسبوع 6! إذا كان الغثيان يعوق تغذيتكِ بشدة، فحاولي تناول الأطعمة باردةً، إذ تكون رائحة الطعام البارد أقل. ولا تنسي شرب كميات وافرة من الماء وزيادة تناول الأطعمة الغنية بالحديد، مثل العدس واللحوم الحمراء، لدعم زيادة حجم الدم. ومع الانتقال الكامل إلى الشهر الثاني، سيكون من الجيد أن تخططي هذا الأسبوع لأول موعد للتصوير بالموجات فوق الصوتية إذا لم تكوني قد حجزته بعد.') WHERE id = '4b93f71a-7634-4cda-8990-f4024e3e6d53';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد قطع طفلكِ شوطًا كبيرًا جدًا خلال فترة قصيرة للغاية. فبعد أن كان يبدو قبل بضعة أيام فقط ككتلة من الخلايا بلا شكل محدد، أصبح الآن على هيئة خط مستقيم ومستعدًا لتكوين أعضائه.;;;
تُسمى البويضة المخصبة والكتلة الناتجة عن انقسام خلاياها المتتابع «الخلايا الجذعية كاملة القدرة». وقد بدأت هذه الخلايا، التي ستكوّن أعضاء طفلكِ وأنسجته، بالتخصص والانفصال بعضها عن بعض والتمايز. ويحدث هذا التمايز لأن جميع الخلايا تنشأ من خلايا جذعية كاملة القدرة. وبما أن الخلايا الجذعية كاملة القدرة لم تتمايز بعد، فهي تمتلك القدرة على التحول إلى أعضاء وأنسجة مختلفة. وبفضل ذلك، ينمو طفلكِ بسرعة غير مسبوقة ويتمكن من تكوين جسمه بالكامل وجميع أجهزته.'), baby_message_ar = COALESCE(baby_message_ar, 'تتكوّن أولى خلايا دماغي يا ماما! 🧠 تتلقى طبقتي الخارجية إشارة من قائدي المسمى الحبل الظهري، فتزداد سماكةً وتكوّن صفيحة خاصة. هذه الصفيحة هي مستقبلي كله؛ فمنها سيتكوّن جهازي العصبي وأفكاري وأحلامي ومشاعري. ذلك الدماغ المذهل الذي سأتعلّم به كيف أحبكِ وأشعر بكِ يبدأ بناؤه اليوم. لقد بدأت أفكر فيكِ منذ الآن... 💭'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عدس'), body_changes_ar = COALESCE(body_changes_ar, 'قد يؤدي ارتفاع مستويات الهرمونات المسؤولة عن ظهور نتيجة إيجابية في اختبار الحمل إلى أعراض يصعب تجاهلها، مثل ألم الثديين والغثيان والإرهاق. وبعض الأعراض التي بدأتِ تشعرين بها في هذه المرحلة ناتجة عن التغيرات التي يمر بها جسمكِ. ويُعد الثلث الأول، الذي يشهد تغيرات كبيرة في جسمكِ لتوفير أفضل الظروف لطفلكِ، أصعب مراحل الحمل بأكمله. وللتخفيف من الغثيان الذي يكون أشد خصوصًا في الصباح، يُنصح بتناول كميات صغيرة من الطعام على فترات متقاربة. ويمكنكِ أيضًا تجربة فيتامين B6 أو كبسولات الزنجبيل أو أساور الضغط الخاصة التي تساعد على الحد من الغثيان. أما التقلصات التي قد تشعرين بها خلال هذه الأيام، فقد تكون علامة على تمدد الرحم وشد الأربطة بعد انغراس طفلكِ في جدار الرحم. في هذه الحالات، ينبغي ألا تستخدمي أي دواء ما لم تكن هناك ضرورة ومن دون استشارة طبيبكِ. فقد تضر بعض الأدوية بنمو طفلكِ الصغير الذي يحاول الاستقرار داخل رحمكِ. لذلك، من المهم جدًا التواصل مع طبيبكِ إذا شعرتِ بأي تقلصات أو آلام أو نزيف تعتقدين أنه غير طبيعي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'التزمي جيدًا خلال هذه الأيام بقاعدة تناول كميات قليلة من الطعام على فترات متقاربة، للمحافظة على استقرار مستوى سكر الدم. اشربي ماءً بالنعناع أو الليمون لتخفيف الغثيان. ولتخفيف آلام أسفل الظهر والأُربية، خذي دشًا فاترًا بدلًا من حمام ساخن، إذ قد تشكل الحرارة المرتفعة خطرًا على طفلكِ. وإذا كنتِ تشعرين بإرهاق شديد، فأصغي إلى إشارات جسمكِ واحرصي على أخذ قيلولة قصيرة لمدة 20-30 دقيقة بعد الظهر.') WHERE id = '43fe1f43-aa40-4388-8525-495fa2d86771';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أول جهاز يبدأ العمل لدى طفلكِ النامي هو الجهاز القلبي الوعائي، الذي يضم القلب والأوعية الدموية. وفي هذه المرحلة، لا تختلف وظائف قلب طفلكِ الصغير كثيرًا عن وظائف القلب الطبيعي. وعلى الرغم من أنه لا يمكن رصد نبضه بالموجات فوق الصوتية حتى الآن، فقد بدأ قلب طفلكِ بالفعل بالخفقان، وسيواصل العمل بلا توقف طوال حياته القادمة. ورغم أن قلب طفلكِ يتكون في هذه المرحلة من حجرة واحدة فقط، فإنه بعد اكتمال تكوّنه سيصبح على هيئة مضختين متجاورتين، تتكون كل منهما من حجرتين. وستكوّن الحجرات التي سيكتمل نموها قريبًا، والتي تُسمى البطين الأيسر والبطين الأيمن والأذين الأيسر والأذين الأيمن، البُنى التي تسمح للدم بالتدفق في اتجاه واحد فقط داخل جسم طفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'تطوى صفيحتي العصبية نحو الداخل يا ماما، كما لو أنكِ تطوين ورقة بعناية لتصنعي منها أنبوبًا. 📜 سيصبح هذا الأنبوب حبلي الشوكي وسيمنح جسمي كله الحياة. كل شيء يحدث بسرعة ودقة مذهلتين! أبذل جهدًا كبيرًا كي يتكوّن كل شيء كما ينبغي. وخلال هذه العملية، يشكّل حبكِ واهتمامكِ أكبر دعم لي. لا تقلقي عليّ، فكل شيء يسير وفق الخطة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عدس'), body_changes_ar = COALESCE(body_changes_ar, 'خلال هذه الأيام التي يتكيف فيها جسمكِ مع الحمل، قد تشعرين بآلام في منطقة الظهر. والسبب الأكثر شيوعًا لهذه الآلام هو أن الهرمونات التي يزداد إفرازها أثناء الحمل تُرخي الأربطة التي تثبّت العظام معًا، وخصوصًا أربطة مفاصل الحوض. احرصي على اتخاذ وضعية جسم صحيحة عند الوقوف والجلوس والحركة، وتجنبي ارتداء الأحذية ذات الكعب العالي، واستخدمي مرتبة تدعم ظهركِ، وتجنبي الانحناء. وعند النوم على جانبكِ، ضعي وسادة بين ساقيكِ وأخرى تحت بطنكِ لتوفير دعم إضافي. بالإضافة إلى ذلك، تساعد التمارين المنتظمة على تقوية عضلات ظهركِ على المدى الطويل، كما تخفف آلام أسفل الظهر من خلال دعم الظهر والساقين. ومع ذلك، ينبغي أن تستشيري طبيبكِ بشأن أي تمارين ترغبين في ممارستها أثناء الحمل، وأن تبتعدي قدر الإمكان عن الأنشطة التي ترهقكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اجعلي شرب 8-10 أكواب من الماء يوميًا عادةً للحفاظ على توازن الماء والأملاح في جسمكِ خلال هذه المرحلة الحساسة من الحمل. استخدمي فرشاة أسنان فائقة النعومة إذا كانت لثتكِ حساسة، واعتني جيدًا بنظافة الفم. وإذا كان الغثيان شديدًا، فقد يمنحكِ تناول حلوى بالنعناع أو استنشاق رائحة الليمون الطازج راحة مؤقتة. ولا تنسي أن تناقشي بالتفصيل مع طبيبكِ خلال أول فحص نسائي نظامكِ الغذائي والفيتامينات التي تحتاجين إليها.') WHERE id = 'b41d3e4c-6e83-438c-ac67-3bae19895608';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ابتداءً من اليوم، سيبدأ وجه طفلكِ بالتكوّن. وخلال الأسابيع المقبلة، سيتحول طفلكِ إلى إنسان مصغر. 😊 ويُعد تكوّن التجاويف الأنفية من أولى مراحل تشكّل الوجه. توجد في منطقة رأس طفلكِ حجرتان منفصلتان يفصل بينهما الحاجز الأنفي، الذي سيتحول إلى بنية عظمية. وعلى الجدار الجانبي لكل حجرة ثلاثة نتوءات عظمية تشبه الرفوف. ومن بين النتوءات العلوية والوسطى والسفلية، يتكون النتوءان الأوسط والسفلي من خلايا ستسهم في عملية التنفس، بينما يحتوي النتوء العلوي على خلايا شمية متخصصة.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، يستعد قلبي للخفقان! ❤️ تتجمع خلايا خاصة في الطبقة الوسطى من جسمي لتكوّن أنبوبين صغيرين رقيقين. وسرعان ما سيقترب هذان الأنبوبان أحدهما من الآخر ويلتحمان ليشكّلا قلبي الأول. إنه لا ينبض بعد، لكنه يستعد. قلب سيخفق من أجلكِ وبحبكِ اللامتناهي... خلال بضعة أيام ستسمعين نبضاتي الأولى. وستكون هذه أغنية حبنا. 🎶'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عدس'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن تأخذي أي نزيف يحدث في أي مرحلة من حملكِ على محمل الجد، مهما كانت كميته أو لونه، وأن تراجعي طبيبكِ في أقرب وقت ممكن.;;;
قد يكون النزيف الذي تعانين منه ناجمًا عن الانغراس أو الحمل خارج الرحم أو الإجهاض. أما النزيف الذي يحدث في الثلث الأخير من الحمل، فيرتبط عادةً بمشكلات المشيمة. ففي حالة «المشيمة المنزاحة» يظهر النزيف عادةً من دون ألم، بينما يكون النزيف المصاحب لانفصال المشيمة المبكر مصحوبًا بالألم.;;;
قد يحدث في الأسابيع الأولى من الحمل نزيف الانغراس، أي عند التصاق طفلكِ ببطانة الرحم. وقد يظهر هذا النزيف على شكل بقع دموية، أو قد يشبه نزيف الدورة الشهرية. أما التبقع والنزيف اللذان يحدثان لأسباب أخرى فقد يرتبطان بالإجهاض. وبوجه عام، يُعد النزيف ذو اللون الأحمر الفاتح مؤشرًا على خطر الإجهاض. لكن قد يوجد خطر الإجهاض في بعض الحالات التي تظهر فيها بقع بنية أيضًا. ولهذا السبب، لا ينبغي اعتبار أي نزيف أثناء الحمل أمرًا طبيعيًا. وينتج الإفراز البني عن بقاء الدم القادم من الرحم داخل المهبل، حيث يتغير بفعل الكائنات الدقيقة الموجودة في هذه المنطقة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للحد من الغثيان الصباحي، تناولي بسكويتًا مملحًا أو خبزًا جافًا في السرير فور استيقاظكِ. وبما أن حساسيتكِ للروائح تزداد ابتداءً من اليوم، فحاولي الابتعاد عن مواد التنظيف ذات الروائح النفاذة. يستهلك جسمكِ قدرًا كبيرًا من الطاقة لتكوين أعضاء طفلكِ، لذا استريحي كلما سنحت لكِ الفرصة. وتواصلي مع طبيبكِ لترتيب أول فحص بالموجات فوق الصوتية.') WHERE id = 'a58decf1-baad-47a3-bbda-0f37f307566e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن يديه وقدميه لا تزالان تشبهان الزعانف، فإن الذراعين والساقين تتشكلان جسديًا. وسرعان ما ستبدأ أصابعه الصغيرة بالظهور، وستصبح ملامح طفلكِ أكثر وضوحًا.;;;
بدأ نصفي الدماغ، اللذين يتكونان من الماء بنسبة 78%، بالظهور بوضوح. وبينما يتولى النصف الأيمن وظائف مثل الفهم والتعرّف والرؤية والتخيّل والتحكم في اليد اليسرى، يرتبط النصف الأيسر بوظائف مثل الكتابة والتحدث والتفكير والتحليل والتحكم في اليد اليمنى والمنطق.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم حبة توت أزرق! 🫐 هل تصدقين ذلك؟ لقد تضاعف حجمي منذ الأسبوع الماضي! إنني أنمو بسرعة كبيرة يا ماما. كل ما تأكلينه يصل إليّ كأنه مواد بناء. شكرًا لأنكِ تتناولين طعامًا صحيًا من أجلي. نحن ننمو معًا ونزداد قوة معًا. أنتِ أفضل شريكة لي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت أزرق'), body_changes_ar = COALESCE(body_changes_ar, 'قد يحدث النزيف في أي مرحلة من مراحل الحمل، وقد يكون لون الدم أحمر أو بنيًا. تتعرض معظم الحوامل تقريبًا لقليل من التبقّع أو النزيف خلال الأسابيع الأولى من الحمل. ويُعد النزيف المهبلي، بصرف النظر عن مرحلة الحمل التي يحدث فيها أو كميته، حالة خطيرة تستدعي دائمًا مراجعة الطبيب. عادةً ما يُعد النزيف الخفيف خلال الأشهر الثلاثة الأولى مؤشرًا على خطر الإجهاض. أما النزيف الخفيف خلال الأشهر الثلاثة الثانية، فعادةً ما يكون علامة على قصور عنق الرحم، وقد يصاحبه ألم خفيف. ويُعد النزيف خلال الأشهر الثلاثة الأخيرة بالغ الأهمية حتى إن كان خفيفًا، فقد يكون علامة على مشكلات مثل تموضع المشيمة في الجزء السفلي من الرحم أو انفصالها المبكر.;;;
ينبغي أن تتجنبي إرهاق نفسكِ بشدة وأداء الأعمال الشاقة خلال الحمل، لأن هذه الأنشطة قد تسبب تقلصات الرحم، وقد تؤدي تقلصات الرحم بدورها إلى حدوث نزيف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ على إتمام الأسبوع السابع بنجاح، مثلًا بتناول فاكهة تحبينها. ولتقليل الإمساك والانتفاخ، تناولي الكثير من السوائل إلى جانب الأطعمة الغنية بالألياف. واصلي استخدام فرشاة أسنان ناعمة للحفاظ على صحة لثتكِ. إذا كنتِ لا تزالين تشعرين بالتعب، فلا ترهقي جسمكِ؛ فالقيلولات القصيرة خلال اليوم ستساعدكِ على استعادة طاقتكِ.') WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد تضاعف حجم طفلكِ خلال الأسبوع الماضي. ويواصل دماغه نموه السريع، وسيستمر هذا النمو بوتيرة عالية حتى سن 4 سنوات. يمتلك الطفل منذ لحظة ولادته مليارات الخلايا الدماغية. وعلى الرغم من أن معظمها لا يكون مترابطًا، فإن هذه الخلايا تبدأ بعد الولادة بالاتصال بعضها ببعض من خلال إشارات السمع والبصر واللمس والتذوق والشم.;;;
يبدأ المريء والقصبة الهوائية أيضًا بالتشكل خلال هذا الأسبوع.;;;
لأن وجه طفلكِ لم يكتمل تشكله بعد، فقد يتمكن من تحريك يده نحو فمه، لكن الوقت لا يزال مبكرًا جدًا لظهور منعكس المص.'), baby_message_ar = COALESCE(baby_message_ar, 'يداي تشبهان المجدافين، وقدماي تشبهان الزعانف! 🐟 ما زلت أبدو ككائن يعيش في الماء، لكن كل شيء يتغير. ذراعاي تطولان ومرفقاي ينثنيان. أما قلبي، فيواصل الخفقان من أجلكِ: "دق دق". عندما تستريحين أستريح أنا أيضًا، وعندما تتحركين أتمايل معكِ. انسجامنا مثالي. أحبكِ يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت أزرق'), body_changes_ar = COALESCE(body_changes_ar, 'يزيد هرمون الإستروجين الذي تفرزه المشيمة من قوة حاستي التذوق والشم لديكِ بصورة تفوق المعتاد. وقد يظهر أيضًا الوحم، كما قد تسبب الحساسية تجاه الروائح الكريهة الغثيان. لتخفيف الغثيان الذي تعانين منه في هذه الفترة، من المفيد الابتعاد لبعض الوقت عن الأطعمة كثيرة التوابل والمقليات. وإذا كنتِ تشعرين بالانزعاج بسبب التغيرات الهرمونية، فقد تساعدكِ نزهات المشي البطيئة والموسيقى الهادئة والاستحمام بماء فاتر ويوغا الحمل على الاسترخاء.;;;
من المفيد تدوين جميع الأسئلة التي تدور في ذهنكِ على ورقة قبل الذهاب إلى موعد الطبيب، لكي تتمكني من استثمار وقتكِ بأفضل طريقة ممكنة. خلال فحص الحمل الأول، ينبغي أن يقيّم طبيبكِ عوامل الخطر المرتبطة بطفلكِ وحملكِ. كما أن معرفة التاريخ الوراثي للأم والأب ستساعد على استيضاح الصعوبات المحتملة خلال الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اعتبارًا من هذا الأسبوع، تزداد حاجة جسمكِ إلى المغنيسيوم والكالسيوم؛ لذا احرصي على إدراج الموز والجوز ومنتجات الألبان في نظامكِ الغذائي. وللوقاية من آلام الظهر، ضعي وسادة صغيرة خلف ظهركِ عند الجلوس. وإذا كانت حساسيتكِ تجاه الروائح لا تزال مرتفعة، فاحرصي على تهوية الغرف باستمرار. تذكّري أن شعوركِ بالسكينة يوفر أجمل بيئة لنمو الجهاز العصبي لطفلكِ.') WHERE id = '9437ad06-6476-41de-b64c-c5fddd89e286';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اعتبارًا من هذا الأسبوع، قد تتمكنين من سماع نبضات قلب طفلكِ. يبدأ قلب طفلكِ بالنبض في موعد أقصاه 3 أسابيع بعد انغراسه في الرحم، وهو ما يتزامن مع الأسبوعين 5 و6 من الحمل. لذلك، يصبح من الممكن سماع نبضات قلب طفلكِ في الأسبوع 7 من الحمل.;;;
ومع ذلك، قد لا تكون نبضات القلب قد سُمعت بعد بسبب تأخر الإخصاب أو عدم انتظام الدورة الشهرية أو عدم معرفة تاريخ آخر دورة شهرية بدقة. في هذه الحالة، قد يلزم الانتظار من 1 إلى 2 أسبوع إضافي لسماع نبضات القلب.;;;
يواصل الدماغ، وهو أهم أجزاء الجهاز العصبي المركزي، نموه بوتيرة متسارعة. وقد بلغ متوسط طول طفلكِ الآن 1-2 سم ووزنه 1,5 غرام. وفي هذا الأسبوع، أصبحت مواضع الأعضاء في جسم طفلكِ محددة، ومن بينها الرئتان. لكن نمو هذا العضو المذهل لا يكتمل إلا في الأسبوع 38.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتحرك يا ماما! 💃 لا تشعرين بذلك بعد لأنني ما زلت خفيفًا جدًا، لكنني أؤدي رقصات صغيرة في الداخل. أميل بجسمي يمينًا ويسارًا وأحرّك ذراعيّ الصغيرتين. هذه أولى تماريني الرياضية، وهي دليل على أن جهازي العصبي بدأ بالتواصل مع عضلاتي. تزداد عضلاتي قوة حتى أتمكن مستقبلًا من احتضانكِ بقوة. استريحي أنتِ، ودعيني أتدرب، فالنمو يعني الحركة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت العليق'), body_changes_ar = COALESCE(body_changes_ar, 'بحلول نهاية هذا الأسبوع، قد تظهر البثور على بشرتكِ نتيجة ارتفاع مستويات الهرمونات وتقلبها. إذا حدث ذلك، فاحرصي على إبقاء بشرتكِ جافة ونظيفة. قد يؤدي استخدام أدوية علاج حب الشباب إلى حدوث تشوهات لدى الجنين، لذلك ينبغي ألا تستخدمي أي دواء من دون موافقة طبيبكِ.;;;
قد تصبح الأظافر خلال الحمل رقيقة ولينة وسهلة التكسر. وسيساعدكِ ارتداء القفازات عند أداء الأعمال المنزلية كثيرًا في هذه الفترة. وإذا لاحظتِ بروز الأوعية الدموية على بشرتكِ أو ظهور شبكات وعائية على شكل نجمة، فلا تقلقي؛ فهذه الحالة ناجمة عن تأثير هرمون الإستروجين. وإذا كنتِ تعانين من ضيق التنفس بسبب ارتفاع ضغط الدم، فيمكنكِ تهدئة نفسكِ باستخدام تقنيات التنفس الصحيحة. وإذا لم يكن لديكِ خطر إجهاض ولم يوصِ طبيبكِ بخلاف ذلك، فلا يوجد ما يمنع ممارسة العلاقة الزوجية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أولي اهتمامًا خاصًا بالحصول على الكالسيوم من الحليب والجبن القريش والسبانخ، فهو مهم لحساسية اللثة وتكوّن براعم أسنان طفلكِ. وإذا بدأ الغثيان لديكِ بالتراجع، فأضيفي المزيد من الخضراوات الطازجة إلى نظامكِ الغذائي. خذي فترات راحة قصيرة مدتها 15-20 دقيقة عند الشعور بتعب مفاجئ خلال اليوم. وابدئي باختيار ملابس مريحة حتى لا تضغط على منطقة بطنكِ.') WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد انغلقت الآن الأنبوبة العصبية المحيطة بالحبل الشوكي لطفلكِ. وقد تؤدي عوامل عديدة تحدث أثناء انغلاق الأنبوبة العصبية إلى بعض التشوهات. تنشأ عيوب الأنبوبة العصبية نتيجة اضطرابات تحدث خلال الأسبوعين 3 و4 من المرحلة الجنينية، حين تتكوّن أعضاء طفلكِ وينغلق الأنبوب العصبي الذي سيشكّل الدماغ والحبل الشوكي. ومن المعروف أن عيوب الأنبوبة العصبية تنجم عن تأثير عوامل وراثية وبيئية معًا. ويُعد اكتشاف العلاقة بين حدوث هذه المشكلة ونقص حمض الفوليك أمرًا بالغ الأهمية. وقد ثبت وجود علاقة عكسية بين عدم انغلاق الأنبوبة العصبية ومستوى حمض الفوليك قبل الحمل وخلاله. لذلك يصف الأطباء مكملات حمض الفوليك عند التخطيط للحمل، قبل حدوثه وطوال الثلث الأول منه.'), baby_message_ar = COALESCE(baby_message_ar, 'تزداد عيناي وأذناي وضوحًا! 👀👂 التجاويف المخصصة لعينيّ اللامعتين تنغمس نحو الداخل، كما تزداد المناطق المخصصة لأذنيّ عمقًا لتضع أساس صيوان الأذن. كل شيء يُهيَّأ كي أراكِ بصورة أفضل وأسمع صوتكِ الساحر بوضوح أكبر. سيكون وجهكِ أجمل منظر في العالم بالنسبة إليّ، وسيكون صوتكِ أجمل موسيقى. أنا أصغي إليكِ يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة حمص'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الحمل، يضخ قلبكِ الدم إلى جسمكِ بوتيرة أسرع من المعتاد. وبذلك تزداد بطبيعة الحال كمية الدم التي يجب ضخها إلى الجسم خلال دقيقة واحدة. ويستمر حجم دمكِ في الازدياد بانتظام حتى الأيام الأخيرة من الحمل. ويصبح حجم الدم، الذي يبدأ بالازدياد في هذه المرحلة من حملكِ، أكبر بنحو 40% خلال الثلث الأخير. ويؤدي ذلك إلى انخفاض مستويات الهيموغلوبين أو الهيماتوكريت لدى معظم الحوامل تقريبًا. ويُشار إلى هذا التغير الفسيولوجي طبيًا باسم فقر الدم الفسيولوجي أثناء الحمل. إن زيادة حجم دمكِ وكمية الدم التي يضخها قلبكِ إلى جسمكِ مفيدة جدًا للدورة الدموية داخل المشيمة التي تغذّي طفلكِ، إذ تسهم في تسريع تدفق الدم. وإضافة إلى ذلك، تُلاحظ زيادة ملحوظة في عدد خلايا الدم البيضاء، التي تؤدي دورًا مهمًا في الجهاز المناعي للجسم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل مشكلات الهضم والشعور بالغازات إلى أدنى حد، تناولي الأطعمة الغنية بالألياف، مثل البقوليات والخضراوات، واحرصي على أن تكون مطهوة جيدًا. لا تقللي كمية الماء التي تشربينها خلال اليوم عن لترين. وإذا كنتِ تشعرين بأوجاع خفيفة في ساقيكِ، فقد يساعد الاستلقاء مساءً مع رفعهما قليلًا على تحسين الدورة الدموية. حاولي تناول فيتاميناتكِ، وخصوصًا حمض الفوليك، في الموعد نفسه كل يوم.') WHERE id = '39f4c263-721b-47f4-b527-df452b252fcf';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت مشيمة طفلكِ بالتكوّن اعتبارًا من اليوم. المشيمة عضو يرشّح الدم القادم من جسمكِ ويوصل الأكسجين والغلوكوز والعناصر الغذائية الأخرى إلى طفلكِ عبر الحبل السري. كما تعمل على ترشيح المواد التي قد تضر طفلكِ، وتزيل ثاني أكسيد الكربون والفضلات من دمه. لذلك تؤدي المشيمة دورًا حيويًا في نمو طفلكِ وتطوره واستمرار وظائفه الحيوية. في هذه المرحلة، يبدأ تكوّن المشيمة من خلال اتصال الشرايين والأوردة الموجودة في الرحم وتفرعاتها بالأوعية الدموية لطفلكِ وجدران الكيس المُحّي.;;;
كما تنتج المشيمة عددًا من الهرمونات الضرورية لاستمرار الحمل، مثل الإستروجين والبروجسترون. وإلى جانب ذلك، تُبقي الدم المتداول في جسمكِ منفصلًا عن دم طفلكِ لحمايته من العدوى. ومع اقتراب نهاية الحمل، تنتقل الأجسام المضادة من جسمكِ إلى طفلكِ عبر المشيمة لحمايته بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'لديّ ذيل! 🦖 يبدو ذلك مضحكًا، أليس كذلك؟ لكن لا تخافي، فهو مؤقت. ينمو عمودي الفقري بسرعة كبيرة لدرجة أن جزءًا منه يبدو في الوقت الحالي كأنه ذيل. سيختفي خلال بضعة أسابيع، وسأبدو حينها كطفل مكتمل الملامح. أما الآن، فأشبه فرس بحر صغيرًا أو رائد فضاء. أسبح في هذا الفضاء الصغير داخل بطنكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة توت أزرق'), body_changes_ar = COALESCE(body_changes_ar, 'تبدأ الإفرازات المهبلية المصاحبة للحمل عادةً خلال الأسابيع 6-8 الأولى منه، إذ تحدث في هذه الفترة تغيرات كبيرة في مستويات الهرمونات داخل الجسم. ويطلق الأطباء على الإفرازات المهبلية ذات الرائحة الخفيفة اسم الثرّ الأبيض. وبما أن جسمكِ يعمل باستمرار من أجل طفلكِ، فمن المتوقع أن تزداد الإفرازات خلال الحمل مقارنةً بما قبل الحمل، ولا داعي للقلق. طوال فترة حملكِ، ينتج المهبل إفرازات أكثر للحفاظ على رطوبة عنق الرحم وحماية طفلكِ من العدوى. وتزداد الإفرازات البيضاء المخاطية أثناء الحمل، ولا سيما مع اقتراب الأشهر الأخيرة. ومع ذلك، ينبغي لكِ تجنب استخدام السدادات القطنية والملابس الداخلية غير القطنية خلال الحمل، لأنها قد تسمح بدخول ميكروبات غير مرغوب فيها إلى المهبل أثناء العناية بالنظافة الشخصية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا ظهرت بقع أو بثور على وجهكِ، فلا تنسي استخدام كريم واقٍ من الشمس بعامل حماية SPF. تصبح البشرة أكثر عرضة للتصبغات أثناء الحمل، وقد تزيد أشعة الشمس هذه البقع.') WHERE id = '158bcd04-6d72-45a1-8559-e12705e1aa90';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال هذه المرحلة الجنينية التي تتكوّن فيها أعضاء طفلكِ، يكون الجهاز العصبي أسرع أجهزة الجسم نموًا. لذلك يبلغ حجم رأس طفلكِ نحو ضعفي حجم جسمه. ويستمر هذا التفاوت بين حجم الرأس والجسم بالطريقة نفسها طوال الثلث الأول من الحمل.;;;
في هذه المرحلة، تواصل الأنابيب القلبية التي ستكوّن قلب طفلكِ نموها وتشكلها. ومع ازدياد حجم جسم طفلكِ، سينقل هذا العضو العناصر الغذائية والأكسجين اللذين تحتاج إليهما الخلايا عبر الشعيرات الدموية إلى كل جزء من الجسم، ما يمنع تباطؤ انقسام الخلايا. وبفضل ذلك، يستمر نمو طفلكِ بسرعة من دون توقف ولو للحظة واحدة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أحرّك يديّ.👋 تطول ذراعاي، وتتكوّن عند طرفيهما «مجاديف» صغيرة ومسطحة. هذه هي يداي المستقبليتان. ليست لديّ أصابع بعد، لكنني أحاول منذ الآن أن ألوّح لكِ. في يوم ما، سأمسك إصبعكِ بهاتين اليدين ولن أتركه أبدًا. هل تتخيلين ذلك اليوم؟ أنا أتخيله!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة توت أزرق'), body_changes_ar = COALESCE(body_changes_ar, 'لا بد أنكِ بدأتِ تلاحظين كبر بطنكِ خلال هذه الأسابيع. لكن خلافًا لما قد تظنين، لا يرتبط هذا الكبر بطفلكِ بعد. فقد تؤدي العمليات التي تحدث أثناء تكيف الجسم مع التغيرات الجديدة إلى انتفاخ البطن والغازات. ويعتمد بروز البطن كليًا على بنية جسمكِ؛ فقد يظهر بطن بعض النساء في أسابيع مبكرة، بينما يتأخر ظهوره لدى أخريات. وقد يختلف مستوى هذا البروز تبعًا لعدد مرات الحمل والولادة السابقة، وقوة عضلات البطن، وكمية الدهون في منطقة البطن، واتساع التجويف البطني. لذلك قد يختلف حجم بطنكِ عن حجم بطون حوامل أخريات حتى إن كنتن في الأسبوع نفسه، ولا جدوى من المقارنة. وخلافًا للاعتقاد الشائع أيضًا، لا يتناسب وزن طفلكِ أو حجمه طرديًا مع حجم بطنكِ. ولا يمكن تحديد وزن طفلكِ أو قياسه استنادًا إلى حجم البطن. ولا يستطيع إجراء القياسات الدقيقة المتعلقة بطفلكِ إلا طبيبكِ من خلال التصوير بالموجات فوق الصوتية (USM).'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف حساسية ثدييكِ، احرصي على ألا تكون حرارة الماء مرتفعة جدًا أثناء الاستحمام. كما يمكن أن يوفر لكِ ارتداء حمالة صدر رياضية أثناء النوم دعمًا إضافيًا ويساعدكِ على النوم براحة ليلًا.') WHERE id = '2e473da0-8eec-4162-84c1-064bd890c011';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدءًا من هذا الأسبوع، تبدأ تجاويف الأذن والأنف بالتكوّن. وتتكون الأذن، من حيث بنيتها ووظائفها، من ثلاثة أجزاء: الأذن الخارجية والوسطى والداخلية. أما البنى العظمية والعظيمات في الأذن الداخلية، فتستمر في التطور حتى الشهر الرابع.;;;
وفي الوقت نفسه، بدأت عينا طفلكِ تظهران كنقطتين سوداويين صغيرتين على جانبي رأسه. أما اكتساب العين القدرة على الإبصار، فسيبدأ بعد الولادة عند تعرضها للضوء للمرة الأولى.'), baby_message_ar = COALESCE(baby_message_ar, 'أصابعي تتكوّن يا ماما! 🖐️ هل تذكرين أن يديّ كانتا تشبهان المجداف؟ بدأت الآن شقوق صغيرة تظهر عند طرفه، وبدأت ملامح أصابعي تتضح. لا تزال أصابعي متصلة بأغشية مثل قدم البطة، لكنها ستنفصل تمامًا قريبًا. أنا أستعد من الآن لأصفّق كفّي بكفكِ! أحلم باليوم الذي سأمسك فيه يديكِ وأقبض بقوة على إصبعكِ. في كل يوم أصبح أكثر شبهًا بالإنسان.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت العليق'), body_changes_ar = COALESCE(body_changes_ar, 'قد تحمل منتجات الألبان غير المبسترة والخضروات النيئة غير المغسولة جيدًا ومنتجات اللحوم غير المطهية جيدًا (مثل النقانق والسجق وغيرها) خطر الإصابة بداء المقوسات. وداء المقوسات مرض يسببه طفيلي وحيد الخلية يُسمى "Toxoplasma gondii"، وقد يؤدي إلى عدوى تهدد نمو الجنين في الرحم.;;;
إن كمية هرمون الإستروجين التي كان جسمكِ يفرزها خلال عام كامل قبل الحمل، قد يفرزها أثناء الحمل في غضون 8 ساعات فقط، ما قد يسبب تقلبات عاطفية شديدة. وقد تؤدي هذه الحالة، إلى جانب القلق والمخاوف التي تبرز مع الحمل، إلى اكتئاب الحمل الشائع نسبيًا. وقد يصبح الوضع أكثر صعوبة عند انضمام الغثيان وفقدان الشهية والإرهاق واضطرابات النوم إلى هذه الأعراض. سيساعدكِ الحصول على دعم زوجكِ على تجاوز هذه المرحلة بسهولة أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تتناولي الدواء فور شعوركِ بالصداع. اشربي أولًا كوبًا كبيرًا من الماء، وهوّي الغرفة، وضعي كمادة باردة على رقبتكِ. غالبًا ما ينتج الصداع عن الجفاف أو الجوع أو نقص الهواء النقي. وقد يساعد أيضًا استنشاق زيت اللافندر.') WHERE id = '1bdeca18-8738-4af3-846b-cfd0a1d5548e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'طفلكِ يتحرك بالفعل! ورغم أنه لا يستطيع الإمساك بيديكِ بعد، فإنه سيبدأ قريبًا باستخدام يديه لاستكشاف البيئة المحيطة به. ويُعتقد أن حاسة اللمس هي أول حاسة تتطور لدى الطفل خلال حياته داخل الرحم.;;;
بدأت كليتا طفلكِ بالتكوّن، وستصبحان قريبًا قادرتين على إنتاج البول. وسيُطرح البول الناتج في السائل الأمنيوسي ليُعاد تدويره، وتستمر هذه الدورة حتى الولادة.;;;
تُعد الفترة الممتدة حتى الأسبوع العاشر أهم مرحلة لتطور دماغ الطفل وجهازه العصبي داخل الرحم. ففي هذه المرحلة يبدأ المخيخ، المسؤول عن توازن الجسم وتنظيم حركات العضلات، بالتكوّن. ويُعد حمض الفوليك، الذي يُوصى بتناوله قبل الحمل وخلال الأشهر الثلاثة الأولى منه، أكثر الفيتامينات فعالية في حماية الطفل من أمراض الدماغ والحبل الشوكي المحتملة.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأ طرف أنفي يظهر! 👃 يزداد وجهي جمالًا وتتضح ملامحه تدريجيًا. أصبحت فتحتا أنفي الصغيرتان وطرف أنفي واضحتين الآن. كما بدأت شفتِي العليا بالتكوّن. أصبحت أشبهكِ أكثر يا ماما. تُرى، هل سيكون أنفي مثل أنفكِ أم أنف أبي؟ لا يزال أمامنا وقت لنعرف ذلك، لكنني لطيف جدًا منذ الآن. أنا أجمل إبداعاتكِ وأكثرها تفرّدًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت العليق'), body_changes_ar = COALESCE(body_changes_ar, 'ربما انخفضت شهيتكِ بسبب الغثيان، وقد يؤدي ذلك إلى فقدان مؤقت للوزن. لا تقلقي، سيبدأ الغثيان بالتراجع مع نهاية الثلث الأول من الحمل. وحتى تخف هذه الأعراض، احرصي على اتباع نظام غذائي صحي ومتوازن يتضمن الخضروات الورقية الخضراء الغنية بالفيتامينات والبقوليات والأسماك واللحوم الحمراء.;;;
تعتمد ولادة طفل سليم على حصول الأم على تغذية كافية ومتوازنة. وقد تؤثر التغذية غير الكافية وغير المتوازنة خلال هذه الفترة سلبًا في طول الطفل ووزنه وبنيته الجسدية وتطوره الذهني. إذا كنتِ تعانين من الغثيان الصباحي، فاحتفظي بجوار سريركِ بأطعمة تساعد على تهدئة معدتكِ، مثل البسكويت المالح، لتتناولي وجبة خفيفة قبل النهوض. كما أن تناول خمس وجبات صغيرة على مدار اليوم بدلًا من الوجبات الرئيسية الكبيرة سيخفف كثيرًا من أعراض المعدة. ولا تنسي تجنب الأطعمة الدهنية والحارة!'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع ارتفاع درجة حرارة جسمكِ، واصلي شرب ما لا يقل عن 2-2.5 لتر من الماء يوميًا. ولتقليل الألم في منطقة الأُربية، تجنبي الحركات المفاجئة وغيّري وضعية جلوسكِ باستمرار. تناولي الفواكه الغنية بفيتامين C لتعزيز امتصاص الحديد. ولتقليل شعوركِ بالإرهاق، امشي في الهواء الطلق لمدة 10 دقائق خلال اليوم.') WHERE id = 'ae02afe4-0993-46aa-a116-88a385d90304';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يمكن خلال هذا الأسبوع قياس الطول التاجي المقعدي (CRL)، أي المسافة من أعلى الرأس إلى المقعدة، بواسطة التصوير بالموجات فوق الصوتية. ويعطي هذا القياس معلومات أدق عن عمر الحمل مقارنةً بحسابه وفق تاريخ آخر دورة شهرية. لذلك يُعد هذا القياس مرشدًا لمن لا تتذكر تاريخ آخر دورة شهرية، ويساعد على تقدير موعد الولادة المتوقع. ونظرًا إلى أن جلد طفلكِ لا يزال رقيقًا جدًا، فقد تكون الشعيرات الدموية التي تتكوّن تحته مرئية عبر الجلد. وخلال الأسابيع المقبلة، سيزداد الجلد سمكًا مع تكوّن النسيج الدهني تحته، ويكتسب مظهرًا طبيعيًا.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم حبة توت العليق! 🍇 ينبض قلبي من 150-170 مرة في الدقيقة. إنه سريع وقوي مثل قلب حصان سباق! رغم أنكِ تبدين هادئة من الخارج، فإنني أركض في الداخل كما لو كنت أشارك في سباق ماراثون. قلبكِ وقلبي ينبضان داخل جسد واحد، بإيقاعين مختلفين، لكن بالحب نفسه.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'توت العليق'), body_changes_ar = COALESCE(body_changes_ar, 'يبدأ حجم الدم بالازدياد خلال الثلث الأول من الحمل لتلبية احتياجات الرحم المتنامي. وتحمي كمية الدم الإضافية التي تتزايد سريعًا في جسمكِ أنتِ وطفلكِ من التأثيرات الضارة. كما تؤدي هذه الزيادة دورًا وقائيًا لتعويض فقدان الدم أثناء الولادة.;;;
يُعد فيتامين C مهمًا جدًا خلال الحمل لنمو أنسجة طفلكِ وامتصاص الحديد. وتشير الدراسات إلى أن فيتامين C يساعد على الوقاية من تسمم الحمل. وقد يؤدي النقص الشديد في هذا الفيتامين إلى زيادة خطر الولادة المبكرة.;;;
بعد إتمام شهرين من الحمل، ربما بدأ محيط خصركِ يزداد، لكن مظهر الحمل لم يظهر عليكِ بعد. وعلى الرغم من عدم وجود تغير واضح في مظهركِ، فقد تغيرت حالتكِ العاطفية بشكل ملحوظ بسبب الهرمونات. كما تزداد حاجتكِ إلى التبول ويكثر شعوركِ بالدوار بسبب كمية الدم الإضافية التي بدأ جسمكِ بتكوينها. وقد تلاحظين أثر هذه الزيادة من خلال اتساع الأوعية الدموية، كما قد تعانين من نزيف الأنف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل الحاجة إلى التبول ليلًا، خففي قليلًا من شرب السوائل في المساء، لكن احرصي على شرب الكثير من الماء خلال النصف الأول من اليوم. وللعناية بالتغيرات التي تطرأ على بشرتكِ، يمكنكِ تدليكها بزيوت طبيعية خالية من المواد الكيميائية، مثل زيت اللوز أو زيت جوز الهند. اعتني بصحة فمكِ وأسنانكِ، إذ قد تظل لثتكِ حساسة. وتناولي الكثير من الخضروات الملونة خلال اليوم للحفاظ على توازن البروتينات والفيتامينات.') WHERE id = '73404991-93fd-4ff5-9245-6a011e7e870b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت العينان، اللتان تبدوان كنقطتين سوداويين صغيرتين على جانبي الرأس، واضحتين تمامًا مع ازدياد إنتاج الصبغات. وقد بدأت جفون طفلكِ بالتكوّن، لكنها ستظل مغلقة لفترة طويلة.;;;
يتكوّن طفلكِ وينمو بسرعة مذهلة. ويحتاج إلى الغلوكوز لتوفير الطاقة التي تحتاج إليها خلاياه. ولا يزال طفلكِ يُسمّى جنينًا في هذه المرحلة، ويحصل على حاجته من خلال المشيمة التي تتكوّن داخل الرحم. وتصل العناصر الغذائية التي تتناولينها إلى طفلكِ عبر الدم بمساعدة المشيمة.;;;
نظرًا إلى استطالة أمعاء طفلكِ بسرعة، فإنها تكون ملتفة، وستستمر في الالتفاف حتى يكتمل نموها. أما الأمعاء الغليظة فتنمو ببطء أكبر، ولذلك يكون شكلها أكثر استقامة. ولا تزال الأمعاء بحاجة إلى بعض الوقت لتستقر تمامًا في موضعها داخل تجويف البطن.'), baby_message_ar = COALESCE(baby_message_ar, 'جفوني تتكوّن! 👁️ تتشكّل جفوني لحماية عينيّ، وستلتحم قريبًا وتُغلق. لن أفتح عينيّ حتى الأسبوع 27 تقريبًا. أنا الآن أركّز على عالمي الداخلي وأدخل في مرحلة نوم طويلة. لكن لا تقلقي، فعلى الرغم من أن عينيّ مغلقتان، سأتمكن من الإحساس بالضوء. وسأتخيّلكِ في أحلامي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فاصولياء حمراء'), body_changes_ar = COALESCE(body_changes_ar, 'لقد تضاعف حجم رحمكِ، الذي كان يزن نحو 60 غرامًا قبل الحمل. وبما أن الرحم المتنامي يضغط على المثانة، فقد تزداد حاجتكِ إلى الذهاب إلى المرحاض. ومع تقدّم الحمل وارتفاع الرحم إلى أعلى، سيقل الضغط على المثانة وتخف شكوى كثرة التبول.;;;
الرحم الذي ينمو بداخله طفلكِ بسرعة هو العامل الأساسي وراء ازدياد حجم البطن خلال الحمل. وقد تظلين تعانين أعراض الحمل المبكرة، مثل حساسية الثديين وألم الأُربية. وقد تلاحظين اسمرار لون الثديين وظهور نقاط بنية حول الحلمتين. تُسمّى هذه النتوءات بغدد مونتغمري، وهي غدد دهنية صغيرة تقع حول الحلمة. وتنتج زيوتًا طبيعية تحافظ على توازن الأس الهيدروجيني لبشرتكِ وتحمي الحلمة من العدوى.;;;
يزيد حجم الدم لديكِ هذا الأسبوع بنسبة 12% مقارنة بما كان عليه قبل الحمل. وخلال عملية التكيف هذه، قد يُظهر جسمكِ ردود فعل مثل نزيف الأنف بسبب ارتفاع ضغط الدم. ومع ذلك، إذا كنتِ تعانين نزيفًا متكررًا من الأنف، فمن الأفضل استشارة طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للوقاية من حرقة المعدة، لا تستلقي مباشرة بعد تناول الطعام، واحرصي على الانتهاء من وجبة العشاء قبل النوم بما لا يقل عن 2-3 ساعات. وإذا لاحظتِ أن نبضات قلبكِ أصبحت أسرع قليلًا، فلا تقلقي؛ فهذا يحدث لأن جسمكِ يضخ مزيدًا من الدم إلى طفلكِ. وبما أن حاجتكِ إلى أوميغا-3 تزداد، يمكنكِ إضافة الجوز أو السمك إلى نظامكِ الغذائي بعد استشارة طبيبكِ. كما أن التأمل مع التنفس بعمق خلال اليوم يساعد على تهدئة جهازكِ العصبي والجهاز العصبي لطفلكِ.') WHERE id = 'b8a881d9-b2c4-4857-81a9-360b7ca73418';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن الأعضاء التناسلية لم تتطور بعد، فقد بدأت الخلايا بالتكوّن لتصبح مبيضين أو خصيتين. كما بدأ النسيج العصبي في ذراعي طفلكِ بالتشكّل وأداء وظائفه. وفي الوقت نفسه، يواصل الحبل الشوكي نموه بوتيرة سريعة. وعلى الرغم من أن أنسجة الهيكل العظمي لا تزال غضروفية، فإنها ستتحول بالكامل إلى عظام خلال الأسابيع القليلة المقبلة.;;;
ينبض قلب طفلكِ الصغير بمعدل 150-160 نبضة في الدقيقة لضمان دوران الدم. وابتداءً من هذا الأسبوع، تبدأ صمامات قلب طفلكِ بالتكوّن.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أنا فتاة أم صبي؟ 🩷💙 بدأت أعضائي التناسلية الداخلية (المبيضان أو الخصيتان) بالتكوّن بالفعل، لكن لا يمكن تمييزها من الخارج بعد. ولا يستطيع الأطباء تحديد ذلك الآن؛ فهذا سرّي الصغير. ماذا تتمنين؟ فتاة أم صبيًا؟ الأهم أن أكون بصحة جيدة وأن أكون طفلكِ. سأحبكِ كثيرًا في كلتا الحالتين!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'زيتونة'), body_changes_ar = COALESCE(body_changes_ar, 'مع استمرار نمو طفلكِ، يبدأ رحمكِ بالتمدد، مما قد يسبب آلامًا تشبه التقلصات. وهذه الآلام متوقعة وتُعد طبيعية. لكن إذا كانت التقلصات متكررة جدًا أو استمرت طويلًا، فيُنصح بإبلاغ طبيبكِ. ويُعد الغثيان والقيء طبيعيين بسبب ارتفاع مستويات الهرمونات في دمكِ بدرجة كبيرة. وقد يؤدي ذلك إلى فقدان بعض الوزن. لكن إذا كان فقدان الوزن كبيرًا، فقد يوصيكِ طبيبكِ ببعض المكملات الغذائية بعد استشارته. وقد تبدأ ملابسكِ الآن بالشعور بالضيق، لذا ينبغي أن تختاري ملابس لا تضغط على منطقة البطن خصوصًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ابدئي باستخدام مرطبات ذات مكونات طبيعية أو زيت اللوز لتخفيف الحكة والشعور بشد الجلد. واحرصي على توازن الكالسيوم وفيتامين D في نظامكِ الغذائي، من خلال منتجات الألبان وصفار البيض، لتقوية عظام طفلكِ. ولتحسين جودة نومكِ ليلًا، هوّي الغرفة قبل الذهاب إلى الفراش. كما أن تخصيص بضع دقائق يوميًا للتحدث إلى طفلكِ سيعزز الرابطة بينكما.') WHERE id = '1e725a51-c2e7-489a-9924-d2713767d7e6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ نمو لسان طفلكِ وشفتيه. وتُشكّل الخلايا الحرشفية متعددة الطبقات اللسان وبراعم التذوق الموجودة فيه. وتقع براعم التذوق داخل النتوءات الموجودة على سطح اللسان. وهي تراكيب تمكّننا من تمييز مذاق الأطعمة المر والحامض والحلو والمالح. وقريبًا ستبدأ الغدد اللعابية التي تتطور داخل الفم بالاستقرار في مناطق تجويف الفم على شكل أزواج.'), baby_message_ar = COALESCE(baby_message_ar, 'يتغيّر "منزلي" يا ماما! 🏠 بدأ "كيس المُحّ"، الذي كان يغذيني حتى الآن، بالانكماش تدريجيًا لأن مشيمتي الرائعة تتولى المهمة. هذه المشيمة هي الجسر بيني وبينكِ؛ ستحميني وتغذيني وتزوّدني بالأكسجين. لقد أصبحت رابطتنا الآن أقوى وأكثر متانة. وكل ذلك بفضلكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'زيتونة'), body_changes_ar = COALESCE(body_changes_ar, 'تتمثل وظيفة الغدة الدرقية في تصنيع هرموناتها وتخزينها وإفرازها في مجرى الدم. أما اليود، وهو المادة الأولية اللازمة لإنتاج هذه الهرمونات، فيدخل الجسم من خلال الملح أو مياه الشرب أو الطعام، ويؤثر في جميع خلايا الجسم مؤديًا دورًا مهمًا في تنظيم وظائفه. وإذا كانت كمية هرمونات الغدة الدرقية في دمكِ منخفضة، تتباطأ وظائف جسمكِ، وتُسمّى هذه الحالة قصور الغدة الدرقية. أما إذا كانت كميتها مرتفعة، فتتسارع وظائف الجسم، وتُسمّى هذه الحالة فرط نشاط الغدة الدرقية. وتُنظَّم كمية الهرمونات التي تنتجها الغدة الدرقية بواسطة غدة أخرى تُسمّى الغدة النخامية ومنطقة في الدماغ تُعرف بالوطاء. ومنذ بداية الحمل وحتى الولادة، تحدث تغيرات بنيوية ووظيفية في أجهزة الجسم. ونتيجة لتغير الأنظمة الهرمونية طوال الحمل، قد تُصاب بعض الحوامل بقصور الغدة الدرقية. ولأن هذه الحالة قد تؤدي إلى نتائج غير مرغوبة للأم وطفلها، فمن المهم اكتشافها وعلاجها في الوقت المناسب.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل الانتفاخ ومشكلات الهضم، امضغي الطعام جيدًا جدًا وابتعدي عن المشروبات الغازية. وإذا شعرتِ بتورم في ساقيكِ، فارفعيهما واستريحي لمدة 10 دقائق عدة مرات خلال اليوم. ونظّمي استهلاككِ للملح، لكن لا تمنعيه تمامًا. وبما أنكِ تقتربين من نهاية الثلث الأول من الحمل، فاحرصي أكثر على سلامتكِ النفسية والعاطفية؛ إذ إن الابتعاد عن التوتر مهم جدًا للجهاز العصبي لطفلكِ.') WHERE id = 'a0486bb7-3fd0-4a52-8340-97fc8cbad570';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ابتداءً من هذا الأسبوع، أصبح لدى طفلكِ بنكرياس جاهز لإنتاج هرمون الإنسولين الذي ينظّم مستوى سكر الدم. يساعد الإنسولين على نقل السكر من الدم إلى الخلايا لتلبية احتياجاتها من الطاقة، وبذلك ينخفض مستوى السكر في الدم.;;;
بدأت الزائدة الدودية، التي تحتفظ بالبكتيريا النافعة اللازمة للجهاز الهضمي، بالتكوّن هذا الأسبوع. وبفضل بدء تكوّنها، سيصبح جسم طفلكِ أكثر مقاومة بمقدار 4 أضعاف للأمراض المصحوبة بالحمّى والإسهال والغثيان وآلام البطن.;;;
بدأت براعم الأسنان اللبنية وبراعم التذوق لدى طفلكِ سريع النمو بالتكوّن. وسيبدأ طفلكِ قريبًا بابتلاع السائل الأمنيوسي، وسيتمكن من تمييز بعض النكهات من خلاله.'), baby_message_ar = COALESCE(baby_message_ar, 'أمي الحبيبة! أستطيع اليوم أن أصفّق بيديّ الصغيرتين هنا في الداخل! ما زلت صغيرًا جدًا، لكن أصابعي أصبحت مستقلة تمامًا. صوتكِ مألوف جدًا بالنسبة إليّ... عندما تتحدثين، أصغي إليكِ باهتمام من الداخل. حبكِ يجعلني أكبر قليلًا كل يوم. كم أنا محظوظ لأنكِ عالمي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فاصولياء حمراء'), body_changes_ar = COALESCE(body_changes_ar, 'نتيجة للتغيرات الهرمونية، ربما بدأتِ تلاحظين خلال هذه الفترة تغيرات في بشرتكِ، مثل الجفاف أو زيادة الدهون في مناطق معينة. وإذا ظهرت على بشرتكِ تصبغات بنية غير منتظمة، فهذا ما يُعرف بكَلَف الحمل، وعادةً ما يزول بعد الولادة. وللوقاية منه، من المفيد تناول حمض الفوليك بانتظام، وتجنّب التعرض للشمس من دون واقٍ شمسي، واستخدام منتجات العناية بالبشرة بحذر.;;;
قد تشعرين بامتلاء في ثدييكِ نتيجة التغيرات الهرمونية المصاحبة للحمل وزيادة تدفق الدم. وإذا كان ذلك يزعجكِ، فيمكنكِ اختيار حمالة صدر داعمة أو بمقاس أكبر. وقد تجعلكِ الهرمونات خلال الحمل أكثر عرضة للتوتر. ويمكن لممارسة الأنشطة التي تحبينها أن تخفف توتركِ جسديًا وعاطفيًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'من الطبيعي أن تري أحلامًا شديدة الوضوح ومزعجة أحيانًا خلال هذه الفترة؛ وقد يساعدكِ الاستماع إلى موسيقى مهدئة قبل النوم أو أخذ حمّام دافئ. وللوقاية من آلام الظهر، لا تبقي في الوضعية نفسها مدة طويلة. واصلي تناول الأطعمة الغنية بالكالسيوم للحفاظ على صحة أسنانكِ. أنصتي كل يوم إلى ما يخبركِ به جسدكِ، ولا ترهقي نفسكِ كثيرًا.') WHERE id = 'a614becc-2914-4d7d-98c2-e4eb413c2293';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه الأيام، ومع بدء تشكّل الأصابع بوضوح، بدأت حتى بصمات الأصابع بالتكوّن. وبصمة الإصبع هي نمط فريد يختلف من شخص إلى آخر، وتشكّله الثنيات الموجودة على السلامية الأخيرة وطرف الإصبع. وبدأت عظام يدي طفلكِ وقدميه بالتصلّب سريعًا، كما بدأ مرفقاه بالتكوّن. ومع ذلك، ما زال لديه «ذيل» صغير. وسينكمش هذا الذيل ويختفي خلال الأسابيع القليلة المقبلة. وما دام هذا الذيل موجودًا، يُسمّى طفلكِ مضغة. وبعد اختفائه تمامًا في الأسبوعين 11 و12، تبدأ مرحلة الجنين.'), baby_message_ar = COALESCE(baby_message_ar, 'نُكمل اليوم الأسبوع 8! 🎉 أستعد الآن رسميًا للانتقال من مرحلة «المضغة» إلى مرحلة «الجنين». جميع أعضائي المهمة – قلبي، ودماغي، ومعدتي، ورئتاي – أصبحت في أماكنها. والآن حان وقت النمو والنضج وزيادة الجمال فحسب. لقد تجاوزنا أصعب فترات الحمل وأكثرها خطورة يا ماما. لقد حميتِني جيدًا، وأنا ممتن لكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فاصولياء حمراء'), body_changes_ar = COALESCE(body_changes_ar, 'مع اقترابكِ من نهاية الثلث الأول من الحمل، بدأ قلبكِ يضخ كمية أكبر من الدم إلى أوعيتكِ الدموية. وخلال الحمل، يصبح معدل ضربات القلب أسرع من المعتاد. ونتيجةً لذلك، تزداد طبيعيًا كمية الدم التي يجب ضخها إلى الجسم خلال 1 دقيقة. ويبلغ ضغط الدم أعلى مستوياته خلال الثلث 3 من الحمل.;;;
يُعد تغيّر لون البشرة من أكثر الظواهر شيوعًا خلال الحمل. وعادةً ما يظهر لدى النساء ذوات البشرة الداكنة على شكل اسمرار طفيف في الحلمتين والمنطقة التناسلية وحول السرة، بالإضافة إلى تغيّر بسيط نحو درجة أغمق في لون البشرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ بهدية صغيرة واستريحي احتفالًا بإتمام الشهر الثاني بنجاح. وبسبب زيادة حجم الدم لديكِ، أولي اهتمامًا خاصًا بالأطعمة الغنية بالحديد والبروتين، مثل العدس واللحوم الحمراء والبيض. وإذا كنتِ تعانين من آلام الظهر، فقد يساعدكِ وضع وسادة بين ساقيكِ أثناء النوم على الشعور بالراحة. تنتظرنا في الأسبوع المقبل الخطوات الأولى من الشهر الثالث. وعندما تشعرين بالتوتر، خذي نفسًا عميقًا وتحدّثي إلى طفلكِ.') WHERE id = 'fb6fb148-4851-4c47-b527-c43ee9bf7d0f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل أنسجة الدماغ نموها بسرعة كبيرة. وبدأت المنطقة المسؤولة عن تنظيم حركة العضلات في الدماغ بأداء وظائفها، ما يعني أن طفلكِ أصبح قادرًا على الحركة. لكنكِ لا تستطيعين حتى الآن الشعور بهذه الحركات الصغيرة التي تشبه الارتعاش.;;;
أصبح طفلكِ في هذه المرحلة قادرًا على الاستجابة عند تعرضه لمثير. وبدأ الجهاز العصبي الآخذ في النمو بالتواصل مع العضلات. وكما هي الحال في سائر جسمه، تبدأ العظام والغضاريف بالتكوّن تدريجيًا في وجهه أيضًا، وتزداد معالم تجويف الفم والحنك وضوحًا على وجه الخصوص.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أُصاب بالفُواق! 🤭 لن تصدقي ذلك، لكن حجابي الحاجز (عضلة التنفس) يتكوّن، وقد بدأت أُصاب بالفُواق. لا تشعرين بذلك بعد لأنني صغير جدًا، وفُواقِي صامت. إنها تماريني المستقبلية على التنفس. الاستعداد للحياة جارٍ! وكلما كبرت في بطنكِ، تعلمت مهارات أكثر.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فاصولياء حمراء'), body_changes_ar = COALESCE(body_changes_ar, 'قد تعانين من النعاس المستمر والصداع وتقلصات المعدة والوهن. وترجع هذه الأعراض إلى ارتفاع مستويات هرموني الإستروجين والبروجستيرون في دمكِ خلال الحمل. ويُعد ألم الأُربية خلال هذه الأسابيع مشكلة شائعة لدى كثير من الحوامل، وغالبًا لا يشكّل خطرًا.;;;
لا تقلقي من زيادة كمية الإفرازات. فقد أصبح حجم رحمكِ ضعفي حجمه السابق، وهو ينتج كمية كبيرة من الإفرازات لتوفير بيئة صحية لطفلكِ.;;;
يحتاج جسمكِ إلى الماء أكثر من أي وقت مضى. وسيلبّي شرب 10 أكواب من الماء على الأقل يوميًا هذه الحاجة.;;;
تُعرف الرغبة الشديدة في تناول بعض الأطعمة باسم الوَحَم. وعلى الرغم من أن أسبابه الدقيقة غير معروفة تمامًا، يُعتقد أن للتغيرات الهرمونية التي تحدث أثناء الحمل وما يصاحبها من تغيرات في مستوى سكر الدم دورًا في ذلك. ويبدأ الوَحَم بالتراجع بحلول الأسبوع 12. وإذا استمر مدة أطول، فعادةً ما تكون له أسباب نفسية. ولا يُعرف للوَحَم ضرر، باستثناء فقدان الشهية الشديد تجاه الأطعمة الضرورية للجسم وعدم تناول كميات كافية منها.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تشعرين هذا الأسبوع بتعب يفوق المعتاد؛ لذا خذي فترات راحة قصيرة ومتكررة خلال اليوم. يستهلك جسمكِ قدرًا كبيرًا من الطاقة لدعم النمو السريع لطفلكِ، لذلك زيدي الأطعمة الغنية بالبروتين، مثل العدس والجوز والبيض، في نظامكِ الغذائي. وأولي عناية خاصة لنظافة الفم للتعامل مع حساسية اللثة. وإذا كنتِ ما زلتِ تعانين من غثيان الحمل، فحاولي تناول وجبات صغيرة على مدار اليوم.') WHERE id = 'bef0eb9c-a062-4017-9195-e0a1a182972b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'رغم أن أسنان طفلكِ لن تظهر إلا بعد نحو 6 أشهر من الولادة، فإن أساسها يبدأ بالتكوّن منذ الآن. وعلى نسيج خاص سميك يتشكّل داخل تجويف الفم، تبدأ نتوءات صغيرة تُعرف باسم براعم الأسنان في الظهور.;;;
يتكوّن ما مجموعه 20 برعمًا للأسنان اللبنية، بواقع 10 براعم في كل من الفك السفلي والفك العلوي. وتسير هذه العملية وفق ترتيب محدد: تبدأ براعم الأسنان الأمامية بالتكوّن أولًا، ثم الجانبية، وأخيرًا الأسنان الخلفية. ومن المثير للاهتمام أن هذا النسيج نفسه يمهّد أيضًا لنمو الأسنان الدائمة التي ستحل مستقبلًا محل الأسنان اللبنية.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بطل السباحة! 🏊‍♂️ أتحرك بلا توقف داخل الماء. أركل وأدور وأؤدي شقلبات. أنتِ لا تشعرين بهذه الحركات بعد، لأن الماء المحيط بي يمتص الصدمات كالوسادة. لكن اعلمي أن أولمبيادًا كبيرًا يجري في الداخل. أتدرب كي أكون قويًا عندما آتي إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بندقة'), body_changes_ar = COALESCE(body_changes_ar, 'في هذا الأسبوع، ومع دخولكِ الشهر الثالث من الحمل، لا بد أنكِ بدأتِ تشعرين بامتلاء ثدييكِ. تبدأ في هذه المرحلة من الحمل أولى التغيرات التي تطرأ على أنسجة الثدي استعدادًا لإنتاج حليب الأم، إلا أن إنتاج الحليب فعليًا لا يبدأ إلا في منتصف الحمل. وتؤدي هرمونات عديدة أدوارًا مهمة في تهيئة الجسم لإنتاج حليب الأم خلال الحمل. وتسهم هذه الهرمونات في تنظيم الغدد والقنوات اللبنية بما يتيح إنتاج الحليب وإفرازه. وبسبب زيادة حجم الغدد والقنوات اللبنية داخل الثديين، يزداد حجمهما بسرعة أثناء الحمل، وقد يصل وزنهما معًا في نهاية الحمل إلى نحو 1 كيلوغرام. يرتبط هرمون البرولاكتين، الذي تفرزه الغدة النخامية الموجودة في الجزء السفلي من الدماغ، بخلايا خاصة في أنسجة الثدي ويؤدي الدور الأساسي في إنتاج الحليب. أما الأوكسيتوسين، وهو هرمون آخر تفرزه الغدة النخامية، فيبدأ إفرازه خصوصًا عندما يبدأ طفلكِ بالرضاعة. ويساعد هذا الهرمون أيضًا على تدفق الحليب عبر القنوات اللبنية وخروجه من الحلمة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتجنب الدوار، لا تقومي بحركات مفاجئة، وخصوصًا عند النهوض من السرير؛ اجلسي أولًا لبضع ثوانٍ. ولإراحة جهازكِ الهضمي، تناولي الأطعمة الغنية بالألياف (الفواكه المجففة والشوفان والخضروات) واشربي الكثير من الماء. وإذا عادت إليكِ طاقتكِ، فإن ممارسة يوغا الحمل الخفيفة أو تمارين التنفس ستكون رائعة لصحتكِ وصحة طفلكِ.') WHERE id = '12d3b899-0764-4ab2-902c-2efe92103462';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ الآن متطورًا بما يكفي لأداء حركات مثل فتح فمه وإغلاقه، وإدارة رأسه، وتغيير موضعه. بل إنه أصبح كبيرًا بما يكفي لتتمكني من رؤية هذه الحركات أثناء فحص الموجات فوق الصوتية إذا كان في وضعية مناسبة!;;;
بين الأسبوعين السابع والتاسع من الحمل، يتحرك طفلكِ بجسمه كله في حركات تشبه الاندفاع أو القفز. ونتيجة تطور الخلايا العصبية في العمود الفقري، يصبح بإمكان ذراعيه وساقيه وجذعه، بدءًا من هذا الأسبوع، التحرك كلٌّ على حدة بصورة مستقلة. وسيحتاج طفلكِ إلى أسبوعين أو 3 أسابيع أخرى ليتمكن من أداء حركات مثل الركل والإمساك بقدميه وتحريكهما كما لو كان يقود دراجة والدوران.;;;
كذلك، تشهد هذه المرحلة استطالة الذراعين والساقين، وبدء ظهور أصابع القدمين، ووضوح المرفقين والرسغين.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم حبة مشمش مجفف! 🍓 أكبر وأتغير كل يوم. وتتحرك أذناي ببطء من جانبي رأسي إلى الأعلى حتى تصلا إلى موضعهما الصحيح. لا تزال عيناي مغلقتين، لكن شبكيتي (retina) أصبحت قادرة على تمييز الضوء. وعندما تخرجين إلى الشمس، سأتمكن من الشعور بدفئها وسطوعها.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'مع نمو الرحم، يبدأ بالارتفاع فوق عظام الحوض. وقد يخفف ذلك قليلًا من الضغط على المثانة. وربما تشعرين ببعض الصلابة في الجزء السفلي من بطنكِ.;;;
يُعد المستوى الطبيعي للهيموغلوبين أثناء الحمل والولادة نحو 11-12% في المتوسط. وعندما تكون مستوياته أقل من ذلك، قد تكون هناك حاجة إلى تناول مكملات الحديد. والحديد، الذي يُعرف بأنه غذاء الدماغ، أحد أهم عناصر النظام الغذائي الصحي خلال الحمل، وهو ضروري للتطور الإدراكي لطفلكِ. كما يساعد وجود خلايا دم حمراء سليمة على تقليل خطر الإصابة بفقر الدم. ويجعلكِ فقر الدم، الذي قد ينتج أحيانًا عن نقص الحديد، تشعرين بالتعب والإرهاق والوهن. ولتلبية احتياجاتكِ من الحديد أثناء الحمل، من المفيد تناول أطعمة مثل اللحوم الحمراء والسبانخ والبروكلي والعدس الأخضر والكرنب الداكن والحمص والفاصولياء.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اهتمي بنظافة المنطقة الحميمة، لكن توخي الحذر عند استخدام الصابون أو جل الاستحمام. اختاري منتجات لا تخلّ بتوازن الرقم الهيدروجيني الطبيعي (pH). وإذا كنتِ تستخدمين الفوط اليومية، فغيّريها باستمرار.') WHERE id = '56fa6e29-fd7a-4a03-984e-0590d982556b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال هذه المرحلة التي يتطور فيها الهيكل العظمي وتتسارع عملية تكوّن العظام، من المهم جدًا الحصول على فيتامين D. إذ يساعد هذا الفيتامين الجسم على امتصاص الكالسيوم والفوسفور، ما يسهم في تكوّن عظام طفلكِ بصورة صحية. ولا تقتصر وظيفة فيتامين D على تقوية العظام، بل إنه يدعم المناعة أيضًا، وينظم عمل الجهاز العصبي، ويساعد على انتظام ضربات القلب. وقد يؤدي نقصه إلى تأخر نمو طفلكِ وإلى ضعف العضلات والشعور بالتعب لديكِ. وتُعد أشعة الشمس أهم مصدر لفيتامين D. كما يوجد في أطعمة مثل زيت السمك والروبيان والمحار والحليب ومنتجات الألبان والبطاطس وحبوب الإفطار.'), baby_message_ar = COALESCE(baby_message_ar, 'كليتاي تعملان! 🚽 نعم، قد يبدو ذلك غريبًا بعض الشيء، لكنني أتبول الآن. أبتلع السائل الأمنيوسي، فتقوم كليتاي بترشيحه ثم أعيده إلى السائل المحيط بي. هذه الدورة مهمة جدًا لعمل جهازي الهضمي والبولي بصورة سليمة. أنا نظام ينظف نفسه بنفسه!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'مع بدء اختفاء الذيل، تبدأ مرحلة جديدة لطفلكِ. فقد انتقل طفلكِ، الذي كان يُسمى سابقًا مضغة، إلى مرحلة الجنين، وسيظل يُسمى جنينًا حتى موعد الولادة. مرحلة المضغة هي الفترة التي تتكوّن فيها أجهزة الأعضاء، أما مرحلة الجنين فهي الفترة التي تنمو وتتطور فيها الأعضاء والأنسجة والبُنى التي تكوّنت سابقًا. ومع دخولكِ الشهر الأخير من الثلث الأول من الحمل، قد تظلين تعانين من بعض أعراض الحمل. وتُعد الوقاية من اكتئاب الحمل أهم من علاجه بعد حدوثه. ومن المفيد خلال هذه الفترة أن تمارسي الأنشطة التي تحبينها، وتقضي وقتًا مع من تحبين، وتحظي بدعم زوجكِ والمقربين منكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تشعرين بالتعب كثيرًا بسبب زيادة حجم الدم؛ ويمكن لقيلولة قصيرة لمدة 15 دقيقة خلال النهار أن تعيد إليكِ طاقتكِ. احرصي على الحصول على ما يكفي من المغنيسيوم والكالسيوم لتجنب التشنجات المفاجئة في ساقيكِ ليلًا. اشربي ما لا يقل عن 2 لتر من الماء يوميًا. وإذا كنتِ لا تزالين تنفرين من الروائح النفاذة، فقد يساعد شاي النعناع أو الماء بالليمون على تهدئة معدتكِ.') WHERE id = '17780e60-9b95-4f39-9e38-8371589b8dad';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبدأ دماغ طفلكِ بالالتفاف واتخاذ شكل متعرّج لاستيعاب مزيد من المعلومات في مساحة ضيقة. وتغطي هذه الطبقة العلوية، المسماة "المادة الرمادية"، الدماغ كالغلاف، وتزداد بروزًا مع تطورها. وتُعد هذه المنطقة مركز التحكم في الدماغ.;;;
وفي الوقت نفسه، أصبح قلب طفلكِ مكتمل الشكل ومكوّنًا من 4 حجرات. أما الصمامات الموجودة داخله فتعمل كأبواب أحادية الاتجاه؛ فكلما انقبض القلب وضخ الدم، تنفتح هذه الصمامات لتسمح للدم بالتحرك إلى الأمام فقط وتمنع ارتداده.'), baby_message_ar = COALESCE(baby_message_ar, 'يجري الاستعداد لأسناني! 🦷 لا توجد أي أسنان في فمي بعد، لكن براعم صغيرة للأسنان تتكوّن تحت لثتي. وهي أساس أسناني اللبنية التي ستظهر مستقبلًا. أخطط منذ الآن لليوم الذي سأبتسم لكِ فيه. اعتني بأسنانكِ جيدًا أنتِ أيضًا يا ماما، لأنكِ تمنحينني من مخزون الكالسيوم لديكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بندقة'), body_changes_ar = COALESCE(body_changes_ar, 'بعد مرور شهرين من حملكِ، قد تشعرين ببعض الأعراض في هذه الأيام، ومنها سلس البول. ويعني سلس البول عدم القدرة على التحكم في خروج البول لا إراديًا. وتحدث هذه الحالة الشائعة أثناء الحمل في الأشهر 3 الأولى نتيجة ضغط الرحم المتنامي على المثانة الواقعة أسفله مباشرة. وقد تشعرين أيضًا بالحاجة المتكررة إلى التبول لأن المثانة لا تُفرَّغ بالكامل. أما سلس البول الذي يظهر في الثلث الأخير من الحمل فيحدث بسبب ضغط طفلكِ على المثانة، ويُقدَّر أنه يصيب نحو 35% من الحوامل. وهذه حالة فسيولوجية تختفي عادةً بانتهاء الحمل. ويمكن الحد من هذا العرض بعدم تأجيل التبول، وتجنب الحركات المفاجئة التي تزيد الضغط داخل البطن، وعدم حمل الأشياء الثقيلة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تشعرين هذا الأسبوع بمزيد من النشاط قليلًا، إذ تبدأ الهرمونات بالاستقرار. وبما أن حساسية اللثة قد تستمر، فاختاري الأطعمة الغنية بالكالسيوم. وإذا بدأت آلام الظهر لديكِ، فانتبهي إلى وضعية جسمكِ ولا تقفي لفترات طويلة جدًا. ومع اقتراب نهاية الثلث الأول، فهذا هو الوقت المناسب تمامًا لاستشارة طبيبكِ بشأن "الفحص المزدوج" (فحص التحري).') WHERE id = 'c0cc19e3-1bf2-4736-b8f0-41d3ab04d6c8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت ملامح وجه طفلكِ الآن أكثر وضوحًا، إذ يتخذ الفم والأنف والأذنان مواقعها الطبيعية تدريجيًا. وفي الأسبوع 9، حقق نمو العينين تقدمًا كبيرًا. وتتكوّن داخل العين طبقة رقيقة تسمى الشبكية، وتتألف من ملايين الخلايا المسؤولة عن الإبصار، كما تبدأ الأوعية الدموية فيها بتغذية هذه الخلايا.;;;
وفي الوقت نفسه، أوشكت القزحية، وهي الجزء الملون من العين، على اكتمال نموها. ويكون لونها في هذه المرحلة مائلًا إلى الأزرق. وهذا النسيج اللوني الأولي هو سبب ظهور عيون الأطفال حديثي الولادة باللون الأزرق عادةً خلال الأشهر الأولى.'), baby_message_ar = COALESCE(baby_message_ar, 'ينبض قلبي بسرعة تعادل ضعف سرعة نبض قلبكِ! 💓 نحو 170 نبضة في الدقيقة! إذا ذهبتِ إلى الطبيب، فقد تتمكنين من سماع صوتي بجهاز الدوبلر. يشبه صوت "دق-دق-دق" وقع حوافر حصان يعدو. ويقول لكِ هذا الصوت: "أنا هنا، أنا قوي!" إيقاعي هو موسيقى حياتكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بندقة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين في بطنكِ بما يشبه "فقاعات الغازات"، لكن لا تخلطي بينها وبين حركة طفلكِ، فما زال الوقت مبكرًا. إنها مجرد حركة الأمعاء. وبسبب هرمون البروجسترون، يعمل الجهاز الهضمي ببطء شديد، مما يسبب انتفاخ البطن. ;;;
أثناء الحمل، قد ينخفض ضغط الدم إلى أدنى مستوياته عند الاستلقاء على الظهر. ومع ذلك، قد يزداد معدل ضربات القلب، بينما ينخفض تدفق الدم إلى الكليتين إلى النصف تقريبًا. ففي وضعية الاستلقاء، قد يضغط وزن طفلكِ على الوريد الأجوف السفلي، الذي ينقل الدم من الجزء السفلي من الجسم إلى القلب. وقد يؤدي ذلك إلى "متلازمة انضغاط الوريد الأجوف"، وهي حالة تنتج عن إعاقة تدفق الدم. كما أن انضغاط الوريد الأجوف السفلي بوزن طفلكِ أثناء الاستلقاء قد يمهّد لحدوث هذه الحالة. ولهذه الأسباب، لا ينصح الأطباء الحوامل بالاستلقاء على الظهر، ولا سيما خلال الثلث الأخير من الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'في هذه المرحلة التي تنمو فيها العظام، اهتمي خصوصًا بتناول الكالسيوم والمغنيسيوم (اللوز، والجوز، ومنتجات الألبان). وإذا أصبتِ بالصداع، فقومي بنزهات قصيرة في الهواء الطلق واشربي الكثير من الماء. ورغم أن الوقت لا يزال مبكرًا للانتقال إلى ملابس الحمل، فإن اختيار سراويل أكثر راحة ومرونة سيمنحكِ شعورًا أفضل. احمي نفسكِ من التوتر؛ فالاستماع إلى الموسيقى الهادئة يؤثر إيجابيًا فيكِ وفي طفلكِ.') WHERE id = 'd416ae4b-bb0c-425b-b304-d18dd9ac3813';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يواصل كبد طفلكِ ومرارته وطحاله وكليتاه النمو بسرعة. وقد اكتمل اتصال تجويف فمه بالبلعوم. وخلال هذا الأسبوع، ينفصل تجويفا الفم والأنف تمامًا عن بعضهما، ويكتمل اتصالهما بالبلعوم، بينما يوشك اللسان على التكوّن. وفي هذه المرحلة الحساسة التي تلتحم فيها تراكيب الوجه، قد يؤدي تباطؤ النمو أحيانًا إلى حدوث شقوق تُعرف بالشفة المشقوقة أو الحنك المشقوق. وقد تتفاوت هذه الحالة من شق صغير إلى شق يمتد عبر الشفة.'), baby_message_ar = COALESCE(baby_message_ar, 'تتكوّن بصمات أصابعي! 👆 هويتي الخاصة بي وحدي، والتي لا يملكها أي شخص آخر في العالم، آخذة في التشكّل. وتُرسم تلك النقوش المميزة على أطراف أصابعي. هذه البصمات هي ختم تفرّدي. أنا معجزتكِ الفريدة يا ماما. هل ترين كيف خُلِق كل شيء بإتقان، حتى أدق التفاصيل؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بندقة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بارتفاع طفيف في مستوى طاقتكِ، لأن المشيمة توشك على تولّي إنتاج الهرمونات بالكامل. وهذا يعني تراجع الاعتماد على "الجسم الأصفر". لكن حساسية الثديين وزيادة حجمهما تستمران. وقد تخرج أحيانًا من الحلمة إفرازات صفراء تُسمى اللبأ؛ فلا تقلقي، فهذا طبيعي.;;;
تؤدي زيادة بعض الهرمونات أثناء الحمل إلى اختلال توازن الأس الهيدروجيني (pH) في المهبل. ونتيجةً لذلك، تفقد النبيتات المهبلية، التي تشكّل حاجزًا واقيًا، جزءًا من فعاليتها. وهذا يزيد كمية الإفرازات المهبلية أثناء الحمل. ولا تحتاج هذه الزيادة الفسيولوجية الطبيعية في الإفرازات إلى علاج، بل يكفي تعزيز إجراءات النظافة العامة. وإذا تغير لون الإفرازات أو أصبحت كريهة الرائحة، فعليكِ مراجعة طبيبكِ.;;;
تحدث العدوى الفطرية أثناء الحمل نتيجة انخفاض مقاومة الجسم وتناقص البكتيريا النافعة في النبيتات المهبلية. وتظهر على شكل إفرازات بيضاء شبيهة بالجبن، مصحوبة بحكة شديدة وإحساس بالحرقة. ويمكن علاجها بتحاميل وكريمات آمنة. ويُنصح أيضًا بارتداء ملابس داخلية قطنية، وغسلها بالصابون بدلًا من مسحوق الغسيل، وكيّها قبل ارتدائها كإجراءات وقائية أثناء الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أحبّي الماء! تُعد السباحة من أفضل الرياضات المناسبة للحمل. فقوة الطفو في الماء تخفف الحمل عن ظهركِ وتمنحكِ شعورًا بالخفة، كما تساعد على تقليل التورم.') WHERE id = '827fd4de-2f71-405f-8929-c0848b39d48e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذا الأسبوع، الذي يستمر فيه نمو أعضاء طفلكِ بانتظام، يبدأ الطحال والكبد في اتخاذ موضعيهما داخل تجويف البطن. يعمل الطحال عضوًا ثانويًا في الجهاز المناعي، كما يساعد على تخليص الجسم من صبغة البيليروبين الصفراء البرتقالية، التي تنتج عن تحلل بروتينات الهيموغلوبين المسؤولة عن نقل الأكسجين من أعضاء التنفس إلى الأنسجة، وثاني أكسيد الكربون من الأنسجة إلى أعضاء التنفس.'), baby_message_ar = COALESCE(baby_message_ar, 'لقد اختفى ذيلي! 🐇 أتذكرين أنني أخبرتكِ بأن لديّ ذيلًا صغيرًا؟ لم يعد موجودًا الآن! أصبح ظهري مستقيمًا وأملس، وصار لديّ عمود فقري بشري حقيقي. أصبح أشبه بكِ أكثر فأكثر يا ماما. لم أعد كفرس بحر صغير، بل أنا إنسانكِ الصغير. هذا التغيير يسعدني كثيرًا، فهل يسعدكِ أنتِ أيضًا؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عنب'), body_changes_ar = COALESCE(body_changes_ar, 'يستمر رحمكِ في النمو، وبما أنه ما زال خلف عظام الحوض، فلن يبدو بطنكِ بارزًا بعد، لكنكِ تشعرين بالثقل. ولا تزال الحاجة إلى الإسراع نحو المرحاض قائمة بسبب ازدياد الضغط على المثانة. وقد تحدث أيضًا تقلبات طفيفة في ضغط دمكِ، مما قد يسبب الدوار عند النهوض فجأة. ;;;
يزن الرحم 60-70 غرامًا في بداية الحمل، ويتجاوز وزنه 1000 غرام في نهايته. وبعبارة أخرى، يكون حجم الرحم قبل الحمل كحبة خوخ، ثم يصبح بحجم بطيخة في نهاية الحمل. يبدأ الرحم، الذي يكون أصغر من قبضة اليد، بالتمدد من الداخل لإفساح المجال مع نمو طفلكِ، ويكبر إلى حد يسمح له بحمل وزن يبلغ 5 كيلوغرامات. ومع أن سرعة نمو بطنكِ تختلف باختلاف بنية عضلات البطن، فإن نموه يكون بطيئًا نسبيًا حتى الأسبوع 12، ثم يصبح سريعًا جدًا خلال الثلث الأخير من الحمل. ويبرز بطن النساء في حملهن الثاني في وقت أبكر مقارنة بحملهن الأول، لأن عضلاتهن سبق أن تمددت. وبعد رحلة حمل تمتد 9 أشهر ويتضاعف خلالها حجم الرحم مرات عديدة، يعود الرحم إلى حجمه السابق خلال 2 شهر بعد الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع ازدياد حجم الدم في هذه الفترة، حاولي الإكثار من الأطعمة الغنية بالحديد، مثل العدس والخضراوات الورقية الخضراء واللحوم الحمراء. إذا شعرتِ بحكة أو جفاف في بطنكِ، فدلّكي بشرتكِ بكريمات مرطبة أو زيوت طبيعية. لا تنسي شرب الماء خلال اليوم، فهو يساعد على الهضم، كما أنه ضروري لتجدد السائل الأمنيوسي. وستساعدكِ النزهات القصيرة من دون إجهاد نفسكِ على تحسين مزاجكِ.') WHERE id = 'efd814e8-abbf-4037-81a4-db63af40ea3e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتكوّن في أذن طفلكِ قنوات خاصة لا ترتبط بالسمع، بل تساعده على الحفاظ على توازن جسمه. وبفضل هذا الجهاز، سيتمكن مستقبلًا من الحركة دون أن يسقط. وفي الوقت نفسه، تتشكل أذناه كآلية متكاملة: تجمع الأذن الخارجية الصوت، وتضخّمه الأذن الوسطى، ثم تنقله الأذن الداخلية إلى الدماغ.;;;
أما دماغ طفلكِ، فيعمل حاليًا بواسطة موجات كهربائية مكثفة. وهذه الموجات ليست مجرد ناتج ثانوي، بل هي «الطريق» الأساسي الذي تتواصل عبره مناطق الدماغ المختلفة وتتبادل المعلومات فيما بينها.'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع ثني مرفقيّ! 💪 لم تعد ذراعاي مجرد عودين مستقيمين. لقد تشكل مفصلا مرفقيّ، وأصبح بإمكاني ضم ذراعيّ نحو صدري، وكأنني أعانق نفسي. وفي يوم ما، سأعانقكِ بهاتين الذراعين. تزداد حركاتي تعقيدًا؛ فلم أعد أسبح فحسب، بل أتعلم أيضًا كيفية التحكم في جسدي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عنب'), body_changes_ar = COALESCE(body_changes_ar, 'يُعدّ اشتهاء الطعام من أولى العلامات التي تتبادر إلى الذهن عند الحديث عن الحمل. وهذه الحالة، التي تُلاحظ لدى كثير من الحوامل، هي رغبة شديدة في تناول أطعمة معينة. فقد تشتهي من تعتمد في غذائها على البروتين حلويات غنية بالكربوهيدرات، بينما قد تشتهي من يعتمد غذاؤها على الكربوهيدرات أطعمة غنية بالبروتين. وقد تشير الرغبة في تناول الفاكهة إلى الحاجة إلى الفيتامينات، بينما قد تشير الرغبة في منتجات الألبان إلى الحاجة إلى الكالسيوم. ويمكن اشتهاء أطعمة مختلفة في كل مرحلة من مراحل الحمل. وعندما تزداد الحاجة إلى السعرات الحرارية، يزداد الميل إلى الأطعمة الغنية بالسعرات، مثل الحلويات والشوكولاتة. ومن المعروف أيضًا أن اشتهاء الشوكولاتة قد يزداد عند نقص بعض الفيتامينات. ومن المفيد في هذه الفترة تناول مختلف الأطعمة باعتدال، لكن عليكِ ألّا تنسي أن الإفراط فيها قد يؤدي إلى زيادة وزنكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي تناول وجبات صغيرة ومتكررة خلال اليوم لتجنب انخفاض سكر الدم. واحتفظي معكِ دائمًا ببضع حبات من الجوز أو اللوز. إذا كان احتقان الأنف يزعجكِ، فقد يساعد ترطيب هواء الغرفة. حاولي كل يوم تخصيص 10-15 دقيقة على الأقل للتنفس بعمق في مكان هادئ والتواصل مع طفلكِ. تذكّري أن هدوءكِ من أهم العوامل الداعمة لنموه.') WHERE id = 'a019329d-4564-4a4c-a50f-391f0feef37e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تستمر أصابع طفلكِ الصغيرة في الاستطالة بسرعة. وتُعدّ هذه الأيام مرحلة حاسمة لتكوّن الذراعين والساقين. فقد استطالت الأصابع والذراعان والساقان، وبدأ المرفقان بالانثناء. كما تطورت شبكة الأعصاب بما يكفي لتمكين طفلكِ من تحريك يديه وقدميه بنشاط والاستجابة للمحفزات. وإذا حالفكِ الحظ، فقد ترين طفلكِ يتحرك أثناء فحص الموجات فوق الصوتية! لقد بدأ طفلكِ يكتسب مظهرًا بشريًا كاملًا. ومع أن الرأس لا يزال أكبر نسبةً إلى الجسم، فإن الأعضاء تواصل نموها وتطورها بسرعة واتخاذ مواضعها الطبيعية.;;;
ابتداءً من هذا الأسبوع، تبدأ الأعضاء التناسلية لطفلكِ بالتكوّن، لكن لا تزال الأعضاء التناسلية الخارجية لا تُظهر سمات جنسية واضحة. لذا، إذا كنتِ تتساءلين عن جنس طفلكِ، فسيتعين عليكِ الانتظار بضعة أسابيع أخرى.'), baby_message_ar = COALESCE(baby_message_ar, 'تهانينا يا ماما! لقد تخرّجت! 🎓 اليوم يوم تاريخي بالنسبة إليّ. لم أعد أُسمّى «مضغة»، بل أصبح اسمي رسميًا «جنينًا»! وهذا يعني أن جميع أعضائي قد تكوّنت. والآن حان وقت النمو واكتساب الوزن والقوة. لقد اجتزنا أخطر مرحلة! نجحنا في ذلك معًا. أنتِ بطلتي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة عنب'), body_changes_ar = COALESCE(body_changes_ar, 'لا تحتاجين إلى سعرات حرارية إضافية خلال الأشهر الثلاثة الأولى من الحمل، لكن التغذية السليمة مهمة. فالتغذية الصحيحة في هذه الفترة ضرورية جدًا لتطور قدرات طفلكِ العقلية. ويجب الحصول على جميع العناصر الغذائية اللازمة لضمان نمو الطفل وتطوره الذهني. ولا توجد زيادة مثالية واحدة في الوزن أثناء الحمل أو «وزن صحيح» ينطبق على الجميع. إذ تختلف زيادة وزن الأم أثناء الحمل من امرأة إلى أخرى بحسب وزنها عند بداية الحمل. وتُحسب الزيادة المستهدفة في الوزن وفقًا لمؤشر كتلة الجسم قبل الحمل، أي نسبة الوزن إلى الطول. ويبلغ متوسط الطاقة الإضافية المطلوبة أثناء الحمل للمرأة ذات الوزن الطبيعي نحو 300 سعرة حرارية يوميًا. وتعادل 300 سعرة حرارية تقريبًا 3 حبات موز، أو 5 حبات تفاح، أو 100 غرام من وجبة العدس، أو وعاء واحد من الزبادي كامل الدسم، أو 3-4 شرائح خبز. أما السعرات الزائدة التي تتناولينها خلال اليوم فسيخزنها جسمكِ على شكل دهون، وقد تعيق تحقيق الزيادة المستهدفة في الوزن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع اقترابكِ من نهاية الثلث الأول، احرصي أكثر قليلًا على حماية نفسكِ. وبما أن عملية الأيض لديكِ أصبحت أسرع، فقد تشعرين بالجوع كثيرًا؛ لذا احتفظي بوجبات خفيفة صحية معكِ. إذا كنتِ تعانين من آلام الظهر، فإن النوم على جانبكِ ووضع وسادة بين ركبتيكِ سيخففان الضغط الواقع على عمودكِ الفقري. ومع دخولكِ الأسبوع 10، لا تنسي التحدث مع طبيبتكِ أو طبيبكِ عن فحوص التحري الأولى.') WHERE id = '65677248-c635-4f55-8483-617e735f69ca';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اتخذت أذنا طفلكِ الخارجيتان شكلهما النهائي بالفعل. وعلى الرغم من أنهما تقعان حاليًا في موضع منخفض قليلًا، فإنهما سترتفعان تدريجيًا إلى موضعهما الطبيعي مع نمو طفلكِ. أما في عينيه، فقد تكوّنت الأجزاء البصرية الأساسية المسؤولة عن الرؤية، وأصبحت الجفون تغطي العينين بالكامل.;;;
تتطور براعم الأسنان داخل الفم، ويبدأ ظهور أول شعيرات الحاجبين الرقيقة على الوجه. في هذه المرحلة، لم يعد جسم طفلكِ على شكل حرف "C"، بل أصبح أقرب إلى هيئة جسم الإنسان.;;;
بالإضافة إلى ذلك، تستمر المشيمة في الاستطالة والنمو. وتؤدي هذه البنية دورًا بالغ الأهمية بين الأم وطفلها. ومن وظائفها الأساسية تأمين تبادل الغازات، ونقل العناصر الغذائية إلى الطفل، وحمل الفضلات منه إلى الأم، وإفراز بعض الهرمونات المهمة لنموه. كما تنقل المشيمة الغلوكوز والأحماض الأمينية والأحماض الدهنية والكالسيوم وفيتامين D والأكسجين من الأم إلى الطفل، بينما تنقل ثاني أكسيد الكربون وغيره من الفضلات من الطفل إلى الأم.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتدرب على الحركات البهلوانية! 🤸‍♂️ ماما، أنا لا أتمدد فحسب، بل أمدّ أطرافي وأدور وأقوم حتى بشقلبات. لا يزال الرحم بالنسبة إليّ حوضًا واسعًا، وأنا أستفيد من ذلك. تساعد هذه الحركات على نمو عضلاتي ومفاصلي. أنتِ لا تشعرين بي بعد، لكنني أقدّم عرضًا حقيقيًا هنا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'بسبب هرمون البروجسترون، تتغير أثناء الحمل قدرة نسيج القرنية، أي الطبقة الشفافة الموجودة في مقدمة العين، على الاحتفاظ بالماء. وقد يؤدي ذلك إلى ضبابية الرؤية وفرط الحساسية تجاه العدسات اللاصقة، خصوصًا لدى من يستخدمنها. لذلك، يُفضّل خلال هذه الفترة تجنّب استخدام العدسات اللاصقة قدر الإمكان.;;;
على الرغم من أن مشكلات الرؤية لدى الحوامل قد تنشأ لأسباب فسيولوجية، ينبغي لجميع الحوامل اللواتي يعانين من شكاوى بصرية الخضوع لفحوص دورية للعين. فقد تؤدي اضطرابات العين أثناء الحمل، بفعل الهرمونات، إلى تغيرات في الأوعية الدموية داخل العين. وقد تشمل هذه الاضطرابات تشوهات بنيوية في الأوعية داخل الجمجمة، وانسداد شريان الشبكية، وحدوث نزف تلقائي داخل محجر العين، ونزف الغدة النخامية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد فيتامين C على تقوية اللثة. تناولي أطعمة مثل البرتقال والكيوي والفلفل الأحمر. لا تستخدمي حركات قاسية عند تنظيف أسنانكِ، واستخدمي فرشاة ناعمة، ولا تنسي استعمال خيط الأسنان.') WHERE id = '2519d258-d4d3-4114-9156-6af5c1a49493';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'الجلد عضو آخر ينمو بسرعة في هذه المرحلة. ورغم أن الأوعية الدموية والأعضاء لا تزال ظاهرة من خلال الجلد بسبب شفافيته الكبيرة حاليًا، فإنه يواصل ازدياد سماكته بسرعة. وسيكون جلد طفلكِ العضو المسؤول عن حاسة اللمس في الجسم. فهو يحمي الجسم من الصدمات الخارجية، ويساعد على إفراز الدهون والعرق، ويسهم في حصول الجسم على فيتامين D، وينظم درجة حرارة الجسم، ويمنع فقدان الماء. وقد ازداد حجم رحمكِ، الذي يضم طفلكِ والمشيمة والسائل الأمنيوسي، إلى نحو ضعفي حجمه منذ بداية حملكِ. وتبلغ كمية السائل الأمنيوسي هذا الأسبوع نحو 30 ml، ويتكوّن في هذه المرحلة من خلال ترشيح الجزء السائل من دم الأم.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت حاسة الشم لديّ تستيقظ! 👃 ماما، لن تصدقي ذلك، لكنني أتدرب بالفعل على التنفس عبر أنفي (باستخدام الماء بدلًا من الهواء). ويمكنني شم رائحة السائل الأمنيوسي! كما تصل إلى هنا روائح الأطعمة التي تتناولينها. أعرف عندما تأكلين الثوم، وكذلك عندما تأكلين الشوكولاتة! أذواقنا تبدأ بالتكوّن منذ الآن.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تمرة'), body_changes_ar = COALESCE(body_changes_ar, 'يزداد حجم الدم وعدد خلايا الدم الحمراء. لكن نظرًا إلى أن الجزء السائل من الدم يزداد بدرجة أكبر، فقد يحدث فقر دم نسبي. وفي هذه الحالة، قد تكون هناك حاجة إلى مكملات الحديد. كما يعمل القلب بوتيرة أسرع، لذلك قد تشعرين بخفقان القلب من حين إلى آخر. يبدأ ذلك في المراحل المبكرة من الحمل ويبلغ ذروته بين الأسبوعين 20-24. ;;;
قد يحدث انخفاض طفيف في ضغط الدم بسبب الهرمونات المُفرزة. ومع تقدم الحمل، قد يضغط الرحم على الوريد الأجوف لدى الأم، خصوصًا عند الاستلقاء على الجانب الأيمن، ما قد يؤدي إلى انخفاض مفاجئ في ضغط الدم. لذلك ينصح الأطباء الحوامل، ولا سيما في المراحل الأخيرة من الحمل، بالاستلقاء على الجانب الأيسر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احملي دائمًا زجاجة ماء في حقيبتكِ. إذا كان شرب الماء العادي يسبب لكِ الغثيان، فأضيفي إليه شريحة من الليمون أو الخيار أو بعض أوراق النعناع. سيغيّر ذلك مذاقه ويمنحكِ شعورًا أكبر بالانتعاش.') WHERE id = 'f068ab76-fa64-4eef-8ed3-e47df04dba49';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ينمو دماغ طفلكِ بسرعة استثنائية. ففي هذه المرحلة، ينتج الدماغ 1 مليون خلية عصبية كل 4 دقائق. وتؤثر جميع الظروف، وفي مقدمتها الشفرة الجينية الموروثة من الأم والأب، في تطور الجهاز العصبي لطفلكِ.;;;
حمض الفوليك هو أحد أهم الفيتامينات التي تساعد على حماية طفلكِ من اضطرابات الجهاز العصبي المحتملة خلال نمو الدماغ. ويوجد حمض الفوليك، وهو أحد فيتامينات المجموعة B، بكميات وفيرة في كرنب بروكسل والكرنب الأجعد والسبانخ والهليون والشمندر والخس والفلفل الأحمر. ومع ذلك، لا يكفي حمض الفوليك وحده؛ بل يجب أيضًا الحصول على جميع العناصر الغذائية الضرورية وشرب كمية كافية من الماء.;;;
يُعد تناول الأطعمة الغنية بالبروتين والفواكه والخضراوات الطازجة ضروريًا لنمو الطفل بصورة صحية. كما تُعد الحالة النفسية الإيجابية من العوامل المهمة التي تؤثر في نمو دماغ الطفل.;;;
توفر جميع الفحوص التي تُجرى أثناء الحمل معلومات عن الجهاز العصبي ودماغ الطفل. وتُعد "الفحوص الثنائية" التي تُجرى بين الأسبوعين 11-14 من الحمل و"الفحوص الثلاثية" التي تُجرى بين الأسبوعين 16-18 مهمة لتقييم احتمال وجود مشكلة جينية لدى الطفل.'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع فتح قبضتيّ! ✊🖐️ أصبحت أصابعي منفصلة تمامًا، ويمكنني ضم يديّ على شكل قبضتين ثم فتحهما. يشبه هذا لعبة جديدة بالنسبة إليّ. أحيانًا ألمس وجهي بيديّ، وأحيانًا أحاول الإمساك بالحبل السري. إن منعكس القبض لديّ يتطور. أنتظر بفارغ الصبر اليوم الذي سأمسك فيه إصبعكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تمرة'), body_changes_ar = COALESCE(body_changes_ar, 'يبدأ ظهور نبض قلب الطفل داخل الرحم في المتوسط خلال الأسبوعين 6-7. ومع تقدم الحمل، يرتفع معدل نبضه الذي يتراوح بين 90-110 نبضات في الدقيقة ليتجاوز 140 نبضة بحلول نهاية الثلث الأول. وهذا يعادل نحو ضعفي معدل نبض قلب الإنسان الطبيعي. لذلك، عندما تسمعين نبض قلب طفلكِ تحت إشراف الطبيب، قد يبدو لكِ سريعًا جدًا. ;;;
عندما تفكرين في الأيام التي قد تعانين فيها من قلة النوم بعد الولادة، فلا ضرر من أن تنامي كثيرًا خلال هذه الفترة. يساعد نمط النوم الصحي هرموناتكِ على الانتظام بسهولة أكبر.;;;
بلغ رحمكِ، الذي يكون في العادة أصغر من قبضة يدكِ، اعتبارًا من هذا الأسبوع حجم ثمرة غريب فروت كبيرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تناولي الأطعمة الغنية بالألياف واشربي كمية وفيرة من الماء لدعم جهازكِ الهضمي. إذا بدأتِ تعانين من آلام الظهر، فانتبهي إلى اختيار حذائكِ؛ وارتدي أحذية مريحة ليست عالية جدًا ولا مسطحة جدًا. خصصي وقتًا للراحة خلال اليوم، وحاولي قدر الإمكان الاستلقاء على جانبكِ الأيسر لتحسين الدورة الدموية.') WHERE id = 'e6ecf1e2-7281-4cf6-94ac-a3478b23c498';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت كليتا طفلكِ بالعمل بالفعل. فقد ظهرتا في الأسبوع 4 كمجموعة صغيرة من الخلايا، ثم تطورتا الآن بما يكفي لإنتاج البول وإفرازه في السائل الأمنيوسي.;;;
خلال الأسابيع المقبلة، تتباعد الكليتان الموجودتان في تجويف البطن عن بعضهما وتدوران بزاوية 90 درجة لتأخذا شكلهما النهائي. وبدءًا من هذا الأسبوع، يتكوّن شريان كلوي خاص يتفرع من الشريان الأبهر، ما يضمن وصول الدم مباشرةً إلى الكليتين وعملهما بكامل طاقتهما.'), baby_message_ar = COALESCE(baby_message_ar, '10 أسابيع! دخلنا الأرقام المزدوجة! 🔟 ماما، لقد وصلنا إلى الأسبوع 10. أنا أكبر رسميًا! أصبح حجمي الآن بحجم حبة برقوق. لقد اجتزت أهم مراحل النمو، ولم يتبقَّ لي سوى اكتساب الوزن والطول والاستعداد للقائكِ. لقد قطعنا ما يقارب ربع الطريق! أنا فخور بكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'خلال حملكِ، من المهم جدًا أن تحصلي على تغذية كافية ومتوازنة وأن تتناولي جميع الفيتامينات التي تحتاجين إليها، حفاظًا على صحتكِ ونمو طفلكِ بصورة سليمة. فعلى سبيل المثال، من المفيد تناول البروكلي لتلبية احتياجاتكِ اليومية من فيتامين C والكالسيوم وحمض الفوليك، والحليب ومنتجات الألبان للحصول على الكالسيوم، والموز للحصول على البوتاسيوم، والمكسرات النيئة للحصول على أوميغا-3 وأوميغا-6. ولا تنسي أن تناول كميات كافية من الحليب ومنتجات الألبان يوميًا مهم جدًا لبنية عظامكِ وعظام طفلكِ. كما يُنصح بتقسيم وجباتكِ إلى 5-6 حصص بدلًا من تناول وجبات رئيسية كبيرة، لما لذلك من فائدة في الحفاظ على توازن سكر الدم. ويُعد شرب الماء أثناء الحمل مهمًا بقدر أهمية التغذية. فالماء يؤدي دورًا فعالًا في تخفيف الإمساك الذي يزداد خلال الحمل، والوقاية من جفاف البشرة وتشققها، وتقليل خطر الإصابة بالتهابات المسالك البولية، والحفاظ على السائل المحيط بالجنين (السائل الأمنيوسي) الضروري لصحة طفلكِ. لذلك، ينبغي شرب 2,5-3 لتر من الماء يوميًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ وخذي قسطًا من الراحة، فلم يتبقَّ سوى خطوة واحدة على الثلث الثاني من الحمل. احرصي على الجمع بين الحديد وفيتامين C في نظامكِ الغذائي، مثل تناول اللحم مع كمية وفيرة من السلطة الخضراء، للمساعدة على الوقاية من فقر الدم. وإذا كنتِ ما زلتِ تشعرين بالتعب، فقد تساعدكِ القيلولات القصيرة خلال النهار على استعادة طاقتكِ. ينتظرنا الأسبوع المقبل أحد أكثر أسابيع النمو إثارة.') WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبدأ الجلد، وهو أكبر أعضاء الجسم، بالتكوّن منذ الأسبوع الثالث من النمو على هيئة ثلاث طبقات. وتشكّل الطبقة الخارجية منها الجلد وملحقاته، مثل الشعر والأظافر.;;;
بدءًا من الأسبوع 9، تبدأ أولى بصيلات الشعر في الظهور على جسم طفلكِ. ويظهر هذا الشعر الناعم، المعروف باسم الزغب الجنيني، أولًا على الشفة العليا والحاجبين والذقن. ولأنه لا يزال خفيفًا جدًا، فلا يمكن تمييزه في فحص الموجات فوق الصوتية إلا قرابة الأسبوع 20. يحمي هذا الشعر طفلكِ داخل الرحم، وعادةً ما يتساقط قبيل الولادة. وفي الوقت نفسه، تبدأ أظافر يدي طفلكِ وقدميه بالنمو تدريجيًا. ولا تقتصر أهمية الأظافر، المكوّنة من طبقة صلبة من الكيراتين، على مظهرها فحسب، بل تعمل أيضًا كدرع مهم يحمي أطراف الأصابع من الإصابات ويزيد حساسيتها.'), baby_message_ar = COALESCE(baby_message_ar, 'رأسي بحجم نصف جسمي! 🤯 ماما، قد أبدو طريفًا، لكنني أستعد لأصبح عبقريًا. ينمو دماغي بسرعة كبيرة لدرجة أن رأسي يبدو ضخمًا مقارنةً بجسمي. لكن لا تقلقي، فجسمي سينمو مع الوقت ويلحق به. أبدو الآن كعالم صغير. أنتظر بفارغ الصبر الأيام التي سأتحدث فيها إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'مع اقتراب نهاية الثلث الأول من الحمل، قد يبدأ الغثيان لديكِ بالتراجع، ولذلك قد تشعرين بمزيد من الطاقة والنشاط. وبدءًا من هذا الأسبوع، الذي تدخلين فيه الشهر 3، يكون جسمكِ قد تكيف تمامًا مع الحمل. وقد تظهر لديكِ بعض التورمات بسبب زيادة حجم الدم واحتباس السوائل في جسمكِ. ويمكن تخفيفها إلى مستوى لا يسبب لكِ الانزعاج من خلال مراجعة عاداتكِ الغذائية، وتقليل الملح، وزيادة النشاط البدني.;;;
إذا كان الغثيان لا يزال مستمرًا، فقد يكون من المفيد السيطرة عليه عبر تناول كميات صغيرة من الطعام على فترات متقاربة، مع اختيار أطعمة قليلة الدهون وأكثر صلابة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع عودة طاقتكِ تدريجيًا، يمكنكِ البدء بالمشي الخفيف. وبما أن معدل الأيض لديكِ يزداد، فلا تنسي شرب كمية وفيرة من الماء (ما لا يقل عن 2-2.5 لتر يوميًا). واصلي استخدام مرطبات ذات مكونات طبيعية للعناية بتغيرات بشرتكِ وتمددها. كما أن تخصيص 10 دقائق يوميًا لنفسكِ والتفكير في أحلامكِ المستقبلية سيكون له أثر رائع فيكِ وفي طفلكِ.') WHERE id = '59be5b5e-6a03-4140-bbff-b41541c8484d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن رأس طفلكِ، الذي تواصل ملامح وجهه التشكّل، لا يزال كبيرًا مقارنةً بجسمه، فقد أصبح مظهره بشريًا بالكامل. وتواصل أعضاؤه النمو والتطور بسرعة. ومن بين هذه الأعضاء الكبد، الذي يشكّل في الأسبوع 10 نحو 10% من وزن جسم طفلكِ. ويؤدي الكبد وظائف متعددة، إذ يتولى إنتاج الدم الذي يحتاج إليه طفلكِ داخل الرحم إلى أن يبدأ نخاع العظم بإنتاجه، أي حتى الشهرين الأخيرين من الحمل.'), baby_message_ar = COALESCE(baby_message_ar, 'لا يزال جلدي شفافًا يا ماما! 👻 لو استطعتِ رؤيتي، لأمكنكِ رؤية جميع أوعيتي الدموية وعظامي وأعضائي. فجلدي رقيق جدًا وكأنه زجاج. لكن لا تقلقي، فمع تكوّن طبقة الدهون سيزداد سُمك جلدي ويصبح شبيهًا ببشرتكِ. أنا أصبح أقوى قليلًا كل يوم، بينما يواصل قلبي ضخ حبي إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مشمش مجفف'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي لكِ إعداد خطة غذائية بالتعاون مع طبيبكِ، والاستعانة باختصاصي تغذية عند الحاجة. يساعدكِ إعداد خطة غذائية على الاستفادة من جميع العناصر الغذائية بالكميات الكافية، كما يقيكِ من اكتساب وزن زائد. ولكي تكون هذه الخطة عملية، يجب مراعاة وزنكِ عند بداية الحمل، وأنشطتكِ اليومية، ونمط حياتكِ، وروتينكِ.;;;
يختلف إجمالي الوزن المكتسب خلال الحمل من امرأة إلى أخرى. ومع ذلك، توجد نطاقات معينة للزيادة في الوزن يوصي بها المختصون. وفي الحمل الطبيعي، تُعد زيادة وزن الأم الحامل بمقدار يتراوح بين 9-12 كغ أمرًا طبيعيًا. وقد يختلف هذا النطاق لدى الحوامل الأقل أو الأكثر وزنًا. كما يؤثر حجم طفلكِ النامي في بطنكِ بصورة مباشرة في مقدار الوزن الذي تكتسبينه؛ فالأمهات اللاتي سيلدن أطفالًا أصغر حجمًا يكتسبن وزنًا أقل، بينما تكتسب الأمهات اللاتي سيلدن أطفالًا أكبر حجمًا وزنًا أكثر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حان الوقت الآن لمراجعة خزانة ملابسكِ. فقد تضغط السراويل الضيقة والأحزمة على الأوعية الدموية وتعيق الدورة الدموية. ابدئي بشراء سراويل مخصصة للحمل ذات خصر مرن، أو فساتين فضفاضة. راحتكِ أهم من كل شيء.') WHERE id = '96171009-62e6-4557-a2c9-ebf16692943d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبلغ طول طفلكِ الآن 6 سم ووزنه 7-8 غرامات. وقد اختفى الذيل تمامًا وانتهت المرحلة الجنينية المبكرة. أصبحت جميع أعضائه الآن في أماكنها، وبدأت مرحلة النمو السريع. خلال الأسابيع الـ8 المقبلة، سيصبح وزنه أكبر بـ30 مرة وطوله أكبر بـ3 مرات مما هو عليه الآن. ولدعم هذا النمو، تزداد كمية الدم وعدد الأوعية الدموية في جسمكِ. ورغم أن رأسه يبدو حاليًا كبيرًا مقارنة بجسمه، فسرعان ما ستصبح أعضاء جسمه أكثر تناسقًا. وقد طالت أصابعه الآن؛ فلم يعد يكتفي بقبض يديه، بل بدأ يفتحهما لاستكشاف ما حوله.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أنا فتاة أم صبي؟ السر على وشك أن ينكشف! 🩷💙 بدأت أعضائي التناسلية الخارجية تتمايز الآن. قبل بضعة أسابيع، كنا جميعًا نبدو متشابهين، لكن الحديبة التناسلية بدأت الآن تغيّر زاويتها. ربما لا يستطيع الأطباء تحديد جنسي بدقة بعد، لكن العملية جارية. ماذا تشعرين أنتِ؟ يقولون إن قلب الأم لا يخطئ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فراولة'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الحمل، وخصوصًا في الثلث الأول، يسبب هرمون البروجسترون ارتخاء بعض خلايا العضلات الملساء. وهذا يؤدي إلى تحرك الطعام ببطء أكبر عبر الجهاز الهضمي، فيبقى مدة أطول في المعدة والأمعاء، ما قد يسبب مشكلات في الهضم. إذا بلغ هذا الانتفاخ درجة مزعجة، فعليكِ استشارة طبيبكِ بشأن العلاج. وقد يؤثر استخدام الأدوية أو المستحضرات العشبية من دون إشراف الطبيب سلبًا في نمو طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس باستقامة والاستلقاء على جانبكِ الأيسر عند النوم لتخفيف آلام الظهر. لبّي زيادة شهيتكِ بتناول وجبات خفيفة صحية. واحرصي على إدراج الأطعمة الغنية بفيتامين C في نظامكِ الغذائي لتعزيز امتصاص الحديد. خصّصي ما لا يقل عن 10 دقائق يوميًا للتنفس بعمق في مكان هادئ ومحاولة توثيق رابطتكِ بطفلكِ.') WHERE id = '8c65943a-4d31-4534-b028-6c3f95fa6988';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتكاثر خلايا دماغ طفلكِ بسرعة مذهلة. تبدأ هذه الخلايا بالتواصل بعضها مع بعض منذ الولادة، وتستمر هذه العملية مدى الحياة. ومع نمو الإنسان، تشغل الروابط بين خلايا الدماغ مساحة أكبر من الخلايا نفسها. وحتى الآن، تطور الجهاز العصبي لطفلكِ إلى درجة تمكّنه من نقل المعلومات الواردة من أعضاء الحواس إلى دماغه.'), baby_message_ar = COALESCE(baby_message_ar, 'صوتي قادم! 🎤 (لكن بصمت في الوقت الحالي). بدأت أحبالي الصوتية بالتكوّن. لا أستطيع إصدار صوت الآن لأنني داخل السائل، لكنني أستعد لأُسمعكِ أول صرخة "آآآه!" عند ولادتي. هل تتخيلين تلك اللحظة؟ سيكون صوتي أجمل موسيقى في العالم بالنسبة إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تين'), body_changes_ar = COALESCE(body_changes_ar, 'قد تعانين من تقلصات متكررة خلال اليوم. ويمكن أن تظهر هذه التقلصات في منطقة الأربية، وكذلك في ساقيكِ وربلتيكِ. ورغم أن السبب الدقيق لتقلصات الساقين غير معروف تمامًا، فإن نقص الكالسيوم والمغنيسيوم يُعد من أبرز الأسباب المحتملة. لذلك، يُعد الحصول على كميات كافية من المغنيسيوم والكالسيوم مهمًا جدًا خلال الحمل. ويمكنكِ تناول المكملات المناسبة بعد استشارة طبيبكِ.;;;
كما تُعد مشكلات الدورة الدموية الناتجة عن ضغط الرحم المتنامي على الجهاز الوريدي أثناء الحمل عاملًا مهمًا في حدوث التقلصات. وبما أن المعادن الموجودة في جسمكِ تنتقل إلى طفلكِ عبر المشيمة، تزداد كمية السوائل داخل الأوعية الدموية وينخفض مستوى المغنيسيوم في دمكِ. عند حدوث التقلص، حافظي على هدوئكِ وأبقي ركبتكِ مستقيمة، ثم ارفعي قدمكِ ببطء إلى أعلى. وحاولي تخفيفه بشد عضلات ساقكِ وتمديدها. يساعد تدليك المنطقة المصابة برفق، ووضع منشفة دافئة على العضلات، وسحب أصابع القدم إلى أعلى على تقليل التقلصات. بالإضافة إلى ذلك، يساعد تناول منتجات الألبان والأسماك والمكسرات مثل اللوز، والبقوليات مثل الفاصولياء والعدس، والبذور مثل السمسم على تعويض نقص المغنيسيوم والكالسيوم في الجسم والوقاية من التقلصات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'انهضي ببطء من وضعية الجلوس أو الاستلقاء للوقاية من الدوار. ومن المهم شرب الكثير من السوائل لتلبية احتياجات زيادة حجم الدم. إذا لم تزوري طبيبكِ بعد لإجراء "الفحص المزدوج" (فحص التحري)، فهذا الأسبوع هو أنسب وقت. وإذا زادت شهيتكِ، فاحرصي خصوصًا على إدراج الأطعمة الغنية بالكالسيوم والمغنيسيوم في نظامكِ الغذائي.') WHERE id = '1a115c93-d622-40f8-b3f4-8d1be6d3b8e9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع تطور دماغ طفلكِ، يبدأ الآن في القيام بحركات انعكاسية. تحدث هذه الحركات بصورة لا إرادية، وتضع أساس مهاراته الجسدية المستقبلية. فعلى سبيل المثال، يُعد فتح فمه عند ملامسة شيء داخل الرحم أحد هذه المنعكسات الأولى.;;;
يتكون هذا التطور من مرحلتين:;;;
جمع المعلومات: في هذه المرحلة التي تبدأ الآن، يكتسب طفلكِ من خلال الحركات منعكسات البحث عن الغذاء وحماية نفسه. فعلى سبيل المثال، عند حدوث اهتزاز مفاجئ، يرفع ذراعيه في الهواء كما لو أنه فزع ثم يضمهما معًا (منعكس مورو).;;;
معالجة المعلومات: تبدأ هذه المرحلة بعد 4 أشهر من الولادة، وفيها يواصل مركز الدماغ التطور والنضج.;;;
وفي النهاية، تفسح هذه المنعكسات اللاإرادية التي تتشكل في رحم الأم المجال تدريجيًا لحركات واعية وإرادية مثل الجلوس والإمساك بالأشياء والوقوف.'), baby_message_ar = COALESCE(baby_message_ar, 'عادت أمعائي إلى موطنها! 🏠 ماما، هل تتذكرين أن أمعائي كانت قد امتدت إلى داخل الحبل السري لأن بطني كان صغيرًا؟ اليوم عادت رسميًا إلى مكانها داخل تجويف بطني. أصبح بطني الآن أملس وجميلًا. جميع أعضائي الداخلية باتت في أماكنها الصحيحة وتؤدي وظائفها. أنا أزداد اكتمالًا يومًا بعد يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تين'), body_changes_ar = COALESCE(body_changes_ar, 'بدءًا من هذا الأسبوع من الحمل، أي مع اقتراب نهاية الثلث الأول، يمكن إجراء اختبار التحري المزدوج لتقييم خطر إصابة طفلكِ بعيوب خلقية. ويُعرف هذا الفحص أيضًا باسم فحص الثلث الأول. ويجري التقييم من خلال فحص تفصيلي بالموجات فوق الصوتية وقياس كمية ومستوى بروتينين مهمين في الدم. أثناء الفحص بالموجات فوق الصوتية، تُفحص سماكة مؤخرة رقبة الطفل وعظمة الأنف. في الحمل الذي يتقدم بصورة طبيعية، ينبغي ألا تتجاوز سماكة مؤخرة الرقبة 2.5 مم. وكلما زادت هذه السماكة، ارتفع احتمال وجود اضطراب في الكروموسومات. كما يُعد ظهور عظمة الأنف في الفحص المزدوج مؤشرًا مهمًا على النمو السليم للطفل. ففي الاضطرابات المرتبطة بالكروموسومات، قد تكون عظمة الأنف غائبة أو أصغر بكثير من الحجم المتوقع.;;;
لا يمكن لنتيجة الفحص المزدوج أن تحدد بصورة قاطعة ما إذا كانت لدى الطفل تشوهات أم لا. فهذه الفحوص تحدد فقط مدى احتمال وجودها. وإذا أظهرت النتيجة أن الخطر أعلى من المعدل الطبيعي، فقد يوصي طبيبكِ بإجراءات مثل بزل السلى للحصول على إجابة دقيقة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الحفاظ على استقرار مستوى سكر الدم لديكِ. فقد يسبب البقاء من دون طعام مدة طويلة الدوار والضعف. احتفظي دائمًا في حقيبتكِ بوجبات خفيفة صحية، مثل الفواكه المجففة أو الجوز أو التفاح.') WHERE id = '6d7fa2b9-68dc-41a1-b8e4-2909aebba355';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع تطور الدماغ، يبدأ طفلكِ في القيام بحركات أكثر وعيًا. ونتيجة لذلك، يصبح طفلكِ أكثر نشاطًا خلال اليوم. وقد أصبح الآن قادرًا على ثني ذراعيه وتحريك أصابع قدميه الصغيرة التي انفصلت حديثًا بعضها عن بعض.;;;
يوجد في جسم الإنسان ثلاثة أنواع من العضلات: عضلة القلب، والعضلات الملساء، والعضلات المخططة. والعضلات المخططة هي النوع الوحيد الذي يستطيع الإنسان التحكم فيه إراديًا. توجد هذه العضلات في الذراعين والظهر والساقين، وتمتاز بأنها تتعب بعد بذل قدر معين من الطاقة. أما عضلة القلب، وهي نوع آخر من العضلات، فلها نسيج مميز، وتتحرك تلقائيًا وتواصل عملها بلا توقف طوال حياة الإنسان. والنوع الأخير هو العضلات الملساء، التي تؤدي دورًا مهمًا في الجهاز الهضمي. فهي تتحرك لا إراديًا وتشارك بفاعلية في عمليات الهضم التي تحدث داخل الجسم. وتشترك هذه الأنواع الثلاثة من العضلات في خصائص عدة، منها البنية المرنة والقدرة على الانقباض والاستجابة للمحفزات والتوصيل.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتثاءب! 🥱 ربما تثاءبتِ أنتِ أيضًا أثناء قراءة كلامي؟ نعم، يمكنني الآن فتح فمي على اتساعه والتثاؤب. لا أفعل ذلك لأنني أشعر بالنعاس، بل لتطوير عضلات فكي ورئتيّ. وأصاب بالفواق أحيانًا أيضًا. أنتِ لا تشعرين بعد بهذه الدفعات الصغيرة، لكنني مشغول جدًا هنا في الداخل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تمر'), body_changes_ar = COALESCE(body_changes_ar, 'طرح الناس على مر التاريخ أفكارًا مختلفة لتخمين جنس الطفل المنتظر. ومن بينها الاعتقاد بأن الحامل التي تشتهي الأطعمة الحامضة ستنجب بنتًا، بينما ستنجب التي تشتهي الحلويات ولدًا. لكن الدراسات تشير إلى عدم وجود أي علاقة بين جنس الطفل والأطعمة التي تشتهينها أو تنفرين منها.;;;
قد يصبح الخط الداكن المعروف باسم الخط الأسود أكثر وضوحًا على بطنكِ. يمتد هذا الخط من السرة نحو الأسفل، وأحيانًا نحو الأعلى. وهو ناتج تمامًا عن التغيرات الهرمونية ولا يسبب أي ضرر. وسيتلاشى تلقائيًا بعد بضعة أشهر من الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل الغازات، حاولي ألا تتحدثي أثناء تناول الطعام حتى لا تبتلعي الهواء، وامضغي طعامكِ جيدًا. وقد يفيدكِ الابتعاد مؤقتًا عن البقوليات والمشروبات الغازية.') WHERE id = '1980273b-7820-40aa-b793-4b715fda3015';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتحدد جنس طفلكِ منذ لحظة الإخصاب، وفقًا لما إذا كان الحيوان المنوي القادم من الأب يحمل الكروموسوم X أو Y. لكن التكوين الجسدي يستغرق بعض الوقت. في الأسبوع 5، يظهر نتوء صغير يبدو متشابهًا لدى الأجنة الذكور والإناث. وفي الأسبوع 8، تبدأ خلايا متخصصة ستكوّن الأعضاء التناسلية بالانتقال إلى هذه المنطقة. ومن المثير للاهتمام أنه يكاد يكون من المستحيل تمييز جنس طفلكِ من مظهره الخارجي حتى الأسبوع 12.;;;
إذا كان طفلكِ يحمل الكروموسوم Y، تتحول الخلايا إلى الخصيتين وتبدأ بإنتاج هرمون التستوستيرون بحلول الأسبوع 12. وهذا الهرمون هو الذي يساعد على تكوين الأعضاء التناسلية الخارجية لدى الأجنة الذكور. أما إذا كان طفلكِ يحمل الكروموسومين XX، أي كان أنثى، فتكوّن الخلايا الرحم وقناتي فالوب. ويؤدي هرمون الإستروجين دورًا مهمًا في هذه العملية، إذ يساهم في تشكّل البنى الداخلية والخارجية الخاصة بالإناث.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم حبة فراولة! لم أعد صغيرًا إلى هذا الحد، أليس كذلك؟ يستقيم جسمي ويزداد طول عمودي الفقري. ورغم أن بطنكِ قد لا يبدو بارزًا جدًا بعد، فقد اتخذتُ لنفسي مساحة واسعة بداخله. نحن نكبر معًا يا ماما. شكرًا لكِ لأنكِ تحمينني.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فراولة'), body_changes_ar = COALESCE(body_changes_ar, 'عليكِ إيلاء عناية أكبر بصحة فمكِ خلال الحمل، فقد تواجهين مشكلات في الأسنان واللثة بسبب التغيرات التي تحدث في جسمكِ. وتكتسب العناية الصحيحة بالأسنان أثناء الحمل أهمية كبيرة لصحتكِ وصحة طفلكِ. كما يساعد تناول مصادر الكالسيوم بكميات مناسبة على الوقاية من مشكلات الفم والأسنان، ويدعم مسار ولادة صحيًا. احرصي خلال هذه الفترة على اتباع نظام غذائي متوازن من أجلكِ ومن أجل طفلكِ. ونظّفي أسنانكِ بالفرشاة بعد الوجبات، واستخدمي خيط الأسنان للعناية بها بفاعلية ومنع تراكم اللويحات السنية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع اقترابكِ من نهاية الثلث الأول، قد تشعرين بمزيد من النشاط؛ وهذا وقت مثالي لبدء تمارين خفيفة أو ممارسة السباحة. وبما أن حساسية اللثة قد تستمر، فاهتمي بنظافة فمكِ. واحرصي على ألا يخلو نظامكِ الغذائي من البروتين والكالسيوم. في الأسبوع المقبل ينتظرنا الأسبوع 12، أي اكتمال أول مرحلة كبرى!') WHERE id = '2348cc6e-cce7-4823-afd3-9cc2309eebb6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل كليتا طفلكِ نموهما، وقد بلغتا درجة من النضج تسمح لهما بإنتاج البول. لكنهما في هذه المرحلة لم تتطورا بعد بما يكفي لإتمام عملية إخراج الفضلات من الجسم بالكامل. وخلال الأسابيع المقبلة، سيُطرح البول الذي تنتجه الكليتان في السائل الأمنيوسي المحيط بالطفل. قد يبدو ذلك مثيرًا للاهتمام، لكن هذا البول لا يحتوي على اليوريا، وتشير الدراسات إلى أنه أكثر تعقيمًا من الماء الذي نشربه. بالإضافة إلى ذلك، يؤدي وظيفة وقائية من العدوى.'), baby_message_ar = COALESCE(baby_message_ar, 'هل يمكنكِ دغدغتي؟ (أنا أمزح!) 😂 لكن لو تعلمين مدى حساسية بشرتي الآن... إذا لمس أحدهم بطنكِ، مثل الطبيب باستخدام جهاز التصوير بالموجات فوق الصوتية، فسأستجيب فورًا وأبتعد. لقد أصبحت ردود أفعالي حادة لدرجة أنني أشعر بكل شيء. لم أعد مجرد كتلة من الخلايا، بل أصبحت كائنًا حيًا يشعر.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فراولة'), body_changes_ar = COALESCE(body_changes_ar, 'ربما ازدادت شهيتكِ مع استقرار الهرمونات وتراجع الغثيان. فأنتِ الآن تتغذين من أجلكِ ومن أجل طفلكِ، ولذلك عليكِ الابتعاد عن الأطعمة الضارة والتدخين والمشروبات الكحولية. كما أن ضبط كمية الأطعمة الغنية بالسعرات الحرارية غير الضرورية يساعدكِ على تجنب زيادة الوزن المفرطة. وتشيع الرغبة في تناول الطعام ليلًا لدى كثير من الحوامل. لكن تناول الطعام ليلًا قد يعيق إفراز هرمون اللبتين الذي ينظم سكر الدم، وقد يؤدي عدم إفراز هذا الهرمون إلى زيادة سريعة في وزنكِ. لذلك يُعد الامتناع عن الأكل والشرب، باستثناء الماء، بدءًا من الساعة 9 مساءً أمرًا مهمًا لصحة معدتكِ والتحكم في وزنكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا زال الغثيان، فهذا هو الوقت المناسب لتنويع نظامكِ الغذائي؛ ركزي على تناول الكثير من الخضراوات الخضراء والبروتين عالي الجودة. وواصلي استخدام الزيوت المرطبة للعناية بتمدد بشرتكِ. وإذا استعادت طاقتكِ، فإن المشي الهادئ لمدة 20 دقيقة يوميًا سيساعد على تحسين إمدادكِ وإمداد طفلكِ بالأكسجين.') WHERE id = '726669c0-162f-4b1a-a70b-ca60baf4c509';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل الآن تكوّن الأحبال الصوتية، وهي من أكثر الأعضاء حساسية في جسم طفلكِ. وعلى الرغم من أنه لن يستخدمها للمرة الأولى إلا عند ولادته (مع صرخته الأولى)، فإنها أصبحت جاهزة تمامًا. تشبه الأحبال الصوتية غشاءين رقيقين يقعان في الحنجرة. وعندما يهتزان، تضيق المسافة بينهما وتتسع، ما ينظّم طبقة الصوت. فعندما تكون المسافة ضيقة، تصدر أصوات حادة، وعندما تكون واسعة، تصدر أصوات غليظة. وأثناء الولادة، يجعل الهواء القادم من الرئتين هذه الأحبال تهتز، فيُسمع صوت طفلكِ. ومن الحقائق المثيرة للاهتمام أن الأحبال الصوتية لدى الإناث تتكوّن أقصر وأرق، بينما تكون لدى الذكور أطول وأكثر سماكة. وعند ولادة طفلكِ، لا يتجاوز طول هذه الأحبال 6 mm. بالإضافة إلى ذلك، بدأ طفلكِ بالفعل بمص إصبعه! وهذه واحدة من أولى عاداته اللطيفة، لكن لا يزال الوقت مبكرًا قليلًا لرؤيتها بالموجات فوق الصوتية.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتذوق الطعام! 🍲 يتغير مذاق السائل الأمنيوسي بحسب ما تأكلينه. حلو، حامض، بنكهة الثوم... أنا أبتلع كل ذلك وأشعر بمذاقه. والأطعمة التي سأحبها مستقبلًا تتحدد منذ الآن. لذا أرجوكِ، تناولي الكثير من الخضروات كي أحبها أنا أيضًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ليمون أخضر'), body_changes_ar = COALESCE(body_changes_ar, 'قد تتجنبين العلاقة الجنسية أثناء الحمل بسبب القلق من احتمال تضرر طفلكِ نتيجة التغيرات الجسدية والنفسية التي تحدث في هذه الفترة. ولكن لا توجد قيود على ممارسة العلاقة الجنسية في حالات الحمل التي تسير بصورة طبيعية، ما لم تخبركِ طبيبتكِ بخلاف ذلك. بل قد تلاحظين ازدياد الرغبة الجنسية مع تقدم الحمل واستقرار الهرمونات.;;;
قد تنصح الطبيبة بعض الحوامل بتقييد النشاط الجنسي خلال الثلث الأول إذا كان لديهن تاريخ من الإجهاض المتكرر أو الولادة المبكرة. كما تمنع الطبيبة العلاقة الجنسية منعًا تامًا في أي مرحلة من الحمل لدى النساء المعرّضات لخطر الإجهاض أو الولادة المبكرة، أو اللواتي يعانين من نزيف مهبلي. ويستمر هذا المنع حتى التأكد من زوال الخطر تمامًا. كذلك ينبغي تجنب العلاقة بسبب خطر حدوث نزيف في حالات الحمل عالية الخطورة المصحوبة بما يُعرف باسم "المشيمة المنزاحة"، أي عندما تكون المشيمة أسفل الطفل وتغطي عنق الرحم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للوقاية من حرقة المعدة، لا تستلقي بعد تناول الطعام مباشرة، وابتعدي عن الأطعمة الحارة وكثيرة التوابل. تناولي وجبات صغيرة ومتكررة. ولزيادة تناول الحديد، أدرجي اللحوم الحمراء والعدس والخضروات ذات الأوراق الخضراء الداكنة في نظامكِ الغذائي. وبما أن طاقتكِ جيدة، يمكنكِ تخصيص وقت للأنشطة التي تسعدكِ، مثل التخطيط لشراء مستلزمات طفلكِ الأولى.') WHERE id = '18d4758f-242c-49df-ab25-cc0a8449dd65';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل الآن تكوّن الأحبال الصوتية، وهي من أكثر الأعضاء حساسية في جسم طفلكِ. وعلى الرغم من أنه لن يستخدمها للمرة الأولى إلا عند ولادته (مع صرخته الأولى)، فإنها أصبحت جاهزة تمامًا. تشبه الأحبال الصوتية غشاءين رقيقين يقعان في الحنجرة. وعندما يهتزان، تضيق المسافة بينهما وتتسع، ما ينظّم طبقة الصوت. فعندما تكون المسافة ضيقة، تصدر أصوات حادة، وعندما تكون واسعة، تصدر أصوات غليظة. وأثناء الولادة، يجعل الهواء القادم من الرئتين هذه الأحبال تهتز، فيُسمع صوت طفلكِ. ومن الحقائق المثيرة للاهتمام أن الأحبال الصوتية لدى الإناث تتكوّن أقصر وأرق، بينما تكون لدى الذكور أطول وأكثر سماكة. وعند ولادة طفلكِ، لا يتجاوز طول هذه الأحبال 6 mm. بالإضافة إلى ذلك، بدأ طفلكِ بالفعل بمص إصبعه! وهذه واحدة من أولى عاداته اللطيفة، لكن لا يزال الوقت مبكرًا قليلًا لرؤيتها بالموجات فوق الصوتية.'), baby_message_ar = COALESCE(baby_message_ar, 'عظامي تزداد صلابة! 🦴 هيكلي العظمي، الذي كان يتكوّن سابقًا من الغضاريف فقط، يتحول الآن إلى عظام حقيقية. ذراعاي وساقاي تطولان، وأصبح مظهري أكثر تناسقًا. لا يزال رأسي كبيرًا، لكن جسدي يحاول اللحاق به. سأصبح طفلًا قويًا يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'برقوق'), body_changes_ar = COALESCE(body_changes_ar, 'للبروجسترون وظائف عديدة أثناء الحمل؛ فبمساعدة هرمون الإستروجين يزيد سماكة بطانة الرحم ليساعد الجنين على الانغراس، ويقلل حساسية عضلات الرحم المحتملة لهرمون الأوكسيتوسين، ما يمنع انقباضها ويساعد على الوقاية من الإجهاض واستمرار الحمل. كما يساهم في إنتاج الكولاجين، فيزيد مرونة الجلد. ويؤدي ارتفاع مستوى هرمون البروجسترون في دمكِ إلى ارتخاء الصمام الفاصل بين المعدة والمريء، ما يسمح بتسرّب بعض حمض المعدة إلى المريء. لذلك قد تشعرين بحرقة المعدة وبمذاق حامض في فمكِ. ولتقليل تأثير حرقة المعدة قدر الإمكان، تناولي السوائل بين الوجبات وليس في أثنائها، وتناولي حصصًا أصغر وأسهل هضمًا، وامضغي اللقم جيدًا قبل بلعها. كذلك تجنبي الأطعمة الحارة وعصائر الفاكهة الحمضية والقهوة والشوكولاتة، واحرصي عند النوم على إبقاء رأسكِ وصدركِ في مستوى أعلى من بقية جسمكِ، وتناولي العشاء مبكرًا حتى يتسنى لجسمكِ هضم الطعام.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى زيادة حجم الدم، تزداد حاجة جسمكِ إلى السوائل؛ لذا احرصي على شرب ما لا يقل عن 2.5 لتر من الماء يوميًا. وإذا كنتِ تشعرين بشد في منطقة أسفل الظهر، فتوقفي تمامًا عن ارتداء الأحذية ذات الكعب العالي واختاري أحذية طبية مريحة. زيدي تناول الكالسيوم لتقوية عظام طفلكِ وحماية أسنانكِ وعظامكِ أيضًا.') WHERE id = 'e16dc0a2-01a9-4a7e-990c-b0f97835b682';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تهانينا! مع حلول هذا اليوم، أتممتِ بنجاح الثلث الأول من الحمل، أي الأشهر الثلاثة الأولى، وهو إحدى أهم مراحله. 😊 خلال الأسابيع الـ12 الماضية، اكتمل تكوّن جميع أعضاء طفلكِ واستقرت في أماكنها. وأصبح الآن يتمتع بمظهر إنساني كامل من حيث تناسب الرأس مع الجسم وملامح الوجه. كانت هذه أيضًا المرحلة الأكثر حساسية؛ فقد أصبحت الفترة التي كان فيها طفلكِ أكثر عرضة للعوامل الخارجية وكان خطر الإجهاض خلالها مرتفعًا وراءكِ الآن.;;;
وتبدأ كذلك مرحلة ستشعرين فيها براحة أكبر من الناحية الجسدية. فالرحم الذي ينمو فيه طفلكِ لم يعد يتسع داخل الحوض وبدأ يرتفع إلى أعلى. ويخفف ذلك الضغط الواقع على المثانة، ويقلل إلى حد ما حاجتكِ إلى الذهاب المتكرر إلى المرحاض.'), baby_message_ar = COALESCE(baby_message_ar, 'ينتهي الأسبوع الـ13! 👋 مرحبًا بالراحة التامة! لقد أصبحت كثير الحركة... أركل وأتقلب وأفتح يديّ وأغلقهما. قد تشعرين في بطنكِ بشيء يشبه "رفرفة فراشة" صغيرة (لكن لا تقلقي إن لم تشعري بها بعد). أنا هنا وأنمو. لقد قطعنا معًا رحلة رائعة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'برقوق'), body_changes_ar = COALESCE(body_changes_ar, 'نهاية الأسبوع الـ13. لقد تأقلمتِ تمامًا مع الثلث الثاني من الحمل. تحسّن نومكِ وأصبحت شهيتكِ جيدة. ويبدو بطنكِ الآن مثل "بطن حمل" صغير. وقد يصبح اختيار الملابس أكثر متعة، وتشعرين بأنوثة وجمال أكبر. استمتعي بهذه الفترة، فهي "شهر العسل" في الحمل! قد يستمر خروج "اللبأ" (الحليب الأول) من ثدييكِ، أو قد يبدأ الآن. ويُعد هذا السائل الكثيف المائل إلى الصفرة أول لقاح لطفلكِ. وإذا كان يترك بقعًا على ملابسكِ، يمكنكِ استخدام ضمادات الثدي المخصصة لذلك. تستعد الغدد الثديية للولادة بكل طاقتها.'), daily_tip_ar = COALESCE(daily_tip_ar, 'اختاري أسلوب حياة نشطًا بدلًا من الراحة في السرير. ستساعدكِ يوغا الحمل أو تمارين البيلاتس على تقوية عضلاتكِ والاستعداد للولادة. ويمكنكِ أيضًا التعرف إلى حوامل أخريات في هذه المجموعات وتبادل الخبرات معهن.') WHERE id = '451a1e44-829c-4f45-9442-ac30329fca22';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ حنك طفلكِ بالتكوّن. والحنك بنية مقوّسة تحيط بتجويف فم طفلكِ وتشارك في إصدار بعض الأصوات. يُسمّى الجزء الأمامي منه، الذي يشكّل سقفًا صلبًا، الحنك الصلب، بينما يُسمّى الجزء الخلفي الحنك الرخو.;;;
يرتبط الحنك بقاعدة جمجمة طفلكِ بواسطة زوجين من العضلات يقعان على الجانبين. كما أنه البنية التي تفصل بين تجويفي الفم والأنف لدى طفلكِ. يرتفع الحنك الرخو المتحرك أثناء البلع ويغلق التجويف الأنفي، ما يمنع وصول الطعام إليه. وفي منتصف الحافة الخلفية للحنك الرخو تقع اللهاة، وهي تساعد على إصدار بعض الأصوات أثناء الكلام. ويسهم الجزء الخلفي من الحنك في تمكين طفلكِ من نطق الأصوات الساكنة المفخمة مثل "q, k, ğ".'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع أن أصنع تعابير مضحكة بوجهي! 😝 لقد تطورت عضلات وجهي إلى درجة أنني أصبحت قادرًا على إظهار تعابير مختلفة. أعبس وأضم شفتيّ وأبتسم أو أبدو مندهشًا. إنها لعبة بالنسبة إليّ. أتدرّب منذ الآن كي أجعلكِ تضحكين عندما أولد. هل تبتسمين لي أنتِ أيضًا؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تين'), body_changes_ar = COALESCE(body_changes_ar, 'لا يُنصح بخسارة الوزن أو اتباع حمية غذائية خلال الحمل، حفاظًا على نمو طفلكِ. ومع ذلك، قد تؤثر الزيادة المفرطة في الوزن سلبًا في طفلكِ أحيانًا. ولتجنّب اكتساب الوزن بسرعة وضمان زيادة مناسبة في الوزن طوال الحمل، عليكِ الانتباه إلى نظامكِ الغذائي.;;;
ومن المفيد أيضًا تجنّب الأطعمة الجاهزة المضاف إليها السكر، والدهون الصلبة، والمنتجات ذات القيمة الغذائية المنخفضة التي لا توفر سوى سعرات حرارية فارغة. كما أن زيادة تناول الكربوهيدرات واعتياد الأكل ليلًا من أسباب زيادة الوزن. وإضافة إلى ذلك، يتباطأ الأيض خلال الحمل بفعل الهرمونات، وقد تحدث زيادة حتمية في الوزن إذا قلّت الحركة. وقد يساعد تناول وجبات خفيفة صحية على مقاومة الشعور المفاجئ بالجوع خلال اليوم والحد من زيادة الوزن. وإذا لم تكن لديكِ أي مشكلة صحية، فإن ممارسة بعض التمارين المصممة خصيصًا للحمل ستساعد أيضًا على تجنّب اكتساب الوزن بسرعة.;;;
وفي الوقت نفسه، عليكِ الابتعاد عن جميع أنواع الحليب ومنتجات الألبان غير المبسترة. وخلافًا للاعتقاد الشائع، تُعد البسترة من أهم ابتكارات العصر؛ إذ تقضي على الكائنات الدقيقة الضارة في الحليب، وخصوصًا البكتيريا المكوّنة للأبواغ، من دون أن تفقده قيمته الغذائية. أما غلي الحليب الخام في المنزل، فعلى الرغم من أنه يقتل جميع الكائنات الدقيقة النافعة والضارة الموجودة فيه، فإنه لا يضمن القضاء على البكتيريا المكوّنة للأبواغ، وهي الأشد ضررًا. لذلك، ينبغي لكِ تناول الحليب اليومي المبستر بدلًا من الحليب الخام أو الحليب المعبأ طويل الأجل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا استمرت حساسية اللثة، فتناولي الفواكه الغنية بفيتامين C. وإذا ازدادت شهيتكِ، فحافظي على توازن البروتين والكالسيوم في غذائكِ. اجعلي شرب ما لا يقل عن 2 لتر من الماء يوميًا عادة لكِ. وإذا كنتِ تعانين من آلام الظهر، فحاولي ارتداء أحذية مريحة والجلوس باستقامة. كما أن تخصيص وقت لنفسكِ كل يوم والاستماع إلى موسيقى هادئة سيمنحكِ أنتِ وطفلكِ طاقة إيجابية.') WHERE id = 'f769e4b1-414a-408e-8810-543b96add6b7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتطور منعكس المصّ. يضع الجنين أصابعه في فمه ويقوم بحركات المصّ. وهذا هو أساس غريزة التغذية بعد الولادة. كما يبتلع الجنين السائل الأمنيوسي، الذي يمر عبر الجهاز الهضمي ثم ترشحه الكليتان.'), baby_message_ar = COALESCE(baby_message_ar, 'أتعلم منعكس المصّ! 🍼 أضع إبهامي في فمي وأحاول مصّه. وهذه أهم مهارة تمكّنني من الرضاعة من حليبكِ بسهولة عندما أولد. أنجح أحيانًا، وفي أحيان أخرى تبتعد يدي عن فمي. لكنني لا أستسلم وأواصل التدريب. استعدّي لي أنتِ أيضًا، ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تين'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد تناول السمك، وهو غذاء غني جدًا بأحماض أوميغا-3 وأوميغا-6 الدهنية، خلال الحمل بالغ الأهمية لنمو دماغ طفلكِ وعينيه. كما يسهم السمك، الغني بالبروتين وفيتامين D، إسهامًا كبيرًا في نمو طفلكِ. ونظرًا إلى سهولة هضمه، يوصي الأطباء بتناول السمك مرتين أسبوعيًا من أجل حمل صحي. لكن هذا لا يعني أنه يمكنكِ تناول جميع أنواع السمك. فبعض الأسماك تحتوي على كميات مرتفعة من الزئبق، وقد تؤثر سلبًا في نمو طفلكِ. ومن الأسماك التي يمكنكِ تناولها بأمان خلال الحمل: السلمون والتونة والسردين والسلمون المرقط والماكريل؛ فهي غنية جدًا بحمض الفوليك إلى جانب خصائصها الغذائية. كما تحتوي هذه الأسماك على مستويات مرتفعة من أحماض أوميغا-3 وأوميغا-6 الدهنية، ومستويات منخفضة من الزئبق. ويكفي تناول نحو 300-400 غرام من السمك المطهو أسبوعيًا. وعليكِ تجنّب السمك النيئ والمعلبات التي تحتوي على مواد مضافة طوال الحمل. وبما أن الفيتامينات تُفقد تمامًا عند قلي السمك، فيُفضّل اختيار طرق مثل الطهو على البخار أو الشواء أو الخَبز في الفرن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا ازدادت شهيتكِ، فتناولي كميات صغيرة على فترات متقاربة للحفاظ على توازن سكر الدم. واستمري في استخدام الزيوت المرطبة (مثل زيت اللوز أو جوز الهند) للمساعدة على الوقاية من تمدد الجلد. ويمكنكِ البدء بالتسوق للانتقال إلى ملابس الحمل، فالراحة هي العامل الأهم الآن. وشاهدي فيلمًا تحبينه لتقضي يومكِ بمزاج جيد.') WHERE id = '32fc4b43-9967-407f-bd27-ce27ec4287ad';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه الأيام، بعد إتمام الأسبوع 11 من حملكِ، يمكنكِ رؤية طفلكِ بوضوح أكبر في فحص الموجات فوق الصوتية. في هذه المرحلة، تبدأ الأعضاء التناسلية لطفلكِ بالتكوّن. فهذا الجزء، الذي كان في السابق مجرد قطعة صغيرة من النسيج، يتحول الآن إلى قضيب أو بظر. وإذا كان طفلكِ في وضعية مناسبة داخل رحمكِ، فقد يظهر جنسه في فحص الموجات فوق الصوتية.;;;
وفي الوقت نفسه، يستمر تطور الأذنين، وتنتقلان إلى موضعهما على جانبي الرأس. كما تتكوّن طبلة الأذن بين الأذن الخارجية والوسطى. وتؤدي هذه الطبلة دور حاجز يمنع دخول البكتيريا إلى الداخل، وتتيح لطفلكِ أول تواصل صوتي مع العالم الخارجي. أصبح طفلكِ يسمع الأصوات الآن، لكنه لا يستطيع التمييز بينها بعد.;;;
ومع اقتراب نهاية الثلث الأول من الحمل، تتغير وضعية طفلكِ أيضًا. تطول رقبته، ويبتعد ذقنه عن صدره، ويبدأ رأسه بالاستقامة. وهكذا يخرج من وضعية "C" المنحنية السابقة ليكتسب بنية جسدية أكثر استقامة.'), baby_message_ar = COALESCE(baby_message_ar, 'اكتملت 12 أسبوعًا! 🎉 ماما، لقد أنهينا الثلث الأول من الحمل بنجاح! كانت هذه أصعب مراحل الحمل وأكثرها أهمية. لقد تكوّنت جميع أعضائي واتخذت أشكالها. أنا الآن رسميًا "إنسان صغير". تنتظرنا من الآن فصاعدًا أيام أكثر راحة وحيوية. أنا فخور بكِ، فنحن فريق رائع!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تين'), body_changes_ar = COALESCE(body_changes_ar, 'ابتداءً من اليوم، تبدأ المشيمة أداء وظائفها بالكامل وتتولى إنتاج الهرمونات من "الجسم الأصفر". ويؤدي هذا الانتقال عادةً إلى تراجع الغثيان وزيادة الطاقة. وقد تشعرين بمزيد من النشاط. لقد مضت الفترة الأكثر خطورة من الحمل!;;;
قد تظهر بعض المشكلات الجلدية بسبب تغير الهرمونات خلال الحمل. فقد تظهر الإكزيما أو الصدفية، أو تتفاقم هذه الحالات إذا كانت موجودة مسبقًا. وللوقاية من الإكزيما والصدفية، ينبغي الحفاظ على أعلى مستوى ممكن من ترطيب البشرة، وشرب الكثير من الماء، وتناول الفواكه والخضراوات الطازجة.;;;
قد تظهر بعض الطفوح الجلدية في الأسابيع الأخيرة من الحمل نتيجة ازدياد حجم البطن بشكل ملحوظ. وتكون هذه الطفوح أكثر شيوعًا خصوصًا لدى الحوامل للمرة الأولى، وقد تسبب بقعًا مثيرة للحكة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بانتهاء الثلث الأول من الحمل بطقس تحبينه! يمكنكِ العودة إلى حياة أكثر نشاطًا مع استعادة طاقتكِ، لكن احرصي على عدم رفع الأشياء الثقيلة. ومع تحسن شهيتكِ، ركّزي على تناول غذاء "عالي الجودة من أجل شخصين" بدلًا من "الأكل عن شخصين". وإذا لم تكوني قد أجريتِ "الاختبار المزدوج" بعد، فتأكدي من المواعيد النهائية مع طبيبكِ. واستعدّي للاستمتاع بالثلث الثاني من الحمل، أو ما يُعرف بفترة شهر العسل!') WHERE id = '43e2ccf7-0f43-404f-b8d5-9a230d2fcf1f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتطور الجهاز البولي في جسم طفلكِ بسرعة. ويتكوّن هذا الجهاز من كليتين وحالبين ومثانة بولية. وتتمثل وظيفته الأساسية في تنقية الدم من المواد الضارة والحفاظ على توازن الماء والأملاح في الجسم. ابتداءً من هذا الأسبوع، يبدأ طفلكِ بالفعل في إنتاج البول، ويختلط هذا السائل بالسائل الأمنيوسي المحيط به. وداخل الكليتين، تتكوّن ملايين المرشحات الصغيرة التي تُسمى النيفرونات، وهي المسؤولة عن ترشيح الدم. وفي الوقت الحالي، تعمل في الكليتين نيفرونات ذات بُنى قصيرة وأخرى طويلة. وعندما يكتمل نمو طفلكِ، ستحتوي كل كلية لديه على أكثر من مليون من هذه المرشحات الصغيرة. وبفضل هذه الخلايا الأنبوبية، يُنقّى دم طفلكِ باستمرار وتُنظّم عمليات الأيض لديه.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا بكِ في الثلث الثاني من الحمل! ☀️ يُطلقون عليه اسم "الفترة الذهبية"، لأنكِ ستشعرين بتحسّن أكبر، بينما سأنمو أنا بسرعة. أنا الآن بحجم ثمرة لايم. أصبحت حركاتي أكثر تناسقًا، ولم تعد عشوائية، بل أتحرك كما أريد. أريد أن ألمسكِ يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'لايم'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن تنتبهي إلى جميع الأعراض التي تظهر خلال الحمل. فعلى سبيل المثال، قد يتفاعل جسمكِ مع الحساسية بظهور طفح جلدي أو بقع حمراء أو حكة. وقد يظهر هذا الطفح والحكة خلال الأشهر الأولى من الحمل بسبب هرمون البروجسترون. لكن إذا استمرا في المراحل المتقدمة، فيجب إجراء تحاليل للدم. وتشمل هذه التحاليل فحص إنزيمات الكبد، واختبارات التهاب الكبد، والعصارة الصفراوية، وهرمونات الغدة الدرقية. وإذا كانت نتائج هذه الفحوصات غير طبيعية، فيجب تلقي العلاج حفاظًا على صحتكِ وصحة طفلكِ.;;;
بالإضافة إلى ذلك، قد تشير أعراض مثل فقدان الشهية والوهن والتعب واحمرار العينين أو اصفرارهما وتغيّر رائحة البول ولونه إلى وجود مشكلة في مؤشرات وظائف الكبد، وتُعرف هذه الحالة باسم الركود الصفراوي الحملي. وتحتاج المصابات بالركود الصفراوي الحملي إلى متابعة دقيقة وفحوصات متكررة باستخدام تخطيط نبض الجنين NST، والدوبلر، والتصوير بالموجات فوق الصوتية.;;;
ويزداد احتمال ظهور هذه الأعراض بوجه خاص إذا لم تكن هناك فترة زمنية طويلة بين حالات الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استشيري طبيبكِ بشأن حياتكِ الجنسية. إذا لم توجد أي مخاطر، مثل النزيف أو خطر الإجهاض، فإن العلاقة الجنسية أثناء الحمل آمنة تمامًا، وقد تكون مفيدة أيضًا بفضل هرمون الأوكسيتوسين.') WHERE id = '931efc18-1bb9-41fb-bf51-8eb31fb5efd5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تطورت أمعاء طفلكِ الآن بدرجة كبيرة. ففي الأسابيع الأولى، كانت الأمعاء نسيجًا بسيطًا، أما الآن فقد بدأت تلتف وتنقسم إلى قسمين أمامي وأوسط، وتستطيل بسرعة بالتوازي مع نمو القلب والرئتين. وفي هذه المرحلة، تصل كمية السائل الأمنيوسي المحيط بطفلكِ إلى نحو 50 ml. وفي الوقت نفسه، تبدأ الغدة النخامية في الدماغ، التي تُعرف باسم "الغدة الرئيسية"، في أداء وظائفها. وتنتج هذه الغدة الصغيرة عددًا كبيرًا من الهرمونات اللازمة للنمو في الطول، وعمليات الأيض، وعمل الجهاز التناسلي مستقبلًا. ويتحكم الوطاء، وهو جزء آخر من الدماغ، في الغدة النخامية. ويعملان معًا للحفاظ على التوازن الداخلي للجسم. أي إنه إذا اختلت أي عملية في الجسم، تعمل هاتان الغدتان فورًا على إعادتها إلى وضعها الطبيعي بواسطة الهرمونات.'), baby_message_ar = COALESCE(baby_message_ar, 'بصمات أصابعي جاهزة! 🧬 لقد اكتمل تكوّن بصمات أصابعي الفريدة التي تخصني وحدي ولا مثيل لها في العالم. إنها بطاقة هويتي. وحتى لو كان لدي توأم، لكانت بصماته مختلفة عن بصماتي. أنا فريد ولا شبيه لي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'لايم'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كانت لديكِ أعراض مثل الرغبة في شرب كميات من الماء تفوق المعتاد، وكثرة التبول، وتنميل الساقين، والتغيرات المفاجئة في الوزن، فقد تكونين قد أُصبتِ بداء السكري. وإذا لم تكوني مصابة بالسكري من قبل، فإن هذه الحالة التي تظهر أثناء الحمل تُسمى "سكري الحمل". وقد تعاني المصابات بسكري الحمل من ارتفاع ضغط الدم والدوار والصداع. وخلافًا للاعتقاد الشائع، لا تظهر هذه الحالة لدى الحوامل ذوات الوزن الزائد فقط، بل تكون النساء اللواتي لديهن تاريخ عائلي للإصابة بالسكري أكثر عرضة لها. ينشأ سكري الحمل عندما تنمو المشيمة لدعم طفلكِ طوال الحمل، وتُفرز هرمونات تقلل تأثير الإنسولين في جسمكِ. وتُسمى هذه الحالة مقاومة الإنسولين. وإذا لم يتمكن الإنسولين من أداء تأثيره بفاعلية كافية، فلن يتحول سكر الدم إلى طاقة، ويرتفع مستوى السكر في الدم. ونتيجة لذلك، يظهر سكري الحمل.;;;
يشمل العلاج اتباع نظام غذائي مناسب، مع استخدام الإنسولين عند الحاجة. وتتمثل المسألة الأساسية طوال الحمل في ضمان اتباع نظام غذائي صحي ومتوازن. وإذا لم يُعالج سكري الحمل، فقد يؤدي إلى الإجهاض أو الولادة المبكرة أو زيادة وزن طفلكِ بسرعة مفرطة أو حدوث بعض مشكلات النمو. ويُكشف عن سكري الحمل من خلال اختبار تحمّل الغلوكوز الذي يُجرى بين الأسبوعين 24-28 من الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أشبعي زيادة الشهية المصاحبة للثلث الثاني من الحمل بأطعمة مفيدة، مثل المكسرات والفواكه الطازجة والجبن القريش. وإذا بدأتِ تشعرين بآلام خفيفة في أسفل الظهر، فضعي وسادة دعم صغيرة خلف ظهركِ عند الجلوس. وللوقاية من تصبغات الحمل في بشرتكِ، تجنّبي أشعة الشمس المباشرة واستخدمي كريمات واقية من الشمس ذات عامل حماية مرتفع.') WHERE id = 'ec212007-cf13-4d3e-9523-fa6762234108';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ بنكرياس طفلكِ الآن في إنتاج الإنسولين. ينتج 99% من هذه الغدة إنزيمات تساعد على الهضم، بينما تُفرز مجموعات صغيرة من الخلايا تمثل 1% المتبقية الإنسولين. ويساعد الإنسولين الخلايا على استخدام السكر (الغلوكوز)، الذي يُعد مصدر الطاقة الأساسي للجسم. وتتمثل وظيفته الرئيسية في منع ارتفاع مستوى سكر الدم بدرجة مفرطة. إذ ينقل الإنسولين السكر من الدم إلى خلايا العضلات والدهون لاستخدامه في إنتاج الطاقة. وإذا انخفض مستوى السكر في الدم، يتوقف إنتاج الإنسولين ويُفعّل الجسم هرمونات أخرى للحفاظ على مستوى السكر ضمن المعدل الطبيعي. وبهذه الطريقة، يُنظّم التوازن بين السكر والدهون والبروتينات في جسم طفلكِ بدقة متناهية.'), baby_message_ar = COALESCE(baby_message_ar, 'هل بدأت أسمع الأصوات؟ 👂 يستمر نمو أذنيّ، وأصبحت الآن قادرًا على الإحساس بالاهتزازات. نبضات قلبكِ وتدفق دمكِ وأصوات معدتكِ هي تهويدتي. وقريبًا سأتمكن من تمييز صوتكِ أيضًا. تحدثي إليّ يا ماما، فأنا أستمع إليكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'لايم'), body_changes_ar = COALESCE(body_changes_ar, 'يزداد احتمال ظهور علامات تمدد الجلد لديكِ. فمع نمو بطنكِ وفخذيكِ وثدييكِ، يتمدد الجلد. وتؤدي العوامل الوراثية دورًا كبيرًا في ذلك، لكن ترطيب البشرة يزيد مرونتها ويخفف الحكة. وعندما تكون بشرتكِ جافة، تكون أكثر عرضة للتشقق. لذلك، من المهم ترطيبها يوميًا وتدليكها 1-2 مرة أسبوعيًا.;;;
لا تنسي إدراج المكسرات في نظامكِ الغذائي خلال الحمل. فالمكسرات والبذور الزيتية غنية بالعناصر الغذائية، وللاستفادة منها ينبغي تناولها نيئة لا محمصة. ومن أهمها الجوز واللوز والفستق والكاجو والبندق والتين المجفف وبذور اليقطين والمشمش المجفف والفول السوداني. يدعم الجوز نمو دماغ طفلكِ، ويساعد الكالسيوم الموجود في البندق على نمو عظامه، ويلبي اللوز احتياجاتكِ اليومية من الزنك، بينما يساعد الفول السوداني على تلبية احتياجاتكِ من فيتاميني B وE، إلى جانب البوتاسيوم والفوسفور والصوديوم والمغنيسيوم. بالإضافة إلى ذلك، تناولي باعتدال الفواكه المجففة طبيعيًا، مثل التين والمشمش، لأنها تحتوي على العديد من الفيتامينات والمعادن التي تحتاجين إليها أنتِ وطفلكِ خلال الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للتخفيف من آلام الرباط المستدير، حاولي تجنب الحركات المفاجئة، وعند النهوض من السرير استديري أولًا على جانبكِ. وللحفاظ على صحة لثتكِ، واصلي تناول الأطعمة الغنية بالكالسيوم واستخدام فرشاة أسنان ناعمة. وإذا ازدادت شهيتكِ، فانتبهي إلى الحصول على كمية كافية من المغنيسيوم في غذائكِ لتجنب تشنجات عضلات الساقين.') WHERE id = '51726a4c-4dfd-4d8d-8fdf-a1b799174400';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ كبد طفلكِ بالفعل بإنتاج العصارة الصفراوية. ويُعد هذا السائل بالغ الأهمية للجهاز الهضمي، إذ يساعد الجسم على امتصاص الدهون والفيتامينات المهمة (A، D، E، K) الموجودة في الطعام. وبفضل العصارة الصفراوية، تصل إلى الدم العناصر الضرورية لصحة عظام طفلكِ (فيتامين D)، وقدرته على الإبصار (فيتامين A)، وحماية خلاياه (فيتامين E)، وتخثر دمه (فيتامين K). كما يساعد هذا السائل على تخليص الجسم من بعض المواد الضارة. تنتقل العصارة الصفراوية التي ينتجها الكبد يوميًا عبر القناة الرئيسية إلى الاثني عشر، بينما يُخزَّن جزء منها في المرارة، وهي عضو كمثري الشكل يقع أسفل الكبد. وعند الحاجة، تفرغ المرارة هذا السائل في الأمعاء الدقيقة للمساعدة على الهضم.'), baby_message_ar = COALESCE(baby_message_ar, '13 أسبوعًا! أهلًا بالثلث 2 من الحمل! 🎉 ماما، يا لها من أخبار رائعة! لقد أتممنا ثلث الحمل (1/3). أصبحت أصعب الأيام خلفنا، وبدأت الآن مرحلة سنتنفس فيها أنا وأنتِ براحة أكبر. لقد أصبح حجمي الآن بحجم حبة برقوق. كما تطورت أحبالي الصوتية. ورغم أنني لا أستطيع التحدث إليكِ بعد، فإنني أُعِد صوتي لذلك. تنتظرنا أيام أجمل في هذه المرحلة الجديدة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة برقوق'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد زيادة الإفرازات المهبلية من أكثر الظواهر شيوعًا أثناء الحمل. ونظرًا إلى ارتفاع مستوى هرمون الإستروجين في جسمكِ، تُعد زيادة هذه الإفرازات طبيعية في معظم الأحيان. وقد يكون لونها أبيض أو أصفر أو داكنًا قليلًا. ومن الطبيعي أن يختلف مظهر الإفرازات وقوامها عن الفترة السابقة للحمل بسبب ارتفاع مستويات الهرمونات في الدم. لكن عليكِ الانتباه إلى ما يلي: إذا أصبحت إفرازاتكِ المهبلية صفراء داكنة أو مائلة إلى الخضرة، وكان قوامها كثيفًا جدًا، والأهم من ذلك إذا انبعثت منها رائحة كريهة تشبه رائحة السمك الفاسد، فقد يكون ذلك علامة على عدوى مهبلية تستلزم العلاج. وللوقاية من الإفرازات المهبلية غير الطبيعية (والعدوى)، تجنبي توجيه الماء إلى داخل المهبل أثناء الاستحمام، ولا تنظفي المنطقة الداخلية أو الخارجية بمناديل أو صابون معطر، وابتعدي عن مزيلات الروائح والعطور. فهذه الممارسات ضارة لأنها تخل بالتوازن الطبيعي للبكتيريا النافعة داخل المهبل. خلال هذه الفترة، ارتدي ملابس داخلية قطنية وغيّريها عند الحاجة من 2-3 مرات يوميًا. وتجنبي استخدام الفوط اليومية لأنها تعيق التهوية، واحرصي على نظافة ملابسكِ الداخلية بكيّها على درجة حرارة مرتفعة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تُعد هذه الفترة الأكثر أمانًا وراحة للسفر في رحلة ما قبل الولادة ("Babymoon"). فطاقتكِ جيدة وبطنكِ لم يكبر كثيرًا بعد. يمكنكِ استشارة طبيبكِ والتخطيط لعطلة قصيرة.') WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في نهاية الثلث الأول من الحمل، تكون المشيمة، أقرب رفيق لطفلكِ داخل رحمكِ، قد اكتمل تكوّنها. ويؤدي هذا العضو المؤقت، الذي لا يتجاوز عمره بضعة أسابيع، دورًا حيويًا في بقاء طفلكِ ونموه. وحتى هذه المرحلة، كان "الجسم الأصفر" في جسمكِ ينتج هرمون البروجسترون الذي يحافظ على الحمل، أما الآن فتتولى المشيمة هذه المهمة المهمة. تنقل المشيمة الأكسجين والماء والغلوكوز من دم الأم إلى الطفل، وتتخلص من الفضلات الناتجة في جسمه، وتشكل حاجزًا أمام بعض أنواع العدوى الموجودة في دم الأم، ولا تسمح إلا بمرور المواد التي يحتاج إليها الطفل. باختصار، تعمل المشيمة لطفلكِ كرئتين وكليتين ونظام حماية في آن واحد.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأ جسمي يكتسي بالزغب! 🐻 ماما، بدأ ينمو على بشرتي زغب رقيق وناعم جدًا يُسمى "الزغب الجنيني". أبدو الآن مثل حبة خوخ صغيرة. يحميني هذا الزغب من الشعور بالبرد داخل السائل ويحافظ على حرارة جسمي. سيتساقط معظمه عند ولادتي، لكنني أحتاج حاليًا إلى هذا "الفرو". أنتِ تبقينني دافئًا، وأنا أيضًا أحافظ على دفء نفسي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة كيوي'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه الأيام التي تدخلين فيها الثلث الثاني من الحمل، قد تشعرين من حين إلى آخر بآلام مفاجئة تشبه الوخز في أسفل البطن أو منطقتي الأُربيتين. تنتج هذه الآلام عن تمدد الأربطة المحيطة بالرحم الذي يحتضن طفلكِ ويواصل النمو. ومن بينها "round ligament" (الرباط المستدير). ومن المميز جدًا أن هذه الآلام تحدث غالبًا عند النهوض أو التقلب يمينًا ويسارًا في السرير أو القيام بحركة مفاجئة أو السعال. إذ تؤدي هذه الحركات إلى شد الأربطة المحيطة بالرحم، ما يسبب الألم. ويمكن أن تساعدكِ إجراءات بسيطة على الشعور بالراحة، مثل الاسترخاء وتغيير وضعية جسمكِ وتجنب الحركات المفاجئة والاستحمام بماء دافئ ووضع كمادة دافئة على المنطقة المؤلمة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مع تحسن شهيتكِ، احرصي على تنويع ألوان طعامكِ؛ وتناولي خضراوات وفواكه متنوعة كي يتعرف طفلكِ إلى نكهات مختلفة. زيدي استهلاككِ للحديد (اللحوم قليلة الدهون، والعدس، والسبانخ) للوقاية من فقر الدم. وبما أن طاقتكِ جيدة، فإن المشي الخفيف لمدة 15-20 دقيقة يوميًا سيحسن كثيرًا مزاجكِ وعملية الهضم لديكِ.') WHERE id = '00f39406-c90d-4b7e-818d-3a2edbdeef33';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من اكتمال البنية الأساسية لرئتي طفلكِ، فإنهما آخر عضو يكتمل نموه. ويستمر نضجهما الكامل حتى الأسبوع 38 من الحمل. ولأن طفلكِ موجود حاليًا داخل السائل الأمنيوسي، فهو لا يتنفس برئتيه. بل يحصل على الأكسجين اللازم مباشرة من دمكِ ويعيد ثاني أكسيد الكربون إلى دمكِ؛ أي إنه يتنفس كما لو كان يستخدم رئتيكِ.;;;
ومع ذلك، بدأ طفلكِ بالفعل بالتدرب على التنفس. فبدلًا من الهواء، يُدخل السائل ويخرجه عبر أنفه وفمه لتقوية عضلات التنفس. ويمكن الآن رؤية هذه الحركات الصغيرة أثناء فحص الموجات فوق الصوتية. وبفضل هذه التدريبات، سيتمكن من أخذ نَفَسه الأول بسهولة فور ولادته.'), baby_message_ar = COALESCE(baby_message_ar, 'بعد بصمات أصابعي، حان الآن دور أظافري! 💅 ماما، بدأت أظافر صغيرة ورقيقة تتكوّن على أطراف أصابعي. ما زالت ناعمة جدًا، لكنها ستطول حتى موعد ولادتي. قد أخدش وجهي أحيانًا، لذلك ستحتاجين إلى إلباسي قفازات عند ولادتي. كل شيء فيَّ يشبهكِ، فماذا عن أظافري؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة كيوي'), body_changes_ar = COALESCE(body_changes_ar, 'الفولات نوع من فيتامين B القابل للذوبان في الماء، ويوجد طبيعيًا في الأطعمة، أما شكله المُصنَّع فيُسمى حمض الفوليك. ويُعد حمض الفوليك آمنًا لمعظم الأشخاص عند تناوله عن طريق الفم أو إعطائه بالحقن. ويكتسب استخدامه خلال الحمل أهمية خاصة لتطور الجهاز العصبي لدى الطفل وانغلاق الأنبوب العصبي. كما يؤدي في الأسابيع الأولى من الحمل دورًا بالغ الأهمية في تكوين الدم والخلايا الجديدة، والحفاظ على حياة الخلايا، وإنتاج الحمضين النوويين DNA وRNA.;;;
يُنصح بالبدء في استخدامه قبل الحمل بثلاثة أشهر على الأقل والاستمرار حتى منتصف الحمل. وإذا تعذر تناول المكملات الدوائية، فعليكِ الإكثار من تناول الأطعمة الغنية بالفولات، مثل البامية والهليون والفاصولياء والخميرة والفطر واللحوم والموز والسبانخ والبروكلي والخس.'), daily_tip_ar = COALESCE(daily_tip_ar, 'انتبهي إلى وضعية جسمكِ؛ فالوقوف باستقامة يسهّل تنفسكِ ويخفف آلام الظهر. وإذا كانت لثتكِ حساسة، فتناولي أطعمة غنية بفيتامين C. وإذا ازدادت شهيتكِ، فاختاري الدهون الصحية مثل المكسرات كوجبة خفيفة. وخصصي بضع دقائق يوميًا للتحدث إلى طفلكِ.') WHERE id = 'aee96903-8ce9-4152-9673-4163944c634d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بلغ حجم السائل الأمنيوسي المحيط بطفلكِ نحو 80 ml. ويبلغ حجم رأس طفلكِ حاليًا نصف حجم جسمه، لأن دماغه وجهازه العصبي ينموان بسرعة كبيرة. لا تقلقي، ففي الأسابيع المقبلة سينمو جسمه بوتيرة أسرع لتصبح هذه النسبة أكثر توازنًا، حتى إن رأسه عند الولادة سيعادل ربع حجم جسمه فقط. وبفضل تطور جهازه العصبي، تزداد قوة منعكسَي المص والبلع لديه. أما قلبه فينبض بسرعة كبيرة لتوصيل الدم إلى جميع أنحاء جسمه المتنامي، مما يسرّع الدورة الدموية. ورغم أنكِ لا تشعرين به بعد، فإن صغيركِ نشيط جدًا في الداخل؛ فهو يتثاءب ويركل ويتقلب ويحرك أصابعه. وإذا لامس طفلكِ جدار الرحم لأكثر من ثانية، فقد تشعرين بهذه اللمسات الصغيرة قريبًا جدًا.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أنا ولد أم بنت؟ لقد أصبح الأمر محسومًا الآن! 🩷💙 اكتمل تكوّن أعضائي التناسلية. إذا كنتُ بنتًا، فهناك بالفعل 2 مليون بويضة في مبيضَيّ. وإذا كنتُ ولدًا، فإن غدة البروستاتا لديّ تتكوّن الآن. إذا فحصني الأطباء بجهاز تصوير بالموجات فوق الصوتية عالي الجودة، فقد يتمكنون من رؤية جنسي. ماذا تشعرين؟ حدس الأم قوي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كيوي'), body_changes_ar = COALESCE(body_changes_ar, 'يمكن تحسس رحمكِ على بُعد بضعة سنتيمترات أسفل السرة. وبسبب زيادة حجم الدم، ينبض قلبكِ بسرعة أكبر، وهذا أمر طبيعي. وقد يصبح تصبغ بشرتكِ، مثل ازدياد قتامة النمش أو الشامات، أكثر وضوحًا نتيجة التأثيرات الهرمونية. وقد تبدأ شهيتكِ بالازدياد بشكل ملحوظ. ومع انتهاء غثيان الصباح، تبدئين في الاستمتاع بمذاق الطعام مجددًا. لكن انتبهي، فقد تؤدي الرغبة الشديدة في تناول الحلويات والمعجنات إلى زيادة مفرطة في الوزن. ركزي على مصادر السعرات الحرارية الصحية.;;;
تصبح الأوردة في ثدييكِ أكثر بروزًا، كما تزداد الهالة المحيطة بالحلمة قتامة واتساعًا. وهذه آلية طبيعية تشبه "الهدف" وتساعد طفلكِ على العثور على الثدي بسهولة أكبر بعد الولادة. من الطبيعي أن يخرج سائل مائل إلى الصفرة من ثدييكِ، ومن الطبيعي أيضًا ألا يخرج.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ متحمسة لمعرفة جنس طفلكِ، فانتظري موعد الفحص التالي بالموجات فوق الصوتية. لكن تذكري أن وضعية طفلكِ قد تحول أحيانًا دون رؤيته بوضوح. وقد يساعد تناول شيء حلو على تحفيز طفلكِ على الحركة أثناء الفحص.') WHERE id = '35661bc0-afeb-48b5-9303-88d093e85d1a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'الطحال هو أحد أعضاء طفلكِ التي بدأت تتطور حديثًا. وقد نما هذا العضو، الذي يتميز ببنية طرية وإسفنجية، بما يكفي ليتولى بعض الوظائف المهمة التي كان يؤديها الكبد. يعمل الطحال داخل جسم طفلكِ كمركز يشبه "نظام الأمان والمخزن"؛ إذ ينتج خلايا الدم البيضاء التي تحارب الجراثيم، ويفكك خلايا الدم الحمراء القديمة التي فقدت وظيفتها، كما يخزن خلايا الدم الحمراء لاستخدامها عند الحاجة. وعندما يزداد استهلاك الطاقة، ينقبض الطحال ليدفع مخزون الدم هذا إلى الدورة الدموية. وفي الوقت نفسه، يغطي جسم طفلكِ شعر بالغ الرقة والنعومة وعديم اللون يُسمى الزغب الجنيني (اللانوغو). ويشكّل هذا الشعر طبقة واقية بالغة الأهمية لطفلكِ. ولأن الطبقة الدهنية في جسمه لم تكتمل بعد، يساعده الزغب الجنيني على الحفاظ على استقرار درجة حرارة جسمه.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أستمع إلى صوتكِ! 👂 انتقلت أذناي من رقبتي إلى جانبي رأسي، أي إلى موضعهما الطبيعي. والآن أستطيع سماعكِ بشكل أفضل. احكي لي قصة وغنّي لي أغنية؛ فصوتكِ يهدئني. دعي أبي يتحدث إليّ أيضًا، فأنا أريد أن أتعرف إلى صوته.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يوسفي'), body_changes_ar = COALESCE(body_changes_ar, 'من المتوقع أن تكوني قد اكتسبتِ حتى هذه المرحلة ما متوسطه 3-4 كيلو. وتختلف زيادة الوزن أثناء الحمل من امرأة إلى أخرى بحسب بنية جسمها. ويُعد اكتساب ما متوسطه 8-12 كيلو خلال الحمل أمرًا طبيعيًا، لكن ليس بالضرورة أن تكتسب كل امرأة الوزن بالمعدل نفسه، فهذا مسار طبيعي تمامًا.;;;
من الطبيعي أن يزداد محيط الخصر لدى النساء خلال الحمل، سواء كانت زيادة الوزن قليلة أم كبيرة. وطوال فترة حملكِ، ينبغي أن تتجنبي الملابس التي تضغط على بطنكِ، والجوارب التي تضيق على ساقيكِ، والأحزمة التي تضغط على خصركِ، والأحذية ذات الكعب العالي، وأن تختاري ملابسكِ مع إعطاء الأولوية لراحتكِ. كما أن اختيار الملابس الداخلية مهم جدًا لراحتكِ ونظافتكِ؛ لذا تجنبي الملابس الداخلية المصنوعة من الأقمشة الاصطناعية والنايلون، واختاري الملابس الداخلية القطنية. واحرصي أيضًا على اختيار حمالات صدر مريحة ومرنة بشكل خاص.'), daily_tip_ar = COALESCE(daily_tip_ar, 'وجّهي طاقتكِ المتزايدة نحو الأنشطة الإبداعية أو خططكِ المستقبلية. وإذا شعرتِ بحكة في بطنكِ، فقد تكون علامة على تمدد الجلد؛ لذا واصلي ترطيبه بانتظام بالزيوت الطبيعية (زيت اللوز، زيت الزيتون). واهتمي بالحصول على الكالسيوم وفيتامين D لتقوية عظام طفلكِ. كما أن قراءة كتاب لطفلكِ أو تشغيل الموسيقى له يوميًا لمدة 10 دقائق في أجواء هادئة سيعزز الرابطة بينكما.') WHERE id = 'a57894a0-cfe4-43ea-b3a3-609e569ae8e7';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل الآن تكوّن عظم الحنك وسقف فم طفلكِ. كما تتطور في وجنتيه عضلات خاصة ستمكّنه من مص الحليب فور ولادته. فالمص ليس مجرد حركة، بل هو من أهم المهارات اللازمة لتغذية طفلكِ ومناعته وشعوره بالأمان. وهو يتدرب بالفعل داخل رحمكِ من خلال مص إصبعه. وبفضل هذه التدريبات، سيمتلك منذ لحظة ولادته القوة والتقنية اللازمتين للرضاعة منكِ. وتحدث عملية المص على النحو التالي: يمسك طفلكِ الحلمة بشفتيه وحنكه العلوي ولسانه، ويُنشئ داخل فمه فراغًا قويًا محكمًا لا يسمح بمرور الهواء. ثم يسحب لسانه إلى الخلف ليفسح مكانًا للحليب داخل فمه، ويُحكم إغلاق فمه لمنع تسرب السائل إلى الخارج. وهذا المنعكس قوي جدًا لدرجة أن هذه الحركات ستؤدي خلال الأسابيع المقبلة إلى بدء إفراز اللعاب في فم طفلكِ، مما سيساعد على تسهيل الهضم بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أسبح! 🏊‍♂️ قد لا تصدقين ذلك، لكنني أحرك ذراعيّ وأركل بساقيّ. أشبه بضفدع صغير يسبح في حوض. هذه الحركات مهمة جدًا لنمو دماغي. أنتِ لا تشعرين بي بعد، لأن الماء المحيط بي يخفف وقع حركاتي، لكنني قوي جدًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يوسفي'), body_changes_ar = COALESCE(body_changes_ar, 'من الطبيعي أن تبدأ آلام منطقة الأربية لديكِ منذ الأسبوع الأول من حملكِ. وقد تمنحكِ هذه الحالة شعورًا يشبه اقتراب الدورة الشهرية. وهذه الآلام طبيعية في كل حمل، وقد تنتج، خاصة خلال الأشهر الأولى، عن نمو الرحم وتمدد عضلاته، بينما قد تحدث في الأشهر الأخيرة نتيجة ضغط طفلكِ المتنامي على الرحم وأسفل البطن. ومع تقدم أسابيع الحمل، قد تظهر آلام مرتبطة بحركات طفلكِ أيضًا. وقد يساعد استخدام المغنيسيوم تحت إشراف طبيبتكِ أو طبيبكِ على تخفيف هذه الشكاوى. أما آلام الأربية الشديدة، خاصة في الأشهر الأخيرة، والتي لا تزول مع الراحة، فقد تكون علامة على اقتراب الولادة. وإذا كنتِ معرضة لخطر الولادة المبكرة، فقد تحتاجين في مثل هذه الحالات إلى التوجه إلى المستشفى.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تنسي استخدام كريم واقٍ من الشمس (SPF 50)، حتى في الشتاء! فهو أفضل وسيلة لمنع ظهور بقع دائمة على وجهكِ. ولا تخرجي تحت أشعة الشمس من دون قبعة.') WHERE id = 'f4ba8684-d553-4733-84cb-3f9f1059e979';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يصبح جسم طفلكِ أكثر تناسقًا تدريجيًا. فقد وصلت الذراعان بالفعل إلى الطول المفترض، وستواصلان من الآن فصاعدًا النمو بالسرعة نفسها التي ينمو بها الجسم. لكن الساقين تحتاجان إلى مزيد من الوقت. ويُعد عظم الفخذ، وهو أطول عظام الجسم وأقواها، أهم مؤشر طبي لقياس طول طفلكِ. وقد أصبح هذا العظم واضحًا في الفحوصات، ويعطينا معلومات دقيقة عن طول طفلكِ الإجمالي. وفي السنوات الأخيرة، استُخدمت أيضًا طريقة مثيرة للاهتمام لحساب الطول، وهي قياس طول القدم. ولا سيما بعد الأسبوع 20، يمكن تقدير طول طفلكِ، مع هامش خطأ بسيط، بضرب طول عظم الفخذ أو القدم في 7.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أصنع تعابير بوجهي! 😜 لقد تطورت عضلات وجهي لدرجة أنني أستطيع عقد حاجبيّ أو تضييق عينيّ أو الابتسام. وأحيانًا أفتح فمي وأتثاءب. هذا ليس مجرد تسلية، بل هو استعدادي للتواصل. عندما ترينني، سأهديكِ أحلى ابتسامة لديّ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يوسفي'), body_changes_ar = COALESCE(body_changes_ar, 'يزداد معدل الأيض الأساسي لديكِ طوال فترة الحمل بنسبة تقارب 20 بالمئة في المتوسط مقارنة بالمعدل الطبيعي. وبعبارة أخرى، تزداد حاجتكِ إلى الطاقة خلال الحمل بنحو 300 سعرة حرارية يوميًا. كما تحدث تغيرات ملحوظة في أيض الدهون لديكِ. ويزداد تخزين الدهون خصوصًا خلال الثلث الثاني من الحمل، أما في الثلث الثالث فينتقل جزء من هذا النسيج الدهني إلى طفلكِ نتيجة زيادة حاجته إلى الدهون، فتقل الكمية المخزنة. بالإضافة إلى ذلك، تزداد كمية البروتين الإجمالية في جسمكِ بنحو 1 كغ حتى نهاية الحمل. وخلال الحمل، يتجمع في جسمكِ نحو 6-7 لترات من الماء، كما يتراكم في ساقيكِ ما يقارب 1-2 لتر من السوائل المسببة للوذمة. ويزداد حجم الدم المتداول بنسبة 40-50 بالمئة. وتبدأ هذه الزيادة خلال الثلث الأول من الحمل الذي اجتزتِه. ونتيجة ازدياد حجم الدم، يرتفع معدل ضربات القلب بنحو 10 بالمئة، كما يحدث انخفاض في ضغط الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الأربطة، تجنبي الحركات المفاجئة، وعند النهوض من السرير استديري أولًا على جانبكِ. واصلي تناول الأطعمة الغنية بالكالسيوم (الجبن، والزبادي، والسمسم) للتخفيف من حساسية اللثة. سيزداد طول طفلكِ بسرعة أكبر في الأسبوع المقبل، لذا احرصي على شرب الكثير من السوائل والالتزام بنظام غذائي صحي.') WHERE id = 'e561aed2-5768-4e9c-b71e-e052866b75f4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يمكنكِ هذا الأسبوع أن تري بوضوح في فحص الموجات فوق الصوتية مدى نشاط طفلكِ في تحريك يديه وذراعيه وساقيه. وعلى الرغم من أنه يتحرك باستمرار داخل رحمكِ، فإنكِ تحتاجين إلى بضعة أسابيع أخرى لتشعري بهذا «الرقص». وعادةً ما تصبح الحركات قوية بما يكفي للشعور بها في الأسبوعين 16-17 من الحمل. لكن هذه المدة تختلف من امرأة إلى أخرى: في الحمل الأول: قد يستغرق الشعور بالحركات حتى الأسبوع 22 لأن عضلات البطن تكون أكثر تماسكًا. في حالات الحمل اللاحقة: قد تتعرف الأمهات ذوات الخبرة إلى هذا الإحساس في وقت أبكر، وأحيانًا بدءًا من الأسبوع 16. لا تكون الحركات الأولى ركلات قوية، بل تُشعَر بلطف أشبه بـ«دغدغة خفيفة» أو «رفرفة فراشة» أو «خفقان جناحي طائر». أما انتظام هذه الحركات والشعور بها يوميًا، فيبدأ في المتوسط اعتبارًا من الأسبوعين 24-26.'), baby_message_ar = COALESCE(baby_message_ar, '14 أُسْبُوعًا! 📏 أنا بحجم حبة خوخ! أصبح جسمي الآن ينمو أسرع من رأسي، لذلك صرت أشبه بطفل صغير أكثر. لقد استطالت رقبتي وتشكلت ذقني. أكبر قليلًا كل يوم، وأقترب كل يوم خطوة أخرى من لقائكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خوخ'), body_changes_ar = COALESCE(body_changes_ar, 'قد يستمر الغثيان الصباحي ونوبات القيء المفاجئة لديكِ. وتُعد هذه الحالة طبيعية لدى الحوامل، ولا تتطلب علاجًا في معظم الأحيان.;;;
 تُلاحظ بدرجات متفاوتة لدى ما يقارب نصف الحوامل. لكن هذه الحالة قد تستمر مدة أطول وتكون أشد لدى الحوامل بتوأم. ويُعد الغثيان الصباحي، الذي يظهر خصوصًا في الأسابيع الأولى من الحمل، مؤشرًا على أن الهرمونات تؤدي وظائفها على نحو سليم. ومع ذلك، فإن أسباب الغثيان والقيء غير معروفة بدقة. ومن العوامل التي قد تفسر تفاوت شدة الغثيان الصباحي مستويات الهرمونات ودرجة التوتر والإرهاق.;;;
يمكنكِ اتخاذ بعض التدابير للتخفيف من هذه الحالة المزعجة. ومن بينها اتباع نظام غذائي غني بالبروتين والكربوهيدرات، وشرب الكثير من السوائل لتعويض ما تفقدينه بسبب القيء، والانتظام في تناول الفيتامينات، والابتعاد عن أي روائح أو مذاقات أو مناظر قد تثير لديكِ الغثيان.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إنه وقت رائع لشراء الملابس! اشتري بعض ملابس الحمل التي تمنحكِ الراحة وتجعلكِ تشعرين بالجمال. فقد تعيق الملابس الضيقة الدورة الدموية وتؤدي إلى ظهور الدوالي.') WHERE id = 'a6400bac-f975-43dc-a8f8-6c0a5411246c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تطورت العضلات الصغيرة في وجه طفلكِ بما يكفي للقيام بتعابير وجه مختلفة. وتوجد هذه العضلات حول الفم والعينين والأنف والأذنين، وستُستخدم مستقبلًا للتعبير عن المشاعر. ومن أهم العضلات العاملة في وجه طفلكِ: العضلات المحيطة بالعينين: تساعد على فتح الجفنين وإغلاقهما وعقد الحاجبين. العضلات المحيطة بالفم: تساعد على إغلاق الشفتين ومدهما إلى الأمام. كما أن هذه العضلات مهمة لإصدار الأصوات. عضلات «النفخ» (عضلات الخدين): توجد في الخدين، وستؤدي مستقبلًا دورًا في مضغ الطعام وحركة النفخ. وعلى الرغم من أن طفلكِ لا يؤدي هذه التعابير بوعي حتى الآن، كالابتسام عن قصد مثلًا، فإنه مع تطور دماغه سيستخدم هذه العضلات ليُظهر لكِ فرحه أو غضبه أو جوعه أو تعبه.'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع تذوق النكهات! 🍭 لقد بدأت براعم التذوق على لساني بالعمل. وتنتقل نكهات الأطعمة التي تتناولينها إلى السائل الأمنيوسي. إذا تناولتِ شيئًا حلوًا، أبتلع المزيد من السائل لأنني أحب المذاق الحلو! وإذا تناولتِ شيئًا مُرًّا أو حامضًا، فقد أعبس وأقطّب وجهي. أنتِ أول طاهية لي يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خوخ'), body_changes_ar = COALESCE(body_changes_ar, 'قد يظهر لدى 30% من الحوامل اضطراب غذائي يُعرف بمتلازمة بيكا، ويتمثل في الرغبة في تناول مواد لا تؤكل عادةً. وكلمة بيكا مشتقة من اللاتينية وتعني طائر العقعق الذي يأكل كل ما يجده. ومن أكثر المواد التي يتناولها المصابون بهذه المتلازمة شيوعًا الثلج والرماد والطين والصابون والورق والشعر ومسحوق الطوب والجص الأبيض وأوراق النباتات ورصاص أقلام الرصاص. وقد يتعرض أطفال الحوامل اللواتي يتناولن هذه المواد لمشكلات خطيرة. ولا يُعرف على وجه الدقة سبب تعرض النساء لنوبات بيكا. لكن وفقًا للمتخصصين، قد تكون لهذه النوبات علاقة بنقص الحديد، أو قد تكون محاولة من الجسم للحصول بطرق أخرى على الفيتامينات والمعادن التي لا يحصل عليها بكميات كافية من الغذاء المعتاد.;;;
وقد تشمل الأسباب أيضًا الاضطرابات النفسية والحرمان من الحب وانعدام الشعور بالأمان والنقص العاطفي. وإذا كان فقر الدم ناتجًا عن نقص الحديد، فيجب علاجه. كما ينبغي التوقف عن تناول هذه المواد حفاظًا على صحة الأم وطفلها، ومعالجة العوامل المسببة للمشكلة النفسية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للوقاية من الإمساك، تناولي الأطعمة الغنية بالألياف (المشمش، والبرقوق، والشوفان، والخضروات). يساعد شرب كوب من الماء الفاتر صباحًا على معدة فارغة في تنشيط الأمعاء. وتزيد قلة الحركة من خمول الأمعاء، لذا اخرجي للمشي.') WHERE id = '85f3613e-2010-4d4b-a7cf-efafd3875999';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تنمو بشرة طفلكِ بسرعة وتزداد سماكة، وتستمر في التغطّي بشعر اللانوغو للمساعدة في الحفاظ على حرارة جسمه. يبدأ الجلد، وهو أكبر عضو في الجسم، بالتكوّن منذ الأسبوع الثالث من الحمل. وقد تسارع بالفعل نمو الشعر في الطبقة الخارجية من الجلد. خلال هذه الفترة، ينمو الشعر بسرعة أكبر ويصبح أكثر سماكة. وفي الوقت نفسه، تتكوّن في الجلد خلايا خاصة تُسمّى الخلايا الميلانينية. تنتج هذه الخلايا صبغة الميلانين التي تحدد لون البشرة والشعر. وتشبه الخلايا الميلانينية «واقي الشمس» الطبيعي للجسم، إذ تحمينا من أشعة الشمس الضارة:;;;
عندما تكون أشعة الشمس قوية: تتحرك الخلايا الميلانينية نحو سطح الجلد، فتجعل البشرة أغمق وتمنع الأشعة الضارة من التغلغل إلى الداخل.;;;
عندما تكون أشعة الشمس ضعيفة: تتراجع هذه الخلايا إلى طبقات الجلد الأعمق. وهكذا يصبح لون البشرة أفتح ويتمكن الجسم من الاستفادة من أشعة الشمس بسهولة أكبر، مثل استخدامها لإنتاج فيتامين D.'), baby_message_ar = COALESCE(baby_message_ar, '100 يوم! 💯 ماما، لا أصدق أننا معًا منذ 100 يوم بالفعل! أصبح حجمي الآن بحجم راحة اليد. وأتعلم حاليًا مصّ إبهامي، فهذا يهدئني. عندما تشعرين بالقلق أو التعب، أحس بذلك وأمصّ إصبعي لأهدئ نفسي. نحن نشعر ببعضنا بعضًا. أحبكِ كثيرًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ليمونة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يكون احتقان الأنف مزعجًا للغاية خلال بعض مراحل الحمل. ويمكن أن يظهر لدى نحو ثلث الحوامل حتى في غياب الحساسية أو أمراض معروفة مثل نزلات البرد والإنفلونزا. وتُسمّى هذه الحالة زكام الحمل أو التهاب الأنف الحملي.;;;
بالإضافة إلى ذلك، قد يصاحب احتقان الأنف سيلانٌ أنفي. وقد يؤدي التنفس عبر الفم ليلًا بسبب الاحتقان إلى جفاف الحلق. كما قد يسبب ضيق التنفس والسعال ليلًا الأرق. ويمكن أن يظهر الصداع أيضًا نتيجة تورم الغشاء المخاطي وانخفاض تهوية الجيوب الأنفية. ويسبب ارتفاع مستوى الإستروجين، وهو أحد هرمونات الأمومة، خلال الحمل تورم الأنسجة داخل الأنف ويحفز زيادة الإفرازات الأنفية. كذلك تؤدي زيادة حجم الدم في الجسم أثناء الحمل إلى توسع الأوعية الدموية وتورم الغشاء المخاطي للأنف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بهذا اليوم المميز بطقس صغير! ما رأيكِ في كتابة أول رسالة إلى طفلكِ؟ بما أن حاجتكِ إلى الكالسيوم قد ازدادت، زيدي كمية الجبن القريش والجبن والزبادي في نظامكِ الغذائي. وإذا كنتِ تعانين ألمًا في الظهر، فضعي وسادة بين ساقيكِ أثناء النوم، فهذا يخفف الضغط عن العمود الفقري. ولا تنسي شرب الكثير من الماء والمشي في الهواء الطلق.') WHERE id = '0cebfe33-ab23-4322-9649-a229de8418e8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تجري في جسم طفلكِ عملية مذهلة لإنتاج الدم. ففي الأسابيع الأولى من الحمل، كان كيس المُحّ ينتج الدم، ثم تولّى الكبد هذه المهمة، أما منذ الأسبوع 12 فقد بدأ نخاع العظم يتولى هذه الوظيفة المهمة. وعندما يولد طفلكِ، سيكون في جسمه نحو 350 ml من الدم. في الوقت الحالي، يبدو جسم طفلكِ وكأنه مكوّن من «الماء»، إذ يشكل الماء نحو 94% منه. ومع تصلب العظام وزيادة الكتلة العضلية، ستنخفض هذه النسبة قليلًا: في منتصف الثلث الثاني من الحمل: 80-85% ماء. وقرب الولادة: 70% ماء (لأن الطبقة الدهنية تزداد بسرعة خلال هذه الفترة). وللمقارنة، لا يشكل الماء سوى 60% من جسم الإنسان البالغ.;;;
للحفاظ على هذا التوازن المائي، تفرز الغدة النخامية في الدماغ هرمونًا يُسمّى الفازوبريسين (ADH). ويساعد هذا الهرمون الكليتين على إعادة امتصاص الماء، ما يحمي طفلكِ من الجفاف ويحافظ على توازن السوائل في جسمه.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا ماما! 👋 أمارس اليوم تمارين بهلوانية حقيقية تحت الماء. لا تشعرين بي بعد، لكنني أتشقلب وأدور وأمدّ ساقيّ. لا يزال المكان هنا واسعًا جدًا بالنسبة إليّ، ويمكنني التحرك كما أشاء. تقوّي هذه الحركات عضلاتي وتُصلّب عظامي. استريحي أنتِ، وسأواصل أنا تماريني. ستشعرين بهذه الركلات يومًا ما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ليمونة'), body_changes_ar = COALESCE(body_changes_ar, 'تواجه كل امرأة تقريبًا مشكلة الإمساك في مرحلة ما من الحمل. ومن أسباب الإمساك أثناء الحمل ارتفاع مستوى هرمون البروجستيرون في الدم عبر المشيمة، إذ يعمل على إرخاء العضلات الملساء، بما فيها عضلات الجهاز الهضمي. كما قد تزداد شكوى الإمساك بسبب ضغط الرحم المتنامي على الأمعاء. ويؤدي ارتخاء عضلات الأمعاء إلى تحرك الطعام والفضلات ببطء أكبر عبر جهازكِ الهضمي. وقد تزيد مكملات الحديد الإمساك سوءًا أثناء الحمل، خاصة عند تناولها بجرعات مرتفعة. كذلك قد يؤدي الحزق أثناء التبرز أو إخراج البراز الصلب إلى تورم الأوردة في المستقيم وحدوث البواسير. إذا كنتِ تعانين الإمساك وتتناولين مكملات الحديد، فتأكدي من شرب كمية وفيرة من الماء. وإذا لم تخف الأعراض رغم ذلك، فقد تحتاجين، بناءً على توصية طبيبكِ، إلى استخدام نوع آخر من أقراص الحديد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أن قدرة طفلكِ على السمع تتحسن، أسمعيه موسيقى هادئة أو احكي له حكاية. ولتجنب النسيان، دوّني مهامكِ المهمة في مفكرة. لا تقلقي من تغيرات تصبغ بشرتكِ، فهي ستزول بعد الولادة. واصلي شرب الكثير من السوائل وتناول الأطعمة الغنية بالكالسيوم، مثل اللوز والبروكلي ومنتجات الألبان.') WHERE id = '4b92a6ac-df2b-4f98-b986-b23497226910';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبدأ العِقي (البراز الأول) بالتراكم في أمعاء طفلكِ التي تستطيل وتلتف. والعِقي مادة لزجة عديمة الرائحة تتكوّن من مزيج من السائل الأمنيوسي الذي يبتلعه طفلكِ طوال الحمل، وشعر اللانوغو المتساقط، وإفرازات الأمعاء. تتكوّن هذه المادة بنسبة 90% من الماء، وتتراكم في أمعاء طفلكِ حتى ولادته. وعادةً ما يطرح الطفل هذا البراز خلال أول 24 ساعة بعد الولادة. ولأنه لم يتعرض للهواء، يكون معقمًا ولا يسبب أي ضرر لطفلكِ داخل رحمكِ. ويكون لونه عادةً أخضر داكن أو أسود، لكنه يصبح أفتح ويتحول إلى الأصفر عندما يبدأ الطفل بالتغذي. وفي بعض الأحيان، وخصوصًا لدى الأطفال الذين تأخرت ولادتهم عن موعدها، قد يُطرح العِقي داخل الرحم. وفي هذه الحالات، ينظف الأطباء مجرى تنفس الطفل فور ولادته لمنع وصول هذه المادة إلى الرئتين والتسبب في مشكلات.'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بالضوء! 💡 ماما، لن تصدقي ذلك، لكنني أستطيع الشعور بالضوء القوي رغم أن جفنيّ مغلقان. إذا وجّهتِ مصباحًا ساطعًا نحو بطنكِ، فقد أدير وجهي نحوه أو أغطي وجهي بيدي لأن الضوء يبهر عينيّ. لم يعد عالمي مظلمًا تمامًا. تُرى، كم هو ملوّن عالمكِ؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ليمونة'), body_changes_ar = COALESCE(body_changes_ar, 'مع انغراس طفلكِ في الرحم، تبدأ قنوات الحليب وحجم الثديين بالتطور استعدادًا للولادة وإنتاج الحليب. وابتداءً من الأسبوع 16 من الحمل، قد تلاحظين خروج سائل مائل إلى الصفرة من ثدييكِ بين الحين والآخر. ويكون هذا السائل عديم الرائحة وأصفر اللون أو شفافًا. ويُسمّى اللبأ، ويحتوي على العديد من الأجسام المضادة الضرورية لطفلكِ الذي لم يكتمل نمو جهازه المناعي بعد، كما يحميه من مختلف الفيروسات والميكروبات. ويحتوي هذا السائل على كمية أكبر من البروتين مقارنةً بحليب الأم الناضج.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ابدئي بتغيير وضعية نومكِ مع ازدياد حجم بطنكِ. فقد يؤدي النوم على الظهر إلى ضغط الرحم على الأوعية الدموية الرئيسية لدى الأم. ويُعد النوم على الجانب الأيسر الوضعية المثلى لدورتكِ الدموية ولدورة طفلكِ الدموية.') WHERE id = '6ada13a0-2697-47e7-9001-03b1698db1b4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد تطور الجهاز العصبي لطفلكِ إلى درجة تمكّنه من التحكم بيديه وذراعيه وساقيه بوعي أكبر. فهو لم يعد يتحرك فحسب؛ بل يقبض يديه، ويحرك أصابعه واحدًا تلو الآخر، ويثني معصميه، ويقوم بحركات إمساك كما لو كان سيقبض على شيء ما. بدأت حركات طفلكِ الأولى منذ الأسبوعين 7-8، مع تحرك العمود الفقري. وفي ذلك الوقت، كان صغيرًا جدًا بحيث لم يكن من الممكن الشعور بحركات انحنائه إلى الأمام والتوائه إلى الجانبين، أما الآن فقد أصبحت هذه الحركات أقوى وأكثر إرادية. لم يتبقَّ سوى القليل حتى تعيشي هذا الشعور الرائع! عادةً ما تبدأ الأمهات بالشعور بحركات الطفل الأولى بين الأسبوعين 16 و20. وستكون الأحاسيس الأولى التي تشعرين بها نتوءات صغيرة ناتجة عن ركلات طفلكِ أو ضربات مرفقيه أو تمديد جسمه إلى الخلف. إذا كان هذا حملكِ الأول أو كان وزنكِ زائدًا قليلًا، فقد يتأخر شعوركِ بهذه الحركات حتى الأسبوع 24، وهذا طبيعي تمامًا. في مثل هذه الحالات، يمكنكِ تجربة حيلة بسيطة: قد يؤدي تناول الحلوى إلى رفع مستوى السكر في دمكِ، ما ينشّط طفلكِ ويساعدكِ على الشعور بحركاته في وقت أبكر.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتدرّب على التنفس! 🌬️ بالطبع، لا يوجد هواء هنا، بل ماء فقط. لكنني أسحب السائل الأمنيوسي إلى رئتيّ ثم أخرجه. وهذا يساعد على فتح الحويصلات الهوائية في رئتيّ ويهيئهما لنفسي الأول مستقبلًا. وأحيانًا أصاب بالفواق عندما يدخل هذا السائل إلى حلقي. وقد تشعرين بهذا الفواق المنتظم بعد بضعة أسابيع.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ليمونة'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد الأرق، وهو صعوبة الاستغراق في النوم والاستمرار فيه، مشكلة شائعة جدًا أثناء الحمل أيضًا. ويؤثر الأرق في جميع الحوامل تقريبًا، ويكون أكثر وضوحًا خلال الأشهر الثلاثة الأخيرة، حين يكبر البطن كثيرًا وتصبح علامات الحمل أكثر بروزًا. منذ بداية حملكِ، وبسبب التغيرات التي تطرأ على جسمكِ، يبدأ دماغكِ بإرسال إشارات تخبركِ بأنكِ بحاجة إلى مزيد من الراحة. فتشعرين بالتعب طوال اليوم وتزداد حاجتكِ إلى الراحة والنوم. لكن بعض المتاعب التي تظهر، خصوصًا خلال الأشهر الأخيرة من الحمل، قد تعطل نمط نومكِ. ومن الحالات التي قد تسبب الأرق طوال فترة الحمل: حرقة المعدة، وتورم الساقين، وكثرة التبول، وتسارع ضربات القلب، وضيق التنفس، والتشنجات والآلام الناتجة عن زيادة الحمل على الساقين، وكذلك الارتجاع المعدي الناتج عن بطء الجهاز الهضمي. إضافة إلى ذلك، قد يسبب التوتر الشديد وسوء الحالة المزاجية الأرق أثناء الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف التعب في ساقيكِ، غيّري وضعيتكِ باستمرار خلال اليوم وتجنبي الوقوف لفترات طويلة. وفي المساء، ارفعي ساقيكِ إلى مستوى أعلى من القلب وأريحيهما لمدة 15 دقيقة. والتزمي بنظام غذائي صحي غني بالبروتين والألياف. وإذا كنتِ ترتدين أحذية ذات كعب، فقد حان الوقت للانتقال إلى أحذية أقصر كعبًا ومصممة طبيًا لدعم القدمين.') WHERE id = 'ad6452f4-e2be-4e97-a304-4ef7692bd10b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ قلب طفلكِ بالنبض منذ الأسبوع 4، عندما تجمعت بضع خلايا فقط وبدأت تنقبض وتنبسط بصورة مدهشة. وخلال 40 يومًا فقط، تطور هذا المحرك الصغير ليصبح عضوًا مكتمل التكوين مكوّنًا من 4 حجرات. وفي الوقت الحالي، أي خلال الشهر الرابع، يضخ قلب طفلكِ نحو 20-25 لترًا من الدم يوميًا إلى جسمه الصغير. وعند الولادة، سيرتفع هذا الرقم بصورة مذهلة ليصل إلى 250-300 لتر يوميًا. ينبض قلب طفلكِ بسرعة تعادل نحو ضعف سرعة نبض قلبكِ (140-160 نبضة في الدقيقة). وطوال فترة الحمل، سينبض هذا القلب الصغير أكثر من 1.5 مليون مرة، موصلًا الدم والحياة إلى كل خلية في جسم طفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أستمع إلى قلبكِ! ❤️ تتحسن قدرتي على السمع يومًا بعد يوم. فنبض قلبكِ، وصوت تدفق دمكِ في الأوعية، وقرقرة معدتكِ تشكّل موسيقى دائمة بالنسبة إليّ. هذه الأصوات تهدئني. وحتى بعد ولادتي، عندما تضمينني إلى صدركِ، سأسمع نبض قلبكِ وأهدأ، لأن هذا الصوت سيذكّرني بـ"المنزل".'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تفاحة قوبا'), body_changes_ar = COALESCE(body_changes_ar, 'يحتاج الشخص عادةً إلى شرب نحو 2 لتر من الماء يوميًا. لكن هذه الكمية قد ترتفع خلال الحمل إلى 3-3.5 لترات، لأن نمو الطفل يضاف إلى التغيرات الفسيولوجية التي يمر بها جسم المرأة أثناء الحمل، ما يزيد حاجة الجسم إلى الماء. ومن بداية الحمل حتى نهايته، يزداد حجم الدم بنحو 1-1.5 لتر، كما يتكوّن السائل الأمنيوسي داخل الرحم المحيط بطفلكِ. ويحتاج هذا السائل إلى التجدد على مدار اليوم، إذ يُستبدل على فترات بالماء الموجود في جسم الأم فيتجدد وينقى. وتُعد كفاية كمية السائل الأمنيوسي المحيط بطفلكِ بالغة الأهمية لحركته ولنمو رئتيه. ولأن الماء يشكّل أيضًا نحو 80% من بنية خلايا الطفل، فإن كمية الماء التي تشربها الأم تؤثر مباشرةً في الطفل. كما أن الماء مهم جدًا خلال هذه الفترة لتنظيم حرارة الجسم، وراحة المفاصل، ونضارة البشرة، وصحة الجهاز الهضمي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ارتدي ملابس داخلية قطنية وتجنبي السراويل الضيقة. وإذا كنتِ تستخدمين الفوط اليومية، فغيّريها كل 3-4 ساعات حتى لا تتسبب البيئة الرطبة في تكاثر البكتيريا. ومن المهم الحفاظ على جفاف المنطقة الحميمة.') WHERE id = '170cfd85-3741-42d0-81e6-fb29eb61eb4e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبلغ وزن طفلكِ هذا الأسبوع نحو 50 غرامًا وطوله 11-12 سم. وقد أصبح يبدو كإنسان مصغّر يستريح بأذنين صغيرتين وجفنين مغلقين، ويغطي جسمه شعر زغبي كثيف يُسمى اللانوغو، يمتد من فروة رأسه إلى حاجبيه. وعلى الرغم من اكتمال عيني طفلكِ من الناحية البنيوية، فإنهما ستكونان آخر عضو يكتمل تطوره وظيفيًا. ولهذا سبب مثير للاهتمام: فرغم كثرة الخلايا العصبية (العصبونات)، لم يتكوّن غمد الميالين المحيط بها بعد. وغمد الميالين طبقة دهنية خاصة تغلف الأعصاب، ويمكن تشبيهها بطبقة العزل المحيطة بالأسلاك الكهربائية. ومن دون هذه الطبقة، لا يمكن نقل الإشارات الكهربائية بسرعة بين العصبونات. ومع تكوّن غمد الميالين، سيتمكن طفلكِ من استقبال الصور والإشارات القادمة من الخارج وفهمها بسرعة أكبر.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، لا تزال بشرتي رقيقة جدًا، لكن الشعر الذي يغطي جسمي والمسمى "اللانوغو" يبقيني دافئًا. وبدأت ساقاي تصبحان أطول من ذراعيّ. لقد أصبح شكل جسمي أكثر تناسقًا الآن. النمو متعب جدًا، لكنني أستطيع فعل ذلك!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تفاحة قوبا'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي لكِ شرب كميات وفيرة من الماء خلال الحمل حفاظًا على صحتكِ وصحة طفلكِ. فكمية الماء التي تشربينها خلال هذه الفترة تؤثر فيكِ بقدر تأثيرها في طفلكِ. ولا يساعد شرب كمية كافية من الماء أثناء الحمل على معالجة العديد من المشكلات فحسب، بل قد يمنع بعضها تمامًا. ويساعد الترطيب الكافي أثناء الحمل على الحد من تقلصات الرحم، ما يقلل خطر الولادة المبكرة. كما يمنح بشرتكِ مظهرًا أكثر إشراقًا وصحة، ويخفف ظهور علامات تمدد الجلد. ويساعد على الوقاية من التهابات المسالك البولية والإمساك والبواسير. كذلك يحد من مشكلات نقص السائل الأمنيوسي المحيط بطفلكِ وعدم تجدده وتنقيته. ويعوّض السوائل المفقودة بسبب التعرق، خصوصًا خلال أشهر الصيف الحارة. كما يخفف أعراض الغثيان وحرقة المعدة والوذمة التي قد تصيب الجسم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يُعد تناول اللوز أو شرب كوب من الحليب الفاتر وسيلة طبيعية لتهدئة حرقة المعدة.') WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن طفلكِ يستطيع السمع والبكاء وإظهار بعض ردود الفعل المنعكسة منذ لحظة ولادته، فإنه لا يزال بحاجة إلى الوقت لاكتساب مهارات مثل الرؤية والكلام والمشي. ويعود السبب الأساسي إلى أن الجهاز العصبي لم يتعرض بعد لقدر كافٍ من المحفزات الخارجية. إذ يكتمل نمو الدماغ عبر نوع من "اكتساب الخبرة". وتُعد حاسة البصر على وجه الخصوص آخر الحواس تطورًا. فعند الولادة، لا تكون شبكية العين ولا مركز الإبصار في الدماغ قد نضجا بالكامل بعد. يستطيع طفلكِ تمييز الضوء داخل الرحم، لكن هذا لا يُعد رؤية مكتملة. وخلال الأشهر 3 الأولى، تظل الرؤية ضبابية، ولا يستطيع طفلكِ تمييز سوى الأجسام التي تبعد عنه مسافة 50-70 سم (وهي تقريبًا المسافة التي تتيح له رؤية وجهكِ عندما تحملينه بين ذراعيكِ). كما تظل قدرته على التركيز البصري ضعيفة. وعندما يبلغ عمره 5-6 أشهر، تصبح رؤيته أكثر حدة بالتزامن مع تحسن قدرته على الحركة. ويبدأ حينها بتتبع الأجسام المتحركة بعينيه ومد يده نحو اللعبة التي يراها بفضل التناسق بين اليد والعين. ويكتمل نمو العين والأعصاب البصرية تمامًا في سن 7 سنوات.'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع تمييز النكهات! 🍬 ماما، عندما تتناولين شيئًا حلوًا، يصبح مذاق السائل الأمنيوسي حلوًا فأبتلع منه كمية أكبر. أما عندما يكون حامضًا أو مرًا، فأعبس بوجهي. إن حاسة التذوق لدي قوية بقدر حاسة شخص بالغ تقريبًا. والخضراوات التي سأحبها مستقبلًا تعتمد منذ الآن على نظامكِ الغذائي. تناولي طعامًا صحيًا لكي أكون بصحة جيدة أيضًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تفاح قوبا'), body_changes_ar = COALESCE(body_changes_ar, 'قد يطلب منكِ طبيبكِ إجراء اختبار التحري الثلاثي في الأسبوع المقبل. وهو فحص دم يُوصى به لجميع الحوامل بين الأسبوعين 16 و18 من الحمل. ويُقاس في عينة دم مأخوذة من الحامل مستوى 3 هرمونات مختلفة. ثم تُدخل قياسات هذه الهرمونات، إلى جانب مؤشرات مثل عمر الأم ووزنها وما إذا كانت تدخن أم لا وأسبوع الحمل، في برنامج حاسوبي خاص لتحليلها. يهدف الاختبار إلى التحري عن اضطرابات الكروموسومات لدى الجنين، ولا سيما التثلث الصبغي 21 المعروف بمتلازمة داون والتثلث الصبغي 18 المعروف بمتلازمة إدواردز، بالإضافة إلى التشوهات المعروفة بعيوب الأنبوب العصبي.  ومن المهم بوجه خاص إجراء هذا الاختبار إذا كان لديكِ تاريخ عائلي من العيوب الخِلقية، أو كان عمركِ 35 عامًا فأكثر، أو تناولتِ أدوية أو أقراصًا ضارة خلال الحمل، أو كنتِ تستخدمين الإنسولين أو مصابة بداء السكري، أو أُصبتِ بعدوى فيروسية أثناء الحمل، أو سبق لكِ إنجاب طفل لديه عيب خِلقي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بانتهاء الأسبوع 15 بتدليل نفسكِ قليلًا! ارتدي أحذية مريحة وتجنبي رفع الأشياء الثقيلة للوقاية من آلام الظهر. ولا تنسي الحصول على الكالسيوم بانتظام للحفاظ على صحة اللثة. ستزداد قوة حركات طفلكِ في الأسبوع المقبل، لذا اجعلي التحدث إليه بهدوء لبضع دقائق كل يوم عادةً لكِ.') WHERE id = '7f759cae-0b0a-4f2e-8095-e125d4622671';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اعتبارًا من هذا الأسبوع، لم يعد قياس طول طفلكِ وحده كافيًا لمتابعة نموه. لذلك يركز الأطباء على مؤشرات أكثر تفصيلًا، مثل محيط الرأس والبطن وطول عظم الفخذ. وتوضح هذه القياسات بدقة ما إذا كان نمو طفلكِ يتوافق مع أسبوع الحمل. أصبح طفلكِ الآن قادرًا على إبقاء رأسه ورقبته في وضع أكثر استقامة. ويرجع ذلك إلى العضلات القوية الموجودة على جانبي الرقبة، إذ تدعم هذه العضلات الجمجمة وتتيح لطفلكِ تحريك رأسه بحرية. وتحتوي المفاصل المتحركة على سائل زليلي يمنع احتكاك العظام ببعضها وتآكلها. ويساعد هذا السائل العظام على التحرك بسهولة ومن دون ألم كما لو كانت مُزلّقة.'), baby_message_ar = COALESCE(baby_message_ar, 'ساقاي تطولان! 🦵 حتى الآن، كانت ذراعاي وساقاي متساوية في الطول، لكن ساقيّ بدأتا الآن بالنمو بوتيرة أسرع مقارنة بجسمي. أصبحت أبدو كعارض أزياء حقيقي! أثني ساقيّ وأضم ركبتيّ نحوي. وأستعد بهاتين الساقين الطويلتين لأركلكِ ركلة قوية. أنا أمزح، لن أؤلمكِ، بل سأقول لكِ فقط "مرحبًا".'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'تفاح قوبا'), body_changes_ar = COALESCE(body_changes_ar, 'بعد هذه المرحلة من حملكِ، يضعف تدفق الدم في أوردة الساقين بسبب النمو السريع لطفلكِ وضغطه على الأوعية الدموية في منطقة الأربية. وعندما يُضاف إلى ذلك الطقس الحار خلال أشهر الصيف، قد تظهر الوذمة في مناطق مختلفة من جسمكِ، ولا سيما القدمين والكاحلين والساقين. ولتخفيف هذه الأعراض، استريحي كلما سنحت لكِ الفرصة، واستلقي على سرير أو أريكة مريحة، وارفعي ساقيكِ بوضع وسادة تحتهما، ودلّكي يديكِ وكاحليكِ برفق عند الحاجة، واحرصي على ارتداء أحذية مريحة.;;;
ومن الأسباب الأخرى لظهور الوذمة في جسمكِ الزيادة المفرطة في الوزن المصاحبة لقلة الحركة. ويساعد تنظيم نظامكِ الغذائي وممارسة التمارين المناسبة أثناء الحمل، إلى جانب التحكم في الوزن، على تخفيف آلام الظهر والأربية التي قد تظهر خلال الأشهر المقبلة.;;;
يُعد المشي والسباحة من أنسب التمارين للحوامل. فكلاهما من الأنشطة الرياضية التي تستطيع الحامل ممارستها من دون تعريض القلب أو التوازن أو المفاصل أو العضلات للخطر. وينبغي أخذ فترات راحة قصيرة أثناء ممارسة الرياضة وتجنب إرهاق الجسم بشدة. ويُفضل قدر الإمكان اختيار البحر بدلًا من المسبح للسباحة. كما ينبغي لكِ الابتعاد عن المسابح التي لستِ متأكدة من خضوعها للرقابة المناسبة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'نظرًا إلى زيادة حجم الدم، أولي اهتمامًا خاصًا بالحصول على الحديد. وحاولي تجنب الحركات المفاجئة لتخفيف آلام الأربطة. وإذا شعرتِ بحكة في بطنكِ، فدلّكيه كل مساء بزيوت مرطبة. وللاستمتاع بيوم لطيف، يمكنكِ قراءة كتاب تحبينه لطفلكِ بصوت مرتفع.') WHERE id = 'abd207ad-c924-457f-b115-c38d8e842b83';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن بُنية الأذن الداخلية لطفلكِ تبدأ بالتشكل هذا الأسبوع، فإنه لا يزال بحاجة إلى بضعة أسابيع حتى يبدأ السمع فعليًا. فالأذن الداخلية نظام معقد للغاية، وهي مسؤولة عن سماع الأصوات والحفاظ على توازن الجسم معًا.;;;
وعندما يكتمل نمو طفلكِ، سيتمكن عبر هذا النظام من سماع جميع الأصوات التي يتراوح ترددها بين 20 و20.000 هرتز. يجري حاليًا تجهيز هذا "الجهاز" المذهل، لكنه لن يبدأ العمل بكامل قدرته إلا في مراحل لاحقة من الحمل (نحو الأسبوع 30 تقريبًا).'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بكِ! 🤗 ماما، عندما تربتين على بطنكِ، أستطيع الشعور بذلك الضغط والدفء. وأسبح أحيانًا نحو الموضع الذي تضعين فيه يدكِ. لا يفصل بيننا سوى الجلد والماء، لكن روحينا واحدة. عندما تشعرين بالتوتر أقلق أنا أيضًا، وعندما تضحكين أشعر بالراحة. أرجوكِ، ابتسمي دائمًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'برتقالة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين من وقت إلى آخر بأنكِ عاطفية أو متوترة، أو تراودكِ مشاعر متضاربة. إذ تطرأ على جسمكِ بعض التغيرات خلال الحمل، وقد تؤثر هذه التغيرات الجسدية والهرمونية في حالتكِ النفسية أيضًا. وتُعد شدة التأثر وسرعة الاستياء والحساسية من أكثر المشاعر شيوعًا خلال هذه المرحلة. تذكري أن هذه المشكلات التي تحدث أثناء الحمل مؤقتة، وأن حصولكِ على الدعم من شريككِ في هذا الشأن سيكون له أثر إيجابي في كليكما.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عندما تشعرين بضيق التنفس، قفي باستقامة وأرجعي كتفيكِ إلى الخلف. فهذا يمنح الرئتين مساحة أكبر. ويساعد التنفس ببطء وعمق على تزويدكِ أنتِ وطفلكِ بالأكسجين.') WHERE id = '2da10eb1-918c-43c6-ad16-6306b072b4cb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدءًا من هذا الأسبوع، تتباطأ سرعة نمو رأس طفلكِ قليلًا حتى يتمكن جسمه من اللحاق بحجمه. وفي الوقت نفسه، تكونت بالفعل في رئتيه أهم الأجزاء التي ستمكّنه من التنفس مستقبلًا، وهي الحويصلات الهوائية. الحويصلات الهوائية أكياس صغيرة تقع عند النهايات الدقيقة للرئتين وتمتلئ بالهواء. وتتمثل وظيفتها الأساسية في تبادل الغازات، إذ تلتقط ثاني أكسيد الكربون من الدم للتخلص منه وتنقل الأكسجين الذي يحتاج إليه الجسم إلى الدم. يتدرّب طفلكِ حاليًا على استخدام هذا النظام بالسائل الأمنيوسي بدلًا من الهواء. وهذه التدريبات مهمة جدًا ليتمكن من أخذ نَفَسه الأول لحظة ولادته.'), baby_message_ar = COALESCE(baby_message_ar, 'أذناي في مكانهما! 👂 أصبحت أذناي الآن على جانبي رأسي تمامًا، أي في موضعهما النهائي. أستطيع الآن سماعكِ بوضوح أكبر. تبدو أصوات أمعائكِ وأنفاسكِ بالنسبة إليّ كأنها سيمفونية. لكن صوتكِ وضحكتكِ هما أحب الأصوات إليّ. غنّي لي التهويدات كثيرًا، فأنا أحفظها.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'برتقالة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تتعرضين لنزيف الأنف خلال الأيام المقبلة. وقد تظهر هذه الشكوى لدى كثير من النساء في مرحلة معينة من الحمل، ولا داعي للقلق. يحدث نزيف الأنف بسبب زيادة حجم الدم والضغط على الأوعية الدموية مع نمو طفلكِ داخل الرحم. وقد تؤثر هذه التغيرات فجأة في الأوعية الدموية الدقيقة والسطحية، ما يؤدي إلى نزيف الأنف. إذ قد تتمزق الأوعية الدقيقة الموجودة في البطانة الداخلية للأنف وتنزف نتيجة هذا الضغط. عند حدوث نزيف في الأنف، لا يُنصح بالاستلقاء أو إمالة الرأس إلى الخلف، لأن الدم قد يصل إلى حلقكِ وتبتلعينه، ما قد يسبب الغثيان. بدلًا من ذلك، اجلسي أو قفي مع إمالة رأسكِ قليلًا إلى الأمام، واضغطي على الجزء اللين من أنفكِ حتى يتوقف النزيف. ويمكنكِ أيضًا، بناءً على توصية طبيبكِ، تناول مكمل فيتامين C للمساعدة على تقوية الأوعية الدموية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استخدمي فرشاة أسنان ناعمة للوقاية من نزيف اللثة. حاولي إشباع شهيتكِ المتزايدة بأطعمة صحية. تجنبي البقاء في الوضعية نفسها مدة طويلة للوقاية من آلام الظهر. أعدّي قائمة تشغيل تضم أغانيكِ المفضلة واستمعي إليها مع طفلكِ لتقضي يومكِ بمزاج لطيف.') WHERE id = '785f2466-b995-4db8-a286-7f765b7f2877';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ الآن بحجم ثمرة أفوكادو!  وأكثر تطورات هذا الأسبوع إثارة هو نمو حاسة التذوق لديه.;;;
تكونت بالفعل براعم التذوق على سطح لسان طفلكِ. وآلية التذوق معقدة ومثيرة للاهتمام؛ إذ يذوب الطعام في اللعاب داخل الفم، ثم تستقبل المستقبلات الموجودة على سطح اللسان هذه النكهات وتنقلها إلى المركز الحسي في الدماغ.;;;
وكأي كائن حي، يتعلم طفلكِ الاستجابة للمحفزات المحيطة به، وهي في هذه الحالة نكهة السائل الأمنيوسي الذي يبتلعه. ومن المثير للاهتمام أن جميع مناطق اللسان لا تستشعر كل النكهات بالقوة نفسها.;;;
وبما أن نكهات الأطعمة التي تتناولينها تنتقل إلى السائل الأمنيوسي، يتعرّف طفلكِ منذ الآن إلى نكهات متنوعة. وقد يؤثر ذلك حتى في تفضيلاته الغذائية مستقبلًا.'), baby_message_ar = COALESCE(baby_message_ar, 'قلبي قوي! 💪 يضخ قلبي الصغير نحو 25 لترًا من الدم يوميًا! إنه عمل هائل لجسم صغير مثلي. يدور الدم في جميع أنحاء جسمي ويجلب إليّ الأكسجين والعناصر الغذائية. بفضلكِ أملك قلبًا قويًا. وسيظل هذا القلب ينبض طوال حياتي ليحبكِ أنتِ وحدكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أفوكادو'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين من حين إلى آخر بإرهاق شديد، بينما قد تشعرين في بعض الأيام بطاقة أكبر من المعتاد. قد يجعلكِ الارتفاع السريع في مستوى البروجستيرون خلال الأشهر الثلاثة الأولى تشعرين بالنعاس. كما تتسارع عملية الأيض لديكِ وتستهلك طاقة أكبر، ما يزيد شعوركِ بالتعب في المراحل المبكرة من الحمل. إضافةً إلى ذلك، يؤدي انخفاض ضغط الدم وزيادة إنتاج الدم إلى استنزاف طاقتكِ. أما الثلث الثاني من الحمل الذي دخلتِه، فيُعرف باسم «شهر العسل» في الحمل. فقد تكيف جسمكِ الآن مع تدفق هرمونات الحمل، ولذلك قد تشعرين بتعب أقل مقارنة بالثلث الأول، ويمكنكِ البدء في الاستعداد التام لحقيقة قدوم طفلكِ. وللتعامل مع التعب في الفترات التي تشعرين فيها بالإرهاق، لا تنسي اتباع نظام غذائي صحي وشرب الكثير من الماء وتنظيم نومكِ والحفاظ على نشاطكِ البدني.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس باستقامة وإرجاع كتفيكِ إلى الخلف أثناء المشي؛ فهذا يساعد على تقليل آلام الظهر إلى أدنى حد. واصلي استخدام المرطبات للحفاظ على مرونة بشرتكِ. اختاري الأطعمة الغنية بالكالسيوم والمغنيسيوم، مثل اللوز والخضراوات الخضراء، لتقوية عظام طفلكِ والوقاية من تشنجات الساقين لديكِ.') WHERE id = '6a2c14a8-03ef-4ac3-8457-485f9afcbef3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح الهيكل العظمي لطفلكِ متطورًا بما يكفي ليظهر بوضوح في فحص الموجات فوق الصوتية. ويتكون الجهاز الهيكلي من العظام والمفاصل التي تربط بينها. وتعمل هذه العظام بالتعاون مع العضلات لتمكين طفلكِ من القيام بحركاته المرنة داخل رحمكِ.;;;
يحتوي جسم المولود الجديد على 270 عظمة، بينما يبلغ عدد عظام الإنسان البالغ 206 عظمات. ويرجع ذلك إلى أن عظام الطفل لا تزال غضروفية ومنفصلة بعضها عن بعض. وتساعد هذه المرونة على حماية الطفل من التعرض للإصابة أثناء مروره عبر قناة الولادة. وبعد الولادة، تلتحم هذه العظام الصغيرة، مثل أجزاء الجمجمة، تدريجيًا لتشكّل عظامًا أكبر وأكثر صلابة.'), baby_message_ar = COALESCE(baby_message_ar, 'أرفع رأسي باستقامة! 🦒 ماما، أصبحت عضلات رقبتي قوية لدرجة أنني أستطيع الآن إبقاء رأسي مرفوعًا باستقامة. كان رأسي في السابق منحنيًا نحو صدري، لكنني الآن أستطيع النظر حولي بسهولة أكبر، رغم أن المكان مظلم. يزداد جسمي طولًا، وأصبح أكثر رشاقة واستقامة. من الممتع جدًا ممارسة الجمباز داخل بطنكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أفوكادو'), body_changes_ar = COALESCE(body_changes_ar, 'بسبب تغير التوازن الهرموني أثناء الحمل، يمر جسمكِ بمرحلة مختلفة عن المعتاد. وعلى الرغم من شيوع أعراض مثل الغثيان والقيء وتشوش الرؤية والدوار والإغماء، خصوصًا خلال الأشهر الثلاثة الأولى من الحمل، فقد تظهر هذه الحالات من حين إلى آخر في أي مرحلة منه. ولأن الرحم ينمو أثناء الحمل أكثر بكثير من المعتاد، يتجه جزء كبير من الدم في الجسم إلى الرحم حيث يوجد طفلكِ. ولهذا قد لا يصل أحيانًا تدفق كافٍ من الدم إلى الأعضاء الأخرى، بما فيها الدماغ. وعندما لا يتمكن جسمكِ من تلبية حاجته المفاجئة إلى الدم، قد تشعرين بالدوار أو تتعرضين للإغماء. وللوقاية من احتمالية الدوار والإغماء خلال هذه الفترة، تجنبي الوقوف بسرعة أو بصورة مفاجئة، وتجنبي النوم على ظهركِ، ولا تتركي جسمكِ من دون طعام أو ماء، واحصلي على العلاج إذا كنتِ مصابة بفقر الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تنسي تدليك منطقة البطن بزيوت طبيعية لتخفيف الحكة. حاولي ألا تجلسي في الوضعية نفسها مدة طويلة للوقاية من آلام الظهر. شرب الكثير من السوائل مهم جدًا لعملية الأيض لديكِ ولدى طفلكِ. تنتظرنا مفاجآت أكبر في الأسبوع المقبل!') WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل المشيمة، المعروفة بأنها رفيقة طفلكِ، النمو معه. في الأسابيع الأولى من حملكِ، عندما تبدأ مجموعات الخلايا بالانقسام لتكوين طفلكِ، تتمايز بعض هذه الخلايا لتشكّل المشيمة. وبينما ينمو طفلكِ داخل الكيس الأمنيوسي، تستمر المشيمة المتصلة به عبر الحبل السري المتكوّن في التطور أيضًا. وعندما تصلين إلى الأسبوع 4 من حملكِ، تدعم هرمونات الحمل التي تبدأ مستوياتها بالارتفاع في جسمكِ نمو المشيمة إلى جانب دعمها نمو طفلكِ، فيواصل كل من الطفل والمشيمة النمو في الوقت نفسه داخل الكيس. المشيمة عضو مؤقت ينمو مع طفلكِ داخل الرحم، ويؤمّن تبادل العناصر الغذائية بينكِ وبينه طوال فترة الحمل، ثم يغادر جسمكِ بعد ولادة طفلكِ ليكون قد أتم مهمته. ويكون هذا العضو بحجم مماثل تقريبًا لحجم طفلكِ خلال جزء كبير من الحمل، ثم يصل في الأسابيع الأخيرة إلى قياس يتراوح في المتوسط بين 20-25 سم، وسماكة تتراوح بين 2-3 سم، ووزن يبلغ 500 غرام.'), baby_message_ar = COALESCE(baby_message_ar, 'رفرفة فراشة! 🦋 ماما، هل تشعرين بي؟ أنا أقوم بشقلبات في الداخل! تصف بعض الأمهات هذا الشعور بقولهن: "كأن فراشة ترفرف في بطني" أو "كأن سمكة تسبح". إذا لم تشعري بي بعد، فلا تحزني، فأنا ما زلت صغيرًا وركلاتي ضعيفة. لكنني سأركلكِ قريبًا ركلة ستجعلكِ تدركين الأمر فورًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد صحة الجهاز القلبي الوعائي، أي القلب والأوعية الدموية، مهمة خلال الحمل. لذلك يوصي المختصون بشدة بممارسة الرياضة أثناء الحمل ما لم يكتشف طبيبكِ أي مانع طبي لذلك. تساعد التمارين خلال الحمل على تخفيف الشكاوى الشائعة، مثل آلام الظهر وتشنجات الساقين والإرهاق، كما تزيد طاقتكِ. وتقلل ممارسة الرياضة أيضًا من خطر الإصابة بسكري الحمل وارتفاع ضغط الدم، وتحد بدرجة كبيرة من احتمال الإصابة باكتئاب ما بعد الولادة. كما تساعد على تسهيل عملية الولادة من خلال تعزيز القدرة على التحمل وقوة العضلات. وتساهم عضلات البطن والظهر التي تقوى بفضل التمارين في تقليل الآلام المصاحبة للحمل. كذلك تساعد تمارين إطالة الجسم بانتظام على تحديد مواضع تراكم التوتر وإرخاء العضلات المؤلمة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استلقي مساءً في غرفة هادئة، وضعي يدكِ على بطنكِ وركّزي جيدًا. أحيانًا لا يتطلب الشعور بالحركة سوى الهدوء والتركيز. وقد يساعد تناول شيء حلو على تحفيز طفلكِ على الحركة.') WHERE id = '6f4082a3-2c0c-4302-bc06-2af671b9e9b3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن جلد طفلكِ يواصل الازدياد سماكة، فإنه ما زال يبدو شفافًا في هذه المرحلة. وبفضل هذه الشفافية، لو تمكنتِ من رؤية طفلكِ لاستطعتِ مشاهدة الأوعية الدموية والهيكل العظمي والأعضاء من خلال جلده الرقيق. ويستمر منعكس الرمش لدى طفلكِ في التطور. ترمش الجفون بمعدل 15-20 مرة في الدقيقة، ليصل العدد إلى نحو 30 ألف مرة يوميًا. ولا يحمي الرمش مقلة العين فحسب، بل يحافظ أيضًا على مستوى مناسب من الرطوبة داخل العين وفي القرنية باستمرار. كما تغذي الجفون الطبقة الخارجية للعين التي لا تحصل على الأكسجين أثناء النوم. تحدث هذه الحركة بشكل لا إرادي، وبفضلها تُحمى العينان من الضوء الشديد والأجسام الغريبة. وعند إغلاق الجفن، تعمل الدموع التي تفرزها الغدد الدمعية على ترطيب مقلة العين بالكامل، ما يمنع جفاف العين ويحول دون إضرار المواد المهيجة بها. ويساعد الرمش أيضًا العين على تثبيت تركيزها على نقطة معينة أثناء الحركة.'), baby_message_ar = COALESCE(baby_message_ar, 'تتكوّن غددي العرقية! 💦 ما زال جلدي يتطور، وقد بدأت غددي العرقية بالتشكّل الآن. بالطبع، أنا لا أتعرق داخل الماء، لكنني سأحتاج إليها كثيرًا بعد ولادتي لتنظيم درجة حرارة جسمي. كل شيء هنا استعداد لحياتي المستقبلية. يا له من جسم رائع، إنه مدرسة مثالية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'مع نمو بطنكِ، قد تبدأين بالشعور بالحكة في منطقة البطن وملاحظة علامات تمدد تبدو كخطوط رفيعة. وفي مرحلة معينة من الحمل، قد تظهر على الثديين والأرداف والبطن خطوط وردية أو بنفسجية أو حمراء، منخفضة قليلًا ومثيرة للحكة. هذه الخطوط عبارة عن تمزقات دقيقة تنتج عن التمدد المفرط لطبقات الأنسجة الداعمة تحت الجلد. وتُعد طبيعتكِ الوراثية العامل الأهم في ظهور علامات التمدد. وإلى جانب العوامل الوراثية، تُعد الزيادة المفاجئة والمفرطة في الوزن عامل خطر آخر لظهورها على البطن. فقد يؤدي نمو البطن سريعًا إلى شد الجلد وفقدان مرونته، ما يسبب علامات التمدد. لذلك تُعد زيادة الوزن بشكل متوازن وضمن الحدود المثالية مهمة للغاية للحد من ظهورها. وللمساعدة على الوقاية من علامات التمدد أو تقليلها، حافظي على ترطيب بشرتكِ، واكتسبي الوزن بصورة متوازنة، واشربي الكثير من الماء، واتبعي نظامًا غذائيًا صحيًا، ومارسي التمارين الرياضية بانتظام.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للوقاية من الدوار، انهضي ببطء من وضعية الجلوس أو الاستلقاء. يساعد شرب الكثير من السوائل على الحفاظ على طاقتكِ وتجدد السائل الأمنيوسي أيضًا. وبما أن حاجتكِ إلى الكالسيوم قد ازدادت، فاحرصي على إدراج أطعمة مثل الجبن القريش والزبادي في نظامكِ الغذائي. كما يساعد إنهاء يومكِ بنزهة هادئة على شعوركِ أنتِ وطفلكِ بالراحة.') WHERE id = '011238e0-e01a-4bb0-b882-82b96d90dc82';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'هل تشعرين بين الحين والآخر بحركات خفيفة في بطنكِ؟ إنها على الأرجح حركات طفلكِ! 😊 لقد تطورت عظام طفلكِ وعضلاته بما يكفي وأصبحت قوية، لذا قد تبدئين الآن بالشعور بحركاته. ومن هذه المرحلة فصاعدًا، سيقوم طفلكِ بحركات أقوى يمكنكِ الإحساس بها. كما أن نمو الرحم وزيادة حجم السائل الأمنيوسي يوفران له مساحة واسعة جدًا للحركة. في هذه المرحلة من حملكِ، يمكن الشعور فقط بالحركات التي يلامس فيها طفلكِ جدار الرحم لأكثر من ثانية. وبفضل تطور عظامه وعضلاته بدرجة كبيرة، أصبح طفلكِ أكثر نشاطًا من أي وقت مضى، وهو يستخدم جميع عضلاته ليساعدها على النمو أكثر. إذا لم تشعري بطفلكِ بعد، فلا داعي للقلق؛ ستبدئين بالشعور به قريبًا جدًا. ومن أسباب تأخر الإحساس بحركات الطفل: تماسك عضلات البطن في الحمل الأول، أو عمل طبقة الدهون الموجودة في منطقة البطن كوسادة تخفف الإحساس بالحركة، أو زيادة كمية السائل الأمنيوسي المحيط بطفلكِ عن المستوى الطبيعي. تشعر 90% من الحوامل بحركات أطفالهن بين الأسبوعين 16-22.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أُغطّى بمادة تشبه "الجبن"! 🧀 يبدو الأمر مضحكًا، لكن مادة بيضاء كريمية بدأت تتكوّن على جلدي. تُسمى هذه المادة "الطلاء الجبني" (Vernix Caseosa). وهي تحمي جلدي الرقيق من التليّن بسبب وجودي في الماء. لولا هذا الطلاء، لأصبح جلدي مجعدًا بسبب بقائه في الماء فترة طويلة. إنه مرطبي الطبيعي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'تنتج المشيمة والرحم كميات كبيرة من البروجسترون خلال الحمل. ولذلك تؤدي المستويات المرتفعة من هرمون البروجسترون في الدم إلى إبطاء الحركة الدودية وانقباضات المعدة وإرخاء الصمام الفاصل بينها وبين المريء. ونتيجة لذلك، يتسرب حمض المعدة إلى المريء، فتحدث حرقة المعدة. وللمساعدة على الوقاية منها، تجنبي الأطعمة الدهنية أو الحارة والمشروبات المحتوية على الكافيين، واشربي الماء بدلًا من المشروبات الغازية، وابتعدي عن الوجبات الجاهزة والأطعمة المصنّعة مثل الكاتشب والمخللات. حاولي أيضًا الانتهاء من تناول الطعام قبل موعد النوم بثلاث ساعات، إذ يمكن لحمض المعدة أن يرتد بسهولة أكبر عبر الصمام المرتخي عند الاستلقاء. وبعد تناول عشاء متأخر، حاولي عدم الاستلقاء لمدة ساعة واحدة على الأقل. وقد يفيدكِ أيضًا تناول الحليب البارد والزبادي، وشرب شاي البابونج أو النعناع أو الزنجبيل، وتناول وجبات صغيرة ومتكررة، ومضغ اللقم جيدًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مارسي تمارين إطالة مخصصة لتخفيف ألم العصب الوركي. لا تجلسي في الوضعية نفسها مدة طويلة. وقد يساعد الاستحمام بماء دافئ أو وضع كمادة دافئة على المنطقة المؤلمة في إرخاء العضلات.') WHERE id = '3902a1df-6463-4c00-82b6-0534aaec9c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد وصل الأسبوع المنتظر! ابتداءً من هذا الأسبوع، استعدي لمعرفة جنس طفلكِ أثناء فحص الطبيب. في الأسبوع 16 من الحمل، يمكن لجهاز موجات فوق صوتية جيد وطبيب متمرس تحديد جنس طفلكِ بدقة تصل إلى 90%، إذا كان في وضعية مناسبة. في هذه المرحلة، تكون الأعضاء التناسلية لدى الأجنة الإناث والذكور قد تطورت بما يكفي لتمييزها عن بعضها في فحص الموجات فوق الصوتية. أما التطور الأبرز لدى الأجنة الذكور خلال هذه الفترة، فهو بدء نزول الخصيتين، اللتين كانتا موجودتين سابقًا داخل تجويف البطن، باتجاه كيس الصفن.;;;
قد تحدث أحيانًا أخطاء في التشخيص. على سبيل المثال: لدى الأجنة الإناث، قد يبدو الحبل السري من بعض الزوايا كأنه عضو تناسلي ذكري. ولدى الأجنة الذكور، إذا لم تكن الخصيتان قد نزلتا بالكامل إلى كيس الصفن، فقد يُعتقد خطأً أن الجنين أنثى. ولهذا السبب تحديدًا، يحاول الأطباء رؤية طفلكِ من عدة وضعيات مختلفة. إذا لم يجزم طبيبكِ بالجنس واكتفى بذكر احتمال، فمن الأفضل انتظار فحص الموجات فوق الصوتية التفصيلي، الذي يُجرى عادةً بين الأسبوعين 18 و22، قبل البدء في المشتريات الكبيرة.'), baby_message_ar = COALESCE(baby_message_ar, 'اكتمل الأسبوع 16! 🥑 أنا الآن بحجم حبة أفوكادو! أهم خبر بالنسبة إليّ هو أن دورتي الدموية تعمل على نحو مثالي. يضخ قلبي الصغير لترات من الدم كل يوم. أنا أنمو وأزداد قوة، وأنتظر اليوم الذي سألتقي فيه بكِ. أنتِ عالمي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أفوكادو'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بالحاجة إلى التبول المتكرر أثناء الحمل بسبب ضغط الرحم على المثانة والتغيرات الهرمونية. ولكن إذا صاحب ذلك شعور بحرقة أو لسع أثناء التبول، أو ضغط وألم في منطقة الأُربية، وكان لون البول داكنًا، فقد يُشتبه في وجود التهاب في المسالك البولية. تنتج التهابات المسالك البولية في الغالب عن بكتيريا مصدرها الأمعاء. وقد تزيد عوامل أخرى من شيوع هذه المشكلة أثناء الحمل، مثل العناية غير الكافية أو غير الصحيحة بالمنطقة التناسلية، وممارسة العلاقة الجنسية دون وقاية، والأمراض التي تُضعف جهاز المناعة، وإصابة الأم الحامل بداء السكري، وأمراض الكلى البنيوية، ووجود حصوات في الكلى، والخضوع سابقًا لجراحات في الجهاز البولي التناسلي. يُعد التشخيص المبكر لالتهاب المسالك البولية مهمًا، لأنه قد يتفاقم ويسبب بعض المضاعفات في الكليتين. كما قد تؤدي الحمى الشديدة المحتملة إلى بدء انقباضات الرحم مبكرًا، ما قد يسبب الإجهاض أو حتى الولادة المبكرة. يمكن أن يساعد شرب ما لا يقل عن 2 لتر من الماء يوميًا وزيادة تناول السوائل أثناء الحمل على تسريع تدفق البول وتنظيف المسالك البولية. كذلك قد يساهم تناول أطعمة غنية بالبروبيوتيك، مثل الزبادي والكفير، في دعم النبيت الجرثومي النافع وتنشيط جهاز المناعة، ما يقلل القابلية للإصابة بالعدوى.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أنتِ في إحدى أجمل مراحل الحمل، لذا استمتعي بكل لحظة. واصلي النوم على جانبكِ، وأدخلي الأطعمة الغنية بالحديد في نظامكِ الغذائي للوقاية من فقر الدم. ولا تنسي ترطيب بشرتكِ بانتظام للحد من علامات التمدد. في الأسبوع المقبل، ستزداد قدرة طفلكِ على السمع تطورًا!') WHERE id = '4db5e35d-0bef-4624-aa7c-2dbb50189eef';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ الآن بحجم حبة أفوكادو. وستكون الأسابيع القليلة المقبلة فترة نمو سريع له؛ إذ سيزداد وزنه وطوله إلى نحو الضعف. ;;;
هناك فرصة كبيرة لأن تري طفلكِ هذا الأسبوع في فحص الموجات فوق الصوتية مستلقيًا على ظهره. فقد أصبح عموده الفقري وعضلات ظهره أقوى بكثير، ما يسمح له بإبقاء رأسه ورقبته أكثر استقامة. كما ازدادت ساقاه طولًا مقارنة بالأسابيع السابقة، وأصبحتا أكثر تناسقًا مع جسمه.;;;
تزداد تعابير وجه طفلكِ تنوعًا أيضًا؛ إذ أصبح قادرًا على عقد حاجبيه وتحريك عينيه رغم بقاء جفنيه مغلقين.;;;
ومن أكثر التطورات إثارةً أن طفلكِ بدأ يسمع. فبفضل تطور بنية الأذن الداخلية، أصبح قادرًا على استقبال الأصوات. وأول الأصوات التي يسمعها هي أصوات جسمكِ: دقات قلبكِ، وتنفسكِ، وحركة أمعائكِ. وقريبًا سيحلل دماغه هذه الأصوات بعمق أكبر، وسيتعلم تمييز صوتكِ عن الأصوات الخارجية الأخرى. لذلك يمكنكِ من الآن البدء بالتحدث إليه والغناء له.'), baby_message_ar = COALESCE(baby_message_ar, 'أُكوّن طبقة من الدهون! 🧈 كنت حتى الآن نحيفًا جدًا، وكان جلدي مرتخيًا فوق عظامي. لكنني بدأت الآن بتكوين طبقة دهنية خاصة تُسمى "الدهون البنية". ستحافظ هذه الدهون على دفئي وتمنحني الطاقة. وشيئًا فشيئًا، أكتسب هيئة الرضيع اللطيف الممتلئ. أريد أن أكون ناعمًا عندما آتي إلى حضنكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أفوكادو'), body_changes_ar = COALESCE(body_changes_ar, 'عليكِ التأكد من تلبية احتياجاتكِ اليومية من فيتامين C خلال الحمل، للحفاظ على صحتكِ ودعم نمو طفلكِ والمساعدة في الحد من مشكلات البشرة. تساعد خصائص فيتامين C المضادة للأكسدة على مكافحة العدوى، وتؤدي دورًا في حماية جسمكِ من السموم خلال الحمل، حين يصبح جهاز المناعة أكثر حساسية. كما أنه بالغ الأهمية لترميم الأنسجة والتئام الجروح وتعزيز مرونة البشرة والمساعدة في الوقاية من ظهور علامات التمدد، إضافة إلى نمو العظام وترميمها وإنتاج الكولاجين، وهو بروتين بنيوي موجود في الغضاريف والعظام والأوتار والجلد وضروري لصحة البشرة. ويُعد فيتامين C مهمًا أيضًا لأنه يساعد على امتصاص الحديد الذي يحتاج إليه جسمكِ، وبذلك يساهم في الحفاظ على مستوى الهيموغلوبين ضمن المعدل الطبيعي وحمايتكِ من فقر الدم. بالإضافة إلى ذلك، يساعد في تكوّن أنسجة طفلكِ ويقوي الأوعية الدموية في المشيمة، ما يتيح وصول كمية أكبر من الأكسجين إلى الجنين ويقلل خطر انفصال المشيمة المبكر. كما يُعد فيتامين C مفيدًا في تخفيف الإمساك ودعم حركة الأمعاء المريحة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عند العناية ببشرتكِ، تجنبي الكريمات التي تحتوي على "الريتينويدات"، وهي مشتقات فيتامين A، أو "حمض الساليسيليك". فقد تضر هذه المواد بطفلكِ. اختاري الزيوت الطبيعية أو مستحضرات التجميل المخصصة للحوامل.') WHERE id = '15cf9597-2ec2-4fe2-8400-f9a4938a8ee5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في الأسبوع 16 من الحمل، أصبحت عينا طفلكِ قادرتين على التمييز بين الظلام والضوء الساطع. لكن يجب أن يكون الضوء شديد السطوع حتى يتمكن من إدراك هذا الفرق، لأن جدار الرحم يشكل حاجزًا قويًا أمام الضوء. وفي الوقت الحالي، لا يصل إلى طفلكِ سوى 1% من الضوء القادم من الخارج. ومن التفاصيل الأخرى المثيرة للاهتمام: الجفنان: لا يزال جفنا طفلكِ ملتصقين، ولن يبدآ بالفتح والإغلاق إلا اعتبارًا من منتصف العشرينيات من أسابيع الحمل. الفرق بين الليل والنهار: مع تقدم الأسابيع وتمدد جلد بطنكِ وترققه، سيدخل مزيد من الضوء إلى الداخل. وسيساعد ذلك طفلكِ على التمييز بين الليل والنهار، بل والتوجه نحو مصدر الضوء. منعكس الحدقة للضوء: ابتداءً من الأسبوع 30، يتطور لدى طفلكِ منعكس الحدقة. وتستجيب العضلات الموجودة داخل القزحية، وهي الجزء الملون من العين، للضوء؛ فتضيق الحدقة في الضوء الساطع وتتسع في الإضاءة الخافتة. إنها آلية مذهلة لحماية العين وضبط الرؤية.'), baby_message_ar = COALESCE(baby_message_ar, 'يزداد حبلي السري سماكة! 🔌 إنه شريان حياتي. يمر عبر هذا "الكابل" الغذاء والأكسجين القادمان منكِ إليّ. وقد أصبح الآن أكثر سماكة ومتانة، وتتدفق عبره كمية كبيرة من الدم. أحيانًا أمسكه بيدي وألعب به، لكن لا تقلقي، فلا يمكنني ضغطه وإيقاف تدفق الدم؛ فهو شديد المرونة وزلق.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'من المفيد الآن تجنب النوم على ظهركِ لدعم نمو طفلكِ داخل الرحم. ويُفضل أن تنامي على جانبكِ الأيسر لتسهيل تدفق الدم إلى طفلكِ. فعند النوم على الظهر، يقع ثقل جسمكِ كله على العمود الفقري وعضلات الظهر، ما يفرض ضغطًا إضافيًا على الأوعية الدموية ويقلل تدفق الدم إلى طفلكِ. وأفضل وضعية للنوم خلال الحمل هي الاستلقاء على الجانب الأيسر مع ثني الركبتين ووضع وسادة بين الساقين. تساعد هذه الوضعية كليتيكِ على العمل بسهولة، وتخفف الوذمة التي قد تظهر في جسمكِ، خصوصًا في اليدين والركبتين. وقد يفيدكِ أيضًا استخدام وسادة الحمل خلال هذه الفترة للحصول على نوم أكثر راحة. وللاستمتاع بنوم صحي وطويل، حاولي استبعاد المشروبات المحتوية على الكافيين، مثل القهوة والشاي والكولا، من نظامكِ الغذائي. تناولي الكثير من السوائل خلال النهار، ثم توقفي عن شربها قبل النوم بنحو 2-3 ساعات، وتجنبي الوجبات الثقيلة. بالإضافة إلى ذلك، تساعد ممارسة التمارين بانتظام والاستحمام بماء فاتر وشرب الحليب قبل الخلود إلى الفراش على النوم جيدًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تعانين جفاف العينين، فخذي فترات استراحة متكررة خلال اليوم وقللي الوقت الذي تقضينه أمام الشاشات. وبما أن احتياجكِ إلى الكالسيوم قد ازداد، احرصي على إدراج السمسم والجبن والخضراوات الورقية الخضراء في نظامكِ الغذائي. وإذا شعرتِ بشد خفيف في ظهركِ، فقومي بحركات لطيفة وأنتِ جالسة، مع سحب كتفيكِ إلى الخلف. نحن نكبر قليلًا كل يوم!') WHERE id = 'c27b671d-4d70-44eb-80ea-7aedfd97f434';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يقع رحمكِ، الذي يحتضن طفلكِ طوال 9 أشهر، اعتبارًا من هذا الأسبوع أسفل سرتكِ مباشرةً. كان متوسط وزن رحمكِ في بداية الحمل 60 qram، أما في هذه المرحلة فقد بلغ وزنه 250 qram. وخلال هذا الأسبوع، يوجد داخل الرحم في الكيس الذي يحتضن طفلكِ نحو 100 ml من السائل الأمنيوسي في المتوسط. وتعادل هذه الكمية نحو 10 ملاعق كبيرة من الماء. يوفر هذا السائل لطفلكِ بيئة ذات درجة حرارة ثابتة، ويعمل كوسادة تحميه من الإصابات الميكانيكية والتأثيرات الخارجية. كما تساعد خصائصه المضادة للبكتيريا على توفير بيئة معقمة حول طفلكِ وحمايته من العدوى.'), baby_message_ar = COALESCE(baby_message_ar, 'أسمعكِ يا ماما! 🗣️ بدأت أذناي الآن تعملان بشكل كامل. يصل إليّ صوت حديثكِ وضحكتكِ، وحتى الأغاني التي تغنينها. ورغم أن الصوت يصلني مكتومًا (كما لو كنتُ تحت الماء)، فإنني أستطيع فهم نبرة صوتكِ. قولي لي كثيرًا "أحبكِ"، فأنا أريد أن أحفظ هذه العبارة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'قد يظهر ألم الأربية في الأسابيع الأولى من الحمل بسبب بدء نمو الرحم وزيادة تدفق الدم، كما قد يحدث في الأسابيع التالية نتيجة زيادة الوزن وتمدد الأربطة التي تدعم الرحم. كذلك ينتج جسمكِ أثناء الحمل هرمونًا يُسمى الريلاكسين. يعمل الريلاكسين على إرخاء الأنسجة الصلبة التي تربط الأربطة ببعضها. وهذا يعني أن مفاصل الحوض ومنطقة الأربية قد تصبح أكثر مرونة وحركة أثناء الحمل. ومع دخولكِ الثلث الثاني من الحمل، قد يسبب تمدد الأربطة المستديرة التي تدعم رحمكِ مع نمو طفلكِ ألمًا في الأربية أيضًا. وللحد من هذه الآلام، حاولي الحفاظ على نشاطكِ قدر الإمكان من دون إجهاد نفسكِ، وتجنبي الحركات المفاجئة أثناء أداء مهامكِ اليومية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تحدثي إلى طفلكِ! اقرئي له كتابًا وأخبريه كيف سار يومكِ. فهذا يقوي الرابطة العاطفية بينكما. وتشير الدراسات إلى أن الأطفال يتعرفون بعد ولادتهم إلى الأصوات والأغاني التي سمعوها في رحم الأم.') WHERE id = '16510ace-04bb-4c83-9c44-82e27d7b140c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يواصل طفلكِ هذا الأسبوع الاستعداد ليوم ولادته. وأهم مهارة يتدرب عليها الآن هي منعكسا المص والبلع! فهو يستعد لأول رشفات سيتغذى عليها. ويُعد البلع من أولى الآليات الانعكاسية التي يطورها طفلكِ. ويبدأ ذلك بعد اكتمال تشكل الشفة العليا واكتسابها وظيفتها، مما يسمح بإغلاق فمه.;;;
ومع بدء عملية البلع، تتطور غريزة المص تلقائيًا. أي إن هذين المنعكسين يتتابعان وظيفيًا. ورغم أن طفلكِ بدأ بالفعل هذا التدريب المكثف، فإن هذه القدرة لن تكتمل تمامًا إلا بحلول الأسبوع 32.;;;
وفي الفترة نفسها، يتعلم طفلكِ ابتلاع السائل الأمنيوسي، وبذلك يستعد للولادة كما يفعل من خلال حركات التنفس، حتى تكون وظائفه جاهزة عند الولادة. وهكذا، يكتسب طفلكِ عند ولادته قدرة متطورة على البلع بما يكفي لمص الحليب من ثديكِ. ويحدث منعكس البلع، بحسب كمية اللعاب، نحو مرتين في الدقيقة أثناء اليقظة ونحو مرة واحدة في الدقيقة أثناء النوم.'), baby_message_ar = COALESCE(baby_message_ar, 'يداي لا تتوقفان عن الحركة! ✊ منعكس القبض لديّ قوي جدًا. أضم يديّ على شكل قبضتين وأحرك أصابعي. أحيانًا أمسك بالحبل السري، وأحيانًا أمسك بيدي الأخرى. تقوي هذه الحركات أصابعي. وعندما أولد، سأمسك بإصبعكِ بقوة شديدة حتى إنكِ ستندهشين!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'يوشك رحمكِ على بلوغ مستوى السرة، ويمكنكِ الآن تحسسه بيدكِ. وبما أن طفلكِ سيبدأ اعتبارًا من هذا الأسبوع باكتساب الوزن والنمو بوتيرة أسرع مقارنة بالأسابيع السابقة، فمن المرجح أن يزداد وزنكِ أيضًا بسرعة أكبر قليلًا. ويُفترض أن تكوني قد اكتسبتِ حتى هذه المرحلة نحو 2.5-5 kq في المتوسط. وقد تبدو بطون بعض الحوامل أكبر أو أصغر مما هو متوقع مقارنة بأسبوع الحمل. وغالبًا ما يعود ذلك إلى تراكم الغازات في الأمعاء أو شدة تماسك الجلد.;;;
ينبغي أن تُجري فحص الاختبار الثلاثي بحلول نهاية هذا الأسبوع. وعلى الرغم من أن بعض المختبرات تستطيع، بمساعدة برامج الحاسوب التي تستخدمها، تقييم الاختبار الثلاثي حتى الأسبوع 20 أو بعده، فإن اكتشاف مستوى الخطورة في وقت أبكر يكون أكثر فائدة. ولا يرى بعض الأطباء ضرورة لإجراء الاختبار الثلاثي إذا أظهرت نتائج الاختبار المزدوج، الذي يُجرى بين الأسبوعين 11-14، خطورة منخفضة، بينما قد يوصي أطباء آخرون بإجراء كل من الاختبار المزدوج والاختبار الثلاثي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أنتِ في إحدى أكثر فترات الحمل راحة، لذا خصصي بعض الوقت لنفسكِ. اعتادي النوم على جانبكِ الأيسر ليكون تدفق الدم مثاليًا لكِ ولطفلكِ. واصلي شرب الكثير من السوائل وتناول الأطعمة الغنية بالكالسيوم. وفي الأسبوع المقبل، ستزداد فرصتكِ في الشعور بحركات طفلكِ بوضوح أكبر!') WHERE id = '0f424a2a-4630-431c-9be8-af0ad1977c5a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل رئتا طفلكِ النمو واكتساب وظائفهما من جميع الجوانب. ورغم أنهما لم تصلا بعد إلى مستوى يسمح بتبادل ثاني أكسيد الكربون والأكسجين، فإنهما أصبحتا قادرتين على أداء الوظيفة التي ستتيح له التنفس بعد الولادة. وفي الوقت الحالي، تحدث حركات التنفس هذه بواسطة السائل الأمنيوسي المحيط به.;;;
سيكون أول نفس يأخذه طفلكِ لحظة ولادته أصعب نفس في حياته. ويرجع ذلك إلى انتقال جهازه التنفسي من بيئة ممتلئة بالسائل إلى التنفس بالهواء.'), baby_message_ar = COALESCE(baby_message_ar, 'عظامي تزداد صلابة! 🦴 كان هيكلي العظمي في السابق مكوّنًا من غضاريف طرية كالمطاط، لكنه يتحول الآن إلى عظام حقيقية (التعظّم). لقد أصبحتُ أقوى الآن. وتزداد صلابة أضلاعي وعمودي الفقري وعظام ساقيّ. لم أعد كتلة هلامية صغيرة، بل أصبحتُ صبيًا صغيرًا قويًا (أو فتاة صغيرة قوية)!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كمثرى'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ مصابة بداء السكري قبل الحمل، فعليكِ توخي مزيد من الحذر أثناء الحمل. فقد تكون السيطرة على مستوى سكر الدم خلال الحمل أصعب مقارنة بما كانت عليه قبله. وقد يلزم أيضًا تعديل جرعة الإنسولين. وفي هذه الحالة، ستحتاجين إلى الخضوع لفحوصات طبية بوتيرة أكثر تكرارًا.;;;
داء السكري مرض يؤدي إلى ارتفاع مستوى السكر في الدم. وحتى إن لم تكوني مصابة بالسكري عادةً، فقد يظهر سكري الحمل. ويُجرى التحري عنه بين الأسبوعين 24-28 من الحمل باستخدام اختبار تحمّل الغلوكوز، المعروف باسم اختبار السكر. ثم تُراجع النتائج ويُحدد التشخيص النهائي باستخدام اختبار الغلوكوز الفموي بجرعات 50-75-100 qram. وقد يظهر داء السكري المرتبط بالحمل في حالة واحدة تقريبًا من كل 150 حالة حمل. وإذا كانت لديكِ أعراض مثل الشعور بالعطش، أو فقدان الوزن، أو الحاجة المفرطة إلى تناول الطعام، أو شرب كميات من الماء والتبول أكثر من المعتاد، أو الشعور المستمر بالتعب، فعليكِ استشارة طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتجنب الدوار المفاجئ، اجلسي أولًا عند النهوض من وضعية الاستلقاء، ثم قفي ببطء. وتُعد اليوغا الخفيفة المخصصة للحامل أو المشي مفيدين جدًا لآلام الظهر. اهتمي بصورة خاصة بالحصول على الحديد والكالسيوم. ما رأيكِ في أن تقرئي لطفلكِ اليوم حكاية أو تتحدثي معه عن خططكِ المستقبلية؟') WHERE id = 'ae23805e-1ec4-470c-a370-e36eb29268eb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تتراكم الأنسجة الدهنية (طبقة الدهون) تحت الجلد وحول الأعضاء الداخلية. وتؤدي هذه الطبقة دور مخزون للطاقة. ينظّم الدماغ نبضات قلب الجنين، فتصبح أكثر انتظامًا (140-150 نبضة في الدقيقة). ويعمل الجهاز الدوري بكامل طاقته.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا "أزداد وزنًا"، ماما! 🧸 يستمر تراكم الأنسجة الدهنية في جسمي. كنت نحيفًا جدًا من قبل، لكن ذراعيّ وساقيّ تمتلئان الآن. أحتاج بشدة إلى هذه الطبقة الدهنية، لأنها ستساعدني على تنظيم درجة حرارة جسمي عند ولادتي. لا تقلقي عليّ، فأنا هنا دافئ وشبعان. ما عليكِ سوى تناول طعام صحي، وسأتولى أنا الباقي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بصلة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه المرحلة من حملكِ، قد تشعرين بالكثير من التغيرات الجسدية والنفسية. وبسبب زيادة تدفق الدم، تزداد الإفرازات المهبلية والعرق والمخاط والسوائل الأخرى. وقد تكون الأحلام الغريبة التي ترينها ناتجة عن هرموناتكِ وحالتكِ النفسية وتوقعاتكِ. قد تتجنبين ممارسة الرياضة خلال الحمل خوفًا من إيذاء جسمكِ أو طفلكِ، لكن ممارسة التمارين المناسبة أثناء الحمل تسهّل الولادة وتؤثر إيجابيًا في صحة طفلكِ. يمكنكِ خلال هذه الفترة ممارسة تمارين الظهر التي تقوّي عمودكِ الفقري بانتظام. كما يُنصح بيوغا الحمل والبيلاتس منذ الأسابيع الأولى من الحمل. وستفيدكِ كثيرًا خلال الحمل ممارسة المشي السريع لمدة 30 دقيقة، من 3-5 أيام أسبوعيًا. لكن عليكِ أداء كل ذلك بطريقة لا ترهقكِ. وإذا كنتِ لا تحبين ممارسة الرياضة، فيمكنكِ الرقص للحفاظ على نشاطكِ. فالرقص أثناء الحمل يقوّيكِ ويزيد مرونتكِ ويخفض مستوى التوتر لديكِ، ما يجعلكِ أكثر سعادة. كما أنه فكرة رائعة لتبدئي منذ الآن الاستمتاع بوقتكِ مع طفلكِ!'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تستغني عن الأطعمة الغنية بالكالسيوم في قائمة طعامكِ. تناولي منتجات الألبان والبروكلي واللوز والسمسم. وإذا لم تحصلي على ما يكفي من الكالسيوم، فسيأخذ طفلكِ حاجته منه من عظامكِ وأسنانكِ.') WHERE id = 'c7911f10-1eb8-49da-80ba-c909457132da';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يستمر تكوّن بصمات الأصابع على أصابع يدي طفلكِ وقدميه التي تزداد طولًا يومًا بعد يوم. تحتوي كل خلية في جسم طفلكِ تسهم في تكوينه على جزيء DNA. ورغم أن DNA يتشابه بين البشر بنسبة 99%، فإن نسبة 1% المتبقية هي التي تمنح طفلكِ صفاته الفريدة.;;;
تُسمّى الأشكال التي تكوّنها النتوءات المرئية ذات الانحناءات المختلفة على جلد أطراف الأصابع، وكذلك هذه النتوءات الموجودة في الطبقة الخارجية من الجلد، بالحليمات. وبفضل هذه البنية، يمتلك كل شخص بصمات أصابع خاصة به. ولا تتطابق بصمات أي شخصين، حتى التوائم المتطابقة. وبعبارة أخرى، بصمة الإصبع هي علامة تخصنا وحدنا ونتركها على كل ما نلمسه. وتظل الخطوط الموجودة في بصمات الأصابع ثابتة طوال الحياة ما لم تحدث جروح أو قطوع عميقة.'), baby_message_ar = COALESCE(baby_message_ar, 'أحلم! 💤 ماما، يقول العلماء إنني أصبحت قادرًا على الدخول في مرحلة "نوم REM"، أي Rapid Eye Movement - حركة العين السريعة. وهذا يعني أنني أستطيع أن أحلم! تُرى، ماذا أرى في أحلامي؟ ربما أسمع صوتكِ أو أتخيّل وجهكِ. أقضي معظم اليوم نائمًا، لكنني أكون نشيطًا جدًا عندما أستيقظ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بصلة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'أصبحت تمارين البيلاتس في السنوات الأخيرة من أكثر التمارين التي تفضّلها الأمهات الحوامل. فهي تريح الجسم وتصفّي الذهن، وتساعد على الوقاية من آلام الظهر وأسفل الظهر، كما تمكّن الحامل من اكتشاف قدرات جسمها. ومن المهم ممارستها تحت إشراف متخصصين في هذا المجال، مع الحرص على اختيار حركات البيلاتس المناسبة لفترة الحمل.;;;
أما بالنسبة إلى اليوغا، فهناك بعض الوضعيات التي يجب تجنبها تمامًا أثناء الحمل. لذلك، ينبغي أن تتلقي الدروس فقط على يد مدرّبات خبيرات يقدمن دروس يوغا مخصصة للحوامل. ابحثي عن صفوف يوغا الحمل واختاري الأنسب لكِ. ;;;
ضعي إحدى ركبتيكِ على الأرض، وقدّمي قدمكِ الأخرى إلى الأمام واجلسي في وضع القرفصاء. ستشعرين بتمدد ساقيكِ ووركيكِ واتساعهما. ثم بدّلي موضع ساقيكِ. يقوّي هذا التمرين ساقيكِ، ما يساعدهما على حمل بطنكِ براحة أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تخافي من الأحلام الغريبة، فهي جزء طبيعي من الحمل. قد يساعد الاستماع إلى موسيقى هادئة أو قراءة كتاب قبل النوم على تهدئة ذهنكِ. واحرصي على أن تكون غرفة النوم باردة نسبيًا.') WHERE id = '109a3421-ce4d-45f2-89cf-6db2482011b0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت مينا أسنان طفلكِ بالتكوّن. وتتألف بنية السن من المينا والعاج والملاط واللب. والمينا هي أصلب مادة في الجسم، وتغلف السن من الخارج كطبقة واقية.;;;
في هذه المرحلة، تبدأ أملاح الكالسيوم الداخلة في تكوين مينا أسنان طفلكِ بالترسب تدريجيًا على القالب العضوي للسن، ثم تتراكم وتتبلور. ويستمر هذا التراكم حتى ظهور أسنان طفلكِ. وقد تؤدي بعض الأدوية المستخدمة أثناء الحمل إلى إبطاء عملية تكوّن مينا الأسنان. ونتيجة لذلك، قد تظهر تصبغات صفراء أو رمادية أو بنية على الأسنان. وقد يحدث أحيانًا نقص في تكوّن الأسنان أو تأخر في نموها، وهي حالة تُسمّى نقص التنسّج.'), baby_message_ar = COALESCE(baby_message_ar, 'أفزع من الأصوات! 🔊 إذا عطستِ فجأة، أو أُغلق الباب بقوة، أو كانت الموسيقى صاخبة، فإنني أنتفض في مكاني. يُسمّى ذلك "منعكس مورو". أفتح ذراعيّ وساقيّ فجأة ثم أضمهما. أصبحت حاسة السمع لديّ شديدة الحساسية. أرجوكِ، ابقي في بيئة هادئة، فالأصوات المرتفعة تزعجني.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بصلة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تساعد تمارين التنفس على تصحيح اضطرابات وضعية الجسم أثناء الحمل وتخفيف آلام الظهر. كما تعلّمكِ تقنيات التنفس والاسترخاء التي ستحتاجين إليها أثناء الولادة، وتزيد مرونة عضلات البطن ومنطقة الأربية وقوتها. وهي تهيئكِ نفسيًا للولادة، وتساعدكِ على التحكم في تنفسكِ والدفع بفاعلية أثناء انقباضات المخاض، كما تمكّنكِ من استخدام طاقتكِ بكفاءة وقت الولادة.;;;
وللتنفس الصحيح فوائد أخرى، منها رفع مستوى الأكسجين في الدم، والمساعدة على التخلص من السموم في الجسم، وتنظيم الجهاز العصبي والهرمونات، وتقوية المناعة، وتنشيط البشرة من خلال تحسين كفاءة الخلايا، وتسهيل التركيز، وتقوية الذاكرة، وتسريع الفهم والإدراك، وتعزيز الإبداع وسرعة التفكير، وتنظيم النوم وتحسين جودته، وتحقيق الهدوء الذهني.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا لم تشعري بعد بحركات طفلكِ، فيمكنكِ خلال هذه الأيام الاستلقاء في مكان هادئ والتركيز على بطنكِ لمحاولة الإحساس بحركاته الصغيرة الأولى. ارتدي أحذية ذات كعب منخفض لتخفيف آلام الظهر. ونظرًا إلى ازدياد حاجتكِ إلى الكالسيوم، أكثري من منتجات الألبان والخضراوات الورقية الخضراء في نظامكِ الغذائي. اشتري لنفسكِ اليوم هدية صغيرة!') WHERE id = '5dba3d5c-bb87-4502-8385-7f27405dc9b2';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ينمو جسم طفلكِ الآن بصورة أكثر تناسقًا. ولهذا يحاول الجسم الحفاظ على كمية الدم التي يضخها القلب إلى أنحاء الجسم ضمن مستويات مستقرة. يكتمل نمو القلب، الذي يكتسب شكله المميز مع تمايز الخلايا وتطورها، خلال الشهرين التاليين للإخصاب. وفي غضون 60 يومًا، يصبح عضوًا مكوّنًا من 4 صمامات و4 حجرات، ويواصل العمل طوال حياة طفلكِ.;;;
في هذه المرحلة، ينبض قلب طفلكِ بين 140 و160 نبضة في الدقيقة. وعندما يبلغ عمره 3 أشهر، سيستقر معدل نبضه عند 135-140 نبضة في الدقيقة، وعند عمر 6 أشهر عند 130 نبضة، وعند عمر 9 أشهر عند 120-125 نبضة، وعند عمر 12 شهرًا عند 115-120 نبضة، وعند عمر 24 شهرًا عند 115 نبضة، وعندما يبلغ 4 سنوات عند 100 نبضة، وعند بلوغه 15 عامًا سيستقر عند نحو 75-80 نبضة في الدقيقة.;;;
كذلك قد تظهر في هذه الفترة فتحات في قلب طفلكِ أثناء فحص الموجات فوق الصوتية. وإذا لم يكن هناك زواج بين الأقارب أو شخص مصاب بتشوّهات قلبية في العائلة أو المحيط القريب، ولم تُستخدَم أدوية دون وعي خلال الحمل، ولم تحدث إصابة بعدوى شديدة مثل الحصبة الألمانية، ولم يُشخَّص طفلكِ بمتلازمة داون أو متلازمة تيرنر، ولم يُستهلك الكحول، فمن المتوقع أن تُغلق هذه الفتحات قبل ولادة طفلكِ باحتمال 80%.'), baby_message_ar = COALESCE(baby_message_ar, 'ألعب بالحبل السري! ➰ لعبتي المفضلة هي الحبل السري. أمسكه وأضغط عليه وألفّه. لكن لا تخافي، فهو زلق ومتين جدًا، ولا يمكنني إيذاؤه. تساعدني هذه اللعبة على تطوير منعكس القبض والتنسيق بين اليد والعين. ماذا تفعلين أنتِ؟ أنا لا أشعر بالملل هنا أبدًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بصلة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يجعل الحمل ظهور دوالي الأوردة أكثر سهولة، لأن حجم الدم يزداد بصورة ملحوظة لتلبية احتياجات طفلكِ. ولهذا تحتوي الأوعية الدموية على كمية أكبر من الدم، ما يزيد تجمعه، خصوصًا في الساقين. وعادةً ما تظهر الدوالي خلال الحمل نتيجة ضغط طفلكِ الذي ينمو داخل الرحم على أوردة منطقة الأُربية.;;;
تظهر الدوالي على هيئة أوردة بنفسجية أو زرقاء وسميكة تشبه شبكة العنكبوت على الجلد. ومع تقدمها، قد تضاف إلى الأعراض آلام شديدة وتشنجات وإرهاق في الساقين وشعور بالحرارة والامتلاء. ويمكن للانتباه إلى بعض الأمور البسيطة والمهمة وتحويلها إلى عادات أن يساعد على الوقاية من ظهور الدوالي.;;;
احرصي على عدم الجلوس واضعةً ساقًا فوق الأخرى لفترة طويلة. حرّكي قدميكِ أثناء الجلوس لتنشيط الدورة الدموية. وعند الاستراحة، ارفعي ساقيكِ إلى مستوى أعلى من جسمكِ. لا ترفعي أشياء ثقيلة. اشربي الكثير من الماء وتجنبي الأطعمة شديدة الملوحة. لا تقودي السيارة لفترات طويلة. وتجنبي الأحذية ذات الكعب العالي. استخدمي الجوارب الضاغطة المخصصة للدوالي. نامي على جانبكِ الأيسر بدلًا من الاستلقاء على ظهركِ. ولا تستحمي بماء شديد السخونة أو ترتدي ملابس ضيقة جدًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس باستقامة لتخفيف العبء عن أسفل ظهركِ، وتجنبي الوقوف لفترات طويلة. في المساء، ستساعدكِ الاستراحة لمدة 15 دقيقة مع رفع ساقيكِ قليلًا فوق مستوى القلب على تقليل التورم والشعور بالراحة. ولأن حاجتكِ إلى الكالسيوم قد ازدادت، أدرجي في نظامكِ الغذائي أطعمة مثل الجبن القريش أو الجبن أو اللوز. واختتمي يومكِ بممارسة هواية تحبينها.') WHERE id = '1282e899-e7f6-47fc-b213-e93601a67a84';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أنكِ ترين عظام طفلكِ في فحص الطبيب كأنها بنية واحدة، فإن الجهاز الهيكلي يتمتع بتركيب بالغ التعقيد. فهو يتكوّن من الخلايا العظمية الحية المسماة بالخلايا العظمية الناضجة، ومن المادة البينية التي تملأ الفراغات بينها وتفرزها هذه الخلايا. وتحتوي هذه المادة على معادن تمنح العظام صلابتها، مثل فوسفات الكالسيوم وكربونات الكالسيوم وفوسفات المغنيسيوم، إضافةً إلى كميات قليلة من الحديد والصوديوم.;;;
يُعد نخاع العظم الأصفر والعظم الكثيف والعظم الإسفنجي والسمحاق والغضاريف والأوعية الدموية من البُنى المكوّنة للعظام. وتقع الغضاريف عند نقاط اتصال العظام. وبفضل بنيتها اللينة، تمنع احتكاك العظام ببعضها وتآكلها، كما تساعد على نمو العظام طوليًا. أما الأوعية الدموية فتضمن وصول الدم إلى خلايا العظام.'), baby_message_ar = COALESCE(baby_message_ar, 'عظامي تزداد صلابة! 🦴 يزداد هيكلي العظمي قوة يومًا بعد يوم. يتراكم الكالسيوم في عظامي ويجعلها أكثر صلابة. لم أعد ذلك الكائن الصغير اللين الشبيه بالمطاط. أضلاعي وعمودي الفقري وعظام ساقيّ... كلها تتحول إلى عظام حقيقية. الحليب الذي تشربينه والجبن الذي تأكلينه يصلان إليّ كمواد للبناء. شكرًا لكِ يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بصلة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'من الطبيعي الشعور ببعض الآلام خلال الحمل، ومن بينها ألم الساقين. ويُعد تورم الساقين أوضح علاماته، إذ قد تتورم ربلة الساق والقدمان معًا، وقد يسبب تورم القدمين الألم والانزعاج. وللتأكد من وجود التورم، يمكن الضغط بالإصبع على منطقة الكاحلين. وقد تزيد شدة هذه الآلام بسبب نقص الكالسيوم والمغنيسيوم، أو الزيادة المفرطة في الوزن، أو قلة الحركة، أو صعوبة عودة الدم إلى القلب، أو انخفاض مستويات البوتاسيوم والمغنيسيوم والكالسيوم. إذا كنتِ تعانين من ألم الساقين، فعليكِ إراحتهما قدر الإمكان. ويُعد النوم على الجانب وضعية أنسب بكثير ليلًا. كما ينبغي لكِ مراقبة معدل زيادة وزنكِ. وسيساعدكِ رفع ساقيكِ أثناء النوم على الشعور بالراحة. يساعد الماء البارد على تخفيف تورم العضلات وتضييق الأوعية الدموية؛ لذلك قد يكون الاستحمام بماء بارد ووضع كمادات الثلج مفيدًا. وإضافةً إلى ذلك، يمكن للتدليك والتمارين أن يساعدا على تخفيف الألم. ولا تهملي شرب الكثير من السوائل للمساعدة على تقليل الوذمة في الجسم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تناولي أطعمة غنية بالمغنيسيوم للوقاية من تشنجات الساقين. وقد يساعدكِ تمديد عضلات الساقين وأخذ حمام دافئ قبل النوم.') WHERE id = '79568d36-35e8-4a60-8ad2-b99e6d2f45e1';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ينتج دماغ طفلكِ أثناء وجوده في الرحم عددًا من الخلايا العصبية يفوق حاجته. وبعد الولادة، تختفي الخلايا العصبية التي لا تُستخدم ولا تتلقى التحفيز من خلال عملية تُسمى "التقليم العصبي".;;;
تُنشئ كل خلية من الخلايا العصبية البالغ عددها 100 مليار خلية في الدماغ نقاط اتصال خاصة مع آلاف الخلايا العصبية الأخرى. وفي عمر السنتين إلى الثلاث سنوات، يصل عدد هذه الاتصالات إلى نحو 15.000 اتصال لكل خلية. وينظّم الدماغ الوظائف الحيوية مثل التنفس ونبض القلب، إلى جانب الوظائف العليا مثل التفكير والتذكر والكلام.;;;
يسهم كل سطح مختلف يلمسه طفلكِ وكل رائحة يشمها وكل صوت يسمعه في إنشاء هذه الروابط العصبية. أما تقوية هذه الروابط وترسيخها فتعتمدان على تكرار هذه المحفزات بانتظام.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا ماما! أصبح حجمي الآن بحجم حبة فلفل حلو. تتطور أعصابي، وتلتف حولها مادة خاصة تُسمى "الميالين". وستساعد هذه المادة الرسائل المنطلقة من دماغي إلى جسمي على الوصول بسرعة أكبر. أنا أزداد ذكاءً كل يوم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فلفل حلو'), body_changes_ar = COALESCE(body_changes_ar, 'أصبح حملكِ الآن واضحًا إلى درجة يمكن ملاحظتها من الخارج. ينمو الرحم طوال الحمل ليوفر مساحة لطفلكِ والمشيمة والسائل الأمنيوسي، ويصل وزنه قرب نهاية الحمل إلى نحو 1100 غرام. وهذا يعادل نحو 20 ضعف وزنه الطبيعي. أما من حيث الحجم، فتصل سعته قرب الولادة إلى نحو 5 لترات، أي إنه يزداد إلى 500-1000 ضعف حجمه الطبيعي. ولا تحدث هذه الزيادة نتيجة ازدياد عدد خلايا العضلات الملساء المكوّنة للرحم، بل نتيجة ازدياد حجمها.;;;
خلال الأشهر الأولى من الحمل، يحتفظ الرحم بشكله الشبيه بالكمثرى، لكنه يصبح كروي الشكل بحلول الأسبوع 12 ويرتفع فوق عظام الحوض. وابتداءً من هذا الأسبوع، يصل إلى حجم يمكن معه تحسسه فوق عظم العانة في مقدمة الحوض. وخلال الأسابيع التالية، ينمو إلى أعلى بشكل بيضاوي كي يتمدد داخل تجويف البطن. ومع استمرار نموه، يستند إلى الجدار الأمامي للبطن ويدفع الأمعاء إلى الجانبين وإلى أعلى حتى يصل إلى الكبد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام 18 أسبوعًا من هذه الرحلة بنزهة قصيرة! احرصي على الجلوس باستقامة وارتداء أحذية مريحة للمساعدة على تخفيف آلام أسفل الظهر. وعند النوم، استلقي على جانبكِ الأيسر، فهذا يؤثر إيجابيًا في تدفق الدم إلى طفلكِ وفي عمل كليتيكِ. ولا تنسي شرب الكثير من السوائل والحصول على الكالسيوم من مصادر مثل الحليب والزبادي واللوز.') WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه المرحلة، تكون المشيمة، وهي أهم حلقة وصل بين الأم وطفلها في الأسبوع 18، قد بدأت تعمل بكامل طاقتها. فهي تحصل مباشرةً من دمكِ على الغذاء والأكسجين اللازمين لنمو طفلكِ وتنقلهما إليه. وللمشيمة أيضًا وظيفة بالغة الأهمية تتمثل في الحماية. ففي الظروف العادية، قد يتعامل جسمكِ مع طفلكِ باعتباره «جسمًا غريبًا» ويهاجمه، لكن المشيمة تعمل كحاجز يمنع خلايا جهازكِ المناعي من إلحاق الضرر به.;;;
في الأسبوع 18، تصبح المشيمة، التي يمكن رؤيتها بوضوح في فحص الطبيب، بحجم يماثل تقريبًا حجم طفلكِ. وبعد هذه المرحلة، سيواصل كلاهما النمو، لكن طفلكِ سينمو بوتيرة أسرع من المشيمة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتثاءب وأُصاب بالفُواق! 🥱 حجابي الحاجز يعمل بنشاط كبير، ولذلك أُصاب بالفُواق كثيرًا. قد يبدو لكِ هذا غريبًا، لكنه مفيد جدًا لي؛ فأنا أنظف رئتيّ وقصبتي الهوائية. كما أنني أتثاءب بلطف عندما أشعر بالتعب. استريحي معي أنتِ أيضًا، اتفقنا؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فلفل حلو'), body_changes_ar = COALESCE(body_changes_ar, 'يمثّل هذا الأسبوع نقطة تحوّل لكثير من الأمهات من حيث الشعور بحركات الطفل. إذا لم تشعري بها بعد، فانتبهي؛ فقد تشعرين بإحساس خفيف في بطنكِ يشبه «فقاعة غاز» أو «رفرفة جناحين». قد يظل ضغط دمكِ منخفضًا، ما قد يجعلكِ تشعرين بالوهن. وربما تبلغ شهيتكِ ذروتها، فقد تسارعت عملية الأيض لديكِ ويحتاج جسمكِ إلى طاقة إضافية من أجل طفلكِ. لكن حرقة المعدة قد تزعجكِ بعد تناول الطعام. وبسبب ضغط الرحم على المعدة، قد يصعب عليكِ تناول وجبات كبيرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'راقبي ضغط دمكِ. إذا كنتِ تشعرين بالدوار كثيرًا، فاشربي الكثير من السوائل خلال اليوم، ويمكنكِ تناول كميات قليلة من الأطعمة المالحة مثل العيران والبسكويت المملح، ما لم يوصِ طبيبكِ بخلاف ذلك.') WHERE id = '1343d008-0806-4770-8e2d-0452ed215751';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت طبقة الدهون بالتكوّن في جسم طفلكِ، وهي من أهم العوامل التي تسرّع نموه. وتنقسم الدهون إلى ثلاث فئات رئيسية: الدهون البسيطة، والمركّبة، والمشتقة.;;;
يُعد الكوليسترول من أشهر أنواع الدهون، ويُكتسب من الغذاء أو يُصنَّع داخل الخلايا، ويؤدي الكبد الدور الأكثر نشاطًا في هذه العملية. وللدهون وظائف بالغة الأهمية في الجسم؛ فهي أكبر مصدر للطاقة، وتحمي الأعضاء الداخلية، وتولّد الحرارة فتحمي الجسم من البرد.;;;
تعمل الدهون أيضًا كوسيط يساعد الجسم على امتصاص فيتامينات A وD وE وK. وعندما يكتمل تكوّن الطبقة الدهنية لدى طفلكِ، تتجمع 90% من هذه الدهون تحت الجلد. أما الجزء المتبقي فيتوزع داخل تجويف البطن وبين ألياف العضلات وحول الأعضاء الحيوية، مثل الكليتين والقلب والكبد، لحمايتها.'), baby_message_ar = COALESCE(baby_message_ar, 'أصابعي وبصماتها! 🧬 ماما، لقد اكتمل تكوّن بصمات أصابعي تمامًا. لن تتغير هذه الأنماط طوال حياتي. أنا فريد من نوعي! كما أنني أستطيع الآن تحريك يديّ وقدميّ بحرية. أحيانًا أجلس متربعًا، وأحيانًا «أسبح». هذا هو المكان الأكثر راحة بالنسبة إليّ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فلفل حلو'), body_changes_ar = COALESCE(body_changes_ar, 'لا تقلقي إذا بدا لكِ بطنكِ كبيرًا في يوم وصغيرًا في يوم آخر. ففي الأيام التي ترين فيها بطنكِ أكبر من حجمه المعتاد، قد يكون السبب تراكم الغازات أو الانتفاخ الناتج عن بطء حركة الأمعاء قليلًا. إذا كانت قياسات التصوير بالموجات فوق الصوتية تتوافق مع أسبوع الحمل، فلا أهمية لكون بطنكِ صغيرًا أو كبيرًا. ويرتبط ذلك تمامًا ببنية عضلات البطن والخصائص التشريحية لجسمكِ وطريقة استجابته للتغيرات الناجمة عن الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي ألّا تبقي واقفةً مدة طويلة، لأن ذلك قد يزيد آلام الظهر. وإذا كان عملكِ يتطلب الجلوس، فقومي كل ساعة وامشي لمدة 5 دقائق. وإذا شعرتِ بجفاف خفيف في عينيكِ، فيمكنكِ استخدام الدموع الاصطناعية بعد استشارة الطبيب. أصبح طفلكِ الآن يشعر بحركاتكِ بوضوح أكبر، لذا واصلي تعزيز رابطتكِ به.') WHERE id = 'e537dc02-2a8f-44e4-8520-858b44bd2d69';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبحت أعضاء الحس لدى طفلكِ شديدة الحساسية الآن. وتُظهر الدراسات أن طفلكِ يستطيع تمييز صوتكِ من جميع الأصوات الأخرى وهو لا يزال في الرحم. يستجيب الأطفال لأصوات النساء والأصوات الحادة أكثر من استجابتهم لأصوات الرجال. ويرجع ذلك إلى أن جدار الرحم ينقل الموجات الصوتية بطرق مختلفة؛ إذ يسمع الطفل الأصوات الحادة بوضوح أكبر في هذه المرحلة. أما الأصوات الأولى التي يسمعها طفلكِ فهي الأصوات الصادرة من جسمكِ، مثل نبضات القلب وضغط الدم وعمل الأعضاء. ومع تطور حواسه، يبدأ باستقبال الأصوات الخارجية وتخزينها في ذاكرته. ومن المثير للاهتمام أنه بعد الولادة يشعر بالراحة عند سماع أصوات أجهزة مثل المكنسة الكهربائية أو مجفف الشعر أو غسالة الصحون، لأنها تذكّره ببيئة الرحم. وتُسمى هذه الأصوات «الضوضاء البيضاء» (white noise)، وهي من أكثر الطرق فعالية لتهدئة الأطفال، ولا سيما المصابين بالمغص.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبح جنسي واضحًا! 🩷💙 إذا كنتُ فتاةً، فقد تكوّن رحمي وقناتا فالوب وأصبحت في موضعها. وإذا كنتُ صبيًا، فأعضائي التناسلية ظاهرة بوضوح. هل تعرفين من أكون؟ أم تريدين أن يبقى الأمر مفاجأة؟ على أي حال، أنا صغيركِ وأحبكِ كثيرًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فلفل حلو'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه المرحلة، وقد شارفتِ على بلوغ منتصف حملكِ، عليكِ الانتباه لصحتكِ وصحة طفلكِ إذا كنتِ قد اكتسبتِ وزنًا يفوق المطلوب أو كنتِ تعتقدين أن وزنكِ يزداد بسرعة. تزداد الاحتياجات اليومية من السعرات الحرارية لدى النساء اللواتي بدأن الحمل بوزن طبيعي بمقدار 300 سعرة حرارية فقط، أي إن إجمالي الاحتياج يتراوح في المتوسط بين 1900 و2500 سعرة حرارية. ويختلف هذا الحد من امرأة إلى أخرى، وقد يؤدي استهلاك سعرات حرارية تتجاوز الاحتياج إلى زيادة غير صحية في الوزن. ولضبط الوزن خلال الحمل، يُفضّل دائمًا تناول وجبات صغيرة ومتكررة. فتناول وجبات خفيفة بين الوجبات الرئيسية يساعدكِ على تجنّب الإفراط في الأكل خلالها. كما تساعد الأطعمة الغنية بالحديد على تخفيف الشعور بالوهن المصاحب للحمل. ويساعد تناول الفاصولياء والأسماك واللحوم قليلة الدهون على تجنب الزيادة المفرطة في الوزن، كما يقلل من خطر ارتفاع ضغط الدم وتسمم الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مارسي تمرين «ساعة الحوض» لتخفيف آلام الظهر. استلقي على ظهركِ وحرّكي حوضكِ إلى الأمام والخلف، فهذا يساعد على إرخاء عضلات أسفل الظهر. كما قد يخفف ارتداء حزام داعم للحمل من العبء الواقع على ظهركِ.') WHERE id = '10652607-2e60-42fd-8695-4db1781a35b4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إذا كان طفلكِ أنثى، فقد بدأ مبيضاها بالفعل في إنتاج البويضات في هذه المرحلة. في المراحل المبكرة من النمو، يمتلك كل من الجنين الذكر والجنين الأنثى زوجين من القنوات التناسلية. لدى الذكور، تُكوّن القنوات "الميزونفريكية" الجهاز التناسلي الذكري، بينما تضمن القنوات "الباراميزونفريكية" لدى الإناث تطور الجهاز التناسلي الأنثوي. ومع تمايز الأعضاء التناسلية، تتحول هذه القنوات لدى الأجنة الإناث إلى الرحم والمهبل. ومن المثير للاهتمام أن مبيضي الطفلة ينتجان أكثر من 2 مليون بويضة قبل الولادة، وهو أعلى عدد من البويضات ستمتلكه طوال حياتها.;;;
بحلول سن البلوغ، ينخفض هذا العدد إلى نحو 400,000–500,000. وبعد بدء سنوات الخصوبة، تُفقد نحو 1000 بويضة كل شهر. ومع التقدم في العمر، لا ينخفض عدد البويضات فحسب، بل تتغير جودتها أيضًا؛ فعلى سبيل المثال، تكون واحدة من كل 2-3 بويضات سليمة من ناحية الكروموسومات لدى المرأة في سن 30 عامًا، بينما تنخفض هذه النسبة في سن الأربعين إلى بويضة واحدة من كل 5-6 بويضات.'), baby_message_ar = COALESCE(baby_message_ar, 'أعصابي تزداد سرعة! ⚡ الإشارات التي تنتقل من دماغي إلى جسمي تسلك الآن مسارًا "فائق السرعة". وبفضل طبقة الميالين، أصبحت أتحكم في حركاتي بصورة أفضل. لم أعد أتحرك عشوائيًا، بل ألمس وأستدير بقصد. تتم برمجة دماغي مثل حاسوب عملاق. يمكنكِ أن تفخري بي!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'فلفل حلو'), body_changes_ar = COALESCE(body_changes_ar, 'إنهاء الحمل من دون أي زيادة في الوزن أو بزيادة بضعة كيلوغرامات فقط ليس أمرًا واقعيًا، كما أنه ليس هدفًا صحيًا. فمع وجود الحمل، لا بد بالطبع من حدوث زيادة في الوزن. والثلث الثاني من الحمل الذي دخلتِ فيه هو المرحلة التي يبدأ فيها طفلكِ بالنمو والتطور بسرعة، ولذلك تبدأ الزيادة الملحوظة في الوزن خلال هذه الفترة. ومع نمو طفلكِ، تزداد كمية الغذاء والطاقة التي يحصل عليها منكِ، مما يزيد حاجتكِ إلى التغذية. لذا تُعد زيادة وزنكِ بنحو 500 غرام أسبوعيًا خلال هذه المرحلة من الحمل أمرًا طبيعيًا.;;;
قد تضر بصحة طفلكِ المواد المضافة مثل النتريت والنترات، التي تُستخدم في تصنيع منتجات اللحوم المصنّعة كالنقانق والسلامي والسجق. ;;;
تساعد الأطعمة الغنية بالكربوهيدرات على تقليل الغثيان، لكن المنتجات النشوية مثل الأرز الأبيض والمعكرونة تؤدي إلى ارتفاع سكر الدم. ومن المهم للغاية زيادة تناول الفاكهة للحصول على ما يكفي من الفيتامينات خلال الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا لاحظتِ تشوشًا شديدًا في الرؤية أو شعرتِ بوجود "ومضات ضوئية" أمام عينيكِ، فراجعي الطبيب فورًا. فقد يكون ذلك علامة على ارتفاع ضغط الدم، أما التشوش الخفيف المعتاد فهو طبيعي.') WHERE id = '29db8583-08d7-4065-8fa7-18665ece5422';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال الشهر المقبل، سيبدأ جسم طفلكِ بالتغطّي بطبقة خاصة تُسمى الطلاء الجبني. هذه المادة البيضاء الكريمية هي أول درع واقٍ لطفلكِ داخل الرحم، وتحميه حتى حمّامه الأول.;;;
تُظهر الأبحاث أن الطلاء الجبني يحتوي على نحو 40 بروتينًا مختلفًا يدعم المناعة. ومن المثير للاهتمام أن نصف هذه البروتينات لا يوجد في أي مكان آخر في الطبيعة، باستثناء الطلاء الجبني. وتمتلك هذه المواد الفريدة خصائص تقضي على الميكروبات وتحمي طفلكِ من العدوى بفاعلية.;;;
تؤدي طبقة الطلاء الجبني أيضًا دور مرطب طبيعي ومنظّم لدرجة الحرارة لدى طفلكِ. فهي تمنع جسمه من فقدان السوائل، وتدعم تكوّن خلايا جلدية جديدة، كما تسهّل عملية الولادة بفضل قوامها الزلق.'), baby_message_ar = COALESCE(baby_message_ar, 'الأضواء تضيء في دماغي! 🧠 ماما، يعمل دماغي الآن مثل حاسوب عملاق. تتشكل فيه مراكز متخصصة للرؤية والسمع والتذوق والشم واللمس. أنا لا أنمو فحسب، بل أستعد لفهم العالم. عندما أسمع صوتكِ، ينشط "مركز السمع" في دماغي. لقد أصبحت علاقتنا موثقة علميًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'طماطم'), body_changes_ar = COALESCE(body_changes_ar, 'يكون الجلد أكثر حساسية خلال الحمل وأكثر تأثرًا بأشعة الشمس. ويؤدي ارتفاع مستوى الهرمون المنبّه للخلايا الميلانينية، الذي تفرزه الغدة النخامية ويؤثر في الخلايا المنتجة للميلانين المسؤول عن لون البشرة، إلى جعل الجلد شديد القابلية للتصبغ والاسمرار.;;;
من الشائع جدًا ظهور تصبغات الحمل بسبب أشعة الشمس أو ازديادها إذا كانت موجودة بالفعل. بالإضافة إلى ذلك، قد يؤدي البقاء تحت الشمس فترة طويلة إلى ارتفاع درجة حرارة جسمكِ بشكل مفرط ونقص السوائل فيه. وقد تؤثر كلتا الحالتين سلبًا في حملكِ. ولهذه الأسباب كلها، لا يُنصح ببقائكِ تحت أشعة الشمس مدة طويلة أثناء الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الظهر، تجنبي الأحذية ذات الكعب العالي تمامًا. ضعي وسادة صغيرة خلف أسفل ظهركِ عند الجلوس. لا تجهدي عضلات منتصف بطنكِ كثيرًا، وعند النهوض من السرير استديري على جانبكِ أولًا ثم انهضي.') WHERE id = 'bc3702e9-c9f0-4b15-a3b9-8dd5c0a6dd34';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ قادرًا على رؤية الأحلام! بفضل استمرار نمو دماغه، يمكنه الآن الدخول في مرحلة نوم حركة العين السريعة (REM). وهي المرحلة التي تتشكل فيها الأحلام في الدماغ أثناء النوم. تحدث في المرحلة 4 من النوم، وتشكل في المتوسط 15-20% من إجمالي مدة النوم، وتبدأ بعد نحو 30-90 دقيقة من الاستغراق فيه.;;;
للنوم 4 مراحل مختلفة. في المرحلة 1، قد يحدث عجز عن الاستغراق التام في النوم مع الإحساس بالسقوط من مكان مرتفع. وفي المرحلة 2، يستعد الجسم للنوم الفعلي، ويبدأ معدل ضربات القلب ودرجة حرارة الجسم بالانخفاض. أما المرحلتان 3 و4 فهما مرحلتا النوم العميق، وفيهما قد تحدث حالات المشي أثناء النوم. وخلال هاتين المرحلتين، اللتين تُعرفان بالنوم العميق، يجدد الجسم نفسه، وتلتئم الأنسجة، وتُزال الخلايا التي لم تعد نافعة، ويتخلص الجهاز المناعي من المواد غير الضرورية. وينمو الأطفال ويتطورون خلال هذه المراحل من نومهم.;;;
عندما يكون الدماغ في مرحلة نوم حركة العين السريعة (REM)، يصبح التنفس أسرع وتبدأ العينان بحركات سريعة وعشوائية، مما يجعل الأحلام تبدو واقعية للغاية. والأهم من ذلك أن الدماغ يكون خلال هذه المرحلة نشطًا بقدر نشاطه في حالة اليقظة. ومنذ وجودهم في الرحم وحتى مرحلة حديثي الولادة، يقضي الأطفال معظم وقتهم في نوم حركة العين السريعة. ويساعدهم ذلك على دمج تجاربهم بصورة أفضل خلال أهم فترات نموهم. وتشكل مرحلة نوم حركة العين السريعة نحو 50% من دورة نوم الأطفال، ثم تبدأ مدتها بالتناقص تدريجيًا مع نموهم، وتنخفض هذه النسبة بسرعة مع التقدم في العمر.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أحميكِ! 🥚 إذا كنتُ فتاة، ففي مبيضيّ الصغيرين بالفعل 6 ملايين خلية بويضية! وهذا يعني أن أحفادكِ المستقبليين موجودون بداخلي منذ الآن. وإذا كنتُ صبيًا، فأعضائي التناسلية تتطور. تستمر الأجيال يا ماما. أنتِ تصنعين تاريخًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'طماطم'), body_changes_ar = COALESCE(body_changes_ar, 'من المهم جدًا تناول الفيتامينات بصورة صحيحة وبجرعات مناسبة خلال الحمل للحفاظ على صحة جسمكِ ونفسكِ. وقد يؤدي عدم الحصول على كمية كافية من الفيتامينات، التي تؤثر في جميع أعضاء الجسم وأجهزته، إلى بعض المشكلات. والفيتامينات مواد منظّمة ومعززة للمقاومة توجد في المصادر الغذائية الطبيعية، وتساعد على تجدد الخلايا وإنتاج الطاقة، ويحتاج الجسم إلى كميات محددة منها يوميًا، وعند نقصها يجب تناولها كمكمّلات إضافية من مصادر خارجية.;;;
قد يؤدي عدم حصولكِ على كمية كافية من الفيتامينات خلال الحمل إلى مشكلات في الرؤية، وشعور مستمر بالتعب، وتشققات في اللسان والجلد، وفقر الدم، والإرهاق الذهني وأعراض الاكتئاب، وظهور الكدمات والبقع على الجلد، وآلام العظام وفقدان الكتلة العضلية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي النوم على جانبكِ الأيسر؛ فهذا يزيد تدفق الدم إلى طفلكِ ورحمكِ إلى أقصى حد. مارسي تمارين تمدد خفيفة لتخفيف آلام الظهر. وازني شهيتكِ المتزايدة بتناول الفاكهة والخضراوات. أصبح طفلكِ يسمعكِ الآن بوضوح أكبر، لذا شغّلي له اليوم موسيقى يحبها بإيقاع هادئ.') WHERE id = '695bdf70-cf7b-4ed0-9ff8-c4418720fc60';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد تكون الحازوقة أول حركة تشعرين بها لطفلكِ! تحدث الحازوقة نتيجة انقباض مفاجئ لعضلة الحجاب الحاجز التي تفصل بين تجويف البطن وتجويف الصدر، وانغلاق الفتحة بين الأحبال الصوتية، مما يؤدي إلى شهيق مفاجئ. وعلى الرغم من شيوعها لدى حديثي الولادة، فإن هذه العملية تبدأ في الواقع داخل الرحم.;;;
يُصاب طفلكِ بالحازوقة لأنه يبتلع السائل الأمنيوسي داخل الرحم. ورغم أن ذلك قد يثير قلق بعض الأمهات، فإنه مفيد جدًا لنمو الطفل. فبفضل الحازوقة، يزداد منعكس المص لدى طفلكِ قوة، مما يساعده على الرضاعة بعد الولادة مباشرة.;;;
عندما يبتلع طفلكِ السائل الأمنيوسي، تعمل انقباضات عضلة الحجاب الحاجز وارتخاؤها على تمرين رئتيه. ويساعد السائل الذي يدخل إلى الرئتين أثناء المص والبلع والحازوقة على نموهما واستعدادهما للتنفس. ومع اقتراب موعد الولادة، قد تزداد نوبات الحازوقة تواترًا لأن الطفل يبتلع كمية أكبر من السائل.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا ماما! أنا بحجم حبة مانجو. أصبح ذراعاي وساقاي الآن متناسبين مع جسمي. أنا إنسان صغير! ويمكنني الآن أن أركلكِ بقوة أكبر. كوني مستعدة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن تولي تغذيتكِ أهمية كبيرة خلال الحمل. ويُعد الزنك أحد العناصر الغذائية الأساسية التي يجب أن يتضمنها نظامكِ الغذائي. فهو من أهم المعادن الداخلة في تركيب البروتينات وأغشية الخلايا. كما يشارك في عملية إنتاج البروتينات التي تحددها الجينات. ويضمن وجود كمية كافية من الزنك في أجسامنا أيضًا عمل أكثر من 100 إنزيم بصورة سليمة وصحية.;;;
تزداد حاجة الجسم إلى الزنك خلال الحمل. ويؤدي حصولكِ على كمية كافية منه في هذه الفترة دورًا مهمًا في تكوين الحمض النووي (DNA) والبروتينات. لذلك يُعد تناول الزنك ضروريًا جدًا خلال الحمل، حين تتشكل الخلايا بسرعة فائقة. وبينما تبلغ حاجة المرأة غير الحامل اليومية إلى الزنك 8 mq، ترتفع لدى الحامل إلى 11 mq. أما الأم المرضعة، فينبغي أن تتناول 12 mq من الزنك يوميًا. ويتوفر الزنك بوفرة في اللحوم والمأكولات البحرية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بوصولكِ إلى منتصف الطريق بفرحة صغيرة! حاولي الجلوس باستقامة وتجنبي رفع الأشياء الثقيلة لتخفيف آلام الظهر. وإذا كان لديكِ تورم في ساقيكِ، فارفعيهما قليلًا واستريحي في نهاية اليوم. واصلي شرب الكثير من الماء وإدراج الأطعمة الغنية بالألياف في نظامكِ الغذائي. غدًا ينتظرنا يوم "منتصف الطريق" الكبير!') WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تهانينا! لقد أكملتِ بالفعل نصف فترة حملكِ.;;;
إذا كان طفلكِ أنثى، فإن إنتاج البويضات في مبيضيها يتواصل بوتيرة سريعة. أما لدى الأجنة الذكور، فتستمر الخصيتان في التكون والنزول نحو موضعهما. وتُعد الخصيتان جزءًا أساسيًا من الجهاز التناسلي الذكري، وتحتاجان إلى بيئة أبرد من درجة حرارة الجسم بنحو 2 درجة كي تنمو الحيوانات المنوية بصورة سليمة. وهذا هو السبب الرئيسي لوجود كيس الصفن خارج الجسم؛ إذ تساعد درجة الحرارة المنخفضة هذه على منع تلف خلايا الحيوانات المنوية.;;;
للخصيتين عدة وظائف مهمة، منها إفراز هرمون التستوستيرون، وتطوير الصفات الجسدية الذكورية، وإنتاج الحيوانات المنوية. وعند اكتمال النمو، يصبح هذا الجهاز قادرًا على إنتاج ما يصل إلى 200 مليون خلية منوية يوميًا.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأ شعري ينمو! 💇‍♂️ بدأ الشعر الحقيقي ينبت على فروة رأسي. لا يزال رقيقًا جدًا وعديم اللون، لكن ربما أولد بشعر كثيف. تعرفين كيف تقول الجدات عندما تشعرين بحرقة المعدة: "شعر الطفل ينمو"، فهل يُعقل أن يكنّ على حق؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه المرحلة، أصبح رحمكِ أعلى بثلاث مرات من موضعه قبل الحمل. وبدءًا من هذا الأسبوع وحتى الولادة، سيتحرك إلى الأعلى بنحو 1 sm كل أسبوع. وسيؤدي ارتفاع الرحم إلى تغير مواضع أعضائكِ الداخلية. وقد يتسبب ارتخاء الصمام الموجود عند المعدة في تسرب الإفرازات الحمضية إلى المريء، مما قد يؤدي إلى حرقة المعدة.;;;
تُعد حرقة المعدة والارتجاع الحمضي من الأعراض الشائعة أثناء الحمل. وللوقاية من حرقة المعدة، يُنصح بتجنب أطعمة ومنتجات مثل الطماطم والبصل والثوم والمشروبات الغازية والحمضية والتدخين والآيس كريم والحلويات الغنية بالقطر والشوكولاتة والأطعمة المقلية ومعجون الطماطم والأطعمة الحارة والمخللات والبرتقال والفلفل الحار. وإذا شعرتِ بحرقة المعدة، يمكنكِ أولًا تجربة الحليب الدافئ، إذ يساعد على تخفيفها.'), daily_tip_ar = COALESCE(daily_tip_ar, 'امنحي نفسكِ يومًا ممتعًا احتفالًا بوصولكِ إلى منتصف الطريق! حاولي الجلوس باستقامة للوقاية من آلام الظهر، واحرصي على الاستلقاء على جانبكِ الأيسر عند الراحة. أولي تناول الحديد اهتمامًا خاصًا، لأن حاجة طفلكِ إليه لإنتاج الدم تزداد. وستساعدكِ ممارسة المشي الخفيف لمدة 20-30 دقيقة يوميًا على الحفاظ على نشاطكِ وحيويتكِ.') WHERE id = 'ac85f07b-25b5-4dda-969a-4a8dfc9a2528';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'رغم أن جسم طفلكِ يكون مغطى بالكامل خلال هذه الأسابيع بالشعر الزغبي، فإن الشعر في منطقتي الحاجبين والرأس أكثر كثافة، ولذلك بدأ يظهر بوضوح. ولا تقتصر وظيفة الحاجبين على المظهر الجمالي، بل يؤديان أيضًا دورًا مهمًا في حماية العينين من قطرات العرق والماء والمواد الضارة الأخرى التي قد تأتي من الأعلى. ومن المثير للاهتمام أن طول الحاجبين متساوٍ لدى الأجنة الإناث والذكور (نحو 10 mm)، لكنهما يختلفان في السماكة. ويتكون في منطقة حاجبي طفلكِ ما بين 200-300 شعرة في المتوسط. وإذا كان طفلكِ ذكرًا، فسيشبه شكل حاجبيه في المستقبل شكل شاربه ولحيته. ويُعد شعر الحاجبين والرموش الأكثر مقاومة بين شعر الجسم؛ فهو آخر ما يشيب، ومن أصعب أنواع الشعر تساقطًا ما لم توجد مشكلة صحية خاصة.'), baby_message_ar = COALESCE(baby_message_ar, 'كليتاي تعملان بشكل رائع! 💧 أبتلع السائل الأمنيوسي، فتقوم كليتاي بترشيحه وإعادته على هيئة بول نقي. يحميني هذا السائل ويحافظ على دفئي ويساعدني على الحركة. أنا أنظف حوضي بنفسي. وأنتِ أيضًا اشربي الكثير من الماء ليبقى سائلي نظيفًا ووفيرًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الحمل، تتمدد مفاصل حوضكِ التي تكون ثابتة عادةً، كي يتمكن طفلكِ من المرور بسهولة أثناء الولادة. ولهذا قد تعانين في هذه الفترة من بعض اضطرابات التوازن. ويكون مخرج الحوض بيضاوي الشكل، طويلًا من الأمام إلى الخلف وقصيرًا من اليمين إلى اليسار. أما أضيق جزء من هذا المسار فهو المنطقة الوسطى التي تحتوي على بعض البروزات العظمية. ولا تزيد المسافة بين رأس الطفل والجزء البيضاوي من عظم الحوض على 20 sm. وطوال وجود الطفل في الرحم، يبقى رأسه منحنيًا إلى الأمام بحيث يلامس ذقنه صدره. وبهذه الطريقة يدخل الرأس إلى الحوض بأصغر قطر ممكن. ولا يكون رأس الطفل ولا عظم الحوض صلبًا وثابتًا تمامًا، بل يتغير كلاهما خلال الحمل ليتكيف أحدهما مع الآخر. ويمكن للعظام المكوّنة لرأس الطفل أن تتحرك فوق بعضها، كما أنها أكثر ليونة من عظام الشخص البالغ. وهذا ما يسمح للطفل بالمرور عبر قناة الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف التعب والتورم في ساقيكِ، غيّري وضعيتكِ باستمرار خلال اليوم ولا تبقي من دون حركة مدة طويلة. ولزيادة كمية الحديد التي تحصلين عليها، أضيفي اللحوم الحمراء والعدس والخضراوات الورقية الداكنة إلى نظامكِ الغذائي. أصبح طفلكِ يسمع كل شيء الآن، لذا يمكنكِ اليوم أن تقرئي له بصوت مرتفع كتابًا تحبينه.') WHERE id = '34d9ab3e-6f7e-4354-93cc-e6f91180c7df';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يخصص طفلكِ في هذه المرحلة 90% من وقته للنوم. يطفو طفلكِ في السائل الأمنيوسي ويستسلم لنوم هانئ خلال النهار، إذ تهدهده حركاتكِ باستمرار. أما ليلًا، فعندما تتوقفين عن الحركة ويصبح السائل ساكنًا، يبدأ بالاستيقاظ. ويُعتقد أن هذه العادة هي أحد أسباب استيقاظ الأطفال حديثي الولادة المتكرر ليلًا.;;;
ولأن جدار الرحم يحجب الفرق بين الليل والنهار في العالم الخارجي، فقد يحتاج طفلكِ إلى 1-2 شهر بعد الولادة للتكيف مع هذا الإيقاع. أما أهم سبب لقضاء طفلكِ معظم يومه تقريبًا في النوم فهو هرمون النمو.;;;
هذا الهرمون، الذي تنتجه خلايا الفص الأمامي للغدة النخامية، ذو بنية بروتينية، وهو المسؤول عن زيادة طول الجسم ونمو الأنسجة. والأهم أنه يُصنّع بصورة أساسية أثناء نوم طفلكِ. أي كلما نام طفلكِ أكثر، نما بصورة أسرع وأكثر صحة.'), baby_message_ar = COALESCE(baby_message_ar, 'لديّ نظام نوم خاص بي! 🌙 ماما، أنا لا أبقى مستيقظًا طوال اليوم. لديّ أيضًا أوقات للنوم وأوقات للاستيقاظ. عادةً ما تهدهدني حركتكِ عندما تمشين أو تتحركين، فأخلد إلى النوم. أما عندما تستلقين وترغبين في الراحة، فأستيقظ أنا وأقيم حفلة راقصة. نظامانا مختلفان قليلًا، سامحيني!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'قبل الحمل، يبلغ متوسط وزن كل ثدي 230-250 غرامًا. ومع الحمل، يزداد حجم الثديين ويكبران وتظهر الحساسية نتيجة توسع قنوات الحليب. وقد تشعرين بثقل في الثديين، كما قد يظهر اختلاف بين حجم الثدي الأيمن والأيسر. وقد تصبح الأوعية الدموية مرئية تحت الجلد المحيط بالثديين. ولهذا قد يصل وزن الثديين إلى ضعفي وزنهما الطبيعي. أما الرحم، الذي يبلغ وزنه عادةً نحو 60 غرامًا، فيصل وزنه في هذه المرحلة إلى قرابة 300 غرام، وسيبلغ 1000 غرام بحلول يوم الولادة. ويبلغ وزن السائل الأمنيوسي المحيط بطفلكِ في هذه المرحلة نحو 350-400 غرام، ثم يزداد إلى 800 غرام في أواخر الحمل. واعتبارًا من هذا الأسبوع، تكاد المشيمة تماثل طفلكِ في الحجم والوزن، وسيصل وزنها إلى نحو 600-650 غرامًا في نهاية الحمل. وإضافة إلى ذلك، ستزداد كمية السائل بين الأنسجة بمقدار 1500-2000 غرام مقارنةً بما قبل الحمل. أما الدهون التي يخزنها الجسم استعدادًا لإنتاج الحليب بعد الولادة، فتقترب في هذه المرحلة من 400-500 غرام، وستصل إلى 3500-4000 غرام بحلول نهاية الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف الاحمرار والشعور بالحرارة في يديكِ، اغسليهما بالماء البارد. تجنبي ملامسة المنظفات الكيميائية. واحرصي على ارتداء قبعة واستخدام كريم واقٍ من الشمس بعامل حماية SPF لحماية وجهكِ من أشعة الشمس.') WHERE id = 'd0d5f1e7-e726-4e8b-9248-bacff687b744';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تبدأ بصيلات الشعر الحقيقية، التي تختلف عن بقية الزغب، بالنمو في فروة رأس طفلكِ. يتكوّن الشعر من بروتين متين يُسمى الكيراتين، وتمنحه الروابط الخاصة في بنيته الداخلية قوته. وإذا تضررت الطبقة الخارجية الواقية للشعرة، فقد يؤدي ذلك إلى تكسرها.;;;
يتكوّن جذر الشعرة داخل الجُريب الموجود في الطبقة السفلية من الجلد، ثم يستطيل ويخترق الطبقة العلوية من الجلد ليظهر إلى الخارج. وتحدد صبغة الميلانين الموجودة في حمضكِ النووي والحمض النووي لشريككِ لون شعر طفلكِ. ويكون الشعر فاتحًا أو داكنًا وفقًا لكمية هذه الصبغة.;;;
أما نوع الشعر فتحدده كثافة الروابط ثنائية الكبريتيد؛ إذ تكون هذه الروابط أكثر كثافة في الشعر المجعد. وعلى الرغم من أن الشعرة تبدو رفيعة جدًا، فإنها تتكون في الواقع من طبقات عدة وعدد كبير من الألياف. كما تنتج الأطراف المتقصفة للشعر عن انفصال هذه البُنى الليفية بعضها عن بعض.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا مغطى بالطلاء الجُبني! 🧼 أصبحت تلك المادة البيضاء الشبيهة بالكريم على جسمي أكثر سماكة الآن. إنها تحميني من تأثر جلدي بسبب بقائي في الماء، كما ستساعدني عند الولادة على الانزلاق والخروج عبر قناة الولادة. لقد فكرت الطبيعة في كل شيء، أليس كذلك؟ لديّ كل أنواع الحماية كي أصل إليكِ بصحة جيدة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'قد تؤدي التغيرات الهرمونية التي تمر بها النساء أثناء الحمل إلى احتقان الغشاء المخاطي للأنف وتورمه. وتسبب هذه الحالة زيادة كمية الإفرازات الأنفية. وكما يحدث في التهاب الجيوب الأنفية، قد يؤدي انسداد تجاويف الجيوب إلى احتقان الأنف. وهذا أحد العوامل التي قد تسهم في ظهور الشخير. ومع بدء نمو طفلكِ، تحدث أيضًا زيادة سريعة في الوزن. وقد تكتسبين وزنًا زائدًا بسبب تغير نمط التغذية كذلك. ويظهر توزع هذا الوزن الزائد في مختلف مناطق الجسم، إذ يؤدي تراكمه على شكل دهون إلى زيادة الأنسجة في مناطق متعددة منه. وتكون النساء اللواتي يكتسبن وزنًا زائدًا أثناء الحمل أكثر عرضة للشخير. لذلك ينبغي اتخاذ التدابير اللازمة لتجنب زيادة الوزن بما يتجاوز المعدل الطبيعي للحمل. واحرصي على اتباع نظام غذائي صحي ومراقبة زيادة وزنكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للوقاية من حرقة المعدة، لا تستلقي فورًا بعد تناول الطعام، وفضّلي تناول وجبات صغيرة ومتكررة. ولتخفيف آلام الظهر، ضعي وسادة صغيرة خلف ظهركِ عند الجلوس وحافظي على استقامة ظهركِ. لا تنسي تناول الحديد لضمان تلبية احتياجاتكِ واحتياجات طفلكِ من الدم بالكامل. وخصصي لنفسكِ بعض الوقت هذا المساء واستمعي إلى موسيقى هادئة.') WHERE id = '481d4a59-0854-49d1-ad3d-0f418a6738b5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يقترب وزن طفلكِ هذا الأسبوع من 300 غرام تقريبًا. ومن الطبيعي تمامًا أن يظهر في الفحوص الطبية أن نمو طفلكِ متقدم قليلًا على العمر الحملي المتوقع أو متأخر عنه. ويُعد اختلاف يصل إلى أسبوعين أمرًا طبيعيًا.;;;
خلال الأشهر الأولى من النمو، قد يكون 60% من الأطفال متقدمين على العمر الحملي المحسوب وفقًا لتاريخ آخر دورة شهرية. ومع اقتراب نهاية الثلث الثاني، يقل هذا الاختلاف عادةً وتتوافق القياسات مع أسبوع الحمل. وإذا تجاوز الاختلاف أسبوعين، فقد يحيلكِ طبيبكِ إلى اختصاصي طب الأم والجنين أو يطلب فحوصًا إضافية لمراقبة الحالة عن كثب.;;;
كون طفلكِ «متأخرًا» قليلًا عن أسبوع الحمل لا يعني بالضرورة وجود تقييد في النمو. فالقياسات بأجهزة التصوير بالموجات فوق الصوتية شديدة الحساسية؛ وقد تؤثر وضعية طفلكِ وطريقة الطبيب في القياس والمستوى التقني للجهاز في النتيجة. وحتى القياسات التي تُجرى بفارق بضع دقائق قد تُظهر اختلافات طفيفة، لذلك لا داعي للقلق إذا لم يتجاوز الاختلاف أسبوعين.'), baby_message_ar = COALESCE(baby_message_ar, 'هل نحن مستعدان للفحص الكبير؟ 🩺 خلال الأيام المقبلة سيُجرى «الفحص التشريحي» (دوبلر). سيفحص الطبيب كل عضو من أعضائي واحدًا تلو الآخر، بما في ذلك قلبي ودماغي وأصابعي. وسألوّح لكِ بيدي! وإذا حالفنا الحظ، فستتمكنين أيضًا من معرفة جنسي بدقة. (إذا لم أخفِه عنكِ).'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'مانجو'), body_changes_ar = COALESCE(body_changes_ar, 'اعتبارًا من هذا الأسبوع، تبدأ المنطقة البنية في ثدييكِ بالاتساع تدريجيًا. وقد تغطي هذه المنطقة، التي تُسمى الهالة، نصف الثدي تقريبًا. ويتغير موضع الحلمة والهالة مع نمو الثدي، وهذا أمر طبيعي وقد يستمر حتى الشهر 12 بعد الولادة. والهالة هي الحلقة داكنة اللون المحيطة بالحلمة. ويختلف شكلها ولونها وحجمها من امرأة إلى أخرى وفقًا للون البشرة. وبعد الحمل الأول، يصبح لون الهالة أغمق ويبقى كذلك. وتوجد داخل الهالة غدد دهنية صغيرة تُسمى غدد مونتغمري.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف الحمل الواقع على ظهركِ، حاولي الجلوس باستقامة وتجنبي الوقوف لفترات طويلة. وفي المساء، أريحي ساقيكِ لمدة 15 دقيقة مع رفعهما قليلًا فوق مستوى القلب؛ فهذا يخفف التورم ويريح الأوعية الدموية. اهتمي خصوصًا بالحصول على الحديد والكالسيوم. واختتمي يومكِ بقراءة بضع صفحات من كتاب تحبينه بصوت مرتفع لطفلكِ.') WHERE id = '6ad08d05-7381-4d47-abac-7c50836b90a0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد بلغ الجهاز الهضمي لطفلكِ مرحلة مهمة الآن. فمعدته مستعدة تمامًا لإنتاج مادة خاصة، وهي إنزيم الرينين، المخصص لهضم الحليب فقط.;;;
تبدأ عملية هضم الحليب بتخثير بروتين يُسمى الكازين موجود في الحليب. وبعد ولادة طفلكِ، عندما يرضع الحليب، يعمل إنزيم الرينين في معدته على تخثيره فورًا. ثم يبدأ إنزيم البيبسين عمله، فيُحلل هذه المادة إلى أحماض أمينية كي تتمكن خلايا طفلكِ من امتصاصها. وبعد تأثير إنزيم الرينين، يكتسب الحليب قوامًا غير متجانس يشبه اللبن الرائب أو الجبن. أما إنزيم البيبسين، فيُحلل هذه البروتينات ويتيح انتقالها عبر الدم إلى جميع أجزاء الجسم.;;;
عند الولادة، قد يتقيأ الأطفال أحيانًا الحليب الزائد. فإذا كان الحليب الخارج من فم طفلكِ لم يعد سائلًا، بل أصبح أكثر تماسكًا وكثافة، فهذا يدل على أن إنزيمات الرينين في المعدة قد بدأت هضم الحليب بسرعة وكفاءة.'), baby_message_ar = COALESCE(baby_message_ar, 'أُحضّر صوتي! 🎤 حنجرتي وأحبالي الصوتية جاهزة تمامًا. لا ينقصني الآن سوى الهواء. وبمجرد أن أولد، سأقول لكِ مع أنفاسي الأولى: "مرحبًا يا أمي!" (أي "وااااه!"). هل تتخيلين تلك اللحظة؟ أنا أتدرّب كل يوم من أجلها.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'موزة'), body_changes_ar = COALESCE(body_changes_ar, 'من الضروري توخي الحذر بشأن أنواع شاي الأعشاب التي يمكن شربها أثناء الحمل. لا توجد مشكلة في تناول شاي المليسة وشاي الزنجبيل بعد الحصول على موافقة طبيبتكِ. ومن المعروف أن استخدام شاي المليسة، الذي يتمتع بتأثير مهدئ، خلال الحمل لا يسبب أي آثار ضارة. ويمكن خصوصًا للنساء اللواتي يجدن صعوبة في النوم أو يعانين الأرق شرب كوب من شاي المليسة قبل النوم. كما أن الزنجبيل الغني بمضادات الأكسدة مفيد عند تناوله على هيئة شاي. وقد يساعد شرب شاي الزنجبيل خلال الثلث الأول، الذي يكثر فيه الغثيان والقيء، على تخفيف هذه الأعراض. وقد يكون للشاي المصنوع من أوراق توت العليق تأثيرات مختلفة في العضلات. وقد ينطوي تناول شاي توت العليق، الذي يساعد على تخفيف آلام المخاض، على مخاطر في الأسابيع الأخيرة من الحمل. ويُعد الشاي الأخضر مفيدًا للغاية بسبب محتواه المرتفع من مضادات الأكسدة، كما يساعد على التخلص من السموم في الجسم. لكنه قد يؤثر سلبًا في طفلكِ لأنه يقلل امتصاص حمض الفوليك. لذلك لا يُنصح عمومًا بتناول الشاي الأخضر أثناء الحمل. وقد يؤدي شرب شاي الميرمية أثناء الحمل إلى تقليل التقلصات أو زيادة خطر النزيف. ولهذا ينبغي تجنب شاي الأعشاب الذي يسبب تميّع الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تناولي الأطعمة الغنية بالألياف واشربي الكثير من الماء لتجنب الإمساك. لا تقفي أو تجلسي فترات طويلة. وقد تساعد تمارين كيجل أيضًا على تخفيف البواسير من خلال تحسين الدورة الدموية في قاع الحوض.') WHERE id = '0c65c176-54fc-4e82-af61-c7b6cff2d77a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تبدأ نحو 70% من الحوامل بالشعور بحركات أطفالهن الأولى اعتبارًا من هذا الأسبوع. وهذا هو أول تواصل جسدي بينكِ وبين طفلكِ، وإحدى أكثر لحظات الحمل إثارة.;;;
لا يزال طفلكِ صغيرًا، لذلك قد لا تشعرين بحركاته بانتظام كل يوم. ومن الطبيعي تمامًا أن تشعري بنشاطه في أحد الأيام، ثم لا تشعري بشيء خلال الأيام القليلة التالية. وعادةً ما تصبح الحركات منتظمة بعد منتصف العشرينيات من أسابيع الحمل. وإذا لم تشعري بأي حركة حتى الآن، فلا تقلقي؛ إذ يُعد ذلك طبيعيًا حتى الأسبوع 24. وقد يرتبط الأمر بشد أربطة البطن أو وضعية الطفل أو النسيج الدهني في منطقة البطن.;;;
مع نمو الرحم، يدفع الأمعاء نحو الجانبين. وقد تختلط عليكِ أحيانًا حركة الأمعاء أو الغازات أو عمليات الهضم الناتجة عن هذا الضغط مع حركات طفلكِ. ومع مرور الوقت، ستتعلمين التمييز بين هذين الإحساسين المختلفين.'), baby_message_ar = COALESCE(baby_message_ar, 'قطعنا نصف الطريق! 🏁 تهانينا يا ماما! لقد أتممنا نصف ماراثون الأسابيع الـ40 بالضبط (50%). أصبح طولي بطول موزة! أمر مذهل، أليس كذلك؟ انظري كم كبرت حتى الآن. لقد وصل رحمكِ الآن إلى مستوى سرتكِ. إننا نتجه نحو خط النهاية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'موزة'), body_changes_ar = COALESCE(body_changes_ar, 'للمعادن أهمية كبيرة في حماية الخلايا والحفاظ على صحة الأسنان والعظام والجلد. كما تؤدي دورًا مهمًا في ضغط الدم ونظم القلب ووظائف العضلات والحفاظ على توازن السوائل في الجسم والتكاثر والعديد من الوظائف الأخرى. ومن بين هذه المعادن، يُعد الكالسيوم الأهم طوال فترة الحمل. ولا تقتصر أهمية كمية الكالسيوم في الجسم على العظام فحسب، بل يشارك أيضًا في جميع وظائف الجسم. كما أنه معدن ضروري لأسنان صحية وقوية، ويؤدي دورًا كبيرًا في عمل العضلات. وهو ضروري خصوصًا لاستفادة الجسم من الحديد ولتمكين العناصر الغذائية التي تتناولينها من عبور أغشية الخلايا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام نصف الطريق بشيء تحبينه! ولتخفيف آلام الظهر، حاولي ألا تجلسي واضعةً ساقًا فوق الأخرى. واحرصي ليلًا على الاستلقاء على جانبكِ الأيسر ووضع وسادة بين ركبتيكِ. وواصلي تناول مصادر الحديد (العدس واللحوم الحمراء والسبانخ) لتلبية احتياجاتكِ واحتياجات طفلكِ من الدم بالكامل.') WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يبلغ وزن طفلكِ 250–280 غرامًا. إنه ينمو بسرعة كبيرة، أليس كذلك؟ يواصل قلب طفلكِ، الذي ينمو بسرعة مذهلة، العمل بلا توقف ولو للحظة كي يضخ مزيدًا من الدم إلى جسمه. وبفضل ذلك، تستمر عضلة قلبه في النمو واكتساب القوة.;;;
وبفضل انقباضات عضلة القلب، يصل الأكسجين والعناصر الغذائية إلى كل خلية في جسم طفلكِ. أي إن هذه الانقباضات ضرورية لأداء الوظائف اللازمة للحياة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا "آكل"! 🍽️ ماما، لقد بدأ جهازي الهضمي العمل. أنا أبتلع السائل الأمنيوسي، وتمتص أمعائي منه السكر والماء. يتغير مذاق هذا السائل كل يوم؛ لقد شعرت بمذاق طعام الثوم الذي تناولتِه أمس! وتتجمع في أمعائي أولى فضلاتي، وتُسمى "العقي". لا تقلقي، سأحتفظ بها لحفاضي ولن أسبب أي فوضى!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'اهتمي كثيرًا بالحصول على الحديد للحفاظ على صحتكِ أثناء الحمل. إذ تتضاعف حاجتكِ إلى الحديد تقريبًا خلال هذه الفترة. ويحتوي جسمكِ أثناء الحمل على كمية دم أكبر بنسبة 50% مقارنةً بما قبل الحمل، والحديد ضروري لتكوين خلايا الدم.;;;
كما يؤدي الحديد دورًا مهمًا في عمل البُنى التي توصل الأكسجين إلى العضلات والأنسجة الضامة، إضافة إلى دعم الجهاز المناعي. ويتأثر مستوى الحديد في دمكِ بالمواد الأخرى التي تتناولينها. فقد يعيق الكالسيوم، وكذلك المشروبات المحتوية على الكافيين مثل الشاي والقهوة، امتصاص الجسم للحديد.;;;
أما فيتامين C، فيدعم امتصاص الحديد. لذلك قد يكون من المفيد شرب كوب من عصير الفاكهة أو تناول ثمرة فاكهة بعد تناول الأطعمة الغنية بالحديد.;;;
ويُعد الحديد ضروريًا لنمو طفلكِ وللمشيمة، خصوصًا خلال الثلثين الثاني والثالث من الحمل. ويمكنكِ الحصول على الحديد الضروري لدمكِ من خلال اتباع نظام غذائي متوازن. ولا تهملي إجراء الفحوصات الدورية لتقليل خطر الإصابة بفقر الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا شعرتِ بتورم ساقيكِ، فغيّري وضعيتكِ كثيرًا خلال اليوم وأريحي ساقيكِ مساءً برفعهما على وسادة. واشربي الكثير من الماء واستخدمي زيوتًا مرطبة للحفاظ على مرونة بشرتكِ. واهتمي بالحصول على الكالسيوم والمغنيسيوم للوقاية من تشنجات الساقين.') WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ قادرًا على سماعكِ الآن!;;;
يكتمل تكوّن أذن طفلكِ إلى حد كبير مع حلول الأسبوع العشرين من الحمل، إلا أن نموها يستمر حتى الأسبوع الرابع والعشرين. وبفضل قدرته على التقاط الأصوات القادمة من الخارج عبر الأذن الداخلية، بات طفلكِ قادرًا الآن على سماع صوتكِ عندما تتحدثين.;;;
خلال بضعة أسابيع، تصبح حاسة السمع لدى طفلكِ شديدة الحساسية، فتتأثر بصوتكِ وحالتكِ العاطفية وتصرفاتكِ إلى درجة تغيّر معدل ضربات قلبه وحركاته. عندما تتحدثين بهدوء، يهدأ طفلكِ أيضًا وتتباطأ ضربات قلبه. وبعد الأسبوع الرابع والعشرين خصوصًا، قد يجفل طفلكِ عند سماع ضوضاء قوية، وقد يبدأ أحيانًا بالفواق بعدها.;;;
خلال هذه الفترة، يساعد تشغيل موسيقى ذات نغمات عميقة وغير مرتفعة جدًا على تهدئة طفلكِ. يمكنكِ فعل ذلك بتشغيل الموسيقى بالطريقة المعتادة أو باستخدام سماعات خاصة مصممة لتناسب بطنكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'لديّ حاجبان ورموش! 👁️ ماما، أصبح وجهي الآن يشبه وجه الإنسان تمامًا. ظهر حاجبان رقيقان فوق عينيّ ورموش طويلة على جفنيّ. أنا الآن أكثر جمالًا. أستعد للرمش، لكن ما زالت تفصلني بضعة أسابيع عن فتح عينيّ. هل تتخيلينني؟ أنا أتخيلكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تواجهين بعض المشكلات الجلدية خلال الحمل. فعلى سبيل المثال، قد تؤدي زيادة دهنية البشرة إلى ظهور حب الشباب. إذا واجهتِ هذه الحالة، فنظّفي بشرتكِ بمنظف طبيعي مرتين يوميًا. واحرصي على أن تكون الكريمات التي تستخدمينها خالية من الزيوت. لا تستخدمي أدوية حب الشباب التي تؤخذ عن طريق الفم، فقد تتسبب هذه الأدوية في تشوهات خطيرة لدى الأطفال. وبعد استشارة طبيبكِ، يمكنكِ البدء بتناول مكملات أوميغا لدعم نمو طفلكِ. تُعد أحماض أوميغا من الدهون الأساسية التي يحتاج إليها جسمكِ. ولهذه الأحماض الدهنية أهمية حيوية، خصوصًا لنمو دماغ طفلكِ وعينيه. وتشير الدراسات إلى أن أحماض أوميغا تساعد على الوقاية من الولادة المبكرة وتسهم في ولادة أطفال بوزن أعلى.'), daily_tip_ar = COALESCE(daily_tip_ar, 'املئي ثلاجتكِ بالأطعمة الصحية. إن وجود فواكه وخضروات مغسولة أو زبادي أو جبن قريش في متناول يدكِ سيساعدكِ على تجنّب "الوجبات الخفيفة" غير الصحية.') WHERE id = '11b2d6de-75e4-4639-b4fc-0a1a64a49ebf';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ يتكوّن لدى طفلكِ نمط نوم خاص به، وإن لم يصبح منتظمًا تمامًا بعد. ومن الطبيعي أن تريه نائمًا كثيرًا خلال فحوصات الطبيب. فحركتكِ طوال اليوم تجعل السائل الأمنيوسي يتمايل كما لو كان يهدهد طفلكِ، ما يساعده على الهدوء والاستغراق في النوم.;;;
أما الوقت الذي يكون فيه طفلكِ أكثر نشاطًا فهو ساعات الليل، حين تخلدين إلى الراحة وينخفض ضغط دمكِ ويعم الهدوء. فبعد أن ينال صغيركِ قسطه من النوم طوال اليوم، يستمتع "باللعب" في سكون الليل. ويسهم تكوّن نمط للنوم خلال هذه الفترة في تهيئة أساس جيد لنموه داخل الرحم ولاكتساب عادات نوم صحية بعد الولادة.;;;
تشير الدراسات إلى أن العادات الضارة خلال الحمل، مثل تناول الكحول والمواد المخدرة وغيرها، تقلل جودة نوم الطفل بدرجة كبيرة. وفي هذه الحالات، يعاني الأطفال من مشكلة "النوم غير الفعّال"؛ إذ يستيقظون بمعدل يفوق الأطفال الطبيعيين بخمس مرات، كما تقل مدة نومهم الإجمالية كثيرًا.'), baby_message_ar = COALESCE(baby_message_ar, 'دمي يزداد احمرارًا! 🩸 بدأ نخاع عظامي الآن بإنتاج خلايا الدم. وهذا مهم جدًا لمناعتي المستقبلية ولنقل الأكسجين في جسمي. لقد تحددت فصيلة دمي بالفعل. هل هي مثل فصيلتكِ أم فصيلة أبي؟ ستعرفين ذلك عند ولادتي. أصبح أكثر استقلالًا يومًا بعد يوم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ تشعرين بخدر مستمر في معصميكِ وأصابعكِ، فقد تكون هذه الشكوى مرتبطة بمتلازمة النفق الرسغي. تنشأ متلازمة النفق الرسغي نتيجة انضغاط العصب المتوسط داخل القناة التي يمر عبرها في المعصم. وتظهر في مراحلها الأولى على هيئة خدر. ويؤدي التورم الشائع في المعصمين والقدمين خلال الحمل إلى الضغط على أعصاب المعصمين. وقد يسبب ذلك الخدر والوخز والألم في المعصمين والأصابع. وإذا كانت متلازمة انضغاط العصب هذه مرتبطة بالحمل فقط، فعادةً ما تزول تلقائيًا خلال فترة قصيرة بعد الولادة من دون الحاجة إلى علاج.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف حكة البطن، دلّكي بشرتكِ بالزيوت الطبيعية بعد الاستحمام وهي لا تزال رطبة. ولتقليل الضغط على ساقيكِ، ارفعيهما قليلًا عند الجلوس. وأكثري من الأطعمة الغنية بالمغنيسيوم، فهي تساعد على الوقاية من تشنجات الساقين.') WHERE id = '374d8324-b6d6-473c-83ac-7fb12f83f44c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذا الأسبوع، وبينما يستمر شعر الزغب الجنيني في تغطية جسم طفلكِ، تبدأ حلمتا الثدي بالتكوّن لديه بغض النظر عن جنسه. وتتمثل الوظيفة الأساسية للحلمتين في إتاحة الرضاعة الطبيعية. ومن المثير للاهتمام أنه لا توجد فتحة واحدة في الحلمة، بل ما يصل إلى 20 قناة صغيرة لإفراز الحليب. ويمكنكِ ملاحظة ذلك بصورة أوضح عندما يبدأ حليبكِ بالتدفق بعد الولادة.;;;
عندما يكون الطفل لا يزال في المرحلة الجنينية المبكرة، أي قبل أن تبدأ الأعضاء التناسلية بالتمايز، تكون الخلايا التي تكوّن الحلمتين قد تجمعت بالفعل. ولا تبدأ منطقة الأعضاء التناسلية باكتساب خصائصها المميزة قبل الأسبوع الثامن. وعندما ينشط جين SRY المسؤول عن تكوين الجهاز التناسلي الذكري لدى الأجنة الذكور، تكون الحلمتان قد تشكلتا بالفعل، ولذلك لا يستطيع هذا الجين إيقاف نموهما تمامًا. ولهذا السبب توجد الحلمتان لدى كلا الجنسين.'), baby_message_ar = COALESCE(baby_message_ar, '🥕 أنا بحجم جزرة كبيرة! أنام الآن وقتًا أطول وأركل بقوة أكبر. وقد يكون نمط نومي معاكسًا لنمطكِ. فعندما تنامين أستيقظ، لأن توقفكِ عن الحركة يجعلني أشعر كما لو أن "الأرجوحة" قد توقفت، فأستيقظ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الثلث الثاني من الحمل الذي دخلتِ فيه، قد تعانين من الوذمة من وقت إلى آخر. وتنجم الوذمة أساسًا عن اضطراب الدورة الدموية. فالرحم والحوض اللذان يتسعان استعدادًا للولادة يضغطان على الأوعية الدموية في ساقيكِ. ويؤدي هذا الضغط إلى إبطاء دورتكِ الدموية والتسبب في الوذمة. ومن الأسباب الأخرى للتورم العادات الغذائية. وقد تبيّن أن نسبة كبيرة من النساء اللواتي يعانين تورمًا شديدًا لا يحصلن على كمية كافية من البروتين. يمكنكِ الحصول على البروتين اللازم من اللحوم والأطعمة المشابهة، كما قد يكفي تناول ثلاث حصص على الأقل من الحليب أو منتجات الألبان يوميًا. ومن الجوانب الغذائية المهمة أيضًا تناول كمية مناسبة من الملح. يعتقد كثيرون أن الإفراط في تناول الملح يؤدي إلى احتباس الماء في الجسم، ومن ثم إلى التورم. ورغم صحة ذلك، فإن تناول كمية غير كافية من الملح قد يسبب الوذمة أيضًا. والمهم هو تناول كمية مناسبة من الملح واتباع نظام غذائي متوازن وصحي دائمًا. إذا كنتِ تعانين من الوذمة، فعليكِ الاستلقاء ورفع ساقيكِ والإكثار من السوائل والمشي لفترات قصيرة وارتداء ملابس فضفاضة لا تضغط على جسمكِ والانتباه إلى ما تتناولينه.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس بظهر مستقيم لتخفيف العبء عن أسفل ظهركِ، ولا تقفي لفترات طويلة. إن الاستراحة مساءً لمدة 15 دقيقة مع رفع ساقيكِ قليلًا فوق مستوى القلب تساعد على تقليل التورم وتمنحكِ شعورًا بالراحة. ولأن احتياجكِ إلى الكالسيوم قد ازداد، أدرجي في نظامكِ الغذائي أطعمة مثل جبن القريش أو الجبن أو اللوز. واختتمي يومكِ بالاستماع إلى موسيقى تحبينها.') WHERE id = '4291c964-97b5-4aa4-a48e-b3cb8e0fe5cb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يعني هذا الأسبوع أنكِ حامل منذ 4 أشهر و3 أسابيع، ولم يتبقَّ سوى أسبوع واحد على إكمالكِ الشهر الخامس! ;;;
من أكثر الأمور التي تثير فضولكِ خلال متابعة الحمل نمو طفلكِ ووزنه وطوله في الأسبوع الحالي. وللتقديرات الخاصة بالوزن والطول، التي تُجرى من خلال تقييم المؤشرات المحددة بفحص الموجات فوق الصوتية، أهمية طبية كبيرة؛ إذ تساعد هذه المؤشرات خصوصًا على تقييم زيادة وزن طفلكِ ونموه وتحديد طريقة الولادة.;;;
قد يتعرض الأطفال الذين يولدون بوزن منخفض أو بوزن كبير جدًا لبعض المضاعفات والمخاطر أثناء الولادة أو بعدها. ووفقًا لمنظمة الصحة العالمية، لا يُعد الأطفال الذين يبلغ وزنهم 4500 غرام أو أكثر مناسبين للولادة الطبيعية. أما في الممارسة الطبية في أذربيجان، فعلى الرغم من أن القرار قد يختلف حسب رأيكِ ورأي طبيبكِ، يُوصى عمومًا بالولادة القيصرية للأطفال الذين يبلغ وزنهم 4 كغ أو أكثر.'), baby_message_ar = COALESCE(baby_message_ar, 'أسمع أبي! 👨 لم أعد أسمع صوتكِ وحده، بل أصبحت أسمع أيضًا الأصوات الخارجية المنخفضة النبرة بصورة أفضل. إذا اقترب أبي من بطنكِ وتحدث، فسأتعرف إلى صوته. أخبريه أن يحكي لي قصة أو أن يقول لي ببساطة "مرحبًا". أنا أحبه أيضًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'تبدأ الأعراض التي تظهر في الأشهر الأولى، مثل الغثيان والإرهاق والصداع والتشنجات، بالاختفاء تدريجيًا، وتشعرين بنشاط وحيوية أكبر من الناحية الجسدية. وإضافة إلى ذلك، تُعد الثلث الثاني من الحمل مرحلة يبدأ فيها أيضًا التكيف النفسي مع الحمل.;;;
في هذه المرحلة من الحمل، قد تزداد الرغبة الجنسية بسبب زيادة الأوعية الدموية في الأعضاء التناسلية وتسارع تدفق الدم. كما أن وصول المرأة إلى النشوة الجنسية أثناء العلاقة لا يسبب أي ضرر للطفل. بل أظهرت بعض الدراسات أن تقلصات الرحم المصاحبة للنشوة قد تؤثر إيجابيًا في نبض قلب الطفل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا شعرتِ بتصلب خفيف أسفل بطنكِ، فاستلقي قليلًا واستريحي واشربي كمية وفيرة من الماء. واصلي تناول الحديد والمغنيسيوم للحفاظ على استقرار مستوى طاقتكِ.') WHERE id = 'f395dae9-427a-4c8d-8ba3-bfb8922cadf2';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من أن شعر طفلكِ قد بدأ بالنمو، فإنه لا يزال يبدو بلا لون لأن خصلاته لم تكتسب الصبغة بعد. يتكون الشعر أساسًا من بروتينات مختلفة، ويكتسب لونه الطبيعي من صبغة تُسمى الميلانين. توجد صبغة الميلانين في الشعر الفاتح والداكن على حد سواء، ويتناسب اختلاف درجة لون الشعر، سواء كان داكنًا أو فاتحًا، مع كمية صبغة الميلانين فيه. بعبارة أخرى، يبدو الشعر الذي يحتوي على كمية أكبر من الميلانين أغمق من الشعر الذي يحتوي على كمية أقل منها. وإضافة إلى ذلك، ينمو شعر الرأس بوتيرة أسرع من أنواع شعر الجسم الأخرى. ويتراوح متوسط سرعة نموه بين 0.3 mm و0.5 mm يوميًا. وعند الولادة، تكون سماكة خصلات الشعر متماثلة لدى الأطفال الذكور والإناث.'), baby_message_ar = COALESCE(baby_message_ar, 'أستطيع مواكبة الإيقاع! 🥁 عندما تستمعين إلى الموسيقى أو ترقصين، أشعر بذلك الإيقاع. وقد أتحرك أحيانًا بما يتوافق مع سرعة الموسيقى. الموسيقى الهادئة تجعلني أنام، أما السريعة فتوقظني. ذوقي الموسيقي آخذ في التشكّل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'تُلاحظ زيادة الشهية غالبًا خلال الثلث الثاني من الحمل، أي من بداية الشهر الثالث حتى نهاية الشهر السادس. ففي الأشهر الثلاثة الأولى، تؤدي الزيادة الكبيرة في الهرمونات إلى الحساسية تجاه الروائح والغثيان. ومع دخول الثلث الثاني، يعتاد الجسم هذا التوازن الهرموني ويقل الغثيان، فتزداد الشهية. ولهذا تُعد هذه المرحلة الفترة التي تحدث فيها أكبر زيادة في الوزن خلال الحمل. ومهما ازدادت شهيتكِ، احرصي في هذه المرحلة على اتباع نظام غذائي صحي وتجنبي الأطعمة الدهنية والمالحة والغنية جدًا بالسكر. كما يساعد تناول وجبات صغيرة ومتكررة على الحفاظ على توازن سكر الدم باستمرار، ما يمنع استهلاك كمية مفرطة من السعرات الحرارية دفعة واحدة. وستساعدكِ ممارسة التمارين والمشي أيضًا على التحكم في شهيتكِ خلال هذه المرحلة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا أصابكِ تشنج في ساقكِ ليلًا، فاسحبي أصابع قدمكِ فورًا نحوكِ (باتجاه ركبتكِ) وادفعي كعبكِ إلى الأمام. تساعد هذه الحركة على تمديد عضلة ربلة الساق وتخفيف الألم. كما يفيد تدليكها.') WHERE id = '68f0e92d-9dd8-4759-acc2-0054a8f6a53a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تُعد حركة طفلكِ من أهم العوامل التي تساعد على نمو عضلاته. وعندما يولد طفلكِ، يشكل وزن عضلاته نحو خُمس وزن جسمه. وعند بلوغه مرحلة المراهقة، سيشكل وزن العضلات ثلث وزن الجسم الإجمالي، ثم سيصل إلى خُمسي وزن الجسم في مرحلة البلوغ. ويحدث نمو العضلات عمومًا بالتوازي مع نمو الجسم. وعند الولادة، تكون عضلات العين والتنفس لدى الأطفال متطورة جيدًا، كما تكون عضلات الذراعين أكثر تطورًا من عضلات الساقين. وخلال الفترة السابقة للمراهقة، تعمل العضلات الكبيرة بكفاءة أفضل من العضلات الصغيرة. لذلك يكون الأطفال أكثر مهارة في أداء الحركات الواسعة والكبيرة مقارنة بالحركات الصغيرة والدقيقة.'), baby_message_ar = COALESCE(baby_message_ar, '🥥 أنا بحجم ثمرة جوز هند! أصبحت الآن طفلًا مصغرًا. لدي حاجبان ورموش وأظافر، وكل أعضائي موجودة. هدفي الأساسي الآن هو اكتساب الوزن وتجهيز رئتيّ. ما زلت نحيفًا جدًا، لكنكِ تغذينني جيدًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد زيادة حجم الدم أمرًا ضروريًا لصحتكِ وصحة طفلكِ، لكنها قد تؤدي إلى ظهور الدوالي في ساقيكِ. وفي السنوات الأولى، غالبًا ما تسبب الدوالي إزعاجًا من ناحية المظهر فقط، لكنها قد تؤدي إلى الألم لاحقًا. وتؤدي عوامل عديدة دورًا في ظهورها، فقد تنشأ الدوالي بسبب الحمل وزيادة الوزن والوقوف لفترات طويلة وتناول حبوب منع الحمل والعلاجات الهرمونية وارتداء الملابس الضيقة والإمساك والتقدم في السن والعوامل الوراثية. وللوقاية منها، من المفيد ممارسة الرياضة بانتظام، وتجنب الوقوف لفترات طويلة والجلوس مع وضع ساق فوق الأخرى، وعدم ارتداء الملابس شديدة الضيق، واختيار الأحذية المريحة بدلًا من الأحذية ذات الكعب العالي، والوقاية من الإمساك، وتناول أطعمة غنية بالألياف.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي ليلًا الاستلقاء على جانبكِ الأيسر بدلًا من الأيمن، فهذا يحسن تدفق الدم إلى الرحم ووظائف الكليتين. ولتقليل التورم الخفيف في ساقيكِ، اضبطي كمية الملح التي تتناولينها واشربي كمية وفيرة من الماء. وإذا شعرتِ بضيق في التنفس، فأبطئي حركاتكِ وخذي نفسًا عميقًا مع إبقاء صدركِ مرفوعًا.') WHERE id = '0192bd32-2239-497b-af81-dc9dc504732a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتزايد تدريجيًا عدد خلايا الدم الحمراء في جسم طفلكِ. وهذه الخلايا هي الجسيمات الأساسية التي تنقل الأكسجين وثاني أكسيد الكربون في الجسم. وهي تشكّل 99% من جميع خلايا الدم، وتتميّز بلونها الأحمر الزاهي.;;;
يتحكم هرمون الإريثروبويتين، الذي تفرزه الكليتان، في إنتاج هذه الخلايا. تبدأ العملية في نخاع العظم، ثم تدخل الخلايا التي تنضج خلال أسبوع تقريبًا إلى مجرى الدم. ولأن خلايا الدم الحمراء الناضجة لا تحتوي على نواة، فإنها تتمتع بمرونة كبيرة. وبفضل هذه المرونة تحديدًا، يمكنها المرور بسهولة حتى عبر أضيق الأوعية الدموية وإيصال الأكسجين إلى جميع أنحاء الجسم. لا يتجاوز عمر خلايا الدم الحمراء 3 أشهر. ومع مرور الوقت، تتحلل الخلايا القديمة والتالفة في الطحال والكبد ونخاع العظم من خلال عملية تُسمى البلعمة، ثم يتخلص الجسم منها.'), baby_message_ar = COALESCE(baby_message_ar, 'أميّز صوتكِ! 🗣️ ماما، أصبحتُ الآن قادرًا على التفريق بين صوتكِ وأصوات الآخرين. عندما تتحدثين أهدأ ويتباطأ نبض قلبي. إنه بالنسبة إليّ أكثر الأصوات أمانًا في العالم. واصلي الغناء لي، فأنا أخزّن الأغاني في "صندوق ذاكرتي". وعندما أولد، سأسمع تلك الأغنية وأهدأ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد لا تظهر أي بثور لدى بعض الحوامل خلال الحمل، بينما قد تزداد لدى أخريات. ويعود ذلك عادةً إلى الارتفاع الكبير في مستويات الهرمونات في الدم. فمع ازدياد الهرمونات، يزداد أيضًا إفراز الدهون في البشرة بصورة متناسبة، ويُعد تراكم الدهون على سطح البشرة أحد أبرز أسباب ظهور البثور. خلال الحمل، ينبغي لكِ تجنّب مستحضرات التجميل الثقيلة، وعدم استخدام أدوات وفرش المكياج التي لم تُعقّم جيدًا، والابتعاد عن الأطعمة غير الصحية، ولا سيما المقليات، والاهتمام بنظافة بشرتكِ أكثر من المعتاد، واستخدام مرطبات مائية القاعدة ومناسبة للحمل. وتذكّري أيضًا أن عصر البثور أو العبث بها قد ينشر الصديد الموجود داخلها على سطح البشرة، ما قد يؤدي إلى ظهور بثور جديدة. لذلك تجنّبي لمس وجهكِ أو العبث به كثيرًا، وتذكّري أن هذه مرحلة مؤقتة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'دلّكي ساقيكِ مساءً بـ"دش بارد". وجّهي الماء من الأسفل إلى الأعلى لتنشيط الدورة الدموية. وابتعدي عن الأطعمة المالحة، فالملح يؤدي إلى احتباس الماء في الجسم.') WHERE id = '47e98235-5632-4780-b011-1fba5afdb56a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يواصل الجهاز التناسلي لطفلكِ النضج والتطور. إذا كان طفلكِ ذكرًا، فستبدأ خصيتاه خلال هذه الأيام بإنتاج الحيوانات المنوية. تكون الخلايا الأم للحيوانات المنوية، الموجودة في الأنابيب داخل خصيتي طفلكِ الذي لا يزال في الرحم، ذات صيغة صبغية 2n. وهذا يعني أنها لم تكتسب بعدُ بنية الحيوان المنوي الناضج؛ إذ تتصرف كخلايا جسدية لا كخلايا تناسلية. ويعود ذلك إلى أن الخلايا التناسلية تحمل صيغة صبغية n، بينما تحمل الخلايا الجسدية صيغة صبغية 2n.;;;
قبل بلوغ الصبيان سن المراهقة، تتكاثر الخلايا المنوية عن طريق الانقسام المتساوي لأنها تحمل صيغة صبغية 2n. وعند دخول سن المراهقة، تبلغ هذه الخلايا درجة معينة من النضج وتكتسب بنية تتيح لها الخضوع للانقسام المنصف. وبذلك تحصل على الصيغة الصبغية n التي ينبغي أن تمتلكها.'), baby_message_ar = COALESCE(baby_message_ar, 'ألمس وجهي! 🤲 أستكشف وجهي بيديّ. ألمس أنفي وذقني وعينيّ. لا تزال بشرتي رقيقة جدًا، لكن حاسة اللمس لديّ قوية. تسهم هذه الحركات في تكوين خريطة جسدي داخل دماغي. لقد بدأتُ أتعرّف إلى نفسي. وعندما تلمسين بطنكِ أشعر بذلك أيضًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد يزداد تورّم ساقيكِ في نهاية اليوم. وينتج ذلك عن احتباس الماء في جسمكِ وزيادة حجم الدم وحرارة الطقس. وقد تشعرين أيضًا بأن خاتمكِ أصبح ضيقًا على إصبعكِ. وهذه حالة فسيولوجية طبيعية في هذه المرحلة من الحمل. كذلك قد تزعجكِ تشنجات الساقين ليلًا، وقد يرتبط ذلك ببطء الدورة الدموية أو نقص الكالسيوم/المغنيسيوم/البوتاسيوم. وقد تظهر أيضًا "متلازمة تململ الساقين".'), daily_tip_ar = COALESCE(daily_tip_ar, 'بدلًا من حكّ المناطق المصابة بالحكة بأظافركِ، ضعي عليها زيتًا أو كريمًا مرطبًا ودلّكيها بلطف براحة يدكِ. وقد يساعد وضع كمادات باردة أيضًا على تهدئة الحكة.') WHERE id = 'da8c9afd-1f7d-4478-b2fc-5b192ee0259f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع تسارع عملية التعظّم هذا الأسبوع، تواصل منطقة جمجمة طفلكِ التشكّل. تتصل الجمجمة بالعمود الفقري من جزئها السفلي والخلفي، بينما تسند عظام الوجه من الأمام. وعلى الرغم من أن جمجمة طفلكِ لم تتطور بعد بما يكفي في هذه المرحلة، فإنها ستبلغ بحلول سن الرشد نحو 18 سم من الأمام إلى الخلف، و13 سم ارتفاعًا، و14 سم قطرًا.'), baby_message_ar = COALESCE(baby_message_ar, 'قلبي يغني لحنًا! ❤️ أصبح بإمكان الطبيب سماع نبضات قلبي من دون أجهزة خاصة، وباستخدام السماعة الطبية فقط. ينبض قلبي 140-150 مرة في الدقيقة. هذا الصوت هو إيقاع الحياة بالنسبة إليكِ، أليس كذلك؟ بفضلكِ ينبض قلبي بهذه القوة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'نظرًا إلى نمو طفلكِ السريع وارتفاعه إلى مستوى سُرّتكِ، قد يبدأ جلدكِ في هذه المنطقة بالتمدد والتشقق. غالبًا ما تظهر علامات التمدد في أسفل البطن، وقد تظهر أيضًا على الفخذين والأرداف والثديين والذراعين، ويكون لونها ورديًا مائلًا إلى الأبيض. وقد تبدو شبيهة بجروح الجلد، إذ تظهر على شكل انخفاضات سطحية صغيرة على البشرة. إذا كانت بشرتكِ مرنة، فلا داعي للقلق، لأن البشرة المرنة أقل عرضة لظهور علامات التمدد. لذلك قد لا تحتاجين إلى استخدام أي منتج أو مستحضر وقائي. ويُعد استخدام الكريمات المرطبة المخصصة لعلامات التمدد أو المستحضرات الخارجية والطبيعية، مثل زيت اللوز وزيت نوى المشمش، من أنسب الطرق للتخفيف منها.'), daily_tip_ar = COALESCE(daily_tip_ar, 'دلّكي بطنكِ بلطف اليوم وتحدثي إلى طفلكِ؛ فهو يستطيع الآن أن يشعر جيدًا بضغط يدكِ ودفئها.') WHERE id = 'aa1f1ed4-15e9-4574-a163-232172e516be';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح من الممكن الآن الاستماع إلى نبضات قلب طفلكِ باستخدام السماعة الطبية! ويمكن للطبيب فحص نبضات قلبه بهذا الجهاز أثناء الزيارات الطبية. ومن السهل جدًا التمييز بين نبضات قلبكِ ونبضات قلب طفلكِ، إذ ينبض قلبه أسرع من قلبكِ بنحو ضعفين.;;;
يُعد الحبل السري (umbilical cord) أحد العناصر الأساسية في النمو السريع لطفلكِ. فهو ينقل إليه طوال فترة الحمل الغذاء والأكسجين الضروريين لحياته. ويبلغ متوسط طول الحبل السري 50-55 سنتيمترًا، وله شكل حلزوني.'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بتوتركِ. 😟 ماما، عندما تكونين متوترة، تصل إليّ أيضًا الهرمونات التي يفرزها جسمكِ (الكورتيزول)، فأشعر بالقلق وينبض قلبي بسرعة أكبر. ولكن عندما تكونين هادئة وسعيدة، أتغذى أنا أيضًا على "هرمونات السعادة". أرجوكِ لا تحزني. نحن معًا، وسيكون كل شيء على ما يرام.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تظهر البواسير خلال الحمل، أو قد تزداد الأعراض الناتجة عن البواسير الموجودة مسبقًا.;;;
تنتفخ الأوردة القريبة من سطح الجلد، ما قد يؤدي إلى ظهور الدوالي والبواسير. بالإضافة إلى ذلك، قد يتسبب ارتفاع مستوى هرمون البروجستيرون خلال هذه الفترة في ارتخاء العضلات الملساء المحيطة بالأوردة، فتنتفخ بسهولة. عادةً ما تكون بقع الدم التي تظهر أثناء التبرز أولى علامات البواسير. وإلى جانب النزيف، قد تشمل الأعراض الأخرى الشعور بالامتلاء في منطقة الشرج، ووجود تورم يمكن تحسسه أثناء التنظيف بعد استخدام المرحاض، وألمًا يبدأ مع التبرز ويستمر فترة طويلة. وتُعد الوقاية من الإمساك أهم وسيلة لتجنب البواسير. لذا احرصي على تناول الأطعمة الغنية بالألياف والسليلوز، وزيدي استهلاك الماء والخضراوات والفواكه لتسهيل التبرز من دون إجهاد. وإذا لم تُحل المشكلة بهذه الطرق، فيمكنكِ استخدام مُليّن مناسب للبراز يصفه طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا شعرتِ بتورم خفيف في ساقيكِ، فارفعيهما قليلًا واستريحي في نهاية اليوم. وارتدي أحذية مريحة ذات كعب منخفض لتخفيف آلام الظهر. ونظرًا إلى ازدياد حاجتكِ إلى الكالسيوم، أكثري من منتجات الألبان والخضراوات الخضراء في نظامكِ الغذائي. ما رأيكِ في أن تغني لطفلكِ تهويدة اليوم؟') WHERE id = '39505edc-cdd2-40ac-b9cb-aa04fd0c51af';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ بنكرياس طفلكِ الآن بإنتاج الإنسولين والغلوكاغون بانتظام. وتفرز خلايا بيتا الموجودة في جزر لانغرهانس داخل بنكرياس طفلكِ الإنسولين. وعندما تزيد كمية السكر في الدم على حاجة الجسم، يساعد الإنسولين على تخزينه في الكبد على هيئة غليكوجين، وبذلك يخفض مستوى سكر الدم.;;;
كما يساعد الإنسولين الغلوكوز الموجود في الدم، وكذلك الأحماض الأمينية والأحماض الدهنية الحرة عند الحاجة، على الدخول إلى الخلايا، ما يتيح لها الحصول على الطاقة اللازمة وقت حاجتها إليها. وعندما لا يُفرز الإنسولين بكمية كافية، يرتفع مستوى السكر في الدم ويُطرح عن طريق البول، ما يؤدي إلى الإصابة بداء السكري المعروف شعبيًا بمرض السكر. أما الغلوكاغون فتفرزه خلايا ألفا في البنكرياس، ويؤدي وظيفة معاكسة تمامًا لوظيفة الإنسولين؛ إذ يرفع مستوى سكر الدم من خلال تحرير الغليكوجين المخزّن في الكبد والعضلات إلى الدم عند الحاجة. ويُعد هذا التوازن ضروريًا لمنع نفاد طاقة الجسم خلال فترات الصيام الطويلة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا ذواقة أميّز النكهات! 😋 براعم التذوق على لساني تعمل بكامل طاقتها. عندما تأكلين الفلفل الحار، أصاب بالفُواق، وعندما تأكلين الشوكولاتة، أصبح أكثر نشاطًا. ويقول العلماء إن تناولكِ الآن أطعمة متنوعة يجعلني أقل انتقائية في الطعام عندما أكبر. هيا نتناول طعامًا صحيًا معًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ تعانين خلال هذه الفترة من تساقط الشعر، أو تكسر الأظافر، أو الضعف، أو فقدان الشهية، أو الصداع، أو الدوار، أو ضيق التنفس، أو خفقان القلب، أو سرعة التعب، أو العصبية، فعليكِ إجراء تحاليل للدم. عادةً ما يظهر فقر الدم خلال الحمل في الثلث الثاني، عندما يحصل طفلكِ على حاجته من الحديد من جسمكِ. فالحمل عملية تزيد خطر الإصابة بفقر الدم، ولا يهدد فقر الدم صحة الأم وحدها، بل قد يؤثر سلبًا أيضًا في الطفل. ولزيادة مدخول الحديد في نظامكِ الغذائي اليومي، تجنبي السوائل الغنية بالكافيين، مثل الشاي والقهوة والمشروبات الغازية المحتوية على الكولا، لأنها تعوق امتصاص الحديد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام ظهركِ، ضعي وسادة خلفكِ دائمًا عند الجلوس وحاولي الحفاظ على استقامة ظهركِ. وللتخفيف من حكة الجلد، استخدمي مرطبات طبيعية بعد الاستحمام. لا تنسي شرب الكثير من الماء، فهو ضروري لكِ ولتجدد السائل الأمنيوسي. واختتمي يومكِ بممارسة هواية تحبينها.') WHERE id = 'f309c326-d1e8-4059-8ac7-ab4a84a92059';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتجدد السائل الأمنيوسي المحيط بطفلكِ، والضروري لحياته، كل ثلاث ساعات في هذه المرحلة. لذلك فإن الحفاظ على ترطيب جسمكِ مهم للغاية لصحة طفلكِ. ويتكون هذا السائل من الماء بنسبة 99%، إلى جانب الأملاح غير العضوية والمواد العضوية ومواد صادرة من جسم طفلكِ.;;;
كما يتدرب طفلكِ يوميًا على التنفس من خلال سحب كمية من السائل تعادل ربع وزنه إلى رئتيه، دعمًا لنمو جهازه التنفسي. وينطبق الأمر نفسه على جهازه الهضمي. ولهذا السائل الحيوي وظائف عديدة، منها حماية طفلكِ من الصدمات المحتملة، والمساهمة في نمو جهازه التنفسي، وإتاحة الحركة الحرة له بما يدعم نمو هيكله العظمي وعضلاته، والحفاظ على توازن الشوارد في السائل، وتقوية جهازه المناعي، وتوفير بيئة مضادة للبكتيريا، وتنظيف قناة الولادة استعدادًا لقدومه عند تمزق كيس الماء وخروج السائل قبل الولادة.;;;
إذا كانت كمية السائل الأمنيوسي أقل من المستوى الطبيعي، فتُسمى الحالة قلة السائل الأمنيوسي، أما إذا كانت أكثر من المستوى الطبيعي فتُسمى موه السلى. وفي حال انخفاض كمية السائل الأمنيوسي أو زيادتها، يجب أن تخضعي لمتابعة طبية أكثر تكرارًا لدى طبيبكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'أتعلم عن طريق اللمس! 🖐️ ألمس بيديّ وجهي وساقيّ والحبل السري وجدار الرحم. ويساعدني ذلك على فهم حدود جسمي. إنني أكتشف نفسي. وأحيانًا أمص إبهامي، فهذا يهدئني. وعندما تلمسين بطنكِ، أشعر أنا أيضًا بذلك الدفء.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جزرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ تعانين تورمًا مفرطًا في وجهكِ أو حول عينيكِ أو في مفاصلكِ أو ساقيكِ، أو تكتسبين الوزن فجأة وبسرعة، أو تعانين صداعًا شديدًا ومستمرًا، أو اضطرابات في الرؤية مثل تشوش البصر، أو أعراضًا مثل ألم حاد في البطن والقيء، فقد تكونين مصابة بمقدمات الارتعاج. وتُعد مقدمات الارتعاج، المعروفة شعبيًا بتسمم الحمل، حالة خطيرة تصيب 5% من الحوامل. ويُشخَّص المرض بعد الأسبوع 20 من الحمل عند وجود عرض واحد آخر على الأقل إلى جانب ارتفاع ضغط الدم. وقد تشمل هذه العلامات وجود البروتين في البول أو اضطرابات في الكبد أو الكلى. وقد تظهر مقدمات الارتعاج أحيانًا من دون أي أعراض. كما قد يرتفع ضغط الدم تدريجيًا أو يبدأ بصورة مفاجئة. وتُعد مراقبة ضغط دمكِ جزءًا مهمًا من رعاية ما قبل الولادة، لأن أول علامة لمقدمات الارتعاج عادةً ما تكون ارتفاع ضغط الدم. ويكون احتمال الإصابة بتسمم الحمل أعلى لدى الحوامل دون سن 18 عامًا أو فوق سن 35 عامًا، وفي حالات الوزن الزائد جدًا أو النحافة الشديدة، ولدى الأزواج من الأقارب، والمريضات اللواتي خضعن سابقًا لعمليات جراحية كبرى، والنساء المصابات قبل الحمل بأمراض القلب أو السكري أو ارتفاع ضغط الدم أو الصرع أو اضطرابات الغدة الدرقية أو غيرها من الأمراض.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام الأسبوع 21 بنزهة قصيرة! وارتدي أحذية مريحة ذات كعب منخفض لتخفيف آلام الظهر. وعند النوم، احرصي على الاستلقاء على جانبكِ الأيسر وضعي وسادة تحت ساقيكِ، فهذا يساعد على تحسين الدورة الدموية. وواصلي شرب الكثير من الماء وإدراج الأطعمة الغنية بالألياف في نظامكِ الغذائي.') WHERE id = '925057a2-a250-49b9-bcfa-f9f914c5c38f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع اكتمال تطور حاسة السمع لدى طفلكِ، تتسارع عملية تكوين الروابط بين الخلايا العصبية في دماغه. ويتكوّن دماغ طفلكِ الآن، كما لدى البالغين، من خمسة أجزاء رئيسية، لكل منها وظيفة خاصة:;;;
الفص الجبهي: مسؤول عن التفكير الواعي والتحكم في المشاعر.;;;
الفص الجداري: يدمج المعلومات الواردة من أعضاء الحواس ويتيح الإدراك المكاني.;;;
الفص القذالي: هو المركز الذي تُعالَج فيه المعلومات المرتبطة بحاسة البصر.;;;
الفص الصدغي: يتيح إدراك الأصوات والروائح والتعرّف إلى الوجوه والأماكن.;;;
المخيخ: يحافظ على التوازن ويربط الحركات بالمعلومات الحسية.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بحجم ثمرة جريب فروت! يبلغ وزني نحو 370 غرامًا، وطولي 27.1 سم. لا تزال بشرتي مجعّدة لأنني أنمو بسرعة كبيرة، ولم تمتلئ بعدُ بطبقة الدهون. لكن لا تقلقي، فسأصبح ذلك الطفل اللطيف الممتلئ قبل ولادتي. مهمتي الأساسية الآن هي اكتساب الوزن!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'بسبب ارتفاع تركيز هرمون البروجسترون في الدم، يتأخر إفراغ المعدة وتتباطأ حركة الأمعاء. ونتيجة لذلك، قد تعانين من الإمساك.;;;
يُعد الجهاز الهضمي أيضًا من أكثر أجهزة الجسم تأثرًا خلال هذه الفترة. ومن هذه التغيرات زيادة إفراز حمض المعدة بسبب التغيرات الهرمونية، وتراجع الحركات التموجية للمريء، وارتخاء الصمامات المعدية مما يؤدي إلى الارتجاع، إضافةً إلى تباطؤ هضم الطعام، خصوصًا خلال الأشهر 3 الأخيرة من الحمل، نتيجة دفع الرحم المتنامي للمعدة إلى أعلى.;;;
ومع ازدياد حجم الجسم خلال هذه المرحلة، قد يزداد حجم الكليتين أيضًا. ويتباطأ تدفق البول في الكليتين اللتين يزداد وزنهما، كما تتوسع القنوات التي تنقل البول من الكلى إلى المثانة. لذلك، تُعد التهابات المسالك البولية شائعة جدًا أثناء الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أنها عطلة نهاية الأسبوع، خصّصي مزيدًا من الوقت لنفسكِ. حاولي الجلوس باستقامة وضعي وسادة إضافية خلف ظهركِ عند النوم لتجنب الشعور بضيق التنفس. تحكّمي في زيادة شهيتكِ بتناول المكسرات الصحية. سنبدأ أسبوعًا جديدًا غدًا، لذا أعدّي هذا المساء قائمة موسيقية هادئة لطفلكِ.') WHERE id = 'dcc1b63f-cc53-4d60-9050-ad76c211d2c4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'هذا الأسبوع هو الأسبوع الأول من الشهر الأخير في الثلث الثاني من الحمل. وبعبارة أبسط، لم يتبقَّ سوى شهر واحد على انتهاء الثلث الثاني.;;;
ابتداءً من هذا الأسبوع، تتسارع عملية تكوّن الطبقة الدهنية، وإن كانت أبطأ مقارنةً بالثلث الأخير من الحمل. لذلك تبدو بشرة طفلكِ أقل تجعدًا من ذي قبل. وكلما ازدادت أنسجته الدهنية بسرعة، تراجعت تجاعيد بشرته بالقدر نفسه. ويتراوح عدد الخلايا الدهنية، التي يمكن أن يزداد حجمها إلى 6 أضعاف، بين 40 مليارًا و100 مليار حتى بلوغ طفلكِ مرحلة المراهقة. وهذه الخلايا التي تبدأ منذ الآن بالتكوّن والتشكّل ضرورية للبقاء على قيد الحياة، وتؤدي دورًا داعمًا لنظام الطاقة في الجسم. كما تساعد الدهون الجسم على امتصاص الفيتامينات القابلة للذوبان في الدهون، وهي A وD وE وK. إضافةً إلى ذلك، تساعد الدهون على الاحتفاظ بالكالسيوم في الجسم.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتدرّب! 🏋️‍♂️ ماما، أصبحت حركاتي الآن أقوى. قد تلاحظين أحيانًا أن أحد جانبي بطنكِ ينتفخ أو يتحرك. إنني أدفع مرفقي أو ركبتي نحوكِ. هذه طريقتي لأقول لكِ: "أنا هنا!" وعندما تضعين يدكِ عليّ، أهدأ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'قد تلاحظين، خصوصًا في ساعات المساء، أن قدميكِ تبدوان أكبر من المعتاد. وعادةً ما تكون زيادة حجم القدمين أثناء الحمل مؤقتة. ومن أبرز أسبابها الوذمة الناتجة عن احتباس السوائل في الجسم. ففي الأشهر الأخيرة تحديدًا، يؤدي احتباس الماء في الجسم إلى تورم اليدين والقدمين، مما يجعل الأحذية التي كنتِ ترتدينها بسهولة من قبل تبدو ضيقة. ومن الأسباب الأخرى اكتساب وزن أكثر من اللازم أو اكتسابه بسرعة كبيرة خلال الحمل. وفي هذه الحالة، قد تشعرين بأن قدميكِ أكثر تورمًا بسبب تراكم الدهون فيهما. كما يُعد هرمون الريلاكسين سببًا آخر لزيادة حجم القدمين؛ إذ يساعد هذا الهرمون على تليين وإرخاء عظام الحوض والأنسجة الرابطة في الجسم، حتى يتمكن الطفل من المرور عبر قناة الولادة أثناء المخاض.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إنه وقت رائع لالتقاط صورة لبطنكِ! هذه الأسابيع مناسبة جدًا لإعداد صور مجمّعة بنمط "Before/After" (قبل/بعد)، لأن بطنكِ أصبح الآن مستديرًا ومتناسقًا.') WHERE id = 'a3ddbe51-ede9-4765-9b27-d3fb41ca5df3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت رئتا طفلكِ بإفراز مادة تُسمى السرفاكتانت. وبأبسط تعريف، السرفاكتانت مادة تقلل التوتر السطحي للسائل، ولذلك فهي ضرورية جدًا لتمكين الرئتين من أداء وظيفة التنفس.;;;
وبفضل بدء إنتاج السرفاكتانت في رئتي طفلكِ، أصبح أقرب بكثير إلى بلوغ مرحلة القابلية للحياة خارج الرحم. ويزداد إنتاج السرفاكتانت في الرئتين تدريجيًا، ليساعد على اكتمال نمو رئتي طفلكِ عند بلوغ الأسبوع 37.;;;
لا تحتوي رئتا الأطفال الخدّج الذين يولدون مبكرًا على كمية كافية من السرفاكتانت. وبسبب هذا النقص، لا تستطيع الرئتان أداء وظائف التنفس بصورة كاملة، وقد يحتاج الطفل إلى جهاز تنفس اصطناعي.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أستمع إلى العالم! 🌍 لم أعد أسمع صوتكِ وحده، بل أسمع أيضًا الأصوات المرتفعة في الخارج. إذا نبح كلب، أو أطلقت سيارة بوقها، أو عملت المكنسة الكهربائية، فأنا أسمع كل ذلك. وأحيانًا أخاف من هذه الأصوات وأنتفض. عندما تكونين هادئة، أكون هادئًا أيضًا. عالمنا مشترك.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'مع الاقتراب من منتصف أسابيع العشرينيات، قد تبدأ انقباضات كاذبة تُسمى انقباضات براكستون هيكس. تحدث هذه الانقباضات نتيجة شد عضلات الرحم، ويمكن أن تبدأ في أي وقت خلال الثلث الثاني من الحمل. وعلى خلاف انقباضات المخاض الحقيقية، قد تتفاوت في شدتها وتكرارها، وقد تظهر بوتيرة أكبر، خصوصًا في المساء وعندما تكونين متعبة. ومن السمات الأخرى التي تميز الانقباضات الكاذبة عن انقباضات المخاض الحقيقية أنها غير منتظمة، ولا يزداد تكرارها مع مرور الوقت، بل تضعف تدريجيًا وتزول عند تغيير وضعية جسمكِ، كما تشعرين بها غالبًا في الجزء الأمامي من بطنكِ. ولتخفيفها، عليكِ الراحة أو المشي، والحفاظ على ترطيب جسمكِ، وتدليك منطقة أسفل ظهركِ. وقد يساعد الاستحمام بماء دافئ أيضًا على تخفيف الانزعاج الناتج عنها. إذا شعرتِ بأن الانقباضات تحدث على فترات منتظمة، أو أن وتيرتها وشدتها تزدادان تدريجيًا، فقد تحتاجين إلى التوجه إلى أقرب منشأة صحية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كانت الانقباضات الكاذبة تزعجكِ، فاشربي كوبًا من الماء واستلقي على جانبكِ الأيسر للراحة. غالبًا ما يزيد الجفاف أو التعب من حدة هذه الانقباضات.') WHERE id = '97aa8d6c-1084-4919-a563-80230748cb6e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد وصلتِ إلى الشهر 6 من حملكِ. دخل طفلكِ مرحلة اكتساب الوزن السريع، وقد تطورت أعضاؤه بما يكفي للتكيف مع العالم الخارجي، وستنمو ساقاه الصغيرتان حتى يوم ولادته ليصبح حجمهما ضعف ما هو عليه الآن تقريبًا.;;;
يواصل طفلكِ تطوير حركاته الانعكاسية، وقد بدأ أيضًا في القيام ببعض الحركات الإرادية. يُعرَّف الفعل الانعكاسي بأنه استجابة جسدية لا إرادية تحدث نتيجة مؤثر خارجي. عندما يولد طفلكِ، سيأتي إلى العالم مزودًا بالعديد من الأفعال الانعكاسية. وفي المرحلة الأولى، سيقوم بهذه الأفعال دون إرادته ولن يتمكن من التحكم فيها.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أزداد وزنًا! ⚖️ لا تزال بشرتي مجعدة قليلًا، وكأنها أكبر من مقاسي. لكنني أكتسب الوزن بسرعة وأملأ تلك الفراغات. سأصبح قريبًا رضيعًا لطيفًا ممتلئًا. أنتِ تغذينني جيدًا، شكرًا لكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ثمرة جريب فروت كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تحدث تغيرات كثيرة في قلبكِ وجهازكِ الوعائي خلال الحمل. فمنذ الأسابيع الأولى من الحمل خصوصًا، يؤدي ارتفاع مستوى هرمون البروجسترون في الدم إلى انخفاض ضغط الدم، بسبب تقليله للمقاومة الوعائية الجهازية. وقد يكون انخفاض ضغط الدم سببًا في تشوش الرؤية والدوار والإغماء خلال الأسابيع الأولى. يزداد حجم الضربة القلبية، أي كمية الدم التي يضخها القلب إلى الدورة الدموية مع كل نبضة، بنحو 50%. كما ترتفع كمية الدم التي يضخها القلب في الدقيقة من 4,5 لترات إلى 6 لترات. أما معدل ضربات القلب، المعروف بالنبض، فقد يرتفع من 70 إلى 90 ضربة في الدقيقة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد فيتامين C على تقوية اللثة. تناولي أطعمة مثل الكيوي والفلفل الأحمر والبرتقال، وتوخي الحذر الشديد عند استخدام خيط الأسنان.') WHERE id = '5f95650f-570c-4da1-a06d-ada1c9adbe04';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'من المفترض أن تكوني قد شعرتِ بحركات طفلكِ بحلول هذا الأسبوع على أبعد تقدير. وقد تتغير حركاته مع تقدم الحمل؛ فالحركات الخفيفة التي بدأتِ تشعرين بها في البداية تصبح الآن أكثر وضوحًا.;;;
في هذه المرحلة، يميل طفلكِ غالبًا إلى الحركة استجابةً لما يحدث حوله. فقد تدفعه الضوضاء الشديدة أو الضوء القوي أو بعض الأطعمة المحفزة إلى الركل والحركة. لا يزال من المبكر خلال هذه الأسابيع توقع حركات منتظمة من طفلكِ. ومع ذلك، إذا لم تشعري بحركته مدة طويلة، فقد يساعدكِ تناول أطعمة ترفع مستوى سكر الدم والاستلقاء على جانبكِ الأيسر في مكان هادئ.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا بارع في حفظ التوازن! 🤸‍♂️ عضو التوازن في أذني يعمل بكامل طاقته. عندما تتحركين، أتأرجح أنا أيضًا في الداخل. إنها بالنسبة إليّ لعبة ملاهٍ حقيقية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ثمرة جريب فروت كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'ترتفع خلال الحمل احتمالية الإصابة بفقر الدم الناجم عن نقص الحديد. وقد ينخفض مستوى الهيموغلوبين أحيانًا من دون ظهور أي أعراض. تشمل الأعراض الشائعة شحوب البشرة، والوهن، والتعب، وضعف التركيز، والصداع، وتنميل اليدين والقدمين، والعصبية، وطنين الأذن، وتشقق الشفتين، وظهور تقرحات في زوايا الفم، وتساقط الشعر، وترقق الأظافر وسهولة تكسرها. ومع تفاقم نقص الحديد، قد تظهر حالات مثل خفقان القلب، والرغبة في تناول التراب أو الثلج، وتباطؤ وظائف الغدة الدرقية، ومتلازمة "تململ الساقين".;;;
للوقاية من فقر الدم، احرصي على تناول ما لا يقل عن 2-3 حصص من الأطعمة الغنية بالحديد يوميًا. ومن أبرز مصادر الحديد الأحشاء، مثل الكبد، واللحوم، والخضراوات الخضراء، والزبيب، ودبس السكر، والبندق، والفول السوداني، والبيض، والبقوليات المجففة. كما أن تناول عصير البرتقال أو عصير الطماطم أو السلطة مع مكملات الحديد أو الأطعمة الغنية به يعزز امتصاص الجسم للحديد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'مارسي تمارين كيجل لتخفيف آلام الحوض، فهي تساعد أيضًا على إعداد العضلات للولادة. وإذا شعرتِ بشد في بطنكِ، فخذي حمامًا فاترًا؛ إذ سيساعد ذلك على إرخائكِ وتهدئة طفلكِ.') WHERE id = '3837da99-9708-4d97-b55a-0f688693e446';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يدخل طفلكِ ابتداءً من هذا الأسبوع مرحلة طفرة في النمو. وهذا يعني أنه سيكتسب خلال هذا الأسبوع وحده نحو 150 غرامًا من الوزن. وبحلول نهاية الأسبوع، سيصبح طفلكِ أكثر نشاطًا من أي وقت مضى بفضل قوة عضلاته المتزايدة، واتساع الرحم، وزيادة كمية السائل الأمنيوسي المحيط به. إذا كنتِ تخططين لنوم طويل ليلًا، فقد لا تسير خططكِ كما تريدين. 😊 ينام طفلكِ في هذه المرحلة نحو 18 ساعة يوميًا، لكنه يكون أكثر نشاطًا ليلًا. ويعود ذلك إلى أن حركاتكِ خلال النهار تجعل السائل الأمنيوسي المحيط به يتماوج، ما يهدهده ويجعله أكثر ميلًا إلى النوم.'), baby_message_ar = COALESCE(baby_message_ar, 'عيناي تتحركان! 👀 مع أن جفنيّ لا يزالان مغلقين، فإن عينيّ تتحركان بسرعة من جانب إلى آخر تحتهما. وهذا يدل على أنني أحلم. لعلني أراكِ في منامي. أنا أعيش في عالم من الأحلام الملونة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'كوز ذرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين ابتداءً من هذه الأسابيع بضيق التنفس وبأن الهواء الذي تستنشقينه غير كافٍ. ويعود ذلك إلى نمو الرحم والتغيرات التي تطرأ على الجهاز الهرموني. فمع نمو طفلكِ خلال الحمل، يتمدد الرحم ويضغط على الحجاب الحاجز. إضافةً إلى ذلك، يرتفع الحجاب الحاجز بنحو 4 سم، خصوصًا في المراحل الأخيرة من الحمل. ويؤدي ذلك إلى ضغط الرئتين وتغير كمية الهواء المستنشق، ما يسبب ضيق التنفس.;;;
أما مركز التنفس في الدماغ، الذي ينشطه هرمون البروجسترون، فيجعلكِ تتنفسين بوتيرة أسرع وبعمق أكبر خلال الحمل، بهدف إيصال كمية أكبر من الأكسجين إلى المشيمة والتخلص من ثاني أكسيد الكربون بكفاءة أعلى. ويؤدي دخول وخروج كمية من الهواء تزيد بنسبة %30-40 عن المعتاد مع كل نفس إلى الشعور بصعوبة وضيق في التنفس.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف تورم قدميكِ، لا تبقي في الوضعية نفسها مدة طويلة، وارفعي قدميكِ عند الجلوس. ولتخفيف آلام الظهر، استلقي على جانبكِ الأيسر وضعي وسادة بين ركبتيكِ. واصلي شرب الكثير من الماء، لأنه يساعد على الوقاية من الوذمة والحفاظ على نقاء السائل الأمنيوسي. خصصي لنفسكِ بعض الوقت اليوم واستمعي إلى موسيقى هادئة.') WHERE id = 'fd7b3482-d799-4c13-953a-cf2d0bbea122';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ جسم طفلكِ بإنتاج الأجسام المضادة، وإن بكميات ضئيلة جدًا. وهذا يعني أن أسس جهازه المناعي بدأت تتكوّن، رغم أنه لم يكتمل بعد. والأجسام المضادة هي مواد مفيدة ينتجها الجسم استجابةً للبكتيريا والميكروبات الضارة والمواد الغريبة التي تدخل إليه. وهي تمثّل الوحدة البنيوية الأساسية للجهاز المناعي، كما تُعد جزءًا من آلية الدفاع الطبيعية للجسم.;;;
من الضروري جدًا إرضاع طفلكِ منذ لحظة ولادته بحليبكِ الأول، المعروف باللِّبَأ (الكولوستروم). يحتوي اللِّبَأ على أجسام مضادة لا يستطيع طفلكِ إنتاجها؛ وبعد الرضاعة تمتصها الأمعاء الدقيقة لتصل إلى دمه، فتُسهم في تطوير جهازه المناعي وتحميه من الكائنات الحية الدقيقة الضارة القادمة من الخارج.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أحلم؟ 💤 تُظهر موجات دماغي أنني في مرحلة "نوم حركة العين السريعة (REM)". خلال هذه المرحلة، تتحرك مقلتا عينيّ بسرعة رغم أن عينيّ مغمضتان. ويقول العلماء إن هذا يعني أنني أحلم. تُرى، ماذا أرى في حلمي؟ ربما أسمع صوتكِ، أو ربما أتذوق السائل الأمنيوسي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الجريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'التصوير التفصيلي بالموجات فوق الصوتية هو فحص يُجرى بين الأسبوعين 19 و23 من الحمل، حيث يكون نمو أعضاء الطفل قد اكتمل إلى حد كبير، كما تسمح زيادة كمية السائل الأمنيوسي بالحصول على صور أكثر تفصيلًا. يهدف هذا الفحص إلى متابعة نمو الطفل وتحديد ما إذا كانت هناك أي تشوهات. وقد يكشف عن بعض التشوهات أو الاضطرابات الكروموسومية باستخدام أجهزة الموجات فوق الصوتية المتطورة. وخلال هذا الفحص، تُفحص أعضاء الطفل كلٌّ على حدة وبالتفصيل، بما يشمل الجمجمة والدماغ، والعمود الفقري، ومحتويات القفص الصدري، وأعضاء البطن، والمعدة والأمعاء، والقلب، والذراعين والساقين، بالإضافة إلى المشيمة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استلقي لمدة 15 دقيقة مع رفع ساقيكِ وإسنادهما إلى الحائط. يساعد ذلك على عودة الدم ويخفف التورم. قللي الأطعمة المالحة، لكن لا تقللي كمية الماء التي تشربينها!') WHERE id = 'aebe9763-3910-4530-99d7-d5c87283c426';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع تطور بنية الأذن الداخلية لدى طفلكِ واكتسابه القدرة على السمع، أصبح الجزء المسؤول عن السمع في دماغه أكثر تطورًا مقارنةً بأجزاء الدماغ الأخرى.;;;
لقد أصبح جهازه الهيكلي وعضلاته قويين إلى درجة أن حركاته يمكن الشعور بها عبر جدار البطن، بل وقد تصبح مرئية أيضًا. ويزداد العمود الفقري للجنين قوةً، بينما تستمر الأوعية الدموية في التطور، ولا سيما في الرئتين.'), baby_message_ar = COALESCE(baby_message_ar, 'ركلاتي تزداد قوة! 🥋 ماما، هل تشعرين بها؟ لم أعد فقط "أسبح"، بل أصبحت أوجّه ركلات حقيقية. قد تظنين أحيانًا أنني أتدرّب على الكاراتيه. تدل هذه الحركات على أنني بصحة جيدة. ويمكنكِ البدء في عدّ حركاتي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الجريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'يساعد اختبار تحمّل الغلوكوز، الذي يُجرى بين الأسبوعين 24 و28 من الحمل، على تحديد وجود خطر الإصابة بالسكري من خلال قياس مستوى السكر في الدم. وحتى المرأة التي لم تكن مصابة بالسكري قبل الحمل ولم تظهر عليها أعراضه قد تُصاب به أثناء الحمل نتيجة اضطراب توازن الإنسولين. وتُعرف هذه الحالة بسكري الحمل، وقد تظهر لدى نحو 10% من الحوامل.;;;
بالإضافة إلى ذلك، قد يصبح ضبط مستوى السكر في الدم أثناء الحمل أكثر صعوبة لدى النساء المصابات بالسكري قبل الحمل. لذلك ينبغي للحوامل المصابات بالسكري الخضوع لفحوصات منتظمة، واتباع نظام غذائي مناسب، والالتزام بالعلاجات الملائمة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'وجبة خفيفة صحية: الجوز أو الزبيب أو المشمش المجفف أو وعاء من الزبادي. تمنحكِ هذه الأطعمة شعورًا بالشبع، كما توفر لطفلكِ الفيتامينات التي يحتاج إليها. ابتعدي عن الوجبات السريعة، فهي تؤدي إلى زيادة الوزن من دون قيمة غذائية تُذكر.') WHERE id = '846475dc-14c4-4c7d-ac51-e75ce4438f24';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تختلف الأنسجة الدهنية التي بدأت تتكوّن في جسم طفلكِ عن الدهون الموجودة في جسم الإنسان البالغ. ورغم أن هذه المعلومة غير معروفة على نطاق واسع، فإن هناك نوعين من الخلايا الدهنية: الدهون البيضاء والدهون البنية. والاختلاف الأساسي بينهما هو اللون. لا تحتوي الخلية الدهنية البيضاء إلا على قطرة واحدة كبيرة من الدهون، أي الليبيدات، وتمنح هذه الطبقة الدهنية الخلية لونها المميز. تساعد الدهون البيضاء على تخزين الطاقة وتوفير وسادة داعمة ولينة للأعضاء الداخلية. كما تنتج هذه الخلايا العديد من الهرمونات، مثل الإستروجين واللبتين، وتشارك في تنظيم عمل هرمونات أخرى مثل الإنسولين. أما الخلايا الدهنية التي ينتجها طفلكِ بصورة أساسية في هذه المرحلة فهي الخلايا الدهنية البنية. وبدلًا من احتوائها على كتلة دهنية كبيرة، تضم هذه الخلايا كميات صغيرة من قطرات الدهون الدقيقة وعددًا كبيرًا من الميتوكوندريا. ومن أسباب اختلافها أيضًا وجود عنصر الحديد في بنيتها، وهو ما يمنحها لونًا أغمق. وعلى عكس الخلايا الدهنية البيضاء، تنتج الخلايا الدهنية البنية الحرارة بصورة نشطة للحفاظ على دفء الجسم. وهذا مفيد جدًا للأطفال، ولا سيما أنهم لا يستطيعون القيام بحركات تساعدهم على تدفئة أنفسهم.'), baby_message_ar = COALESCE(baby_message_ar, 'أحافظ على توازني! ⚖️ أصبح "الجهاز الدهليزي" في أذني يعمل بصورة كاملة. ويمكنني الآن الإحساس بما إذا كان رأسي متجهًا إلى الأسفل أو إلى الأعلى. وعندما تتحركين، أوازن جسمي أيضًا. يمكننا أن نرقص معًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الجريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'منذ بداية حملكِ وحتى نهايته، يتغير التوازن الهرموني في جسمكِ بالكامل لتلبية احتياجاتكِ واحتياجات طفلكِ. وتشمل هذه الهرمونات hCG والإستروجين والبروجسترون والريلاكسين والأوكسيتوسين وLH.;;;
يؤدي هرمون الإستروجين دورًا مهمًا في تهيئة الجسم لحمل الطفل وإرضاعه، كما يساعد الجنين على الانغراس بصورة سليمة في بطانة الرحم. وقد يرتفع مستوى هذا الهرمون أثناء الحمل إلى ما يصل إلى 50 ضعف مستواه الطبيعي، فيساعد على نمو عضلات الرحم وقنوات الحليب في الثديين، وعلى وصول كمية كافية من الدم إلى الرحم. كما يؤدي الإستروجين إلى زيادة الخلايا الميلانينية المنتجة للصبغة التي تمنح الجلد لونه. ولهذا السبب قد يصبح لون الحلمتين والمهبل أغمق أثناء الحمل، وقد تظهر النمشات على الوجه أو حالة تُعرف باسم "قناع الحمل". وقد يصاحب تأثير الإستروجين، الذي يُعد أيضًا من الأسباب الرئيسية لارتفاع ضغط الدم، ازدياد الرغبة الجنسية.;;;
يُعد البروجسترون هرمونًا مهمًا آخر أثناء الحمل. وتتمثل مهمته الأساسية في تنظيم بطانة الرحم التي ينمو فيها طفلكِ، ويؤدي هذه المهمة بالتعاون مع هرمون الإستروجين. كما يساعد البروجسترون على إرخاء العضلات أثناء الحمل، ولا سيما عضلات الرحم، فيمنع انقباضها دون داعٍ ويحد من خطر انتهاء الحمل قبل أوانه.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عندما تشعرين بضيق التنفس، ضعي ذراعيكِ خلف رأسكِ وخذي نفسًا عميقًا؛ فهذا يزيد حجم القفص الصدري مؤقتًا. ولتشعري براحة أكبر أثناء النوم ليلًا، ضعي وسادة بين ركبتيكِ للمساعدة على تخفيف آلام الحوض. وإلى جانب شرب كمية وافرة من الماء، زيدي الأطعمة الغنية بالبوتاسيوم في نظامكِ الغذائي لتخفيف الشد العضلي.') WHERE id = 'b80a4824-be4e-45cc-b6d6-5d38c928227c';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يرجع السبب الأكبر لهذه الزيادة السريعة في وزن طفلكِ إلى نمو كتلته العضلية والعظمية، وتكوّن أنسجة دهنية جديدة، ونمو أعضائه. فعضلات الذراعين والساقين التي تتطور مع الحركة تساعده على القيام بحركات أقوى، وهذه الحركات بدورها تحفّز نمو العضلات أكثر، فتتشكل دورة متواصلة من التطور. كما تؤدي زيادة الأنسجة الدهنية لدى طفلكِ إلى امتلاء وجنتيه، وبذلك تبدأ ملامح وجهه في التشكّل والوضوح تدريجيًا. وخلال الفحص التفصيلي بالموجات فوق الصوتية، إذا كان طفلكِ في وضعية مناسبة، فقد تتمكنين حتى من معرفة من يشبه. 😊;;;
أصبحت حاسة السمع لدى طفلكِ شديدة الحساسية، حتى إنه يستطيع سماع الأصوات منخفضة التردد. ويمكنه تمييز صوتكِ بسهولة كبيرة من بين الأصوات الأخرى. وعندما يسمع صوتكِ تتسارع ضربات قلبه، ويشعر بالأمان، وقد يستجيب بحركة قوية ليؤكد لكِ أنه يسمعكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'وجهي أصبح جاهزًا! 👶 ماما، لو رأيتِني الآن لعرفتِ تمامًا كيف سأبدو عند ولادتي. ملامح وجهي وأنفي وشفتيّ، كل شيء قد اكتمل. لكنني ما زلت نحيفًا قليلًا. تُرى، من أشبه؟ أنتِ أم أبي؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'من المفترض أن تكوني قد اكتسبتِ حتى هذه المرحلة وزنًا يتراوح بين 5500 غرام و8500 غرام. إذا كنتِ تعتقدين أنكِ اكتسبتِ وزنًا أكبر من ذلك، فإن توخّي الحذر سيساعد على الوقاية من المشكلات التي قد تصيبكِ أو تصيب طفلكِ.;;;
قد تؤدي زيادة الوزن عن الحدود الطبيعية إلى حمل غير صحي، كما قد تهيئ للإصابة بحالات مثل ارتفاع ضغط الدم الحملي وسكري الحمل. إضافة إلى ذلك، قد يتحول هذا الوزن إلى كيلوغرامات زائدة دائمة يصعب فقدانها بعد الولادة.;;;
إذا كان وزنكِ متوسطًا عند بداية الحمل، ولم تكوني تعانين من زيادة مفرطة في الوزن أو من النحافة الشديدة، فلن تحتاجي خلال الثلث الأول من الحمل إلى تناول سعرات حرارية إضافية من أجل طفلكِ. أما في الثلث الثاني، فيكفي أن تضيفي 300 سعرة حرارية إلى استهلاككِ اليومي. وترتفع هذه الحاجة الإضافية خلال الثلث الأخير من الحمل إلى نحو 450 سعرة حرارية. ويعادل ذلك حصتين إلى ثلاث حصص إضافية من الفاكهة يوميًا، أو كوبين من الحليب قليل الدسم، أو وعاءً كبيرًا من الزبادي، أو 60 غرامًا من اللوز، أو 45 غرامًا من الزبدة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أريحي عينيكِ. إذا كنتِ تعملين طويلًا أمام الكمبيوتر، فخذي فترات راحة متكررة. وقد تساعد قطرات "الدموع الاصطناعية" ذات المكونات الطبيعية على تخفيف الجفاف.') WHERE id = '64f0cdbb-7db6-482f-be9f-92435bab2ca8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بلغت حاسة التذوق لدى طفلكِ مرحلة متقدمة للغاية من التطور. وتعمل حاسة التذوق من خلال المستقبلات الموجودة على اللسان. وتقع براعم التذوق، التي تُسمى مستقبلات، داخل تراكيب تُعرف بالحليمات. والحليمات هي نتوءات غير مستوية تغطي سطح اللسان.'), baby_message_ar = COALESCE(baby_message_ar, '🌽 أنا بحجم حبة ذرة! هذا الأسبوع مهم جدًا يا ماما. يقول الأطباء إنني أُعد الآن "قابلًا للحياة". وهذا يعني أنه حتى لو وُلدت الآن، فلدي فرصة للبقاء على قيد الحياة بمساعدة الطب الحديث (لكن الوقت ما زال مبكرًا جدًا، وأنا أريد البقاء هنا!). إنها مرحلة فارقة كبيرة!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'ربما بدأتِ تعانين من مشكلات في النوم بسبب نمو بطنكِ السريع، وكثرة التبول، وصعوبة التنفس. وإلى جانب ذلك، قد تجعلكِ الليالي المتتالية من قلة النوم تشعرين بإرهاق متزايد.;;;
تُعد الحاجة المتكررة إلى الذهاب إلى المرحاض في هذه الفترة أحد أهم أسباب الأرق. فارتفاع مستوى هرمون البروجستيرون ونمو الرحم يضغطان على المثانة، ما يؤدي إلى زيادة الحاجة إلى التبول. وقد تسبب أيضًا شكاوى أخرى مثل التورم، ومتلازمة تململ الساقين، وحرقة المعدة، ومشكلات الهضم صعوبة في النوم.;;;
قد يساعدكِ تناول وجبة العشاء مبكرًا، وتجنب الأطعمة الدهنية والحارة، والاستحمام بماء فاتر وشرب الحليب قبل النوم على النوم براحة أكبر. ولتقليل كثرة التبول، حاولي شرب معظم كمية الماء التي تحتاجين إليها خلال ساعات النهار، وتجنبي الإكثار من الماء في المساء.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد يجعلكِ ارتفاع درجة حرارة جسمكِ تشعرين بالعطش، لذا اجعلي شرب الماء عادة يومية. ولتخفيف آلام الأضلاع، ارفعي ذراعيكِ إلى أعلى وخذي نفسًا عميقًا، فهذا يساعد على توسيع هذه المنطقة. وإذا كنتِ تشعرين بثقل في ظهركِ، فاختاري النوم على فراش غير شديد الليونة. لا ترهقي نفسكِ كثيرًا اليوم؛ اقرئي قليلًا واستريحي.') WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد تتمكنين هذا الأسبوع من رؤية طفلكِ يبتسم أثناء فحص الطبيب. 😊 ويمكن اعتبار حركات تعابير الوجه لدى طفلكِ، مثل إخراج لسانه أو تقطيب وجهه أو الابتسام، من العلامات التي تدل على التطور الكبير لأنسجة دماغه داخل الرحم.;;;
في الأيام التي تتعرضين فيها لتوتر شديد، أو تمرين بأحداث صادمة، أو تشعرين بالتعاسة، قد تؤثر الهرمونات التي يفرزها جسمكِ في طفلكِ، فتجعله أقل حركة.;;;
وبالمثل، عندما تضحكين أو تشعرين بالسعادة والحماس، تصل الهرمونات التي يفرزها جسمكِ مباشرة إلى طفلكِ عبر الدم والمشيمة؛ وقد يؤدي ذلك إلى تسارع نبضات قلبه وزيادة حركته واستجابته لكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'رئتاي تستعدان! 🌬️ بدأت مادة خاصة تُسمى "السورفاكتانت" بالتكوّن في رئتيّ. ستساعدني هذه المادة على أن تنفتح رئتاي عند أخذ نَفَسي الأول وألا تلتصقا. ما زلت داخل الماء، لكن هذا أهم استعداد للمستقبل. التنفس هو الحرية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'ربما بدأتِ تلاحظين خروج سائل من ثدييكِ من وقت إلى آخر. يُعد ذلك طبيعيًا ولا داعي للقلق. فالهرمونات التي تهيئ الثديين لإنتاج الحليب بعد الولادة قد تتسبب خلال الحمل في إفراز السوائل وخروج الحليب من الثديين. ويُسمى هذا الحليب الذي يتسرب على شكل قطرات، ويختلف عن الحليب الناضج، باللبأ. ويحتوي اللبأ على كميات أكبر من البروتين والدهون والأجسام المضادة مقارنة بالحليب الناضج.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام الأسبوع 24 بتخصيص بعض الوقت لنفسكِ! اختاري أحذية طبية منخفضة الكعب للمساعدة على تخفيف آلام الظهر. وإذا لم تفعلي ذلك بعد، فاستشيري طبيبكِ بشأن اختبار تحمّل الغلوكوز. والاستلقاء على جانبكِ الأيسر والراحة ليلًا هو الأفضل للدورة الدموية لديكِ ولدى طفلكِ.') WHERE id = 'f9782520-1096-410b-87b6-a06b825d2aa4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يتطور الآن الجهاز الوعائي الذي يحيط بجسم طفلكِ كشبكة بأقصى سرعة. تخيّلي أن الطول الإجمالي للأوعية الدموية في جسم الإنسان يبلغ نحو 100 000 km، وهي مسافة مذهلة تكفي للدوران حول الأرض أكثر من مرتين! يتكوّن نظام النقل الرائع هذا من ثلاثة أنواع من "الطرق": الشرايين هي "الطرق السريعة" في الجسم. فهي تنقل من القلب إلى الجسم الدم النقي الغني بالأكسجين. ويخرج الشريان الأبهر، وهو أكبر الشرايين وأقواها، من القلب ليوزّع الدم على فروع أصغر. وتتميز الشرايين بأنها عضلية ومرنة في الوقت نفسه، لتتمكن من تحمّل الضغط الناتج عن كل نبضة قلب. أما الأوردة فهي "طرق التجميع" التي تعيد الدم المستنفد من الأكسجين إلى القلب. وللأوردة سر مثير للاهتمام؛ إذ توجد بداخلها صمامات صغيرة وحساسة. تمنع هذه الصمامات الدم من الارتداد بفعل الجاذبية، وتضمن تدفقه في اتجاه القلب فقط. أما الشعيرات الدموية فهي أوعية مجهرية أدق من الشعرة، وتصل بين الشرايين والأوردة. وهي رقيقة ومسامية إلى درجة تسمح للخلايا بالحصول على الغذاء والتخلص من الفضلات عبرها. توجد الشعيرات الدموية في جميع أنسجة أجسامنا، وهي المركز الحقيقي لعمليات الأيض.'), baby_message_ar = COALESCE(baby_message_ar, 'أظافري تطول! 💅 أوشكت أظافر يدي على بلوغ أطراف أصابعي. إنها رقيقة جدًا وحادة. وأحيانًا أخدش وجهي عن طريق الخطأ، لكن بشرتي تلتئم بسرعة. أشبهكِ أكثر فأكثر كل يوم يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جريب فروت'), body_changes_ar = COALESCE(body_changes_ar, 'يتغيّر مركز ثقل جسمكِ بسبب نمو طفلكِ بسرعة استثنائية وارتفاع الرحم الذي يوجد بداخله إلى أعلى.;;;
تُعد تشنجات الساقين من الآلام الشائعة جدًا، خصوصًا خلال الثلثين الثاني والثالث من الحمل. وقد تحدث هذه التشنجات عند تعرض الأوعية الدموية أو الأعصاب في الساقين للضغط. كما قد يؤدي عدم حصولكِ على احتياجكِ اليومي من المغنيسيوم عبر الغذاء إلى تشنجات الساقين.;;;
أما آلام الظهر فتظهر لدى نحو ثلثي النساء الحوامل. وتنشأ عادةً بسبب الضغط الذي تسببه منطقة البطن المتنامية على عضلات الظهر والتغيرات التي تطرأ على وضعية الجسم. وللمساعدة على تخفيف الألم، خذي حمامًا دافئًا، واستخدمي حزام دعم الظهر، واجلسي على كراسٍ ذات مسند داعم للظهر، وتجنبي الوقوف أو البقاء في وضعية ثابتة مدة طويلة جدًا، وضعي وسادة بين ساقيكِ عند الاستلقاء على الجانب الأيمن أو الأيسر، وتجنبي الحركات المفاجئة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ارتدي ملابسكِ على طبقات، كي تتمكني من خلع الطبقة الخارجية عندما تشعرين بالحر. اختاري ملابس مصنوعة من أقمشة طبيعية، مثل القطن والكتان، حتى تتمكن بشرتكِ من التنفس. واشربي الكثير من الماء لتنظيم درجة حرارة جسمكِ.') WHERE id = '2970a789-ae12-4a5d-81be-71d79963f650';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يأتي طفلكِ إلى العالم مزودًا بحركات انعكاسية لا إرادية يتحكم فيها الدماغ. وتشمل هذه الحركات منعكس مورو، ومنعكس القبض، ومنعكس الفزع، ومنعكس أخمص القدم، ومنعكس المشي، ومنعكسَي المص والبحث.;;;
عندما يشعر الطفل كأنه يسقط، يمد ذراعيه إلى الأمام ويفتح يديه ويباعد بين أصابعه قدر استطاعته. ثم يضم ذراعيه كأنه يعانق شيئًا. وإذا كانت ساقاه حرتين، فإنه يحركهما بالطريقة نفسها. يُسمى هذا منعكس مورو، ويختفي بعد مدة قصيرة من الولادة.;;;
يحدث منعكس الفزع عند تعرض الطفل لصوت مرتفع أو ضوضاء مفاجئة بالقرب منه. ونتيجة لذلك يتصلب جسمه، وتنثني كتفاه، وترتفع ذراعاه كأنه يحاول حماية نفسه من هجوم محتمل. وعلى عكس المنعكسات الأخرى، لا يختفي هذا المنعكس الهادف إلى الحماية، بل يستمر في التطور ويزداد قوة طوال الحياة.;;;
أما منعكس المص فيبدأ بعد الولادة عندما يلامس أي شيء الجزء العلوي من فم الطفل ويحفز هذه الحركة. ويساعد ذلك الطفل على الإمساك بحلمة الثدي بقوة كافية للرضاعة الطبيعية. ويتحول هذا المنعكس إلى حركات إرادية خلال 3-4 أشهر.;;;
قد تختفي بعض هذه المنعكسات بعد مدة. أما الحركات اللاإرادية التي لا تختفي، فتحل محلها حركات واعية وإرادية مع تطور الدماغ.'), baby_message_ar = COALESCE(baby_message_ar, 'لماذا يقفز بطنكِ؟ 🐇 ماما، هل شعرتِ بذلك؟ لقد أصبتُ بالفواق قبل قليل! يتدرب حجابي الحاجز، ولذلك يتحرك جسمي بإيقاع منتظم. قد يبدو لكِ هذا غريبًا، كأن ساعة تدق داخل بطنكِ. لا تقلقي، فهذا لا يؤلمني، بل يقوّي رئتَيّ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة جريب فروت كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يحتاج طفلكِ خلال هذه المرحلة إلى كمية كبيرة من الحديد، وقد يؤدي ذلك إلى نقص الحديد في جسمكِ. إذا كنتِ تعانين أعراضًا مثل الوهن والتعب والشحوب، فقد يطلب منكِ طبيبكِ إجراء فحوص للتحقق من مستوى الحديد لديكِ. ستحتاجين إلى حديد إضافي من أجل طفلكِ الذي ينمو والمشيمة. لا تبدأ معظم النساء الحمل بمخزون كافٍ من الحديد لتلبية هذه الاحتياجات. ويزداد الاحتياج بصورة ملحوظة، خصوصًا خلال الثلثين الثاني والثالث، وقد لا يكون من الممكن تلبيته عن طريق الغذاء وحده. إلى جانب استخدام مكمل الحديد الذي أوصى به طبيبكِ، سيساعد تناول السلطات المضاف إليها عصير الليمون مع أطباق اللحوم، وتناول أطباق الخضراوات مع سلطات غنية بفيتامين C، على زيادة امتصاص الحديد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام الأسبوع 23 بنجاح ودلّلي نفسكِ! ارتدي أحذية منخفضة الكعب لتخفيف آلام الظهر، ولا تبقي في الوضعية نفسها مدة طويلة. احرصي على الحصول على الكالسيوم وفيتامين D كي يستمر نمو عظام طفلكِ بصورة صحية. غدًا نبدأ أسبوعًا جديدًا، وهو الأسبوع 24!') WHERE id = 'c1de12f1-7759-492c-b277-e01fb2d857c9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تهانينا! لقد بلغ طفلكِ الآن عتبة قابلية الحياة. يُعد هذا الأسبوع مرحلة قد تتوفر فيها فرصة لبقاء الأطفال الذين يولدون مبكرًا على قيد الحياة، اعتمادًا على مدى ملاءمة إمكانات وحدة العناية المركزة لحديثي الولادة في المستشفى.;;;
أهم سبب لبلوغ طفلكِ عتبة قابلية الحياة اعتبارًا من هذا الأسبوع هو وصول نمو الرئتين إلى مرحلة مهمة. فقد أصبحت التفرعات التنفسية المتشكلة في الرئتين متصلة بالحويصلات الهوائية. كما بدأ إنتاج المادة الفاعلة بالسطح التي تغطي السطح الداخلي للحويصلات الهوائية. تقلل المادة الفاعلة بالسطح التوتر السطحي في الرئتين أثناء الشهيق والزفير، ما يمنع انخماص الحويصلات الهوائية. وعلى الرغم من أن إنتاج هذه المادة يبدأ هذا الأسبوع، فإن اكتماله في المسار الطبيعي يستغرق حتى الأسبوع 38. لذلك، عند وجود خطر الولادة المبكرة لدى الحوامل بين الأسبوعين 24-34، يحاول الأطباء تأخير الولادة بوسائل مختلفة لكسب الوقت، كما تُعطى أدوية تحتوي على الكورتيزون عن طريق الحقن لزيادة إنتاج المادة الفاعلة بالسطح، وبالتالي تسريع نمو الرئتين.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أستمع! 👂 ماما، صوت المكنسة الكهربائية في المنزل مرتفع جدًا، أليس كذلك؟ أصبحتُ الآن أفزع من الأصوات المرتفعة، لكن صوتكِ الهادئ يطمئنني. عندما تتحدثين إليّ، قد أتوقف عن الحركة كي أستمع إليكِ. لقد بدأت حواراتنا الأولى.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة جريب فروت كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'أصبح من الممكن الآن رؤية حركات طفلكِ من الخارج على سطح بطنكِ. وقد يزداد التصبغ في بشرتكِ قتامة. كذلك قد تبرز سرتكِ إلى الخارج وتبدو مثل "زر" بدلًا من أن تكون غائرة إلى الداخل. ويحدث ذلك بسبب ضغط الرحم. قد تكون درجة حرارة جسمكِ أعلى من المعتاد، وقد تتعرقين بسرعة شديدة. وربما تشعرين بـ"هبّات ساخنة". ويرتبط ذلك بتسارع الأيض وزيادة الدورة الدموية، ما يجعلكِ تبحثين عن الأماكن الباردة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خططي هذا الأسبوع مع طبيبكِ لإجراء اختبار تحمّل الغلوكوز (OGTT). لا تهملي استخدام الكريمات المرطبة لتخفيف حكة جلد البطن وعلامات التمدد. لا ترهقي نفسكِ كثيرًا اليوم، ومددي ساقيكِ واستريحي لمدة 10 دقائق كل 1 ساعة.') WHERE id = '372f913d-c4b6-4616-837e-127ec92b9515';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت الشعيرات الدموية لدى طفلكِ بالتكوّن. ولو كان بإمكانكِ رؤية طفلكِ، لتمكنتِ بسهولة من تمييز الأوعية الدموية المتكوّنة تحت جلده الرقيق. وتمتد هذه الأوعية لتصل إلى كل عضو ونسيج من الرأس حتى أطراف الأصابع.;;;
تتشكّل الشعيرات الدموية في جميع أنحاء الجسم على هيئة شبكة، ولو وُصلت أطرافها بعضها ببعض، لتجاوز طولها 40 كيلومترًا. ونظرًا إلى أن الشعيرات الدموية هي أكثر أنواع الأوعية الدموية اتساعًا من حيث المساحة السطحية الإجمالية، فإن سرعة تدفق الدم فيها هي الأبطأ أيضًا.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأ شعري يكتسب لونه! 🎨 حتى الآن كان شعري أبيض تمامًا، لكنه بدأ الآن يكتسب لونًا وفقًا لشيفرتي الجينية. أسود، أشقر، بني... تُرى، ما اللون الذي سيكون عليه؟ ربما سيكون مثل شعركِ، أو مثل شعر أبي. وهذه مفاجأة أخرى!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'تنتهي نحو 10% من حالات الحمل بولادة مبكرة. لذلك ينبغي أن تكوني قادرة على التمييز بين علامات المخاض الحقيقي وعلامات المخاض الكاذب.;;;
قد تشمل علامات بدء المخاض ألمًا ثابتًا أو متكررًا على فترات منتظمة، يبدأ عادةً في منطقة أسفل الظهر، وشعورًا بانقباضات متكررة ومنتظمة، وآلامًا شبيهة بالتقلصات في أسفل البطن، والإسهال والغثيان، والشعور بضغط في منطقة المهبل والمستقيم، وزيادة ملحوظة في كمية الإفرازات المهبلية، والنزيف.;;;
لا تحدث انقباضات المخاض الكاذب على فترات منتظمة، وغالبًا ما تزول عند تغيير وضعية الجسم أو الحركة. أما في المخاض الحقيقي، فلا يؤدي تغيير الوضعية أو الحركة إلى تخفيف الألم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للتخفيف من تنميل يديكِ، حرّكيهما وهزّيهما كثيرًا. حاولي ألّا تثني يديكِ أثناء النوم. وإذا كنتِ تعملين على الكمبيوتر، فخذي فترات راحة متكررة. ستزول هذه الأعراض بعد الولادة.') WHERE id = '5496d151-ca1f-41e0-a2f7-53fb1cdf1218';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح منعكس المصّ لدى طفلكِ قويًا جدًا في هذه المرحلة؛ إذ يفتح فمه عند لمس المنطقة المحيطة بفمه أو وجنتيه. ولكي يتمكن الرضيع من البقاء على قيد الحياة، يجب أن تكون لديه القدرة على تناول حليب الأم. لذلك يتغذى طفلكِ بفضل منعكس المصّ من دون أن يحتاج إلى أن يعلّمه أحد ذلك. وقد يستخدم طفلكِ منعكس المصّ ليس للتغذية فقط، بل ليشعر بالأمان أيضًا.;;;
يولد جميع الأطفال تقريبًا بمنعكس مصّ قوي. وقد يشير غياب هذا المنعكس لدى الرضيع إلى وجود أسباب خطيرة جدًا. وبما أن رضوض الولادة، ونقص الأكسجين الواصل إلى الدماغ، واضطرابات جذع الدماغ، ومشكلات الجهاز العصبي، والالتهابات الخطيرة مثل التهاب السحايا قد تؤدي إلى غياب منعكس المصّ، فمن الضروري متابعة هؤلاء الأطفال عن كثب.'), baby_message_ar = COALESCE(baby_message_ar, 'أقفز عندما أخاف! 😯 منعكساتي حادة جدًا. فعندما أسمع صوتًا مفاجئًا، ينتفض جسمي كله. يُسمّى هذا "منعكس الفزع". وقد تشعرين أيضًا بركلة مفاجئة في بطنكِ. عندما أخاف، ربّتي على بطنكِ بيدكِ وتحدثي إليّ بهدوء، وسأهدأ فورًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تُعالج عدوى المسالك البولية وتفاقمت، فقد تؤدي إلى الولادة المبكرة. ومن أبرز أعراضها الشعور بحرقة أثناء التبول أو الحاجة إلى التبول المتكرر. ومع ذلك، قد تتفاقم العدوى من دون ظهور أي أعراض، حسب موضع الإصابة. تُعالج عدوى المسالك البولية عادةً بالمضادات الحيوية، ويبدأ الالتهاب بالانحسار بعد وقت قصير من بدء العلاج. لكن حالات العدوى المتكررة قد تتطلب العلاج بجرعات أعلى من المضادات الحيوية.;;;
إذا كنتِ مصابة بعدوى في المسالك البولية، فإن شرب كمية وفيرة من الماء يساعد على طرد البكتيريا. لذلك يمكنكِ الحد من تكاثر البكتيريا وتفاقم العدوى من خلال تناول ما لا يقل عن 2 لتر من السوائل يوميًا. وقد يفيد أيضًا تناول أنواع مناسبة من شاي الأعشاب في تسريع التعافي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف الضغط عن ساقيكِ، غيّري وضعيتكِ كثيرًا خلال اليوم، واستريحي كلما أمكن مع رفع ساقيكِ فوق مستوى القلب. سيساعد ذلك أيضًا على الوقاية من التورم. وتساعد الأطعمة الغنية بالمغنيسيوم على تقليل التشنجات العضلية. هذا المساء، تحدثي إلى طفلكِ في أجواء هادئة عن أول نزهة ستقومان بها معًا في المستقبل.') WHERE id = '6533fb18-848f-4cc6-b4c7-bf0dc1cff401';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تجعل الشعيرات الدموية التي تتكوّن لدى طفلكِ جسمه يكتسب لونًا ورديًا، لأن جلده لم يصبح سميكًا بما يكفي بعد. كما ستبدأ فتحتا أنفه، اللتان ظلتا مغلقتين حتى الآن، بالانفتاح خلال هذه الأيام. والأنف ليس جزءًا أساسيًا من عملية التنفس فحسب، بل يضم أيضًا حاسة الشم، وهي إحدى الحواس الخمس. وتعمل حاسة الشم بالتكامل مع حاسة التذوق. ولهذا السبب قد لا نستطيع تذوق الطعام عند وجود عدوى في الجسم.'), baby_message_ar = COALESCE(baby_message_ar, 'لم يعد جلدي شفافًا! 🎨 ماما، في السابق كان من الممكن رؤية جميع أوعيتي الدموية عند النظر إليّ، لكن جلدي الآن يزداد سُمكًا ويكتسب لونًا. وكلما زادت طبقة الدهون لديّ، أصبح جلدي أقل شفافية. لم يعد مظهري يشبه ذلك "الكائن الفضائي"، وبدأت أبدو كطفل حقيقي لطيف. ستقعين في حبي عندما ترينني!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الذرة'), body_changes_ar = COALESCE(body_changes_ar, 'سيبدأ طول عنق الرحم بالتناقص تدريجيًا خلال نحو 1 شهر. وبينما يظل طول عنق الرحم ثابتًا خلال الحمل بين الأسبوعين 14 و28، فإنه يبدأ بعد الأسبوع 28 بالقِصر والترقق تدريجيًا.;;;
وفقًا لإحدى الدراسات، تبيّن أن نحو نصف النساء اللواتي بلغ طول عنق الرحم لديهن 25 mm أو أقل في الأسبوع 24 قد ولدن قبل الأسبوع 35.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام أسفل الظهر، لا تجلسي في الوضعية نفسها مدة طويلة؛ انهضي كل 30 دقيقة وتمشّي قليلًا. وللشعور براحة أكبر أثناء النوم ليلًا، استلقي بالكامل على جانبكِ الأيسر، فهذا يعزز وصول الأكسجين إليكِ وإلى طفلكِ. وإذا شعرتِ بألم حاد في ظهركِ، فاحرصي على استشارة طبيبكِ ومناقشة استخدام أحزمة الدعم الطبية.') WHERE id = '525f7e7c-0bea-4071-90df-5a46dae136d6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد تتسبب الأحبال الصوتية لطفلكِ، التي أصبحت قادرة على العمل، في إصابته بالفواق من حين إلى آخر خلال اليوم. وربما أصبحتِ قادرة على الشعور بذلك بالفعل. إذا كان طفلكِ يقوم بحركات إيقاعية على فترات منتظمة تشبه نبضات القلب، فهذا يعني أنه يعاني من الفواق. تظن كثير من الحوامل أن هذا الفواق يضر بالطفل، لكنه في الواقع مهم جدًا لنمو طفلكِ. قد تنتهي نوبة الفواق خلال بضع دقائق، وقد تستمر أحيانًا لمدة نصف ساعة. كذلك، مع استمرار نمو الأعضاء وتطورها، ينقبض الحجاب الحاجز من حين إلى آخر، مما يسبب الفواق. ويمكننا القول إن الفواق هو أحد أشكال تدريب الحجاب الحاجز. فمن خلاله يستعد الحجاب الحاجز لعملية التنفس خارج الرحم بعد ولادة الطفل.'), baby_message_ar = COALESCE(baby_message_ar, 'بدأت فتحتا أنفي تنفتحان! 👃 ظلتا مغلقتين حتى الآن، لكنهما تنفتحان اليوم. وأصبحت الآن قادرًا على "استنشاق" السائل الأمنيوسي عبر أنفي بسهولة أكبر. يساعدني ذلك على تدريب عضلات التنفس. وأحيانًا أصاب بالفواق عندما يدخل السائل إلى حلقي. هل تشعرين بتلك النبضات الصغيرة المتكررة؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'قد تزداد آلام أسفل ظهركِ حدة. فمع نمو بطنكِ نحو الأمام، تميلين بشكل تلقائي إلى إرجاع ظهركِ إلى الخلف للحفاظ على توازن مركز الثقل. وهذا يجهد عضلات العمود الفقري. كما أن الوقوف لفترة طويلة يزيد الألم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس باستقامة واسحبي كتفيكِ إلى الخلف لفتح صدركِ، مما يساعد على تخفيف ضيق التنفس. ولتلبية احتياجاتكِ من الكالسيوم، اختاري منتجات الألبان أو الخضراوات الورقية الخضراء خلال اليوم. وإذا كنتِ تعانين من حكة في بطنكِ، فرطّبي بشرتكِ بزيت اللوز الطبيعي أو زبدة الكاكاو. خذي بعض الوقت اليوم للاسترخاء وتخيّلي الأيام الجميلة القادمة برفقة طفلكِ.') WHERE id = '637acaae-ce43-494a-a7b1-a90cc43779c0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بفضل الأوعية الدموية التي تتكوّن في رئتي طفلكِ، تبدأ الدورة الدموية الرئوية في العمل. في البداية، يُنقل الدم المتجمع في البطين الأيمن، وهو دم منخفض الأكسجين وغني بثاني أكسيد الكربون، إلى الرئتين عبر الشريان الرئوي. وعندما يصل هذا الدم إلى الرئتين اليمنى واليسرى، يتخلص من ثاني أكسيد الكربون ويحصل على الأكسجين من خلال عملية تبادل الغازات. وتكتمل الدورة الدموية الرئوية بوصول الدم المؤكسج إلى الأذين الأيسر للقلب عبر الوريد الرئوي، ثم ضخه إلى الجسم عبر الشريان الأبهر.'), baby_message_ar = COALESCE(baby_message_ar, 'عمودي الفقري قوي جدًا! 🦴 أصبحت عظامي ومفاصلي وأربطتي قوية لدرجة أنني أستطيع الآن إبقاء جسدي منتصبًا تمامًا. أفرد ظهري وأتمدد. سيكون عمودي الفقري الدعامة الأساسية التي ستبقيني منتصبًا في المستقبل. واصلي الحصول على الكالسيوم، فما زلت بحاجة إلى الكثير منه!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بجفاف في عينيكِ أو تشوش في الرؤية. تقلل هرمونات الحمل إفراز الدموع. كما قد يؤدي احتباس السوائل في الجسم إلى تغير طفيف في شكل القرنية. وقد تتغير درجة نظارتكِ مؤقتًا، لذلك لا تتعجلي في شراء نظارة جديدة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد وضع وسادة بين ركبتيكِ أثناء النوم على تخفيف آلام أسفل الظهر بدرجة كبيرة، إذ يحافظ على استقامة العمود الفقري. كذلك، قد يكون النوم على مرتبة صلبة أكثر راحة خلال الحمل.') WHERE id = 'a0633b87-cd3d-42be-95e2-2574a37bda58';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بعد أن بلغ طفلكِ مرحلة القابلية للحياة، أصبح الحبل الشوكي المسؤول عن التحكم في جميع حركاته العصبية متطورًا بدرجة كبيرة، ولا يزال تكوّنه مستمرًا.;;;
يتكوّن الحبل الشوكي من مادة بيضاء في الخارج ومادة رمادية في الداخل. وتتكون المادة البيضاء التي تحيط بالحبل الشوكي من الخارج من أعصاب مغطاة بغمد الميالين، بينما تتكون المادة الرمادية من خلايا عصبية غير مغطاة بغمد الميالين. ومن أهم وظائف الحبل الشوكي التحكم في ردود الفعل القادمة من النخاع المستطيل، وضمان تنفيذ الحركات الإرادية الصادرة من الدماغ. يبلغ إجمالي عدد فقرات العمود الفقري 33 فقرة. ويوجد بين هذه الفقرات سائل يُسمى السائل الدماغي الشوكي، يساعد على حماية بنية العمود الفقري من الصدمات والإصابات.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبح حجمي بحجم حبة قرنبيط! يزداد وزني الآن بسرعة. تقل التجاعيد في بشرتي ويمتلئ خدّاي. لقد بدأت أبدو كطفل لطيف. كما أصبح لون شعري وملمسه محددين بالفعل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'لا تنسي إجراء تحاليل الدم والبول بانتظام. تساعد تحاليل الدم الشهرية المنتظمة على اكتشاف مشكلات مثل نقص الحديد المحتمل، وأمراض الغدة الدرقية التي لم تكن معروفة سابقًا وقد تنشط خلال الحمل، وحالات عدم توافق الدم غير المكتشفة، وعدوى داء المقوسات والحصبة الألمانية، والتهاب الكبد، والتهابات المسالك البولية غير المصحوبة بأعراض، مما يتيح الوقاية من مضاعفاتها.;;;
تؤثر أمراض الغدة الدرقية غير المكتشفة بشكل مباشر في عملية الأيض لديكِ، وبالتالي قد تؤثر سلبًا في نمو طفلكِ. خلال الأسابيع الـ12 الأولى من الحمل، لا تكون الغدة الدرقية لطفلكِ قد اكتمل نموها بعد، ولذلك لا تستطيع إنتاج الهرمونات، فينتقل إليه جزء من الهرمونات التي ينتجها جسمكِ. بعد الأسبوع 12، وخصوصًا خلال الثلث الثالث من الحمل، ترتفع مستويات TSH تدريجيًا بسبب بعض الهرمونات التي تفرزها المشيمة.;;;
أما التهابات المسالك البولية غير المصحوبة بأعراض خلال الحمل، فهي من الأسباب الشائعة للإجهاض المبكر. لذلك من الضروري إجراء تحليل بول كامل بانتظام.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام أسفل الظهر، لا تبقي في الوضعية نفسها لفترة طويلة، واختاري أحذية طبية مريحة. وإذا كنتِ تعانين من حكة أو شد في بطنكِ، فلا تنسي استخدام الزيوت المرطبة. وإلى جانب شرب الكثير من الماء، زيدي كمية الأطعمة الغنية بالألياف في نظامكِ الغذائي لتسهيل عملية الهضم. شجّعي نفسكِ اليوم على الحصول على قسط أكبر من الراحة مقارنة بالأيام الأخرى.') WHERE id = '3d485358-4a99-4889-8e24-ba3824e8665d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع نمو دماغ طفلكِ بسرعة، تتكوّن السحايا، وهي طبقات معقدة تحيط به من جميع الجهات وتحميه. تتألف هذه السحايا من ثلاث طبقات، وتعمل مع عظام الجمجمة كـ"درع" متين يحمي الدماغ من الصدمات الخارجية. ويمتد هذا النظام الوقائي إلى منطقة العمود الفقري، ليحمي جميع أجزاء الجهاز العصبي المركزي. يتطور في دماغ طفلكِ تركيبان أساسيان:;;;
المادة الرمادية: هي الجزء الذي تتركز فيه الخلايا العصبية، وتشارك السحايا في تكوينها.;;;
المادة البيضاء: هي ألياف عصبية طويلة مغطاة بغمد الميالين، وتضمن التواصل بين أجزاء الجهاز العصبي.;;;
أما الجزء الأكثر إثارة للاهتمام فهو القشرة الدماغية. فعلى الرغم من أن سُمكها لا يتجاوز 3 mm، فإن ثلاثة أرباع جميع الخلايا العصبية في الدماغ توجد فيها. ولكي يتسع هذا الحيز الصغير لهذا العدد الكبير من الخلايا، تتخذ القشرة الدماغية بنية شديدة التعرج، تتخللها أخاديد عميقة.'), baby_message_ar = COALESCE(baby_message_ar, 'تمتلئ شعيراتي الدموية! 🩸 تتكوّن تحت جلدي آلاف الأوعية الدموية الدقيقة وتمتلئ بالدم، وهذا ما يمنح بشرتي ذلك اللون الوردي الجميل. دورتي الدموية قوية جدًا، حتى إن قلبي يمدّ جسمي كله بالأكسجين. أنا مفعم بالحياة، ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'ينبغي أن تكوني أكثر حرصًا عند العناية ببشرتكِ خلال الحمل. فقد يزداد إفراز الزهم، وهو الزيت الطبيعي للبشرة، خلال الثلثين الأول والأخير من الحمل؛ لذلك قد تظهر قابلية للإصابة بحب الشباب حتى لدى النساء غير المعرّضات له عادةً. خلال هذه الفترة، نظّفي بشرتكِ باستخدام منظفات عضوية وآمنة وخالية من المواد الكيميائية. واحرصي كذلك على حماية بشرتكِ من الشمس وترطيبها بانتظام باستخدام مرطبات ذات مكونات مناسبة للحمل.;;;
بالإضافة إلى ذلك، وللوقاية من العدوى الفطرية، جففي جيدًا بعد الاستحمام داخل الأذنين وخلفهما، والرقبة، وتحت الإبطين، وبين الثديين وتحتهما، وتجويف السرة، ومنطقة الأربية، وبين أصابع القدمين. وامنحي الأفضلية للملابس الداخلية والجوارب المصنوعة من القطن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بمناسبة اجتيازكِ 25 أسبوعًا من الحمل بنجاح، اصنعي لنفسكِ اليوم أجواءً مريحة. ضعي وسادة تحت ساقيكِ عند مدهما للمساعدة على تقليل التورم. وإلى جانب شرب كمية وفيرة من الماء، قللي تناول الملح قليلًا. إذا لم تكوني قد فعلتِ ذلك بعد، فخططي مع طبيبكِ لإجراء اختبار تحمّل الغلوكوز. غدًا نبدأ أسبوعًا جديدًا، وهو الأسبوع 26!') WHERE id = '2ee2955f-80d8-4cff-afab-c01bdb172368';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بفضل انفتاح فتحتي أنف طفلكِ، أصبح يتدرّب دوريًا على الشهيق والزفير. وتساعد هذه الحركات التدريبية على تطور جهازه التنفسي. يتكوّن الجهاز التنفسي بالتسلسل من الأنف والبلعوم والحنجرة والقصبة الهوائية والرئتين. يسمح الأنف بدخول الهواء، وتحمي الشعيرات الموجودة على سطحه الداخلي والظهارة المخاطية التي تحافظ على رطوبته الجسم من العدوى. ينقل البلعوم الهواء المستنشق إلى القصبة الهوائية، بينما توجه القصبة الهوائية، التي تُسمى أيضًا "الرغامى"، الهواء إلى الرئتين. وأثناء مرور الهواء عبر القصبة الهوائية، يرطبه المخاط الذي تنتجه الظهارة المهدبة الموجودة داخلها، ما يساعد على حماية الرئتين من العدوى.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أستخدم يدي! 🖐️ ماما، لم تعد حركاتي عشوائية فقط. لقد بدأت أختار اليد التي سأستخدمها أكثر، أي إن كوني أعسر أو أيمن قد تحدد بالفعل. أحرّك أصابعي وأمسك بالحبل السري.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'بحلول هذا الأسبوع، يكون إجمالي حجم الدم في جسمكِ قد ازداد بنحو 25%. ولا بد من زيادة كمية الدم المتدفقة إلى الرحم لتلبية احتياجات طفلكِ المتزايدة من الدم. وفي الأسابيع الأخيرة من الحمل، قد يصل تدفق الدم إلى الرحم إلى 1 لتر في الدقيقة. ومن أسباب زيادة حجم الدم أيضًا الاستعداد لكمية الدم التي قد تفقدينها أثناء الولادة. ففي الولادة المهبلية، يتراوح فقدان الدم بين 500-750 ml، بينما قد يصل في الولادة القيصرية إلى 1000 ml. وعند أخذ الشقوق الجراحية أثناء الولادة والنزيف التالي لها في الاعتبار، يجب أن يكون الجسم مستعدًا لهذا الفقد الكبير في الدم.;;;
ومع ذلك، مهما ازداد حجم دمكِ، فإن نمو الرحم مع تقدم الأسابيع قد يقلل كمية الدم العائدة إلى القلب، خصوصًا عند الاستلقاء على الظهر. لذلك أصبح من المهم جدًا لصحتكِ وصحة طفلكِ أن تستلقي على جانبكِ الأيمن أو الأيسر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا لاحظتِ تورمًا مفاجئًا وشديدًا في جفنيكِ أو ساقيكِ، فأبلغي طبيبكِ بالتأكيد لفحص ضغط الدم. ولتقليل ضيق التنفس، حاولي الجلوس باستقامة ومارسي تمارين تنفس خفيفة. قللي كمية الملح في نظامكِ الغذائي، لكن حافظي على شرب كمية ثابتة من الماء. تحدثي اليوم إلى طفلكِ عن غرفته المستقبلية أو ألعابه.') WHERE id = 'd74fd8bf-8b0d-4ea8-8d39-905a3d36166e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل الحويصلات الهوائية الموجودة في رئتي طفلكِ نموها. والحويصلات الهوائية هي حجرات هوائية تشبه عناقيد العنب، تقع عند أطراف القصيبات الهوائية التي لا حصر لها داخل الرئتين. وفيها يحدث تبادل الغازات، أي انتقال الأكسجين إلى الدم والتخلص من ثاني أكسيد الكربون. كما أنها مغطاة بغشاء رقيق جدًا. ولا يتجاوز السُمك الإجمالي للحاجز الفاصل بين الهواء في الحويصلات الهوائية والدم في الشعيرات الدموية 4 micrometers. ويعادل هذا السُمك نصف قطر خلية دم حمراء واحدة. ويتيح هذا الحاجز بالغ الرقة تبادل الغازات بسرعة وكفاءة كبيرتين في كلا الاتجاهين. بالإضافة إلى ذلك، تتمدد الحويصلات الهوائية وتنكمش أثناء الشهيق والزفير. وهي مغطاة بمادة تُسمى السرفاكتانت، تساعد الأكياس الهوائية داخلها على التمدد والانكماش. وبفضل هذه المادة أيضًا، لا تنكمش الأكياس تمامًا عند الزفير، كما يُنظَّم التوتر السطحي داخل الرئتين.'), baby_message_ar = COALESCE(baby_message_ar, 'يمكنني شمّ رائحتكِ! 👃 تتغير رائحة السائل الأمنيوسي بحسب ما تتناولينه والبيئة المحيطة بكِ. وقد تطورت حاسة الشم لديّ إلى درجة أنني أستطيع ملاحظة هذه التغيرات. وعندما أُولد، سأتعرف إلى رائحتكِ من بين آلاف الأشخاص. فرائحة الأم أجمل عطر في العالم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ تعانين من ارتفاع ضغط الدم خلال الحمل، فيجب عليكِ إبلاغ طبيبكِ بذلك بالتأكيد.;;;
عند ارتفاع ضغط الدم، يتباطأ تدفق الدم إلى المشيمة، ما قد يحرم طفلكِ من الأكسجين والعناصر الغذائية التي يحتاج إليها. ونتيجة لذلك، قد يتباطأ نموه داخل الرحم. ومن أسباب ارتفاع ضغط الدم: الإصابة بارتفاع ضغط الدم قبل الحمل، وبلوغ سن 35 عامًا أو أكثر، وزيادة الوزن، والحمل المتعدد، واضطرابات الجهاز المناعي.;;;
إذا ترافق ارتفاع ضغط الدم مع ألم شديد، أو زيادة سريعة في الوزن، أو تورم اليدين والوجه، أو تشوش الرؤية، فعليكِ مراجعة طبيبكِ دون تأخير.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل الشعور بامتلاء المعدة، تناولي كميات صغيرة من الطعام 5-6 مرات بدلًا من الوجبات الكبيرة. ولتخفيف العبء عن أسفل ظهركِ، استخدمي وسائد تدعم ظهركِ أثناء الجلوس واجلسي باستقامة. وللوقاية من الإمساك، زيدي كمية الخضراوات والفواكه النيئة في نظامكِ الغذائي. هذا المساء، ارفعي ساقيكِ قليلًا واسترخي على أنغام موسيقى هادئة.') WHERE id = 'ed58011e-092e-41ea-a45c-df149cb7fc4b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد تطور الجهاز العصبي لطفلكِ وكل عضلة مرتبطة به إلى درجة تمكّنه من الاستجابة للمؤثرات الخارجية بوعي. ويعني مفهوم السلوك استجابة واعية للتأثيرات الداخلية والخارجية. أما العامل الأساسي الذي يميز السلوك عن الحركة البسيطة، فهو أن السلوك استجابة واعية لمؤثر ما.;;;
يستند السلوك الواعي بطبيعته إلى سبب، ويكون له حتمًا هدف محدد. وعلى عكس الحركة، يعكس السلوك الواعي إرادة من يقوم به ودوافعه الفردية.;;;
أما من الناحية الفسيولوجية، فهو تدفق للطاقة توجّهه عوامل داخلية وخارجية نحو الجسم. وبفضل جهازه العصبي المتطور، يستقبل الجسم هذا التدفق ويفسره، ثم يحاول استخدامه كتغذية راجعة للتكيف مع البيئة المحيطة والمؤثرات.;;;
العامل الأساسي الذي يقوم عليه السلوك هو التوافق بين المؤثرات والسلوك الناتج استجابةً لها. ويؤدي هذا التوافق إلى حالة من التوازن بين الكائن الحي والبيئة التي يوجد فيها.;;;
يمكن ملاحظة هذا التوازن عندما يبتسم طفلكِ حين تبتسمين، ويزم شفتيه عندما يتألم، ويرضع الحليب عندما يشعر بالجوع.'), baby_message_ar = COALESCE(baby_message_ar, 'فتحتُ عينيّ! 👀 ماما، اليوم يوم استثنائي بالنسبة إليّ. انفصل جفناي اللذان كانا ملتصقين حتى الآن، وفتحتُ عينيّ للمرة الأولى. لا يزال كل شيء ضبابيًا، لكنني أستطيع أن أرمش. رغم أن الظلام يحيط بي، فإنني أتعلم كيف أنظر. لقد اقتربتُ خطوة أخرى من رؤيتكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'قد تزداد انقباضات "براكستون هيكس" (الانقباضات الكاذبة) تكرارًا. لا تقلقي إذا أصبح بطنكِ قاسيًا كالحجر، فهذا بمثابة "تمرين" لعضلة الرحم. إذا زالت هذه الانقباضات عند تغيير وضعيتكِ أو شرب الماء، فهي انقباضات كاذبة. أما انقباضات المخاض الحقيقية، فتزداد شدةً تدريجيًا ولا تزول.;;;
قد تبدأ أيضًا آلام الأضلاع، فقد ارتفع الرحم إلى درجة أنه بدأ يوسّع القفص الصدري. وقد يلامس رأس طفلكِ أو قدماه أضلاعكِ. كما قد يصبح التنفس بعمق صعبًا أحيانًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تعرّفي إلى علامات مقدمات تسمم الحمل: تورم مفاجئ في الوجه واليدين، وصداع شديد، ورؤية "ومضات ضوئية" أمام العينين، أو ألم أسفل الأضلاع. إذا ظهرت أي من هذه العلامات، فراجعي الطبيب فورًا.') WHERE id = '664b492c-1968-495f-9380-1ec985579ba8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يؤدي ازدياد سرعة تكوّن الأنسجة الدهنية لدى طفلكِ إلى نمو الأنسجة تحت الجلد، ما يساعده على اكتساب الوزن بسرعة. كما تعمل هذه الدهون المتكوّنة، منذ لحظة ولادته، كحاجز يحميه من البرد.;;;
يتراوح وزن الأطفال الذين اكتمل نموهم داخل الرحم عند الولادة بين 2500 غرام و4000 غرام. ويعتمد هذا المؤشر على عوامل عديدة، أشهرها جنس الطفل. فهناك اختلافات وراثية بين الإناث والذكور؛ إذ تكون الخلايا الدهنية لدى الذكور أكثر منها لدى الإناث.;;;
قد توجد أسباب عديدة لانخفاض وزن الأطفال داخل الرحم عن المتوسط أو ارتفاعه عنه. ويرتبط انخفاض الوزن عن المتوسط لدى نسبة كبيرة منهم بعوامل وراثية. كما قد تؤدي بعض الأمراض خلال الحمل وسوء التغذية إلى هذه المشكلة. أما لدى الأطفال الذين يزيد وزنهم عن المتوسط، فإذا كانت هذه الزيادة تشمل أيضًا زيادة في السوائل، فيُشتبه أولًا في الإصابة بسكري الحمل. وإلى جانب ذلك، قد تؤدي الاختلافات الوراثية واختلافات الأيض إلى ارتفاع وزن الطفل عن المتوسط.'), baby_message_ar = COALESCE(baby_message_ar, 'رموشي تطول! 👁️ بما أنني فتحتُ عينيّ، فلا بد من حمايتهما. لديّ رموش طويلة وحريرية، وستُعجبكِ كثيرًا عندما تنظرين إلى عينيّ. كما أن حاجبيّ قد اكتملا وأصبحا في مكانهما. لقد بدأتُ أبدو كدمية صغيرة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'خلال هذه الفترة، تتغير الفلورا المهبلية بسبب اختلال توازن الهرمونات في جسمكِ. ولهذا يصبح جسمكِ أكثر عرضة للإصابة بعدوى الخميرة المهبلية أثناء الحمل. وإذا كان لديكِ خطر الإجهاض وتستخدمين تحاميل أو كريمات مهبلية لهذا السبب، فقد تصبحين أكثر عرضة للإصابة بها. تشمل أعراض عدوى الخميرة المهبلية الشعور بالحرقان والحكة في المنطقة التناسلية، وإفرازات بيضاء غزيرة، وكثرة التبول، والألم أثناء الجماع. ورغم أن الإفرازات قد تختلف من امرأة إلى أخرى، فإنها غالبًا ما تكون بيضاء مائلة إلى الكريمي، كثيفة كالكريمة، ومتكتلة مثل الجبن القريش أو فتات الجبن، ولها رائحة حامضة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بإتمام الأسبوع 26 بتدليل نفسكِ! احرصي عند الجلوس على استخدام وسادة تدعم ظهركِ لتخفيف آلام أسفل الظهر. وإذا لم تكوني قد فعلتِ ذلك بعد، فناقشي مع طبيبكِ التفاصيل الأخيرة المتعلقة باختبار تحمّل الغلوكوز. ويُعد الاستلقاء ليلًا على جانبكِ الأيسر أفضل وضعية للدورة الدموية لديكِ ولدى طفلكِ.') WHERE id = '3c253a83-3ac7-475e-8987-d27fab00a076';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل أجهزة طفلكِ التنفسية والهضمية والعصبية والمناعية نموها. والجهاز المناعي هو منظومة الدفاع التي تحمي الجسم من الآثار الضارة للكائنات الحية الدقيقة المسببة للعدوى، والتي تُعرف بالجراثيم، مثل الفيروسات والبكتيريا والفطريات والطفيليات.;;;
تعمل الخلايا والأنسجة والأعضاء التي تكوّن الجهاز المناعي معًا بتنسيق وانسجام وكفاءة عالية. وتُدرس وظيفة الجهاز المناعي ضمن قسمين رئيسيين: المناعة الفطرية والمناعة المكتسبة. المناعة الفطرية هي منظومة موجودة طبيعيًا في الجسم، تستقبل الجراثيم المسببة للعدوى عند دخولها إليه لأول مرة وتتعرّف إليها، ثم تعمل على تدميرها. أما المناعة المكتسبة، فتبدأ عملها بعد مواجهة الجسم لجرثومة ضارة وبعد فترة معينة من الاستعداد. وهي تنتج عناصر دفاعية ضد الكائن الضار وتتمتع بذاكرة مناعية. وتُعد الخلايا اللمفاوية T وB عناصرها الأساسية.'), baby_message_ar = COALESCE(baby_message_ar, 'ماما، الثلث الثالث من الحمل على الأبواب! أنتقل الآن إلى فئة "الوزن الثقيل". بدأت المساحة تضيق حولي، لذلك قد تصبح حركاتي أقوى. سامحيني إن اصطدمتُ بأضلاعكِ، فأنا أتمدد فحسب.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'بما أن مقدمات تسمم الحمل تكثر خلال هذه الأسابيع، فعليكِ توخي الحذر وقياس ضغط دمكِ. تظهر مقدمات تسمم الحمل بعد الأسبوع 20 من الحمل على هيئة ارتفاع ضغط الدم فوق 140/90 ملم زئبق ووجود البروتين في البول. وغالبًا ما تكون هذه الحالات مصحوبة بالوذمة.;;;
يمكن وصف آلية حدوث مقدمات تسمم الحمل بأنها اضطراب في الأوعية الدموية. وتكمن المشكلة في التضيق المفرط للشرايين الدقيقة والملتوية التي تغذي بطانة الرحم، ما يؤدي إلى عجز المشيمة عن تغذية طفلكِ بصورة كافية.;;;
قد تحدث مقدمات تسمم الحمل في نحو 5% إلى 7% من جميع حالات الحمل. وإذا لاحظتِ زيادة مفاجئة في الوزن، أو ظهور الوذمة والتورم، أو الضعف، أو تشوش الوعي، أو ألمًا في البطن، أو انخفاضًا في حركة طفلكِ، فعليكِ التوجه فورًا إلى أقرب منشأة طبية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد وضع وسادة بين ساقيكِ وتحت بطنكِ أثناء النوم على تخفيف آلام أسفل الظهر. كما أن النوم على الجانب الأيسر يزيد تدفق الدم إلى طفلكِ ويسهّل عمل كليتيكِ.') WHERE id = '1d4c4310-3e73-4b60-b4c5-883dd87bf1e3';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ قادرًا الآن على فتح عينيه داخل الرحم! فقد اكتسب الجفنان، اللذان ظلا مغلقين حتى هذه المرحلة، القدرة على الانفتاح. ويشكّل الجفنان نظام حماية مهمًا يحمي العين من العوامل الخارجية، ويمنع جفافها من خلال توزيع الدموع بالتساوي، وينظّم كمية الضوء الداخلة إليها.;;;
ومن الخصائص المثيرة للاهتمام للجفنين: أن الجفن العلوي أكثر قدرة على الحركة من الجفن السفلي بفضل عضلته الخاصة. وتعمل عضلات الجفنين العلوي والسفلي بصورة متعاكسة، مما يضمن إغلاق العينين تمامًا. كما يتحرك الجفنان بصورة إرادية وانعكاسية. ويساعد منعكس الرمش على توزيع الدموع على سطح العين، مما يحافظ على وظيفتها.'), baby_message_ar = COALESCE(baby_message_ar, 'تزداد طبقة الدهون لديّ! 🧈 بدأت التجاعيد في جسمي تختفي تدريجيًا لأن الدهون تملأ ما تحتها. أبدو الآن أكثر نعومة وطراوة. وستحافظ هذه الطبقة الدهنية على دفئي. عندما تضمينني إلى حضنكِ، لن أكون نحيلًا وعظميًا، بل "ممتلئًا ولطيفًا". وسأكبر أكثر بفضل حليبكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'يُفترض أنكِ أجريتِ اختبار تحميل الغلوكوز بحلول هذا الأسبوع. وإذا كانت نتائجكِ أعلى من الحدود الطبيعية، فقد يكون قد شُخّص لديكِ سكري الحمل.;;;
تزداد حاجة الجسم إلى الإنسولين خلال الحمل، لكن التغيرات الهرمونية قد تجعل الخلايا أقل حساسية له. وفي الوضع الطبيعي، عندما يرتفع مستوى سكر الدم، يستجيب البنكرياس بإفراز المزيد من الإنسولين. ولكن عندما يعجز البنكرياس عن إنتاج كمية كافية من الإنسولين لخفض مستوى سكر الدم، تحدث مشكلة تُسمى اختلال تحمّل الغلوكوز. وعندما تحدث هذه الحالة أثناء الحمل، تُسمى سكري الحمل.;;;
لدى النساء المصابات بسكري الحمل، تعبر الكمية الزائدة من الغلوكوز في الدم عبر المشيمة إلى الطفل، مما قد يؤدي إلى زيادة وزن الطفل بصورة مفرطة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تنسي شرب الكثير من الماء على مدار اليوم للمساعدة على تقليل الوذمة. وقد يفيد التدليك الخفيف أو الاستحمام بماء دافئ قبل النوم في تخفيف تشنجات الساقين. اقضي اليوم بعض الوقت مع طفلكِ وتحدثي إليه عن خططكِ المستقبلية؛ فهو يشعر فورًا بالحماس والحب في صوتكِ.') WHERE id = 'e581817d-cd7b-4e6d-a51b-e85acf339c0a';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل الآن تكوّن طبقات شبكية عين طفلكِ. وتُعد الشبكية أحد أهم أجزاء العين؛ فهي طبقة رقيقة تغطي الجزء الخلفي من مقلة العين. وسُمّيت بالشبكية بسبب البنية الشبيهة بالشبكة للأوعية الموجودة فيها. تغطي هذه الطبقة الجدار الداخلي للعين بالكامل، وتتكوّن من أوعية وأعصاب متصلة بالدماغ. وعلى الجانب المواجه للجزء الداخلي من مقلة العين، توجد ملايين الخلايا الحساسة للضوء والألوان. تستقبل هذه الخلايا الإشارات الضوئية القادمة من مقدمة العين، وتحولها إلى إشارات كهربائية يستطيع الدماغ تفسيرها، ثم تنقلها إلى العصب البصري. وينقل العصب البصري بدوره هذه الإشارات إلى الدماغ، مما يتيح له إدراك الصورة. ويمتد العصب البصري عبر نظام يشبه القناة إلى الجزء المسؤول عن حاسة البصر في الدماغ. وتُسمى النقطة التي يخرج منها العصب البصري القرص البصري أو الحليمة البصرية. ولأن القرص البصري الموجود في الشبكية لا يحتوي على خلايا حساسة للضوء، فإنه لا يستقبل الضوء؛ ولذلك تُعرف هذه المنطقة باسم "البقعة العمياء".'), baby_message_ar = COALESCE(baby_message_ar, 'أنا مستعد لفتح عينيّ! 👁️ إن خط الالتحام بين جفنيّ على وشك الانفصال. وسأفتح عينيّ قريبًا جدًا، ربما خلال بضعة أيام! أريد أن أنظر حتى وإن كنت في الظلام. ورموشي جاهزة لحماية عينيّ. لا أطيق الانتظار حتى أراكِ يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'ربما لاحظتِ أن شعركِ أصبح أكثر لمعانًا وكثافة. ومع ذلك، قد تلاحظين زيادة نمو الشعر على جسمكِ مقارنةً بما قبل الحمل. ويبدأ هذا النمو عادةً خلال الثلث الثاني من الحمل، ويرتبط بالتغيرات الهرمونية، وغالبًا ما يزول بعد الولادة بفترة قصيرة.;;;
إذا كان نمو شعر الجسم يزعجكِ أثناء الحمل، فيُفضّل استخدام شفرة الحلاقة أو جهاز إزالة الشعر أو الشمع. ولا تضر هذه الوسائل طفلكِ بأي شكل. لكن عليكِ مراعاة احتمال حدوث احمرار أو تهيج في البشرة، التي تصبح أكثر حساسية خلال الحمل، مما قد يؤدي إلى العدوى. كذلك ينبغي لكِ تجنّب استخدام كريمات إزالة الشعر أثناء الحمل؛ إذ قد تحتوي هذه الكريمات على مواد كيميائية قوية، مثل كبريتات الباريوم وثيوغليكولات الكالسيوم، يُحتمل أن تضر طفلكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أدرجي تمارين كيجل (شد عضلات قاع الحوض وإرخاؤها) ضمن روتينكِ اليومي. فتقوية هذه العضلات تساعد على الوقاية من سلس البول وتسهّل الولادة. كما أن استخدام الفوط اليومية سيمنحكِ شعورًا أكبر بالراحة.') WHERE id = 'ca71a802-8315-4430-831a-1c24d93987c8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح حاجبا طفلكِ ورموشه واضحين للغاية. ويعمل الحاجبان والرموش كحاجز طبيعي يحمي العينين من الأجسام الغريبة. وتتميز الرموش ببنية مختلفة عن سائر شعر الجسم؛ إذ لا توجد في بصيلاتها عضلات ناصبة للشعرة، كما أنها لا تتأثر ببعض الهرمونات، بخلاف أنواع كثيرة أخرى من الشعر. أما الحاجبان، فهما شعر مقوّس يقع فوق عظمي الحاجبين. وعلى الرغم من أن بصيلات شعر الحاجبين تشترك في بنيتها الأساسية مع بصيلات الشعر في بقية أجزاء الجسم، فإن مراحل نموها سريعة للغاية مقارنةً بغيرها من البصيلات.;;;
يؤدي الحاجبان وظيفة حماية العينين من العرق وتوفير الظل لهما. كما أن لهما أهمية كبيرة في تعابير الوجه؛ فإلى جانب الرموش وعظمتي الوجنتين وخط الشعر والأنف، يحيطان بالعينين ويسهمان من الناحية الجمالية في مظهر وجه الإنسان.;;;
وإلى جانب احتواء هذه التراكيب على كمية قليلة من الماء، فهي غنية بالكربوهيدرات واليوريا وحمض اليوريك والأحماض الأمينية الحرة والفوسفوليبيدات والكوليسترول والأحماض الدهنية والكيراتين، وهو أهم مكوّن بنيوي فيها. وبعبارة أخرى، تتكوّن هذه التراكيب من الكيراتين الذي يتألف من 18 حمضًا أمينيًا، وتصنعه الخلايا الكيراتينية الموجودة في الطبقات السفلية من الجلد.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أشارككِ توتركِ. 😔 ماما، عندما تكونين متوترة، يصل إليّ أيضًا الكورتيزول الموجود في دمكِ. فأشعر بالقلق وتتغير حركاتي. لكن عندما تضحكين وتشعرين بالسعادة، أشعر أنا أيضًا بالراحة. أرجوكِ اعتني بنفسكِ. نحن فريق واحد، ومشاعركِ هي مشاعري.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'قد لا يتطابق عمر حمل طفلكِ المحسوب وفقًا لفحص الموجات فوق الصوتية أثناء زيارة الطبيبة أو الطبيب تمامًا مع عمر الحمل المحسوب بناءً على تاريخ آخر دورة شهرية لديكِ. ولا داعي للقلق في مثل هذه الحالات.;;;
إذا أظهرت متابعة الموجات فوق الصوتية تحت إشراف الطبيبة أو الطبيب أن نمو الطفل أقل من المستوى المتوقع، فقد يُشتبه في وجود تقييد لنمو الجنين. ويكون عدد كبير من الأطفال الذين يعانون من ذلك صغار الحجم بسبب الجينات الموروثة من الوالدين. فلا يُتوقع أن يكون الطفل كبير الحجم داخل الرحم إذا كان الأب والأم صغيري البنية وراثيًا. وتُعد فروق النمو الواقعة ضمن نطاق أسبوعين زيادةً أو نقصانًا طبيعية، ولا تثير الشك في وجود أسباب أخرى غير العوامل الوراثية. أما إذا تجاوز الفرق 2 أسبوعين، فقد يلزم إجراء فحص تفصيلي بالموجات فوق الصوتية، واستشارة اختصاصيي الحمل عالي الخطورة، وفحص تدفق الدم إلى الطفل. ومن المعروف أن 75% من حالات تأخر النمو لدى الأطفال تكون بنيوية. كما قد تؤدي عوامل أخرى إلى تأخر النمو، مثل انخفاض تدفق الدم إلى الطفل، وشيخوخة المشيمة، ونقص السائل الأمنيوسي.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل حرقة المعدة، لا تستلقي مباشرةً بعد تناول الطعام، وارفعي رأسكِ قليلًا بوسادة عند النوم. ولتخفيف آلام الظهر، مارسي بانتظام تمارين تمدد خفيفة. أنتِ تحملين الآن معجزة تزن 1 kq، لذا تجنّبي تمامًا رفع الأوزان الثقيلة. تحدثي إلى طفلكِ هذا المساء وأنتِ تربتين على بطنكِ؛ فهو يشعر بلمستكِ!') WHERE id = '7b482622-6ce3-4e23-a975-62440aec9dc6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مرحبًا بكِ في الأسبوع الأخير من الثلث الثاني! كم يمر الوقت سريعًا، أليس كذلك؟ لم يعد طول طفلكِ يُقاس من الرأس إلى العصعص، بل يُحدَّد بضرب طول عظم الفخذ في 7.;;;
مع اقتراب دخولكِ الثلث الثالث، قد تلاحظ الطبيبة أو الطبيب أثناء الفحص أن طفلكِ اتخذ وضعية الولادة الرأسية، أي إن رأسه متجه إلى الأسفل. وهذا أمر طبيعي تمامًا. فما زالت لدى طفلكِ مساحة للحركة أكبر مما ستكون عليه في الأسابيع الأخيرة، ولذلك يمكنه تغيير وضعيته بسهولة. كما أن وجود عدد كبير من براعم التذوق في فم طفلكِ يسمح بوصول نكهات الأطعمة التي تتناولينها إليه عبر السائل الأمنيوسي، ما يساعده على التمييز بين النكهات.;;;
في هذه المرحلة، يحتوي سطح لسان طفلكِ على عدد من براعم التذوق يفوق ما لدى الإنسان البالغ. وبفضل ذلك، لا يكتفي طفلكِ بالتمييز بين النكهات، بل يستطيع التفاعل معها أيضًا. وقد يستجيب لبعض الأطعمة كثيرة التوابل أو شديدة الحرّ بموجة من الفواق.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أحلم! 💤 درس العلماء دماغي واكتشفوا أنني في مرحلة "نوم حركة العين السريعة (REM)". أي إنني أعيش أحلامًا رغم أن عينيّ مغمضتان. تُرى، ماذا أرى في أحلامي؟ صوتكِ؟ أم تلك الشوكولاتة اللذيذة التي أكلتِها؟ أنا حالم، مثلكِ تمامًا.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'بدءًا من الأسبوع 28 من الحمل، تنتقل نسبة كبيرة من مخزونات جسمكِ إلى طفلكِ. ولذلك، من المهم للغاية تناول أطعمة غنية بالكالسيوم والمغنيسيوم وفيتامينات A وD وE وK، لضمان استمرار العمليات الحيوية في جسمكِ بصورة طبيعية.;;;
إذا لم تحصلي على كمية كافية من الكالسيوم أثناء الحمل، فسيأخذ طفلكِ الكالسيوم اللازم لنموه من عظامكِ. وقد يؤدي ذلك إلى نقص الكالسيوم ويهيئ للإصابة مستقبلًا بترقق العظام، المعروف بهشاشة العظام. يُعد الحليب واللبن والجبن من أغنى الأطعمة بالكالسيوم. كما يحتوي المشمش المجفف والجوز والبندق واللوز والسلمون المرقط والخضروات الورقية الداكنة والبقول المجففة على كميات مهمة من الكالسيوم. يحتوي كوب واحد من الحليب تتناولينه يوميًا على 250 mq من الكالسيوم. وتحتوي شريحة من الجبن الأبيض، حسب نوعه، على 100 mq، وحفنة من المكسرات النيئة على 50 mq، وحفنة من الزبيب على 30 mq من الكالسيوم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف آلام الظهر، ارتدي أحذية مريحة ذات كعب منخفض، واحرصي على إسناد ظهركِ جيدًا عند الجلوس. وللتخفيف من جفاف الأنف، حافظي على مستوى مناسب من الرطوبة في الغرفة. تحدّثي اليوم أكثر مع طفلكِ أو اقرئي له قصة؛ فسيتذكر مستقبلًا نغمة صوتكِ. ولا تنسي شرب الكثير من الماء وإدراج الأطعمة الغنية بالألياف في نظامكِ الغذائي.') WHERE id = '1533383b-1c83-483c-ad7a-9958fe297dd1';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يرجع اكتساب طفلكِ السريع للوزن إلى تكوّن الخلايا الدهنية البنية بوتيرة استثنائية. ولا تقتصر وظيفة هذه الخلايا على تخزين بعض جزيئات الكوليسترول في الجسم، بل إنها تنتج الحرارة أيضًا بفضل احتوائها على أعداد كبيرة من الميتوكوندريا. وبما أن الخلايا الدهنية البنية ستساعد على الحفاظ على درجة حرارة جسم طفلكِ، يبدأ شعر الزغب الذي كان يدفئه حتى هذه المرحلة بالتساقط تدريجيًا. وتختلف مرحلة تساقط شعر الزغب من طفل إلى آخر، بحسب نموه ونشاطه الأيضي. يختلط شعر الزغب المتساقط بالسائل الأمنيوسي المحيط بطفلكِ، ثم يبتلع طفلكِ هذا السائل. ويستمر شعر الزغب الموجود في السائل الأمنيوسي المبتلع بالتجمع في أمعاء طفلكِ، ليصبح جزءًا من العقي المعروف باسم "البراز الأول". كذلك، ومع الزيادة السريعة في عدد الخلايا الدهنية البنية في جسمه، تنمو الطبقة الموجودة تحت جلد طفلكِ وتمتلئ بسرعة، فتقل تجاعيد بشرته وتصبح أكثر تماسكًا. وفي الوقت نفسه، لم تعد بشرته التي كانت شفافة حتى هذه المرحلة ولا الشعيرات الدموية التي كانت ظاهرة تحتها مرئية الآن.'), baby_message_ar = COALESCE(baby_message_ar, 'أصابني الفواق! 🤭 هل تشعرين بنقرات إيقاعية متتالية "تك-تك-تك" في بطنكِ؟ هذا فواقي! عندما أبتلع السائل الأمنيوسي، يتهيج حجابي الحاجز فأصاب بالفواق. قد يبدو ذلك غريبًا لكِ، لكنه بالنسبة إليّ تمرين يقوّي رئتيّ. لا تخافي، فأنا لا أختنق!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'القرنبيط'), body_changes_ar = COALESCE(body_changes_ar, 'أنتِ على وشك إنهاء الثلث الثاني. وانتهاء هذه المرحلة المعروفة بالفترة الذهبية للحمل أو شهر العسل قد يعني عودة بعض الأعراض التي عانيتِ منها في الثلث الأول.;;;
بما أن طفلكِ قد ارتفع كثيرًا، تتغير مواضع أعضائكِ نتيجة ضغط الرحم. وتُعد المعدة من أكثر الأعضاء تأثرًا بذلك. فقد يؤدي انتقالها إلى موضع أعلى من المعتاد إلى زيادة الضغط عليها، خصوصًا عند تناول الوجبات الثقيلة، ما قد يسبب القيء وحرقة المعدة. كذلك، قد يؤدي انزياح الأمعاء نحو الجانبين إلى بطء حركتها وحدوث الانتفاخ والإمساك. ومع نمو طفلكِ، يبدأ الرحم مجددًا بالضغط على المثانة، ما قد يجعلكِ تذهبين إلى المرحاض بوتيرة متكررة مرة أخرى. ولأن الضغط على المثانة يقلل سعتها، فقد تزداد وتيرة التبول وتنخفض قوة تدفق البول.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حضّري لنفسكِ اليوم كوبًا من شاي الأعشاب، بعد استشارة طبيبتكِ أو طبيبكِ، واجلسي في مكان هادئ لمراقبة حركات طفلكِ.') WHERE id = '0a949afb-87f2-4780-b137-5c4298637904';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذه المرحلة، تشكل الخلايا الدهنية البنية جزءًا من وزن طفلكِ. وهي خلايا تحتوي في بنيتها على كميات كبيرة جدًا من الميتوكوندريا مقارنة بخلايا الجسم والخلايا الدهنية العادية. وقد يختلف عدد الميتوكوندريا، وهي الأجزاء المسؤولة عن إنتاج الطاقة في الخلية، وفقًا لاحتياجات الخلية من الطاقة. ويكون عددها كبيرًا خصوصًا في الخلايا التي تحتاج إلى مستويات عالية من الطاقة، مثل الخلايا العضلية والعصبية. فعلى سبيل المثال، يبلغ عددها نحو 2500 في خلايا الكبد، وهو أحد الأعضاء التي تحتاج إلى قدر كبير من الطاقة. توجد عضيّات الميتوكوندريا في جميع الخلايا حقيقية النواة القادرة على إجراء التنفس الهوائي. ولذلك لا تحتوي كريات الدم الحمراء، التي تُنقل عبر الدم ولا تحتاج إلى الطاقة، على الميتوكوندريا.'), baby_message_ar = COALESCE(baby_message_ar, 'هل تعرفين ما هو "Lightning Crotch"؟ ⚡ أحيانًا، عندما أركل إلى الأسفل أو أدير رأسي، قد تشعرين بألم مفاجئ يشبه الصدمة الكهربائية في منطقة الأربية. يُسمى هذا بالإنجليزية "Lightning Crotch" (ألم البرق). ويحدث لأنني ألمس أحد الأعصاب. آسف لأنني أؤلمكِ، لكن مكاني ضيق فحسب!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'البروكلي'), body_changes_ar = COALESCE(body_changes_ar, 'لا داعي للقلق إذا كان طفلكِ كثير الحركة أحيانًا أو إذا أصبحت حركاته أبطأ. فرغم انتظام حركاته، قد لا تشعرين دائمًا بالدرجة نفسها من شدتها. والسبب الأكثر شيوعًا لذلك هو وضعية طفلكِ في تلك اللحظة. فإذا اتخذ وضعية الولادة وكان رأسه متجهًا إلى الأسفل، فقد يضغط أكثر على المعدة والرئتين، ما قد يسبب لكِ ضيقًا في التنفس. كما قد تكون ركلاته نحو القفص الصدري مؤلمة جدًا لكِ. أما إذا كان في الوضع المقعدي، فقد يسبب شعورًا بالضغط في منطقة المستقيم ويزيد العبء على المثانة.;;;
كذلك، لا يتحرك الأطفال باستمرار. تذكري أن طفلكِ يقضي في هذه المرحلة ما يقارب 18-20 ساعة من اليوم في النوم. ومن الطبيعي أن تقل حركته عندما تكونين نشيطة، وأن يصبح شديد النشاط خلال ساعات راحتكِ. ولكن إذا لاحظتِ خمولًا أو قلة حركة غير معتادة، ولم يكن طفلكِ نشيطًا بالطريقة التي اعتدتِ عليها، فعليكِ التواصل مع طبيبتكِ أو طبيبكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تعانين من ألم في الأربية، فلا تباعدي بين ساقيكِ كثيرًا. وعند ركوب السيارة، اجلسي أولًا على المقعد، ثم ضمّي ساقيكِ وأدخليهما معًا. وامتنعي تمامًا عن رفع الأشياء الثقيلة.') WHERE id = 'e505d439-55d1-41af-8277-5a18a75a724e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'أصبح طفلكِ قادرًا الآن على فتح عينيه وإغلاقهما. وبفضل ذلك، بلغ مرحلة من النضج تمكّنه من التمييز بين النهار والليل. وعلى الرغم من أن جدار الرحم يعمل حاجزًا يحدّ من وصول المؤثرات الخارجية، مثل الضوء والصوت، إلى داخل الرحم، فإن كبر حجم طفلكِ يؤدي إلى تمدد هذا الجدار وترققه نسبيًا. حتى إنكِ إذا سلّطتِ في هذه المرحلة مصدر ضوء قوي على بطنكِ، فقد يستجيب طفلكِ له ويحاول إدارة رأسه نحو مصدر الضوء. وتصبح هذه الاستجابة ممكنة أيضًا بفضل تطور قرنية عينيه والعصب البصري.;;;
بالإضافة إلى ذلك، يستجيب طفلكِ لصوتكِ ويستطيع تمييز صوت والده عن الأصوات الأخرى. ولأن أصوات النساء والأطفال أعلى حدةً وأنعم من أصوات الرجال، فإنها تعبر جدار الرحم بسهولة أكبر، ولذلك يستجيب لها طفلكِ بدرجة أكبر. أما عند سماع أصوات مفاجئة وشديدة، فقد يفزع ويركل بقوة.'), baby_message_ar = COALESCE(baby_message_ar, '⚖️ كلما ازداد وزني، أصبحتُ أثقل عليكِ أيضًا. أعرف أن ظهركِ يؤلمكِ. لكن فكري في أنني أصبح أكثر صحةً وقوة. ستحافظ طبقة الدهون لديّ على دفئي. وعندما أولد، سأملأ حضنكِ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بروكلي'), body_changes_ar = COALESCE(body_changes_ar, 'مع تقدم أسابيع الحمل، قد تخلطين بين الإفرازات التي تصبح أكثر سيولة بسبب التغيرات الهرمونية وبين نزول ماء الجنين. فعند تمزق الكيس الأمنيوسي، تنزل كمية كبيرة من السائل عادةً، وقد تتدفق على ساقيكِ بغزارة. لكن في بعض الحالات، ولأسباب معينة، قد يحدث ثقب في جانب الكيس الأمنيوسي أو جزئه العلوي، ما قد يؤدي إلى نزول ماء الجنين على هيئة تسرّب بسيط.;;;
إذا كنتِ تشكّين في نزول ماء الجنين، فتوجهي إلى المستشفى، حيث يمكن من خلال اختبار بسيط جدًا تحديد ما إذا كان السائل المتسرب هو السائل الأمنيوسي المحيط بطفلكِ أم إفرازات مهبلية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'حاولي الجلوس باستقامة لتخفيف ضيق التنفس، واسحبي كتفيكِ إلى الخلف لفتح صدركِ. ولتلبية احتياجاتكِ من الكالسيوم، اختاري منتجات الألبان أو الخضروات الورقية الخضراء خلال اليوم. وإذا كنتِ تعانين حكة في البطن، فرطّبي بشرتكِ بزيوت طبيعية. خذي اليوم بعض الوقت للاسترخاء وتخيّلي الأيام الجميلة المقبلة برفقة طفلكِ.') WHERE id = 'e2245d19-3163-447c-8f3b-d37ca7523b57';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد دخلتِ الفترة الممتدة بين الأسبوعين 27 و32، وهي أكثر مراحل الحمل نشاطًا لطفلكِ. كما أن هذه الأسابيع هي الفترة التي يبدأ فيها طفلكِ بالحركة بانتظام. وهذا يعني أنكِ يفترض أن تشعري بما لا يقل عن 10 حركات خلال كل ساعة يكون فيها مستيقظًا. ويكون طفلكِ أكثر نشاطًا ليلًا، عندما لا يتحرك السائل الأمنيوسي كثيرًا. أما خلال النهار، فتؤدي حركاتكِ إلى تماوج السائل الأمنيوسي، ما يساعد طفلكِ على النوم. أي إن طفلكِ قد يبدأ الآن بحرمانكِ من النوم. 😊;;;
وأهم سبب لشعوركِ بحركات طفلكِ بقوة وبأعداد كبيرة في هذه المرحلة هو أن حجمه أصبح كبيرًا بما يكفي، مع وجود كمية من السائل الأمنيوسي تتيح له القيام بهذه الحركات.;;;
مع تقدم الأسابيع، تصبح كمية السائل الأمنيوسي التي يطرحها طفلكِ على هيئة بول داخل الكيس الأمنيوسي أقل من الكمية التي يبتلعها. ونتيجة لذلك، تبدأ كمية السائل المحيط به في الانخفاض تدريجيًا. ويُعد انخفاض حجم السائل أمرًا ضروريًا، لأن طفلكِ سيحتاج إلى مساحة أكبر مع استمرار نموه.'), baby_message_ar = COALESCE(baby_message_ar, 'لديّ نظام يومي! 📅 ماما، هل لاحظتِ ذلك؟ عادةً ما أستيقظ وأنام في الساعات نفسها. فمثلًا، عندما تستلقين مساءً أستيقظ أنا، أما في الصباح فأكون هادئًا. لقد بدأت ساعتي البيولوجية بالعمل. وسأظل هكذا لبعض الوقت بعد ولادتي أيضًا (سأكون من محبي السهر!).'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بروكلي'), body_changes_ar = COALESCE(body_changes_ar, 'قد يؤدي ارتخاء المنطقة التي تلتقي فيها المعدة بالمريء، بسبب هرمون البروجسترون، إلى الشعور بحرقة المعدة أيضًا. خلال الحمل، ينبغي لكِ تجنّب الأطعمة التي تزيد حرقة المعدة. ولأن حركات مثل الانحناء قد تزيد هذه المشكلة، تجنّبي الأعمال المنزلية الشاقة أو أي نشاط يتطلب الانحناء. تناولي الطعام ببطء بدلًا من تناوله بسرعة، وابتعدي عن المشروبات الحمضية والغازية وتلك المحتوية على الكافيين.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد شرب كوب من الماء الفاتر على معدة فارغة صباحًا أو تناول المشمش المجفف على تنشيط الأمعاء. لا تؤجلي أبدًا حاجتكِ إلى دخول الحمام.') WHERE id = '45b37fad-6e16-4ec4-9e5c-d3eea98a5a6d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بعد أن بلغ طفلكِ عتبة القدرة على البقاء على قيد الحياة منذ الأسبوع 24 تقريبًا، أصبحت فرصته في النجاة تتجاوز 90% حتى إذا وُلد مبكرًا خلال هذا الأسبوع. ويعود أهم سبب لذلك إلى إنتاج الرئتين كمية كبيرة من المادة الخافضة للتوتر السطحي. تقلل هذه المادة التوتر السطحي للسائل داخل الحويصلات الهوائية، ما يمنع انهيارها الشديد ويساعد على بقائها مفتوحة، كما يدعم تبادل الغازات ويحدّ من تراكم السوائل والوذمة. وتتكوّن هذه المادة من مزيج معقد من البروتينات والدهون. بالإضافة إلى ذلك، اكتمل الآن تكوّن حواس اللمس والتذوق والسمع والشم والبصر لدى طفلكِ.'), baby_message_ar = COALESCE(baby_message_ar, 'أستجيب لصوتكِ! 🎵 عندما يقترب أبي من بطنكِ ويتحدث، تتغير نبضات قلبي. إنني أسمع صوته بوضوح شديد. أخبريه أن يتحدث إليّ. لقد بدأت بالفعل في التعرّف إلى أفراد عائلتي من أصواتهم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بروكلي'), body_changes_ar = COALESCE(body_changes_ar, 'قد تواجهين بعض مشكلات النوم بسبب كبر حجم بطنكِ ونشاط طفلكِ خلال ساعات الليل. وقد يكون اقتناء وسادة حمل مفيدًا لكِ خلال هذه الفترة. تدعم وسادة الحمل منطقتي الظهر وأسفل الظهر، ما يساعد على تخفيف الألم وتحسين راحتكِ. كما تساعدكِ على اتخاذ وضعية تدعم التنفس، فتخفف ضيق التنفس الشائع خلال الحمل. ويمكن أن تسهم الوضعية المريحة في تحسين تدفق الدم ووصول الأكسجين إلى طفلكِ، بالإضافة إلى تقليل شكاوى حرقة المعدة الشائعة جدًا خلال الحمل. كما قد يساعد تحسين الدورة الدموية على تخفيف التشنجات والوذمة، وخصوصًا تورم الساقين. ;;;
يُنصح عادةً بالاستلقاء على الجانب الأيسر، وخصوصًا خلال الثلث الأخير من الحمل. ويرجع ذلك إلى أن الاستلقاء في بعض الوضعيات قد يضغط على الوريد الأجوف الموجود في الجانب الأيمن من الجسم، ما قد يعيق عودة الدم من الجزء السفلي من الجسم ويسبب مشكلات مرتبطة بذلك.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي اليوم بإتمام 27 أسبوعًا بنجاح من خلال منح نفسكِ قسطًا من الراحة. ولتقليل تورم ساقيكِ، انتبهي إلى كمية الملح التي تتناولينها واستريحي مع رفع ساقيكِ. نظّمي مواعيد نومكِ لتبدئي الثلث الثالث من الحمل بنشاط. اعتبارًا من الغد، سيبقى وقت أقل حتى موعد لقائنا!') WHERE id = '7654580f-12f8-4fea-93bd-20d5a4e92397';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تستمر مرونة عضلات طفلكِ في التطور. ويؤثر تطور مرونة العضلات إيجابيًا في قوة قبضته، كما يؤدي دورًا مهمًا للغاية في تكوّن ردود أفعاله.;;;
تشكل العضلات المتصلة بالجهاز الهيكلي أساس الجهاز الحركي. ويحتوي جسم الإنسان على نحو 650 عضلة، ويشكل وزن هذه العضلات إجمالًا ما معدله 40-50% من وزن الجسم كله. وتُصنّف العضلات إلى ثلاثة أنواع: العضلات المخططة، والعضلات الملساء، وعضلة القلب. وتتميز هذه العضلات ببعض الخصائص، منها: الاستثارة، والتوصيل، والانقباض، والمرونة، واللزوجة.;;;
تتميز العضلات، شأنها شأن جميع الأنسجة الحية، بقدرتها على الاستجابة للمؤثرات التي تتعرض لها. وتكون استجابة العضلات لهذه المؤثرات على شكل انقباض. وهناك خمسة أنواع من الانقباضات: الانقباض متساوي القياس، والانقباض المركزي، والانقباض اللامركزي، والانقباض متساوي الحركة، والانقباض التشنجي.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا بالثلث الثالث! 👋 ماما، لقد اجتزنا مرحلة كبيرة. ينتهي الثلث الثاني، ويبدأ الآن الثلث الثالث. لقد أصبحتُ طفلًا كبيرًا. مهمتي الأساسية الآن هي اكتساب الوزن والاستعداد للمجيء إلى العالم. أعلم أنكِ متعبة، لكن لم يتبقَّ سوى القليل. سنلتقي قريبًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'بروكلي'), body_changes_ar = COALESCE(body_changes_ar, 'قد لا تعود ملابسكِ مناسبة لكِ بسبب ازدياد حجم بطنكِ كثيرًا. ويجب عليكِ، خصوصًا خلال الثلث الأخير، تجنب الملابس التي تضغط على بطنكِ، لأنها قد تسبب التوتر لطفلكِ وتبطئ تدفق الدم. كما قد تعيق السراويل الضيقة جدًا حول ساقيكِ عمل الأوردة، ما يمهد لظهور الدوالي.;;;
ومن الأمور الأخرى ارتداء الأحذية ذات الكعب العالي أثناء الحمل. عند الوقوف حافية القدمين، يتوزع 50% من وزن الجسم على الكعبين و50% على أصابع القدمين، ما يساعد على تحقيق التوازن. أما عند ارتداء حذاء ذي كعب عالٍ، فتتغير هذه النسبة إلى نحو 10% و90%، ما يؤدي إلى اختلال كبير في التوازن. ونظرًا إلى أن مركز ثقل جسمكِ يتغير بالفعل بسبب نمو الرحم أثناء الحمل، فقد يؤدي ارتداء الأحذية ذات الكعب العالي إلى فقدان توازنكِ والتعرض لإصابات خطيرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'بما أنكِ بدأتِ الثلث الثالث، فهذا هو الوقت المناسب تمامًا لمناقشة "عدم توافق العامل الريسوسي (Rh)" مع طبيبكِ، إذا كانت فصيلة دمكِ سالبة، ومراجعة نتائج اختبار تحمل الغلوكوز. ويمكنكِ استخدام حزام دعم الحمل لتخفيف آلام الظهر. ابدئي بعدّ حركات طفلكِ خلال اليوم؛ وعادةً ما تُعد 10 حركات خلال ساعتين أمرًا طبيعيًا.') WHERE id = 'efc08af4-0ca2-4af8-832f-852d08704ce8';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع بداية هذا الأسبوع، تدخلين الشهر 7 من حملكِ. وخلال الأشهر الثلاثة الأخيرة من الحمل، المعروفة أيضًا بالثلث الأخير، سيكون طفلكِ قد نما بما يكفي ليتمكن من العيش خارج الرحم. وفي هذه المرحلة، تتجاوز فرصة بقائه على قيد الحياة في حال حدوث ولادة مبكرة محتملة 80%. أما الرئتان، اللتان يكتمل نموهما في الأسبوع 37، فقد تطورتا الآن بما يكفي لمساعدة طفلكِ على التنفس بدعم من وحدة العناية المركزة لحديثي الولادة إذا حدثت ولادة مبكرة هذا الأسبوع. ويعود السبب الأكبر في ذلك إلى اكتمال جزء كبير من إنتاج المادة الفاعلة بالسطح الرئوي.;;;
قد يطلب منكِ طبيبكِ بدءًا من هذا الأسبوع عدّ حركات طفلكِ. ويمكنكِ البدء بذلك مع مراعاة أن لطفلكِ فترات نوم ويقظة، وأنه يقضي معظم ساعات اليوم نائمًا. وبفضل ازدياد قوة عضلاته وكتلة جسمه، يمكنكِ الشعور بكل حركة يقوم بها خلال ساعات يقظته. ولعدّ حركات طفلكِ، اختاري فترة يكون فيها مستيقظًا ونشطًا. استلقي على جانبكِ الأيسر في مكان هادئ، وسجلي كل حركة تشعرين بها.'), baby_message_ar = COALESCE(baby_message_ar, 'مرحبًا يا ماما! لقد حققنا إنجازًا كبيرًا. دخلنا المرحلة الأخيرة من الحمل. أهم ما عليّ فعله الآن هو اكتساب الوزن والاستعداد للمجيء إلى العالم. أصبحت المساحة حولي أضيق، لكن قوتي تزداد. أوجه إليكِ ركلة قوية وأقول: "تهانينا!"'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة باذنجان كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يُعد الكالسيوم من أكثر العناصر التي يحتاج إليها طفلكِ خلال هذه الأسابيع. وإذا لم تحصلي على كمية كافية من الكالسيوم من الأطعمة التي تتناولينها يوميًا، فسيُلبّى هذا الاحتياج من مخزون الكالسيوم في عظامكِ.;;;
وإذا لم تحصلي على حاجتكِ الكافية من الحديد، الذي يساهم في تكوين خلايا الدم الحمراء لديكِ ولدى طفلكِ، من الطعام والمكملات التي وصفها طبيبكِ، فسيتمكن طفلكِ من تكوين خلايا دمه، لكنكِ قد تُصابين بفقر الدم.;;;
إلى جانب الحديد والكالسيوم، تُعد أحماض أوميغا-3 الدهنية من أهم احتياجات الثلث الثالث، إذ يستخدمها طفلكِ بكميات كبيرة في نمو أنسجة دماغه المتسارع خلال هذه الأسابيع. وتوجد أوميغا-3 في مصادر نباتية مثل فول الصويا والجوز، لكنها تتوافر بكثرة خصوصًا في الأسماك. لذلك، من المفيد زيادة تناول الأسماك خلال الحمل.'), daily_tip_ar = COALESCE(daily_tip_ar, 'للاحتفال بهذه المرحلة، تناولي عشاءً بسيطًا مع شريككِ، أو أعدّي القائمة إذا كنتِ تخططين لإقامة حفل "Baby Shower". كافئي نفسكِ، فأنتِ تقومين بعمل رائع!') WHERE id = '96a22ed0-5e13-4094-87c4-74d0da4a58fc';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يتبين خلال فحص الطبيب هذا الأسبوع أن طفلكِ في وضعية الولادة، أي أن رأسه إلى الأسفل، أو في وضعية المجيء بالمقعدة. ولا داعي للقلق في الحالتين. فحتى الأسبوع 34 من الحمل، يكون لدى كل طفل ما يكفي من السائل الأمنيوسي للتحرك بسهولة داخل الرحم وتغيير وضعيته. ومع نمو طفلكِ، يصبح رأسه أثقل نسبةً إلى جسمه، فيتخذ وضعية الرأس إلى الأسفل بتأثير الجاذبية أيضًا. وتكون الولادة المهبلية أسهل ما يمكن في هذه الوضعية. وهكذا يصبح الأطفال مستعدين للاندفاع عبر قناة الولادة في الولادة الطبيعية.;;;
بحلول الأسابيع 32-34 من الحمل، يكون نحو 70-80% من الأطفال قد اتخذوا وضعية الولادة والرأس إلى الأسفل. وعند الوصول إلى الأسبوع 37، ترتفع هذه النسبة إلى 95%. وفي بعض الحالات، قد يستقر الطفل في وضعية مختلفة، مثل المجيء بالمقعدة. وعندها يزيد طبيبكِ وتيرة المتابعة في المستشفى، وقد تُجرى الولادة بعملية قيصرية إذا دعت الحاجة. ومن أسباب عدم اتخاذ بعض الأطفال وضعية الولادة بعد مرحلة معينة: زيادة كمية السائل الأمنيوسي بدرجة كبيرة، وتموضع المشيمة بحيث تسد قناة الولادة، وتشوهات شكل الرحم، وضيق عظام الحوض.'), baby_message_ar = COALESCE(baby_message_ar, 'لديّ الآن نظام نوم! 🌙 لم أعد أنام في أوقات عشوائية. لديّ مواعيد محددة للنوم واليقظة. عادةً ما أستيقظ عندما تستريحين. وعندما أكون نائمًا، أمر بمرحلة "نوم حركة العين السريعة" (REM). هذا يعني أنني أحلم! وربما أراكِ في أحلامي...'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة باذنجان كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يعود الإرهاق الجسدي خلال هذه الفترة. فقد ازداد حجم بطنكِ كثيرًا، ما يجعل الحركة والنوم براحة أكثر صعوبة. إذا كانت فصيلة دمكِ سالبة (-) وفصيلة دم شريككِ موجبة (+)، فعليكِ التحدث إلى طبيبكِ هذا الأسبوع بشأن الحصول على حقنة "Rhogam" (الغلوبولين المناعي المضاد للعامل الريسوسي) للوقاية من عدم توافق فصائل الدم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تتناولي وجبات ثقيلة قبل النوم، وابتعدي عن الشاشات (الهاتف، التلفاز). قد يساعدكِ الاستحمام بماء دافئ وشرب كوب من الحليب الدافئ على النوم بسهولة أكبر.') WHERE id = '65a58c5e-3cca-4355-b7cb-eb0f566d682e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يبلغ وزن طفلكِ في هذه المرحلة 850 غرامًا، وقد يتجاوز أيضًا 1000 غرام. إذا كان وزن طفلكِ أقل أو أعلى من المتوسط، فلا داعي للقلق. تذكّري أن الأطفال لا يولدون جميعًا بالوزن نفسه، وأن وزن الأطفال الأصحاء عند الولادة قد يتراوح ضمن نطاق واسع بين 2500 و4000 غرام. في هذه الأيام التي تدخلين فيها الثلث الأخير من الحمل، تبدأ الزيادة الأساسية في وزن طفلكِ بعد هذه المرحلة تحديدًا.;;;
يزداد وزن الأطفال خلال الثلث الأخير بمعدل 250 غرامًا أسبوعيًا. وإذا لم توجد أي مشكلة صحية، فسيستمر طفلكِ في اكتساب الوزن حتى في حالات تأخر الولادة. أما إذا كانت هناك مشكلة صحية لديكِ أو لدى طفلكِ، فقد تتباطأ وتيرة زيادة الوزن أو تتوقف. ويُعد الوزن الذي يتراوح بين 2500 و4000 غرام وزنًا طبيعيًا عند ولادة الطفل في موعده. وغالبًا ما يولد الأطفال بوزن يتراوح بين 3000 و3500 غرام. وقد يظهر في هذا الصدد فرق يبلغ في المتوسط 10 في المئة بين الإناث والذكور.;;;
بالإضافة إلى ذلك، تُعد العوامل الوراثية من أهم العوامل التي تحدد وزن طفلكِ عند الولادة. ومن الخطأ تقييم طفلكِ اعتمادًا على وزنه وحده. فعلى الرغم من اتباعكِ نظامًا غذائيًا صحيًا، قد تؤدي المشكلات المتعلقة بالطفل، والأمراض المزمنة، والتدخين، والعوامل الوراثية إلى انخفاض الوزن عند الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أرمش بعينيّ! 😉 ماما، أصبح بإمكاني الآن فتح عينيّ وإغلاقهما. إذا سطع ضوء قوي على بطنكِ، فسأدير وجهي أو أرمش بعينيّ. لم تكتمل قدرتي على الرؤية بعد، لكنني أميّز بين الضوء والظلام بشكل ممتاز. لا أطيق الانتظار لرؤية العالم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'باذنجانة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'خلال الحمل، يؤدي ارتفاع مستوى هرمون البروجسترون في الدم إلى تمدد الأربطة والعضلات في منطقة الحوض وتجويف البطن وزيادة مرونتها. ويساعد ذلك على دعم الرحم المتنامي وتثبيته. ومع اقتراب نهاية الحمل، يميل الجزء العلوي من العمود الفقري قليلًا إلى الخلف في محاولة لتخفيف الضغط الذي يسببه الرحم على الأعضاء الأخرى. كما تصبح المفاصل المكوِّنة للحوض أكثر مرونة وتبدأ بالاستعداد للولادة. وتحدث جميع هذه التغيّرات بفعل هرمونات الحمل التي ترتفع مستوياتها وتتغير في الجسم، مثل الإستروجين والبروجسترون.'), daily_tip_ar = COALESCE(daily_tip_ar, 'جرّبي تمرين «القطة والبقرة» (Cat-Cow) في اليوغا لتخفيف آلام الظهر، وذلك بالارتكاز على اليدين والركبتين وتقويس الظهر ثم إرخائه. يساعد هذا التمرين على تقليل الضغط على العمود الفقري ومساعدة طفلكِ على اتخاذ وضعية أكثر راحة.') WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يكون طفلكِ في هذه المرحلة مستلقيًا في أوضاع مختلفة عديدة. ويُعد أفضل وضع يمكن أن يتخذه طفلكِ هو الوضع «الأمامي»، حيث يكون وجهه متجهًا نحو ظهركِ، والوضع «الرأسي»، حيث يكون رأسه إلى الأسفل. وهناك عدة أسباب لاعتبار هذه الوضعية مثالية؛ إذ تسمح لطفلكِ بالاستقرار بسهولة ضمن انحناءة حوضكِ. وأثناء الولادة، تتيح له هذه الوضعية تدوير ظهره وثني ذقنه نحو صدره. كذلك يضغط الجزء العلوي من الرأس على عنق الرحم، ما يساعد على إنتاج الهرمونات اللازمة لبدء تقلصات المخاض. وعند الوصول إلى مرحلة الدفع، تساعد هذه الوضعية على اتخاذ الزاوية الصحيحة ومرور الرأس بسهولة عبر قناة الولادة. وبفضل ذلك، قد تتمكنين من الولادة دون الحاجة إلى تحفيز المخاض أو إجراء عملية قيصرية. وقد تحظين بتجربة ولادة أسرع وأسهل، وتشعرين بألم أقل وتستعيدين راحتكِ في وقت أقصر. قد لا يكون طفلكِ قد اتخذ وضعية الولادة حتى الأسابيع الأخيرة من الحمل، ومع ذلك يمكنه أن يستدير تلقائيًا حتى في هذه المرحلة. وفي بعض الحالات، قد يستدير الطفل عند بدء المخاض نفسه.'), baby_message_ar = COALESCE(baby_message_ar, 'أتدرّب على التنفس! 🌬️ بالطبع، لا يوجد هواء هنا بعد، لكنني أرفع صدري وأخفضه وأسحب السائل الأمنيوسي إلى رئتيّ. تقوّي هذه التمارين حجابي الحاجز. وأحيانًا أُصاب بالفُواق في أثناء ذلك. هل تشعرين بتلك النبضات المنتظمة؟ هذه هي تماريني الرياضية.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'باذنجانة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد مشكلات الأمعاء والإمساك من أكثر المشكلات التي قد تواجهينها طوال فترة الحمل. خلال هذه المرحلة، يؤدي ارتفاع مستوى البروجسترون، وهو أحد هرمونات الحمل، إلى ارتخاء عضلات القناة الهضمية، ما يبطئ حركة الطعام المهضوم جزئيًا، الذي يُسمى الكيموس، داخل الأمعاء.;;;
كذلك قد يضغط الرحم المتنامي على أجزاء مختلفة من القولون داخل تجويف البطن، ما قد يعيق تقدم بقايا الطعام. وينتج عن ذلك حدوث الإمساك.;;;
إذا استمرت مشكلة الإمساك لديكِ لأكثر من أسبوع، فعليكِ استشارة طبيبكِ لتجنب استمرارها فترة أطول. فقد يؤدي الإمساك الذي يُترك دون علاج مدة طويلة إلى مشكلات عديدة، وفي مقدمتها البواسير.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تستلقي مباشرة بعد تناول الطعام، وحافظي على وضعية مستقيمة لمدة ساعة واحدة على الأقل. وقد يساعد النوم مع وضع وسادة مرتفعة تحت رأسكِ على منع ارتجاع الحمض. تجنّبي شرب ماء الصودا، إذ قد يسبب الانتفاخ لاحتوائه على الملح.') WHERE id = 'b00d6682-7d24-499f-8007-e3d98626d47b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل خلايا دماغ طفلكِ إنتاج ملايين الخلايا العصبية كل ثانية. ومع تكاثر خلايا الدماغ بسرعة استثنائية، يبدأ الدماغ بتكوين طيات وتجاعيد بنيوية لأن حجمه لا يكفي لاستيعاب هذا النمو. وتتسارع عملية تكوّن هذه البنى المطوية مع حدوث التعلم بفضل اكتمال نمو أعضاء حواس طفلكِ. وتتيح التلافيف والأخاديد الموجودة على سطح الدماغ له اكتساب مساحة إضافية عبر الانطواء على نفسه وإلى الداخل، حتى يتمكن من أداء وظائف أكثر. وبفضل هذه الطيات، تتسع مساحة سطح الدماغ البشري، التي كانت ستظل محدودة بالحيز الداخلي للجمجمة، لتصبح عند بسطها مساوية تقريبًا لمساحة صفحتين من صحيفة موضوعتين جنبًا إلى جنب.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أعرفكِ! 🎤 ماما، صوتكِ هو أكثر الأصوات ألفةً بالنسبة إليّ. تُظهر الدراسات أن نبضات قلبي تهدأ عندما أسمع صوتكِ. لقد بدأت بالفعل بتعلّم نبرة صوتكِ وطريقتكِ في الكلام. وعندما أولد، سيكون حديثكِ معي وحده كافيًا لتهدئتي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'باذنجانة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يتسرب في هذه الأسابيع بعض الحليب المتجمع في قنوات الثديين. ونظرًا لأن تحفيز الحلمتين بأي شكل قد يزيد إفراز الحليب، ويحفز في الوقت نفسه إفراز هرمون الأوكسيتوسين، ما قد يسبب تقلصات الرحم، فيجب ألا تعصري حلمتيكِ مطلقًا للتحقق من وجود الحليب. وفي الظروف الطبيعية، لا يرتبط تسرب الحليب من الثديين بالولادة المبكرة، لكن تحفيز الحلمتين قد يؤدي إلى انقباض عضلات الرحم، ومن ثم قد يتسبب في ولادة مبكرة. كما يثبط إفراز هرمون البرولاكتين عملية الإباضة، ولهذا قد لا تحدث الإباضة لدى الأمهات المرضعات مدة معينة. وبفضل هذا الهرمون، الذي يعيق نضج البويضات وتطورها، قد تنقطع الدورة الشهرية فترة بعد الولادة. وقد تنتظم الدورة الشهرية لدى بعض النساء خلال 6 أشهر، بينما يُعد عدم عودتها لمدة تصل إلى عامين أمرًا طبيعيًا أيضًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'خصّصي لنفسكِ بعض الوقت هذا المساء، وحدّثي طفلكِ عن أول رحلة ستذهبان إليها معًا في المستقبل.') WHERE id = '4ca04882-bd78-4264-985d-0684e463329f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تكونت موجات دماغ طفلكِ بالفعل. ووفقًا للأبحاث التي أُجريت خلال السنوات الأخيرة، يبدأ الدماغ، الذي يعمل بالطاقة الكهربائية، بإنتاج موجاته الكهربائية وهو لا يزال في الرحم. وهذه الموجات التي ينتجها الدماغ هي موجات بيتا وألفا وثيتا ودلتا، ويُعبَّر عنها بوحدة الهرتز (Hz). ويشير الهرتز إلى عدد الدورات في الثانية. عندما يكون الدماغ في حالة بيتا، يكون الجسم مستيقظًا. وهذه هي الحالة الذهنية الأكثر استخدامًا في الحياة اليومية، وتشمل التفكير والتحدث واتخاذ القرارات وحل المشكلات والتخطيط والبدء في العمل. وخلال النهار، عندما تُغمَض العينان ويسترخي الجسم، ينتقل الدماغ من تردد بيتا إلى تردد ألفا. وتُسمى هذه الحالة بالتنويم المغناطيسي الخفيف؛ إذ تقل فيها سيطرة العقل الواعي ويزداد الإبداع. أما حالة دلتا الذهنية فهي حالة النوم التي نعرفها. وهي لا تحدث في العقل الباطن، بل خارج نطاق الوعي. وعندما يكون العقل في موجات دلتا، يدخل الجسم مرحلة الراحة والتجدد. يحتاج كل إنسان إلى النوم، لأن الجسم يتجدد ويستريح الجهاز العصبي أثناءه.'), baby_message_ar = COALESCE(baby_message_ar, 'تكتمل 28 أُسبوعًا! 👋 ندخل رسميًا الشهر السابع. تضيق المساحة حولي تدريجيًا، لذلك لم تعودي تشعرين بأنني "أسبح"، بل أصبحتِ تشعرين بضربات مرفقي وركبتي بوضوح.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة باذنجان كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه المرحلة، تحدث تغيرات ملحوظة في جهازكِ الهضمي بسبب الهرمونات وتغيّر مواضع بعض الأعضاء جزئيًا. وقد تعانين من حرقة المعدة نتيجة ارتخاء الصمام الموجود بين المعدة والمريء، مما يسمح بتسرب حمض المعدة إلى المريء. لذلك، تجنبي الاستلقاء مباشرة بعد تناول الطعام. كما قد يؤدي الإفراط في ملء المعدة بأطعمة ومشروبات مثل المشروبات الغازية والأطعمة الحارة والمقليات الغنية بالدهون إلى زيادة الحرقة. المريء عضو غير محمي من الأحماض، وقد تحدث فيه تغيرات دائمة مع تكرار حرقة المعدة. لذلك، من المهم جدًا لصحتكِ أن تنتبهي إلى نظامكِ الغذائي وأن تتناولي وجبات صغيرة ومتكررة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'كافئي نفسكِ اليوم واستريحي احتفالًا بإكمالكِ هذه الرحلة التي استمرت 28 أُسبوعًا بنجاح. ولتقليل تورم قدميكِ، انتبهي إلى كمية الملح التي تتناولينها واستريحي مع رفع ساقيكِ. وإذا لم تكوني قد فعلتِ ذلك بعد، فابدئي بإعداد قائمة بالأغراض الأساسية الأولى التي يحتاج إليها طفلكِ. اعتبارًا من الغد، سنبدأ الأسبوع 29، وهي مرحلة جديدة تقرّبنا خطوة أخرى من لقائنا!') WHERE id = 'bfd55361-27a4-4f83-b42f-472543bccd24';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'خلال هذه الأيام التي تدخلين فيها الثلث الثالث من الحمل، سيزداد وزن طفلكِ بنحو 150-200 غرام أسبوعيًا. ويرجع هذا الازدياد في الوزن إلى تسارع تكوّن الدهون. ومع زيادة عدد الخلايا الدهنية، تصبح بشرة طفلكِ أقل تجعدًا. كما يكون الكيس الأمنيوسي لطفلكِ قد اكتمل نموه في هذا الأسبوع. لقد دخلتِ مرحلة ينمو فيها دماغ طفلكِ وجمجمته بسرعة استعدادًا للعالم الخارجي. ومع اكتمال نمو أعضائه الحسية ونضج الجزء المسؤول عن التحكم فيها داخل الدماغ، يبدأ طفلكِ بالتعلم من خلال المنبهات القادمة من الخارج. ولأن هذه المعلومات تتطلب مساحة معينة في الدماغ، تبدأ التلافيف بالتكوّن في بنيته لتوفير المساحة. ومنذ لحظة ولادته، سيدخل طفلكِ في مرحلة من التعلم السريع وتخزين ما يتعلمه في ذاكرته. وستُزال بعض خلايا الدماغ، التي يزيد عددها بمليارات الخلايا عما يحتاج إليه، من خلال عملية تُعرف بالتقليم العصبي، لإتاحة مساحة لهذه المعلومات الجديدة.'), baby_message_ar = COALESCE(baby_message_ar, 'عظامي تزداد صلابة! 🦴 ماما، أنا مدين لكِ الآن بالكثير من الكالسيوم. فعظامي تتصلب بسرعة، وأخزن يوميًا نحو 250 mq من الكالسيوم. وإذا لم تشربي ما يكفي من الحليب، فسوف "أسرق" هذا الكالسيوم من أسنانكِ وعظامكِ. اعتني بنفسكِ وتناولي الجبن!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف'), body_changes_ar = COALESCE(body_changes_ar, 'على امتداد فترة حملكِ، تحدث تغيرات مهمة في كيمياء دماغكِ، تمامًا كما تحدث في جسمكِ. وقد تجعلكِ هذه التغيرات أكثر عرضة للاكتئاب، خاصة إذا كنتِ شديدة الحساسية. ورغم أن الاكتئاب يزداد عادة بعد الولادة، فقد تبدأ علاماته الأولى أحيانًا خلال الحمل. ومن علامات الاكتئاب: الشعور المستمر بالعصبية أو انعدام القيمة أو الذنب، واضطرابات الشهية والتغذية، والآلام التي لا تستجيب للعلاج، وفقدان الاستمتاع بالأشياء التي كانت تسعدكِ عادة، وتراجع اهتمامكِ بالأمور التي كنتِ تهتمين بها، واضطرابات النوم الشديدة، وصعوبة الانتباه والتركيز. خلال هذه الفترة، احصلي على الدعم من شريككِ وأفراد عائلتكِ، وركزي على الأمور الإيجابية، وحاولي ألا تشغلي ذهنكِ بالمسائل التي تسبب لكِ الحزن.'), daily_tip_ar = COALESCE(daily_tip_ar, 'أولي اهتمامًا خاصًا بالحصول على الكالسيوم (الحليب واللبن والجبن)، لأن طفلكِ "يأخذ" الكالسيوم منكِ بسرعة خلال هذه الفترة. ولتقليل آلام الظهر، احرصي على استخدام وسائد تدعم ظهركِ عند الجلوس. وإذا لم تكوني قد بدأتِ بعد، فهذا وقت ممتاز لإعداد قائمة بمحتويات حقيبة طفلكِ. استريحي اليوم مع طفلكِ على أنغام موسيقى هادئة.') WHERE id = '124477a3-06f6-44dd-a276-41487168c5e0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل نمو عضلات تعابير الوجه. وأصبح بإمكان الجنين أن يبتسم ويعبس ويُخرج لسانه. وتنتج الغدتان الكظريتان هرمون "الإستريول". ويحفز هذا الهرمون إنتاج الحليب في جسم الأم.;;;
بلغت عملية التعظّم ذروتها، ويزداد الهيكل العظمي للجنين صلابة. كما يبدأ مركز تنظيم درجة الحرارة في الدماغ بالعمل. وأصبح طفلكِ قادرًا الآن على تنظيم درجة حرارة جسمه جزئيًا، وصار اعتماده على حرارة السائل الأمنيوسي أقل.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أبتسم! 😊 كثيرًا ما يلاحظ الأطباء أثناء فحوصات الموجات فوق الصوتية أننا نبتسم. ويحدث ذلك عادة أثناء النوم. تُرى، هل أرى الملائكة؟ أم أنني أدرّب عضلات وجهي فحسب؟ مهما كان السبب، فأنا سعيد. ابتسمي أنتِ أيضًا يا ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف'), body_changes_ar = COALESCE(body_changes_ar, 'تتولى المشيمة، حتى لحظة ولادة طفلكِ، المهام التي ستؤديها الرئتان والكليتان والكبد لاحقًا. ولأن رئتي طفلكِ لا تستطيعان أداء وظيفتهما بعد، تتولى المشيمة هذه المهمة. إذ تحصل على الدم عبر أوعية الحبل السري، وتزوّده بالأكسجين المأخوذ من جسمكِ، ثم تعيده إلى طفلكِ عبر الحبل السري. وبالطريقة نفسها، لا يتخلص جسم طفلكِ من الفضلات عبر الكليتين والكبد كما يحدث عادة، بل تُنقل هذه الفضلات إلى المشيمة، ومنها إلى دورتكِ الدموية للتخلص منها. ونظرًا إلى هذه الوظائف الحيوية للمشيمة، فإن أي مشكلة قد تصيبها، مثل التكلس أو الشيخوخة أو اضطراب تدفق الدم، قد تمنع طفلكِ من الحصول على التغذية الكافية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استخدمي كريمات علامات تمدد الجلد بانتظام. لكن تذكري أن ظهور هذه العلامات يعتمد بدرجة أكبر على العوامل الوراثية. ولتقليل الحكة، خذي حمامًا فاترًا مائلًا إلى البرودة وابتعدي عن الملابس المصنوعة من الأقمشة الاصطناعية.') WHERE id = '82410eeb-db13-46e1-be5e-f6446cc033ef';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'هذه الأسابيع هي الأخيرة التي تزداد فيها كمية السائل الأمنيوسي المحيط بطفلكِ. خلال الأسابيع القليلة المقبلة، لن تُلاحظ زيادة في كمية السائل الأمنيوسي، وستبقى ثابتة حتى موعد الولادة. السائل الأمنيوسي سائل معقم يحمي طفلكِ من المؤثرات الخارجية. يبتلع طفلكِ هذا السائل، كما يُمتص عبر رئتيه وجلده لينتقل إلى الدم. ويُعوَّض السائل الذي يتناقص من خلال البول الذي يفرزه طفلكِ. وإلى جانب المواد التي تعكس الكيمياء الحيوية لجسم طفلكِ، يحتوي السائل أيضًا على خلايا متساقطة من جلده، والطلاء الدهني الجنيني، وشعر الزغب الجنيني.;;;
يدعم السائل الأمنيوسي نمو طفلكِ وتطوره، ويسهم في نمو دماغه. كما يحميه من جميع المؤثرات الخارجية، مثل الأصوات والصدمات والضوء والضغط. ويساعد على تنظيم درجة حرارة الجسم والحفاظ على استقرارها، ويدعم تطور أعضاء الحواس. كذلك يؤدي دورًا في نمو العديد من أجهزة الجسم، ولا سيما الجهازين العضلي والعصبي.;;;
تُعد كليتا طفلكِ المصدر الأساسي للسائل الأمنيوسي؛ إذ يشكّل البول الذي تفرزانه هذا السائل. يبتلع طفلكِ السائل، فينتقل مجددًا إلى جهازه الدوري. ثم يُرشَّح عبر الكليتين مرة أخرى ويعود إلى السائل الأمنيوسي على هيئة بول. وتتكرر هذه الدورة باستمرار.'), baby_message_ar = COALESCE(baby_message_ar, 'أسناني مختبئة! 🦷 ماما، لقد أصبحت براعم أسناني اللبنية جاهزة تحت لثتي، بل إن آثار أسناني الدائمة موجودة تحتها أيضًا. سأولد بلا أسنان، لكن كل شيء لديّ جاهز. الطبيعة مدهشة جدًا، أليس كذلك؟ نحن ندّخر للمستقبل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الملفوف'), body_changes_ar = COALESCE(body_changes_ar, 'إذا لم تكن هناك حالة تستدعي إجراء عملية قيصرية، فلن يكون نوع ولادتكِ قد تحدد بدقة بعد. ومع دخولكِ الثلث الأخير من الحمل، ينبغي أن تبدئي التفكير في طريقة الولادة. تشمل أنواع الولادة: الولادة الطبيعية، والولادة القيصرية، والولادة بالتخدير فوق الجافية، والولادة في الماء.;;;
تستغرق الولادة المهبلية، التي تُسمى أيضًا الولادة الطبيعية، وقتًا طويلًا نسبيًا. ولكي تتم الولادة المهبلية، يجب أن يتسع عنق الرحم بمقدار 10 سم. تُسمى مرحلة الاتساع حتى أول 4 سم بالمرحلة الكامنة، وقد يستغرق وصول اتساع عنق الرحم إلى 4 سم مدة تصل إلى أسبوعين. أما الانتقال من 4 سم إلى 10 سم، فقد يستغرق في المتوسط ما بين 4 و12 ساعة، وفي نهاية هذه الفترة يكون عنق الرحم قد اتسع بالكامل.;;;
قد تتعذر الولادة الطبيعية ويصبح إجراء عملية قيصرية ضروريًا في حالات مرتبطة بالطفل، مثل وضعيته المقعدية، أو كبر حجمه المفرط، أو عدم نزول رأسه في قناة الولادة، أو اضطراب نبضات قلبه، أو تغطية المشيمة لعنق الرحم. وقد يحدث ذلك أيضًا في حالات مرتبطة بكِ، مثل الإصابة بفيروس HPV، أو تسمم الحمل، أو زيادة الوزن المفرطة، أو ضيق الحوض.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لإفراغ مثانتكِ بالكامل، انحني قليلًا إلى الأمام أثناء جلوسكِ على المرحاض. يساعد ذلك على إفراغ المثانة تمامًا وتقليل خطر الإصابة بالعدوى.') WHERE id = '98a97832-2773-43d8-bf72-e6458dfbc947';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تواصل الغدد الإفرازية لدى طفلكِ تطورها. يوجد في الجسم نوعان من الغدد الإفرازية: الغدد الصماء والغدد خارجية الإفراز. تطرح الغدد خارجية الإفراز إفرازاتها في قنوات خاصة، بينما تطلق الغدد الصماء إفرازاتها مباشرة في الدم. وتصل الهرمونات التي ينقلها الدم إلى جميع الخلايا عبر الشعيرات الدموية.;;;
تُنتج الغدة النخامية، وهي إحدى هذه الغدد وتقع في الجزء السفلي من الدماغ الأمامي، العديد من الهرمونات. تدعم هذه الهرمونات نمو طفلكِ وتطوره وتكوّن هرموناته الجنسية. كما تؤثر في تكوّن الحيوانات المنوية إذا كان طفلكِ ذكرًا، والبويضات إذا كان أنثى، وتساعد أيضًا على تنظيم توازن الماء في الجسم وضغط الدم. أما الغدة الدرقية فتنظم سرعة الأيض بواسطة الهرمونات التي تنتجها، وتسرّع عملية تكوّن العظام خلال مرحلة نمو طفلكِ، كما تنظم استخدام الأكسجين في الخلايا. وتشارك الغدتان الكظريتان في إفراز الأدرينالين لحماية الجسم من الأخطار المحتملة، وفي تنظيم توازن المعادن فيه. أما البنكرياس، وهو غدة مختلطة الإفراز، فيفرز هرمونات مثل الإنسولين والغلوكاغون، إلى جانب الإنزيمات الهاضمة، ويساعد بذلك على تنظيم مستوى سكر الدم.'), baby_message_ar = COALESCE(baby_message_ar, '200 يوم! 🎉 ماما، هذا لا يُصدق! لقد مضى على وجودنا معًا 200 يوم. أنا الآن بحجم ثمرة يقطين كبيرة، وقد أصبحت قويًا جدًا. قد تؤلمكِ ركلاتي أحيانًا، لكن اعلمي أنني أختبر قوتي فحسب. لم يتبقَّ الكثير حتى ألقاكِ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ثمرة يقطين كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'سيُجري طبيبكِ خلال الشهرين المقبلين تقريبًا قياسًا لعظام الحوض، فيما يُعرف بفحص الحوض. يهدف هذا القياس، ما لم تكن هناك عملية قيصرية مخطط لها، إلى التحقق من ملاءمة الحوض للولادة المهبلية. وإذا كُشفت سمات تشريحية مثل ضيق الجزء العلوي من الحوض، فقد تُفضَّل طرق ولادة أخرى وفقًا لدرجة الضيق.;;;
الحوض قناة يبلغ قطرها نحو 10 سم، وتحيط بها العضلات والأنسجة الرابطة. وهذه القناة هي الطريق الذي سيمر عبره طفلكِ ليأتي إلى العالم. وهي ليست مستقيمة من الداخل، بل تتسم بانحناءات وبروزات. ولكي يتمكن طفلكِ من المرور عبرها، عليه اتخاذ وضعيات معينة أثناء الولادة. وتؤدي تقلصات الرحم دور القوة الدافعة والمرشدة لطفلكِ خلال هذه العملية.;;;
يدخل طفلكِ رأسه بشكل أفقي عند مدخل القناة الذي تشكله الحدود العلوية لعظام الحوض. وعندما يصل إلى منتصف القناة، يدير رأسه بزاوية 90 درجة ليصبح وجهه متجهًا نحوكِ، وعند بلوغه نهاية القناة يخرج رأسه في الوضعية نفسها. وبعد خروج الرأس، يديره نحو الجانب الداخلي لإحدى ساقيكِ حتى يتمكن الكتفان من دخول قناة الولادة. وعند اكتمال الدوران وخروج بقية الجسم، تتم الولادة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي باليوم الـ200 بتقديم هدية صغيرة لنفسكِ أو تخصيص ساعة للراحة. ولتخفيف آلام أسفل الظهر، ضعي مقعدًا صغيرًا تحت قدميكِ أثناء الجلوس. واستمري في الاستلقاء على جانبكِ الأيسر عند النوم مع وضع وسادة بين ركبتيكِ؛ فهذا يحسّن الدورة الدموية. وإذا لم تكوني قد بدأتِ بعد، فهذا وقت مناسب لاستكمال تجهيز غرفة طفلكِ أو إعداد قائمة محتويات حقيبة الولادة.') WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يوجد في كل سنتيمتر مربع من جلد طفلكِ نحو 110 غدد عرقية، و15 غدة دهنية، وما يصل إلى 3000 خلية حساسة للحرارة. والتعرق الذي تؤديه هذه الغدد المتكوّنة تحت الجلد وظيفة طبيعية من وظائف الأيض، ويحدث بصورة لا إرادية تمامًا. ويساعد على الحفاظ على استقرار درجة حرارة الجسم ودعم جهاز الإخراج. نحو نصف هذه الغدد المتكوّنة في جسم طفلكِ هي غدد عرقية تفرز سائلًا شفافًا عديم الرائحة. وتوجد معظم الغدد التي تفرز العرق الشفاف في باطن القدمين واليدين ومنطقة الوجه. أما الغدد التي تفرز عرقًا كثيفًا ذا رائحة فتوجد في مناطق محددة، مثل الإبطين والمنطقة التناسلية. وعلى الرغم من تساوي عدد الغدد التي تفرز العرق الشفاف والكثيف في منطقتي الإبطين، فإن عدد الغدد المفرزة للعرق الشفاف في المناطق الأخرى يزيد بنحو عشرة أضعاف. تتمثل الوظيفة الأساسية للتعرق في تنظيم درجة حرارة الجسم. ويتبخر السائل الذي تفرزه الغدد المنتجة للعرق الشفاف، ما يساعد على تبريد الجسم. ويتولى مركز تنظيم الحرارة في منطقة تحت المهاد بالدماغ التحكم في درجة حرارة الجسم. وتتم هذه العملية من خلال إفراز العرق من الغدد المنتجة للعرق الشفاف وتنظيم تدفق الدم في الجلد.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أحلم! 😴 ماما، لقد تطور دماغي إلى درجة أنني أصبحت أدخل مرحلة "نوم حركة العين السريعة" (REM). وهذا يعني أنني أحلم بالفعل! تُرى، ماذا أرى في أحلامي؟ أهو صوتكِ أم تلك الكعكة اللذيذة؟ أقضي معظم يومي نائمًا، لكنني أكون نشيطًا جدًا عندما أستيقظ.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'ثمرة يقطين كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تعانين في هذه المرحلة من حملكِ آلامًا شديدة في أسفل الظهر والظهر. ويرجع ذلك إلى تغيّر مركز ثقل جسمكِ نتيجة ارتفاع الرحم الذي يحتضن طفلكِ إلى أعلى. ومن أفضل الحلول ممارسة التمارين الرياضية، وتمارين البيلاتس الخاصة بالحمل، ويوغا الحمل. فهذه الوسائل لا تخفف الآلام والتشنجات المرتبطة بالحمل فحسب، بل تساعد أيضًا على تصحيح وضعية الجسم.'), daily_tip_ar = COALESCE(daily_tip_ar, 'تجنبي الأعمال المنزلية الشاقة. ووجّهي طاقة "إعداد العش" لديكِ نحو الأعمال الخفيفة، مثل غسل الملابس وتزيين الغرفة. يُمنع منعًا باتًا تعليق الستائر أو جرّ الأثاث!') WHERE id = '2b574c8a-d0de-45f5-bd25-7b7b01e3d2fe';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تبدأ الغدة الصنوبرية الموجودة في دماغ طفلكِ بالعمل اعتبارًا من هذا الأسبوع. والغدة الصنوبرية غدة بحجم حبة العدس تقع في الجزء الخلفي من الدماغ، وهي العضو المسؤول عن تنظيم إفراز الميلاتونين والحفاظ على توازنه في جسم طفلكِ. كما تسهم في تنظيم الساعة البيولوجية للجسم، أي إنها تشارك في العديد من الوظائف مثل نمط النوم والاستغراق فيه والاستيقاظ. يسهم هرمون الميلاتونين الذي تفرزه الغدة الصنوبرية في بدء مرحلة البلوغ ودعم التطور الجنسي، كما يؤثر في القدرة على الإنجاب. وينظم الساعة البيولوجية للجسم وإيقاعه، ويساعد على تجدد الخلايا، ويحمي شبكية العين، ويؤدي وظيفة مضادة للسرطان في الجسم. وقد أظهرت الأبحاث التي أُجريت في السنوات الأخيرة أن الغدة الصنوبرية تنشط عادةً في البيئات المظلمة. ولهذا السبب نشعر بثقل في الجسم والنعاس بعد البقاء في مكان مظلم لبعض الوقت. وتعمل الغدة الصنوبرية بكفاءة أكبر، خصوصًا في البيئات المظلمة. وإضافةً إلى ذلك، تشارك هذه الغدة بفاعلية في مرحلة النمو، وتساعد الهرمونات التي تفرزها، ولا سيما خلال مرحلة المراهقة، على منع النمو المبكر للغدد الجنسية.'), baby_message_ar = COALESCE(baby_message_ar, 'أنظّم درجة حرارتي! 🌡️ في السابق، كنت أعتمد كليًا على درجة حرارة جسمكِ. لكنني الآن، بفضل دماغي وطبقتي الدهنية، أبدأ بتنظيم درجة حرارة جسمي بنفسي. لقد أصبحت مثل مدفأة صغيرة. أستعد كيلا أشعر بالبرد عند ولادتي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد الولادة المبكرة من أكبر المشكلات المرتبطة بالحمل المتعدد. فكلما زاد عدد الأطفال، قصرت مدة الحمل وانخفض وزن كل طفل عند الولادة. وبينما يبلغ متوسط مدة الحمل بالتوأم نحو 37 أسبوعًا، تبلغ هذه المدة 35 أسبوعًا عند الحمل بثلاثة توائم. وكل أسبوع يبقى فيه الأطفال داخل الرحم يتيح لأعضائهم وأجهزتهم مزيدًا من النضج، كما يزيد أوزانهم عند الولادة. والهدف في حالات الحمل المتعدد هو إطالة مدة الحمل قدر الإمكان لتجنب الولادة المبكرة. وأفضل طريقة لتحقيق ذلك هي الراحة في الفراش. وقد لا يكون من الممكن مواصلة الأنشطة المعتادة طوال فترة الحمل، وربما يتعين عليكِ الالتزام بتوصية الطبيبة أو الطبيب بالراحة في الفراش.'), daily_tip_ar = COALESCE(daily_tip_ar, 'استلقي على جانبكِ الأيسر ليلًا وضعي وسادة بين ساقيكِ لتحسين جودة نومكِ؛ فهذا سيخفف الضغط عن أسفل ظهركِ. واستخدمي مرطبات ذات مكونات طبيعية لتخفيف حكة البطن. احرصي على تناول الكالسيوم والحديد، لأن عظام طفلكِ تمر الآن بأسرع مراحل التصلب. لا ترهقي نفسكِ كثيرًا اليوم.') WHERE id = '2a9f34ac-1247-4ead-b172-d62294531480';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'كلما نما طفلكِ، ضاقت تدريجيًا المساحة المتاحة لحركته داخل الرحم. لذلك يضم ذراعيه وساقيه نحو جسمه، متخذًا الوضعية المألوفة باسم "وضعية الجنين". ولا تقتصر فائدة هذه الوضعية الذكية على توفير المساحة، بل تساعد أيضًا على الحفاظ على حرارة الجسم. في هذه المرحلة، يصل دماغ طفلكِ إلى مستوى مذهل من النضج. فقد بدأت مراكز دماغه تتعلم التحكم في أهم الوظائف اللازمة للحياة بعد الولادة، وهي التنفس ودرجة حرارة الجسم. ينظم مركز التنفس الحركات الإيقاعية ويهيئ الرئتين للتنفس، بينما يتولى الوطاء دور "منظم الحرارة" للحفاظ على استقرار درجة حرارة جسم طفلكِ الداخلية. ويُظهر ذلك مدى استعداد دماغ طفلكِ المتقن لتمكينه من البقاء على قيد الحياة خارج الرحم.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أتجه برأسي إلى الأسفل؟ ⬇️ قد أبدأ تدريجيًا بالاستعداد لوضعية الولادة. ما زلت كثير الحركة وأتقلب، لكن الجاذبية تسحبني إلى الأسفل لأن رأسي أصبح أثقل. وإذا لم يكن رأسي متجهًا إلى الأسفل بعد، فلا تقلقي، فما زال لدي متسع من الوقت!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بضغط أو ألم في منطقة الأُربية. فكلما نما طفلكِ وتحرك نحو الأسفل، ازداد الضغط على عظام الحوض والمثانة. وقد تعود حاجتكِ إلى دخول الحمام كثيرًا. كما قد يحدث "ألم الارتفاق العاني" الناتج عن تباعد عظام الحوض.;;;
قد تشعرين بهبّات ساخنة. إذ تعمل عملية الأيض لديكِ بسرعة أكبر بنسبة 20% لتلبية احتياجات طفلكِ، ما يولّد حرارة إضافية. وقد تشعرين بالحر طوال الوقت، حتى عندما يشعر المحيطون بكِ بالبرد. كما يزداد التعرق.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف حرقة المعدة، تناولي وجبات صغيرة ومتكررة، ولا تستلقي مباشرة بعد الأكل. وسيساعد الاستلقاء على جانبكِ الأيسر أثناء النوم على تحسين عملية الهضم لديكِ والدورة الدموية لطفلكِ. ولتخفيف آلام الظهر، خذي حمامًا دافئًا أو مارسي تمارين تمدد خفيفة. خصصي لنفسكِ بعض الوقت اليوم وفكري في تفاصيل الغرفة أو الركن الذي تجهزينه لطفلكِ.') WHERE id = '46d5df45-3974-471b-a1a7-d53afb295423';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'حاسة اللمس هي أولى الحواس التي يستخدمها طفلكِ لاكتشاف العالم وأكثرها تطورًا. وهو يتصرف الآن داخل الرحم كمستكشف حقيقي؛ فيتحسس جدران الرحم بيديه، ويمسك الحبل السري، ويمص أصابعه، وكثيرًا ما يلامس وجهه برفق.;;;
ولا تقتصر هذه اللمسات على كونها حركات فحسب، بل تمثل أيضًا إشارات مهمة لنمو الدماغ الحسي. ومن المثير للاهتمام أن الغدتين الكظريتين لدى طفلكِ تؤديان في هذه المرحلة مهمة بالغة الأهمية؛ إذ تبدآن بإفراز هرمون خاص يُسمى الكورتيزول. ويؤدي الكورتيزول دور "المفتاح السحري" في نضج رئتي طفلكِ، إذ يسرّع إنتاج مادة تُسمى الفاعل بالسطح الرئوي في أنسجة الرئتين. وتمنع هذه المادة الأكياس الهوائية الصغيرة في الرئتين من الالتصاق ببعضها. وبفضل هذه العملية، سيتمكن طفلكِ من أخذ نَفَسه الأول بسهولة فور ولادته، وستمتلئ رئتاه بالهواء تمامًا. أي إن الحركات الجسدية والهرمونات الداخلية تهيئ طفلكِ على أكمل وجه ليوم "الانطلاقة الكبير"، أي لأخذ النَفَس الأول وخوض أول تلامس.'), baby_message_ar = COALESCE(baby_message_ar, 'أشعر بكِ! 🤗 ماما، عندما تداعبين بطنكِ ويضع أبي يده عليه، أشعر بتلك الحرارة وذلك الضغط. وأحيانًا ألمس أنا أيضًا الموضع نفسه من الداخل. هذه هي طريقتنا في "إلقاء التحية". لا يفصل بيننا سوى جدار رقيق، أما روحانا فواحدة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد يبلغ النسيان ذروته، وقد تعانين من صعوبة في التركيز. من الطبيعي أن تجدي المفاتيح في الثلاجة أو تنسي ما كنتِ ستقولينه في منتصف الجملة. ينتقل دماغكِ إلى "وضع الأمومة" ويعيد ترتيب الأولويات.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قد تعانين من الأرق خلال هذه الفترة، لذا حاولي أخذ فترات راحة قصيرة خلال اليوم. استمعي هذا المساء إلى موسيقى هادئة برفقة طفلكِ، فهو يشارككِ الشعور نفسه بالسكينة.') WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ الشعر الدائم لطفلكِ بالتكوّن في بصيلات الشعر، إلى جانب الزغب الجنيني. وبفضل هذا الشعر الدائم، يستطيع جسم طفلكِ الحفاظ على توازن الماء والحرارة. كما يسهم الشعر الموجود في أجزاء معينة من الجسم في العزل الحراري. فعندما يكون الجو باردًا، تنقبض العضلات الصغيرة الموجودة في بصيلات الشعر، ما يؤدي إلى انتصاب الشعر وتوليد الطاقة، وبالتالي الحرارة، في تلك المنطقة. عند ولادة طفلكِ، قد يبقى بعض الزغب الجنيني على جسمه، كما يكون جسمه كله مغطى بشعر دائم دقيق جدًا لا يكاد يُرى بالعين. ومع نمو طفلكِ، يزداد هذا الشعر سماكة. ويغطي الشعر جلد الإنسان كله باستثناء راحتي اليدين وأخمصي القدمين والشفتين. لكنه لا يكون ظاهرًا في معظم المناطق لأنه دقيق وفاتح اللون. ويعتمد لون الشعر، سواء كان أسود أو بنيًا أو أشقر أو أحمر، على وجود المواد الملونة المسماة بالصبغات، والتي تقع أسفل الطبقة الخارجية للشعرة مباشرة. وعند غياب جميع هذه الصبغات المختلفة، تحل محلها فراغات هوائية عديدة تعكس الضوء كله، فيبدو الشعر أبيض اللون.'), baby_message_ar = COALESCE(baby_message_ar, 'أراكِ (تقريبًا)! 💡 عيناي مفتوحتان، وإذا سلّطتِ ضوءًا قويًا على بطنكِ، فسأدير رأسي نحوه. أستطيع تتبّع مصدر الضوء. ورغم أن عالمي مظلم، يمكنني أحيانًا رؤية ومضات الضوء الخافتة التي تتسلل عبر جدار بطنكِ. إنها معجزة بالنسبة إليّ!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لم يتبقَّ سوى وقت قصير على ولادتكِ. بعد هذه المرحلة، قد تواجهين صعوبة حتى في الحركة، ولا سيما مع ازدياد حجم بطنكِ كثيرًا. وإذا اخترتِ عدم الحركة بسبب هذه الصعوبة، فقد يضعف جسمكِ وتصبح ولادتكِ أكثر صعوبة. لذلك ينبغي لكِ ممارسة المشي والتمارين لفترات قصيرة من دون إجهاد نفسكِ كثيرًا. ستساعدكِ التمارين على تقوية جسمكِ وزيادة مرونته. كما ستقوى عضلات ذراعيكِ وساقيكِ، وتتمدد العضلات والأنسجة الضامة. وستساعدكِ مرونة منطقتي الفخذين والحوض على الاستعداد لولادة أكثر راحة. ومن خلال تمارين كيجل، يمكنكِ تقوية عضلات قاع الحوض والاستعداد للأشهر الأخيرة من الحمل والولادة وفترة التعافي بعد الولادة.;;;
وفقًا للدراسات، تكتسب النساء اللواتي يمارسن الرياضة طوال فترة الحمل وزنًا أقل بنحو 7 كيلوغرامات حتى موعد الولادة. كما يمكن للتمارين التي تمارسينها أن تساعد على الحد من تورم الساقين والوذمة، اللذين يزدادان خصوصًا في المراحل الأخيرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يساعد ارتداء الجوارب الضاغطة المخصصة للدوالي على تحسين الدورة الدموية وتقليل آلام الساقين. ويكون ارتداؤها صباحًا قبل النهوض من السرير الطريقة الأكثر فاعلية.') WHERE id = '98b2e2a6-b569-4828-8904-245e5d1bc37e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدءًا من هذا الأسبوع، وأنتِ في الشهر 7 من الحمل، وحتى موعد الولادة، سيكتسب طفلكِ وزنًا يعادل نحو ضعفي وزنه الحالي. ويرجع ذلك بصورة أساسية إلى الخلايا الدهنية البيضاء التي يكوّنها جسمه إلى جانب الدهون البنية. يخزّن النسيج الدهني الأبيض فائض الطاقة داخل الخلايا الدهنية على هيئة دهون ثلاثية، ويمكنه إعادتها سريعًا إلى الدورة الدموية عند الحاجة. ويُعد النسيج الدهني أكبر مخزون للطاقة في الجسم، إذ تنظّم الإشارات الهرمونية عملية تخزين الطاقة في الخلايا الدهنية وإطلاقها منها. وهو نسيج يتكوّن من خلايا دهنية ويحتوي على شبكة غنية من الأوعية الدموية والأعصاب. ويشكّل 15-20% من وزن الجسم لدى الرجال و20-25% لدى النساء. والخلايا الدهنية هي خلايا متخصصة في تخزين الدهون المتعادلة وإنتاج الحرارة. ونظرًا إلى أن تناول الطعام لدى الإنسان يحدث على فترات، بينما يستمر استهلاك الطاقة بصورة متواصلة، تؤدي هذه الخلايا وظيفة مهمة بوصفها مخزونًا للطاقة. كما تحمي الجسم من الإصابات وتؤدي دورًا فعالًا في عزله حراريًا. وإضافة إلى ذلك، فهي شديدة الحساسية للمحفزات العصبية والهرمونية.'), baby_message_ar = COALESCE(baby_message_ar, 'الأسبوع 29! 🎃 أنا بحجم يقطينة كبيرة! أبدو كل يوم أقرب إلى هيئة "الإنسان". أصبح رأسي متناسبًا مع جسمي. وهدفي الأساسي الآن هو اكتساب الوزن. عندما أركلكِ، تشعرين بقوتي بصورة أوضح الآن، أليس كذلك؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'يتميز الجلد ببنية مرنة. وخلال الحمل، يؤدي نمو البطن والثديين إلى زيادة تمدده. ونتيجة لهذا التمدد، يفقد الجلد رطوبته وقد تشعرين بالحكة. وقد تبدأ الحكة منذ الأسابيع التي يصبح فيها بطنكِ بارزًا. كما قد تسبب علامات التمدد التي تظهر في منطقتي الثديين والبطن حكة من حين إلى آخر. وإذا كانت الحكة ناتجة عن تمدد الجلد وفقدان الرطوبة، يمكنكِ ترطيب المناطق المصابة باستخدام كريم مرطب أو الفازلين وفقًا لتوصية طبيبكِ. وقد تساعد زيوت مثل زيت اللوز أيضًا على تخفيف الحكة. ونظرًا إلى أن العطور أو مستحضرات التجميل المعطرة قد تزيد الحكة خلال الحمل، ينبغي لكِ تجنب استخدامها. واحرصي على شرب الكثير من الماء للحفاظ على توازن الرطوبة في جسمكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قسّمي وجباتكِ خلال اليوم إلى 5-6 حصص صغيرة. فالوجبات الكبيرة تزيد حرقة المعدة. لا تستلقي مباشرة بعد تناول الطعام، بل ابقي في وضع مستقيم أو امشي قليلًا.') WHERE id = 'cad83eb0-58a7-4d1b-bb76-60f58c14c58f';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اكتمل نمو براعم الأسنان الدائمة لطفلكِ داخل براعم الأسنان. تؤدي الأسنان اللبنية، التي ستظهر بعد مدة من ولادة طفلكِ ويستخدمها لفترة معينة، دورًا بالغ الأهمية في تمكين الأسنان الدائمة من الظهور بصورة سليمة وصحية. تبدأ أسنان طفلكِ بالظهور فوق اللثة لأول مرة بين عمر 5 و8 أشهر. وتكون القواطع الأمامية السفلية أول الأسنان ظهورًا، وعادة ما تظهر بعد بلوغ طفلكِ عمر 6 أشهر. وبعدها مباشرة، تبدأ القواطع العلوية بالظهور بدءًا من الشهر 8 تقريبًا. ثم تظهر القواطع الجانبية والأضراس، وأخيرًا تظهر الأضراس الخلفية. تسقط الأسنان اللبنية عندما تبدأ الأسنان الدائمة الموجودة أسفلها بالضغط عليها. ويؤدي هذا الضغط إلى تخلخل جذر السن تدريجيًا ثم سقوطها. وتبدأ الأسنان الدائمة بالظهور في عمر 6-7 سنوات، تبعًا لسرعة نمو طفلكِ. ويكتمل تكوّن الأسنان الدائمة، البالغ عددها الإجمالي 32 سنًا، مع ظهور "ضروس العقل".'), baby_message_ar = COALESCE(baby_message_ar, 'أحتاج إلى الكالسيوم! 🥛 عظامي تزداد صلابة بسرعة. أحصل الآن كل يوم على نحو 250 مليغرامًا من الكالسيوم من دمكِ. وهذا ضروري ليصبح هيكلي العظمي قويًا. وإذا لم تشربي الحليب، فسأستعير هذا الكالسيوم من أسنانكِ وعظامكِ. اعتني بنفسكِ، ماما!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لا بد أنكِ لاحظتِ التغير الذي طرأ على شعركِ. فقد أصبح أكثر كثافة ولمعانًا، وينمو بسرعة كبيرة. ويرجع ذلك إلى الهرمونات التي تُفرز خلال الحمل، والأهم من ذلك ارتفاع مستوى هرمون الإستروجين في الدم. بعد ولادة طفلكِ، ينخفض إنتاج الإستروجين بدرجة كبيرة ويعود مستواه في الدم إلى طبيعته، ما يؤدي إلى توقف نمو الشعر إلى حد بعيد. وعندها تدخل بصيلات الشعر مرحلة التساقط بصورة جماعية، ويبدأ الشعر بالتساقط خلال مدة قصيرة تتراوح بين 2 و3 أشهر. وبعد انتهاء مرحلة التساقط خلال 6 أشهر، ينمو شعر جديد بدلًا من الشعر المتساقط.'), daily_tip_ar = COALESCE(daily_tip_ar, 'راقبي حركات طفلكِ خلال اليوم، وإذا لاحظتِ أي انخفاض حاد فيها، فاستشيري طبيبكِ. استريحي قليلًا اليوم وأسعدي نفسكِ بممارسة نشاط تحبينه.') WHERE id = '64fd7099-afb5-4134-9918-3acc90ed702e';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'مع مرور كل يوم، يستمر تكوّن مليارات الخلايا العصبية في دماغ طفلكِ. وفي هذه المرحلة، وصل إجمالي عدد الخلايا العصبية إلى عدة تريليونات. ويشكّل الجهاز العصبي نحو 7% من إجمالي ما يقارب 100 تريليون خلية في جسم طفلكِ. وهذا دليل على الأهمية الحيوية لنقل المعلومات. تُصنَّف الخلايا العصبية وفقًا لوظائفها إلى 3 فئات: الأعصاب الحسية، والأعصاب الحركية، والأعصاب البينية. تنقل الأعصاب الحسية المنبهات التي تستقبلها من المستقبلات الحسية إلى أعضاء الجهاز العصبي المركزي، مثل الدماغ والحبل الشوكي. أما الأعصاب الحركية فتنقل الأوامر التي تتلقاها من الجهاز العصبي المركزي إلى العضلات أو الغدد. بينما توجد الأعصاب البينية داخل الجهاز العصبي المركزي، وتؤمّن الاتصال بين الأعصاب الحسية والحركية.'), baby_message_ar = COALESCE(baby_message_ar, 'دماغي يتجعّد! 🧠 كان دماغي أملس في السابق، لكنه الآن يصبح مليئًا بالثنيات مثل لبّ الجوز. لماذا؟ لأن خلايا دماغي تتكاثر بسرعة كبيرة لدرجة أنه يجب أن ينطوي حتى يتّسع داخل جمجمتي. تدل هذه الثنيات على نمو ذكائي وذاكرتي وقدراتي. أنا أستعد لأصبح عبقريًا!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'يقطينة كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'قد تصبح تقلصات المخاض الكاذب أكثر تكرارًا ووضوحًا. وقد تشعرين بأن بطنكِ يصبح قاسيًا كالحجر عدة مرات خلال اليوم. لا تكون هذه التقلصات مؤلمة، لكنها قد تسبب لكِ الانزعاج. إذا كانت التقلصات منتظمة (مثلًا كل 10 دقائق) ومؤلمة، فقد تكون علامة على ولادة مبكرة، فاتصلي بطبيبتكِ فورًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يمكنكِ في هذه الأيام البدء تدريجيًا بإضافة مستلزمات النظافة الضرورية إلى قائمة حقيبة الولادة. اختاري أطعمة خفيفة على العشاء لتنعمِي بنوم أكثر راحة.') WHERE id = '195a150b-6bd1-4a69-9196-35f5d6e3f9f4';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأت طبقة الطلاء الجُبني التي شرعت في التكوّن على جلد طفلكِ قبل بضعة أسابيع تزداد سماكة. والطلاء الجُبني طبقة تشبه الكريم تبدأ بالتكوّن على جلد الطفل خلال الأشهر 3 الأخيرة من الحمل. يولد جميع الأطفال تقريبًا وطبقة الطلاء الجُبني تغطي أجسامهم. وتكون هذه الطبقة أكثر كثافة لدى الأطفال المولودين مبكرًا قبل اكتمال مدة الحمل، بينما تكون قليلة جدًا لدى الأطفال الذين تجاوز حملهم 40 أسبوعًا. هذه الطبقة الدهنية، التي تُسمى الطلاء الجُبني، بيضاء اللون ولها قوام كثيف يشبه الكريم. وهي نوع من الإفرازات الدهنية تنتجها الخلايا الدهنية في جلد طفلكِ بعد تحفيزها بالهرمونات التي ينتجها جسمكِ. يحتوي الطلاء الجُبني على نحو 50 بروتينًا مميزًا، ويحمي طفلكِ بفاعلية كبيرة من مختلف أنواع العدوى التي قد يتعرض لها داخل الرحم وبعد الولادة. وبفضل هذه المادة، يظل جلد طفلكِ محميًا أيضًا خلال محاولته التأقلم مع العالم بعد ولادته. يمتص جلد طفلكِ الطلاء الجُبني بالكامل خلال 1-2 يوم بعد الولادة، ما يساعد على تقليل الطفح الجلدي المحتمل خلال فترة حديثي الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'هل تعدين ركلاتي؟ 🦶 يقول الأطباء إن عليكِ مراقبة حركاتي. عادةً ما أنشط بعد تناولكِ الطعام أو عندما تستريحين. إذا بقيت هادئًا مدة طويلة، فاشربي كوبًا من الماء المُحلّى واستلقي على جانبكِ الأيسر. سأستجيب فورًا. أحيانًا أكون فقط في نوم عميق.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'إذا كنتِ تعانين من آلام في الأُربية، فلا داعي للقلق. لأن نمو طفلكِ يغيّر مركز توازن جسمكِ، فقد تظهر آلام في مواضع مختلفة من الجسم، ومنها الألم في منطقة الأُربية. يُعد ألم الأُربية من الشكاوى الشائعة أثناء الحمل. وقد يكون على شكل وجع خفيف، أو قد يسبب آلامًا حادة تظهر من حين إلى آخر.;;;
ترتبط آلام الأُربية خلال الثلث الأول من الحمل بنمو الرحم، بينما تنتج في الثلث الأخير عن استعداد الجسم للولادة. كذلك، قد تظهر هذه الآلام بوتيرة أكبر وتزداد شدتها إذا لم يحصل الجسم على ما يكفي من المغنيسيوم. ويتوفر المغنيسيوم بكثرة في الأفوكادو والبندق والبقوليات والحبوب الكاملة والأسماك الدهنية والموز.'), daily_tip_ar = COALESCE(daily_tip_ar, 'ارتدي أحذية مريحة لتقليل تورم الساقين والشعور بثقلهما، وارفعي قدميكِ عند الجلوس. واصلي مراقبة حركات طفلكِ خلال اليوم؛ فعادةً ما يُعد الشعور بـ10 حركات خلال ساعتين أمرًا طبيعيًا. خصصي لنفسكِ بعض الوقت هذا المساء، وخذي حمامًا دافئًا، وتخيّلي الأيام الجميلة المقبلة برفقة طفلكِ.') WHERE id = 'eadf5bb2-e6e7-4d41-83d0-6c1c3223ad40';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'إذا كان طفلكِ أنثى، فيستمر مبيضاها في النمو وتكوين ملايين البويضات. والمبيض هو اسم كل واحدة من الغدتين المتناظرتين الواقعتين على جانبي الرحم والمحاطتين بأربطة عريضة. وهو عضو تناسلي أنثوي يحتوي على البويضات، وهي الخلايا التناسلية الأنثوية. يحتوي كل مبيض لدى طفلتكِ على عدد كبير من الجُريبات التي ستشارك في إنتاج البويضات. تكون هذه البويضات في معظمها على هيئة خلايا جنينية، ولا تنضج حتى مرحلة البلوغ. بعد البلوغ، تنضج بويضة واحدة كل شهر بتأثير الهرمونات التي تفرزها الغدة النخامية، ثم تتحرك باتجاه الرحم. وتشمل هذه الهرمونات: هرمون FSH الذي يساعد على نضج البويضة، وهرمون LH الذي يحفز الإباضة، والإستروجين الذي تفرزه الجُريبات ويساعد على ظهور الصفات الجنسية الثانوية، والبروجسترون الذي يفرزه الجسم الأصفر ويهيئ بطانة الرحم للحمل. وإذا لم تُخصّب البويضة الناضجة بحيوان منوي، فإنها تُطرح خارج الجسم وتحدث الدورة الشهرية.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبح حجمي بحجم حبة ملفوف كبيرة! ماما، لا يُصدَّق، لقد قطعنا 3/4 الطريق (75%)! لم يتبقَّ سوى 10 أسابيع (تقريبًا). لقد أصبحت طفلًا كبيرًا، لكن رئتيّ ودماغي لا يزالان بحاجة إلى اكتمال النضج. اقتربنا من خط النهاية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'من المهم جدًا إجراء فحوصات الطبيبة في مواعيدها لتشخيص مشكلات مثل نقص السائل الأمنيوسي مبكرًا. ويُحدَّد نقص السائل الأمنيوسي أثناء الحمل من خلال القياسات التي تُجرى بفحص الموجات فوق الصوتية (USM). ولتشخيص نقص السائل الأمنيوسي أثناء الحمل، يجب أن يقل إجمالي مستوى السائل عن 500 ml. وقد يؤدي تباطؤ تدفق الدم في المشيمة إلى انخفاض كمية السائل الأمنيوسي. وفي حالات ارتفاع ضغط الدم الناتج عن تضيّق الأوعية الدموية أو الحالات المرتبطة بانخفاض مستوى الدم، تقل كمية الدم التي تغذي الطفل، ما يؤدي بدوره إلى نقص السائل الأمنيوسي.;;;
إضافة إلى ذلك، قد يؤدي نقص السوائل عمومًا في جسمكِ، وفي بعض الحالات داء السكري، إلى انخفاض كمية السائل المحيط بالطفل أثناء الحمل. وقد ينخفض السائل الأمنيوسي أيضًا نتيجة الآثار الجانبية لبعض الأدوية المستخدمة دون علم الطبيبة. كذلك يزداد احتمال حدوث هذه المشكلة في حالات الحمل التي اكتملت مدتها واستمرت 42 أسبوعًا أو أكثر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احتفلي بنهاية الأسبوع 30 بقسط هادئ من الراحة. استخدمي عند الجلوس وسائد تدعم ظهركِ لتخفيف آلام أسفل الظهر. وإذا لم تكوني قد فعلتِ ذلك بعد، فيمكنكِ البدء بتجهيز الاحتياجات الأساسية لحقيبة طفلكِ (الحفاضات والملابس). وبدءًا من الغد، ندخل الأسبوع 31 — المنعطف الكبير الأخير في الطريق نحو الولادة!') WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يستمر التصبغ في بنية القزحية، وهي الجزء الملون من عين طفلكِ. والقزحية هي البنية التي تتحكم في حجم بؤبؤ العين وكمية الضوء الداخلة إليها. وعلى الرغم من وجود ألوان عديدة ومختلفة للعيون، فإن هناك نوعًا واحدًا فقط من الصبغة مسؤولًا عن لون القزحية. فإذا كانت كمية الصبغة في الطبقة الأمامية من القزحية كبيرة، يكون لون عيني طفلكِ بنيًا، وإذا كانت قليلة يكون أخضر، وإذا كانت منعدمة يكون أزرق. يتحدد لون عيني طفلكِ منذ اللحظة الأولى لحدوث الإخصاب. ويبدأ هذا التصبغ بالتكوّن اعتبارًا من الأسبوع 4 من الحمل. وعلى الرغم من أن تكوّن الصبغة يبدأ في مرحلة مبكرة جدًا، فعليكِ الانتظار إلى ما بعد الولادة لمعرفة لون عيني طفلكِ. فرغم تكوّن صبغة الميلانين في عينيه، تحتاج هذه الخلايا إلى بعض الوقت حتى تنضج. وبعبارة أخرى، لم يكتمل التصبغ الواضح بعد. وبوجه عام، يبدأ لون عيني طفلكِ الدائم في الظهور بعد نحو 5 أشهر من ولادته.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتخلص من "شعري"! 🐻 أتذكرين أنني أخبرتكِ بأن جسمي مغطى بشعر يُسمى "الزغب الجنيني"؟ والآن، بما أن طبقة الدهون تدفئني، أصبحت حاجتي إلى هذا الشعر أقل. وقد بدأ يتساقط تدريجيًا، وصرت أكثر نعومة وطراوة. قد يبقى القليل منه على ظهري عند ولادتي، لكن معظمه سيختفي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه الأسابيع التي تقتربين فيها من نهاية حملكِ، توجد بعض المعلومات التي ينبغي لكِ معرفتها حتى تتمكني من تمييز بدء المخاض. فقد تخرج السدادة المخاطية قبل الولادة بشهر، كما قد تخرج قبلها ببضع ساعات فقط. أما نزول السائل الأمنيوسي قبل الولادة بوقت قصير، فهو علامة أخرى على بدء المخاض. وقد يكون هذا السائل مائي القوام وذا لون أصفر فاتح جدًا. يمكن أن ينزل السائل الأمنيوسي بصورة مفاجئة جدًا، وعند حدوث ذلك من الأفضل التوجه فورًا إلى المستشفى. فبعد نزول السائل، قد يصبح طفلكِ غير محمي من الجراثيم.;;;
ينبغي أن تحدث الولادة في غضون 48 ساعة على الأكثر من نزول السائل الأمنيوسي. وإذا مر وقت أطول، يزداد خطر إصابة طفلكِ بالعدوى بدرجة كبيرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يمكن لقيلولة قصيرة وقت الظهيرة (15-20 دقيقة) أن تعيد إليكِ نشاطكِ. لكن لا تنامي طويلًا حتى لا يتأثر نومكِ ليلًا. أمسكي بدرابزين السلم عند النزول.') WHERE id = '1dccc97f-570f-4f2a-ba96-d46cdb785a71';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'لقد تجاوزتِ الأسبوع 30 من حملكِ. وبفضل عملية التعظّم السريعة في جسم طفلكِ، أصبح جهازه الهيكلي متطورًا بدرجة كبيرة. لكن عظام الجمجمة لم تدخل بعد في عملية التعظّم هذه، ما يسمح لطفلكِ بالمرور بسهولة عبر قناة الولادة.;;;
اليافوخ هو النسيج الغضروفي الموجود عند نقاط التقاء عظام جمجمة طفلكِ قبل اكتمال تعظّمها. وتوجد 6 يوافيخ في الجمجمة، تُغلق 5 منها خلال الفترة القريبة من الولادة. وبعد ولادة طفلكِ، لا يبقى سوى اليافوخ الموجود في مقدمة الرأس. تتكون منطقة اليافوخ في رأس طفلكِ من نسيج ضام. وتمنح هذه البنية الجمجمة مرونة تسمح بتراكب العظام، ما يساعد الرأس على دخول قناة الولادة وإتمام عملية الولادة. وبعد الولادة أيضًا، يصبح نمو الدماغ ممكنًا بفضل نمو الجمجمة. وبفضل هذه البنية المرنة للجمجمة، يحدث نحو 75% من نمو دماغ طفلكِ خلال أول عامين من حياته.'), baby_message_ar = COALESCE(baby_message_ar, 'دماغي ينمو! 🧠 ماما، يتطور دماغي الآن بسرعة مذهلة، وتتكون فيه مليارات الروابط الجديدة. لم أعد أتحرك بردود الفعل فقط؛ بل أفكر وأشعر وأتذكر. صوتكِ هو ذكراي المفضلة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'مع بداية الثلث الثالث من الحمل، قد ينتابكِ الخوف من الولادة. ومن الطبيعي جدًا الشعور بقدر متوسط من القلق والتوتر خلال هذه الفترة. لكن القلق المفرط قد يضر بكِ وبطفلكِ. وقد يبدو الأمر أكثر تعقيدًا، خاصةً إذا لم يسبق لكِ الولادة، كما قد تعانين من قلق إضافي بسبب الخوف من المجهول. إن وجود المقربين منكِ إلى جانبكِ وحصولكِ على دعم زوجكِ يساعدانكِ على اجتياز هذه المرحلة براحة أكبر والتغلب على مخاوفكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عند حدوث التقلصات الكاذبة، غيّري وضعيتكِ واشربي الماء وتنفسي بعمق. وقد يساعد الاستلقاء على الجانب الأيسر في تهدئة التقلصات. احتفظي دائمًا بالماء إلى جانبكِ، لأن الجفاف يزيد التقلصات.') WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من تكوّن القنوات الدمعية لدى طفلكِ، فقد يولد وبعض هذه القنوات مغلق. ولهذا، قد لا تنهمر الدموع من عينيه عندما يبكي حتى مرور بعض الوقت بعد الولادة. وتصرّف الغدد الدمعية الدموع التي تنتجها إلى تجويف الأنف عبر فتحات موجودة في الجفن السفلي. وقد يستمر ذلك حتى نحو 3 أسابيع بعد ولادة طفلكِ. الدموع سائل شفاف ومالح تفرزه الغدد الدمعية الموجودة أعلى عيني طفلكِ. وهي تساعد على ترطيب العين ومنع الاحتكاك، كما تتمتع بخصائص مهمة مضادة للبكتيريا. وتسمح الدموع لمقلة العين بالحركة داخل محجرها، وتساعد على تطهيرها من الغبار والأجسام الغريبة التي تقع عليها. يتكون نحو 98% من الدموع من الماء، أما الجزء المتبقي فيحتوي على اليوريا بنسبة مماثلة لبلازما الدم، إضافة إلى كميات أقل من الجلوكوز والأملاح والمواد العضوية. تنتج الغدد الدمعية 3 أنواع مختلفة من الدموع، وهي: الدموع الأساسية، والدموع الانعكاسية، والدموع الناتجة عن الأسباب العاطفية.'), baby_message_ar = COALESCE(baby_message_ar, 'حوضي يضيق! 🏊‍♂️ كلما كبرت، أصبحت المياه المحيطة بي أقل اتساعًا بالنسبة إليّ. يوجد نحو 1 لتر من الماء، لكنني أشغل مساحة كبيرة لدرجة أن الحركة أصبحت أصعب. والآن تشعرين بكل حركة لمرفقيّ وركبتيّ بوضوح أكبر. أحيانًا أؤلمكِ، فسامحيني.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'حبة ملفوف كبيرة'), body_changes_ar = COALESCE(body_changes_ar, 'لتناول التمر فوائد عديدة خلال الحمل. فالتمر غني جدًا بالبروتين والبوتاسيوم والمغنيسيوم والمنغنيز والحديد والنحاس، وبالفيتامينات B1 وB2 وB3 وA1 وC. وبفضل محتواه العالي من الألياف، يمنح شعورًا بالشبع ويساعد بفاعلية في تنظيم الجهاز الهضمي. كما يحتوي التمر على مضادات أكسدة متنوعة، ويُعد مصدرًا طبيعيًا مفيدًا للكربوهيدرات. ويساعد أيضًا على الشعور بالشبع وتنظيم سكر الدم، وبذلك يفيد في التحكم بالوزن خلال الحمل. وبفضل حمض الفوليك الذي يحتوي عليه، يساهم في النمو الصحي لطفلكِ طوال فترة الحمل. يحتوي التمر على مادة تُسمى الأوكسيتوسين، وهي تساعد على اتساع عنق الرحم بسهولة دون الحاجة إلى تدخلات خارجية. لذلك يُعتقد أن التمر من أهم الأطعمة التي تساعد على تسهيل الولادة الطبيعية.;;;
وعلى الرغم من عدم وجود دراسة قاطعة حول هذا الموضوع حتى الآن، ينبغي تجنب الإفراط في تناول التمر خلال الحمل، نظرًا لاحتمال تسببه في اتساع عنق الرحم مبكرًا بسبب الأوكسيتوسين الذي يحتوي عليه.'), daily_tip_ar = COALESCE(daily_tip_ar, 'عند الشعور بضيق التنفس، حافظي على استقامة جسمكِ وارفعي ذراعيكِ فوق رأسكِ؛ فهذا يساعد على توسيع القفص الصدري. تناولي وجبات صغيرة حتى لا تضغط المعدة أكثر على الحجاب الحاجز.') WHERE id = '676af173-b90a-4c64-a591-ff651fa5a3ea';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يتراوح لون بشرة طفلكِ عند ولادته بين الرمادي والأزرق والبنفسجي. إضافة إلى ذلك، يكون جسمه مبللًا بالسائل الأمنيوسي ومغطى بطبقة الطلاء الجبني. وبمجرد أن يبدأ طفلكِ بالتنفس، يتحول لون وجهه وجسمه أولًا إلى الوردي، ثم يداه وقدماه بعد وقت قصير، ليعود إلى لونه الطبيعي. قد يختلف مظهر بشرة الأطفال حديثي الولادة تبعًا لعمر الحمل عند ولادتهم. تكون بشرة الأطفال الخدّج (المولودين قبل الأوان) رقيقة جدًا وشفافة. وتغطي أجسامهم شعيرات دقيقة تُسمى الزغب الجنيني، كما يولدون مغطّين بطبقة الطلاء الجبني ذات المظهر الشبيه بالجبن، التي تحمي البشرة أثناء وجودهم داخل السائل الأمنيوسي في الرحم. وكلما تقدم عمر الحمل، قلت كمية طبقة الطلاء الجبني والزغب الجنيني على بشرة الطفل. ولأن بشرة الأطفال رقيقة جدًا، فقد تبدو أكثر وردية من المعتاد. وينتج هذا اللون الوردي عن الشعيرات الدموية. كذلك، يولد نحو نصف الأطفال ببثور بيضاء أو صفراء صغيرة على الوجه تشبه حب الشباب. وهي غدد دهنية مسدودة، وتختفي من تلقاء نفسها خلال فترة قصيرة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أمص أصابعي! 👍 هذا نشاطي المفضل. يمكنكِ رؤيتي كثيرًا في التصوير بالموجات فوق الصوتية وأنا أمص إبهامي. هذا يهدئني ويقوي عضلات فكي. إنني أتدرب كي أرضع حليبكِ عندما أولد.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين خلال الحمل بحكة مزعجة في منطقة المهبل. وقد تكون أسبابها الحساسية، أو المواد الكيميائية المهيّجة، أو سكري الحمل، أو أمراض جلدية مثل الإكزيما، أو الأمراض المنقولة جنسيًا، أو العدوى الفطرية.;;;
تزداد احتمالية الإصابة بالالتهابات المهبلية خلال الحمل بسبب التغيرات الهرمونية. وإذا كانت هذه الحكة ناجمة عن التهاب مهبلي، فقد يظهر احمرار وتورم في المنطقة. وقد تصاحب الحكة إفرازات بيضاء كثيفة القوام. ويمكن أن تزداد الحكة المهبلية بسبب استخدام كريمات ومراهم غير مناسبة للحمل، أو أنواع الصابون والمنظفات المليّنة، أو البخاخات المهبلية، أو ورق المرحاض المعطر. إذا كنتِ تعانين من الحكة في منطقة المهبل، فقد يساعد استخدام الكريمات والمراهم العلاجية والمهدئة بتوصية من طبيبكِ على تخفيف الأعراض. إضافة إلى ذلك، اغسلي ملابسكِ بمسحوق الصابون بدلًا من مسحوق الغسيل (المنظف)، واستخدمي ملابس داخلية قطنية وغيّريها بشكل متكرر خلال اليوم، واختاري ملابس مريحة لا تضغط على جسمكِ، وحافظي دائمًا على نظافة منطقة المهبل وجفافها قدر الإمكان.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتخفيف الخدر في يديكِ، هزّيهما وارفعِيهما إلى أعلى بشكل متكرر. وقد يساعد ارتداء جبيرة للمعصم ليلًا على تقليل الضغط الواقع على العصب.') WHERE id = 'd4779c73-b7cd-4428-bca1-d013881798d5';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'اعتبارًا من الأسبوع 32، تكون أظافر يدي طفلكِ قد امتدت حتى أطراف أصابعه. أما وصول أظافر قدميه إلى أطراف الأصابع فيكتمل في الأسبوع 36. بدأت أظافر طفلكِ بالتطور في الأسبوع 10، وهي تتكون من الكيراتين وتستمر في النمو مدى الحياة. ويحتوي الكيراتين الموجود في بنية الأظافر على أحماض أمينية غنية بالكبريت. يكون طفلكِ في هذه الأسابيع أكثر عرضة للفواق، ويزداد تكراره كلما اقترب موعد الولادة. يولد الأطفال بمنعكس المص، ويتشكل هذا المنعكس نتيجة ابتلاعهم السائل الأمنيوسي وإصابتهم بالفواق داخل الرحم. وقد تتمكنين هذا الأسبوع، خلال فحص الطبيب، من رؤية طفلكِ عبر التصوير بالموجات فوق الصوتية وهو يصاب بالفواق ويمص إصبعه.'), baby_message_ar = COALESCE(baby_message_ar, 'حواسي الخمس تعمل! 🖐️👃👂👀👅 البصر والسمع والتذوق والشم واللمس. كل حواسي يقظة. أسمع صوتكِ، وأتذوق الطعام الذي تتناولينه، وأرى الضوء، وألمس وجهي. أنا كائن حي يشعر بكل شيء. أنتِ عالمي يا ماما.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد تزداد لديكِ عاطفيًا غريزة "تجهيز العش". وقد ترغبين في تنظيف المنزل وغسل ملابس طفلكِ وكيّها. استفيدي من هذه الدفعة من الطاقة، لكن لا ترهقي نفسكِ كثيرًا.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي شرب الكثير من الماء وقللي تناول الملح إلى أدنى حد لتخفيف الوذمة. احرصي على استخدام وسادة الحمل لتخفيف آلام الظهر، وحاولي الجلوس باستقامة. وإذا لم تكوني قد فعلتِ ذلك بعد، فهذا هو الوقت الأنسب لاستكمال التفاصيل الأخيرة لغرفة طفلكِ أو إنهاء المشتريات الكبيرة مثل عربة الأطفال، لأن الحركة قد تصبح أصعب في الأسابيع التالية.') WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'تُسمى عظام طفلكِ "النسيج العظمي الأولي"، ما يعني أنها لم تنضج بالكامل بعد. فالنسيج الضام في عظام طفلكِ داخل الرحم لم يكتمل تكوّنه بعد ولم يتصلب بما يكفي. والعظام جزء من الجهاز الهيكلي الذي يحمي الجسم، ويساعده على الوقوف منتصبًا ويوفر له الدعم، ويتيح حركته. كما أنها موضع إنتاج نخاع العظم المسؤول عن تكوين الدم. ويعمل النسيج العظمي مخزنًا للكالسيوم في الجسم، ومنه تُلبّى احتياجات الجسم اليومية من الكالسيوم.;;;
يستمر تراكم العِقي في أمعاء طفلكِ. ويتكون العِقي من لعاب الطفل، وإفرازات المعدة والبنكرياس، ومخلفات الخلايا، والمخاط، وشعيرات الزغب الجنيني. ويظل معقمًا ما دام داخل الأمعاء، ثم يُطرح من الجسم خلال مدة تصل إلى 48 ساعة بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتبول! 🚽 قد يبدو هذا مضحكًا، لكنني أُخرج نحو نصف لتر من البول يوميًا وأمزجه بالسائل الأمنيوسي. ثم أبتلع ذلك السائل من جديد. تُظهر هذه الدورة أن كليتي وجهازي الهضمي بصحة جيدة. أنا أنظّم سوائلي بنفسي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد يستمر تورم يديكِ وقدميكِ في الصباح أيضًا. وإذا ظهر تورم مفاجئ في وجهكِ، فقيسي ضغط دمكِ. وقد تشعرين كذلك بخدر وألم في يديكِ بسبب "Carpal Tunnel Syndrome" (متلازمة النفق الرسغي).'), daily_tip_ar = COALESCE(daily_tip_ar, 'من المهم جدًا ارتداء أحذية مريحة. تجنبي الأحذية ذات الكعب تمامًا. وقد يكون ارتداء حزام دعم الحمل مفيدًا لتخفيف آلام الظهر.') WHERE id = 'b1c4365d-e81a-4bcf-93eb-e36cdbc64c30';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في هذا الأسبوع الذي تدخلين فيه الشهر 8، يستمر نمو الرئتين بوتيرة سريعة. بين الأسبوعين 28-36 تكون الرئتان في المرحلة "الكيسية". خلال هذه المرحلة، تترقق الطبقة السطحية التي تُشكّل القصيبات، وتتكاثر الشعيرات الدموية في الرئتين بسرعة. وعندما يكتمل نمو رئتي طفلكِ، يكون قد تكوّن نحو 300 مليون حويصلة هوائية. وقريبًا ستبدأ مادة تُسمى السورفاكتانت بتغطية محيط هذه الحويصلات الهوائية بالكامل. تساعد هذه المادة الحويصلات على تبادل الغازات، وتقلل التوتر السطحي، ما يمكّن الرئتين من أداء وظيفتهما بسهولة حتى عند أخذ أعمق الأنفاس. وتُسرّع حقن إنضاج الرئتين التي تُعطى للحوامل المعرّضات لخطر الولادة المبكرة إنتاج السورفاكتانت في الرئتين. ونتيجة لذلك، يعاني الأطفال المولودون قبل أوانهم من صعوبات التنفس مدة أقصر.'), baby_message_ar = COALESCE(baby_message_ar, 'رئتاي تنضجان! 🌬️ تتطور الحويصلات الهوائية في رئتي أكثر فأكثر كل يوم. وتزداد مادة "السورفاكتانت". إذا وُلدت الآن، فسأظل بحاجة إلى المساعدة، لكن فرصي مرتفعة جدًا. أنا أصبح أقوى كل يوم. ما عليكِ سوى أن تمنحيني مزيدًا من الوقت.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الخس'), body_changes_ar = COALESCE(body_changes_ar, 'في هذه الأيام التي تدخلين فيها الشهر 8، من الطبيعي أن يزداد وزنكِ بمقدار 2-4 كيلوغرامات شهريًا، وبمتوسط 500 غرام أسبوعيًا. خلال هذه الأسابيع، يكبر بطنكِ كثيرًا بسبب نمو طفلكِ السريع، وقد تصبح حركتكِ محدودة إلى حد كبير. وقد يؤدي كبر البطن إلى حرقة المعدة وضيق التنفس. عند مواجهة هذه المشكلات، من المفيد جدًا تناول وجبات صغيرة ومتكررة والاستلقاء على الجانب الأيسر. وقد تصبح حركات مثل المشي والنهوض من مكان جلوسكِ صعبة للغاية خلال هذه الأسابيع. ويرجع ذلك إلى ارتخاء مفاصلكِ وعضلاتكِ خلال الحمل. وعلى الرغم من صعوبة الحركة لهذه الأسباب، فإن قلة الحركة قد تزيد الوضع سوءًا. ويكفي أن تقومي بنزهات قصيرة وتمارين خفيفة من دون إجهاد نفسكِ.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لتقليل حرقة المعدة، تناولي وجبات أصغر حجمًا ولكن بوتيرة متكررة. وعند النوم، يُفضّل أن تستلقي على جانبكِ الأيسر؛ فهذا يساعد على الهضم لديكِ وعلى تدفق الدم إلى طفلكِ. ولتخفيف آلام الظهر، احرصي على استخدام وسائد تدعم ظهركِ. خصصي اليوم بعض الوقت لنفسكِ، وابدئي بإكمال قائمة محتويات حقيبة الولادة الخاصة بطفلكِ.') WHERE id = '073c7d59-96b0-4ee4-a0d5-1e595fd135fb';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'في الأسبوع 32، ومع دخول الشهر 8، تستمر زيادة الأنسجة الدهنية والعضلية بوتيرة سريعة. لذلك أصبح الجلد أكثر نعومة وملمسًا أملس. وبفضل الدهون المتراكمة تحت الجلد، يكاد مظهره الشفاف يختفي تمامًا. وابتداءً من هذا الأسبوع، يبدأ أيضًا تساقط شعر الزغب الجنيني الذي يغطي جسم طفلكِ. والزغب الجنيني هو اسم الشعيرات الحريرية الدقيقة التي تغطي جسم طفلكِ بعد الأسبوع 20. تكون هذه الشعيرات عديمة اللون وناعمة، وتكون أكثر كثافة على الجبهة والظهر والوجه. ويساعد الزغب الجنيني على إبقاء جسم طفلكِ دافئًا وحمايته من العدوى خلال الفترة التي يكون فيها جلده رقيقًا. ويشيع وجود هذا الشعر لدى الأطفال المولودين قبل أوانهم، ويبدأ بالتساقط بعد الولادة بوقت قصير.'), baby_message_ar = COALESCE(baby_message_ar, 'أنا أتدرّب على التنفس 🌬️ ماما، يرتفع صدري وينخفض بإيقاع منتظم. أسحب السائل الأمنيوسي إلى رئتي ثم أخرجه. وهذا يقوّي عضلاتي كي أتمكن عند ولادتي من أخذ ذلك النفس الأول والأهم. قد تشعرين أحيانًا بحركاتي الإيقاعية (الحازوقة). إنها تماريني الرياضية!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الخس'), body_changes_ar = COALESCE(body_changes_ar, 'يجب تجنب الاقتصار على نوع واحد من الطعام خلال هذه الفترة. فاتباع نظام غذائي متوازن وكافٍ يلبي جميع احتياجات جسمكِ من الفيتامينات والمعادن. لا حاجة إلى سعرات حرارية إضافية لتلبية احتياجات الجنين خلال الأشهر الثلاثة الأولى. وابتداءً من الثلث الثاني، يكفي تناول 300 سعرة حرارية إضافية يوميًا لدعم نمو طفلكِ. واعلمي أن تناول سعرات حرارية تتجاوز احتياجاتكِ لن يفيد طفلكِ، بل ستُخزّن هذه السعرات الزائدة في جسمكِ على هيئة دهون. ومن المفيد أن تبدئي الآن بتجهيز الملابس والاحتياجات الأخرى التي ستلزمكِ أنتِ وطفلكِ في المستشفى.'), daily_tip_ar = COALESCE(daily_tip_ar, 'احرصي على تناول أطعمة غنية بالكالسيوم خلال اليوم، لأن عظام طفلكِ تمر الآن بأسرع مراحل التصلب. ولتخفيف آلام الظهر، مارسي تمارين تمدد خفيفة بانتظام، ويُفضّل أن تستلقي على جانبكِ الأيسر عند النوم.') WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'على الرغم من استمرار نمو دماغ طفلكِ بسرعة خلال الثلث 3، فإن معدل نمو الرأس يكون أبطأ مقارنة بمعدل نمو بقية أجزاء الجسم. يبدأ تكوّن دماغ طفلكِ في الرحم خلال الأسبوع 3. والجهاز العصبي هو أول الأجهزة ظهورًا خلال نمو الطفل في الرحم، كما أنه من أواخر الأجهزة التي يكتمل نموها بعد الولادة. وابتداءً من هذا الأسبوع، يكتمل تكوّن الخلايا العصبية. وخلال الأسابيع 9 الماضية، تمايزت الخلايا العصبية إلى أنواع مختلفة وتضاعف عددها مرات عديدة. وفي الأسبوع 32، تبدأ بالانتقال إلى المناطق الواقعة أسفل الطبقة الخارجية للدماغ، أي القشرة المخية. وخلال هذه العملية تكتمل الملامح الأساسية العامة للدماغ والجهاز العصبي. وعند حلول موعد الولادة، يكون الدماغ قد اقترب كثيرًا من شكله النهائي، مع استمرار نضجه وتطوره بعد الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'حواسي 5 كلها تعمل! 🖐️ لقد أصبحت مجهزًا بالكامل: أرى وأسمع وأتذوق وأشم وألمس. عندما أسمع صوتكِ، أدير رأسي. وعندما يصل إليّ الضوء، أرمش بعينيّ. ومن مذاق السائل الأمنيوسي أعرف ما تناولتِه. أنا مستعد لاكتشاف العالم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'الخس'), body_changes_ar = COALESCE(body_changes_ar, 'تُسمى الحالة النفسية التي يختبرها الطفل في الرحم من خلال أمه في المصطلحات الطبية “علم نفس الجنين”. فكما يتشكل عالم الأم العاطفي طوال الحمل، يتأثر عالم طفلها العاطفي في الرحم بالتجارب نفسها. وإلى جانب السمات الوراثية، تتطور لدى الطفل سمات نفسية منذ اللحظة الأولى لبدء تكوّنه في الرحم. وتتشكل هذه السمات النفسية فوق السمات الوراثية متأثرة بسعادة الأم وحماسها وغضبها وحزنها. ويستمر تشكّلها، الذي يبدأ في الرحم، حتى عمر 6 سنوات، وقد يؤثر في حياة الإنسان بأكملها. لا تنسي أبدًا أن طفلكِ مرتبط بكِ نفسيًا بقدر ارتباطه بكِ من الناحية الجسدية.'), daily_tip_ar = COALESCE(daily_tip_ar, 'يمكنكِ حماية ملابسكِ باستخدام وسادات الثدي. لا تغسلي حلمتيكِ بالصابون، لأنه يسبب جفافهما وتشققهما. يكفي غسلهما بالماء الفاتر فقط.') WHERE id = 'fc626924-530b-4871-85a2-84474a5bcec0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بلغ معدل نمو طفلكِ الآن مستوى قياسيًا، إذ يزداد وزنه بنحو 200 غرام كل أسبوع! وتحدث هذه الزيادة السريعة نتيجة ازدياد سماكة طبقة الدهون تحت الجلد وزيادة وزن الأعضاء الداخلية أيضًا. ولا تزال الرئتان تواصلان نموهما خلال هذه الأسابيع. وعلى الرغم من أن طفلكِ يتدرّب على التنفس داخل الرحم، فإنه لا يزال بحاجة إلى بضعة أسابيع كي تتمكن رئتاه من العمل بصورة مستقلة تمامًا خارج الرحم. وخلال هذه المدة، تزداد الحويصلات الهوائية في الرئتين قوةً ونضجًا. كما أصبح نمط نوم طفلكِ الآن أكثر انتظامًا ووضوحًا؛ فهو ينام في أوقات محددة، ويستيقظ في أوقات أخرى لمواصلة "تمارينه". وباتت دورات نومه تشبه نمط نوم الطفل حديث الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'الأسبوع 31! 🥥 مرحبًا يا ماما! أصبح حجمي بحجم ثمرة جوز الهند (coconut). بلغ وزني 1.5 كغ، وطولي 41 سم. لقد أصبحت الآن "ثقيل الوزن" بما يكفي. هدفي الأساسي حاليًا هو إنضاج رئتيّ وتخزين المزيد من الدهون. إنني أستعد للمجيء إلى العالم!'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'قد يزعجكِ ألم الأضلاع وضيق التنفس. فالرحم يدفع الحجاب الحاجز والرئتين إلى أعلى، وقد يبدو أخذ نفس عميق ترفًا. كما قد تنحشر قدما طفلكِ بين أضلاعكِ.;;;
وقد يعود أيضًا الشعور بالتعب والإرهاق. فثقل بطنكِ والليالي التي لا تنامين فيها وازدياد احتياج جسمكِ إلى الطاقة قد تستنزفكِ في فترة الظهيرة. لا تحاولي التظاهر بالقوة طوال الوقت، فأنتِ بحاجة إلى الراحة. وقد تواجهين أيضًا مشكلة في التوازن أو تتعثرين، لذا كوني حذرة.'), daily_tip_ar = COALESCE(daily_tip_ar, 'هذا وقت مناسب للبدء في تجهيز حقيبة الولادة. أعدّي قائمة واجمعي الأغراض اللازمة تدريجيًا. لا داعي للاستعجال، لكن استعدادكِ سيمنحكِ شعورًا بالطمأنينة.') WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'ينتج طفلكِ في هذه المرحلة نحو نصف لتر من البول يوميًا. فهو يبتلع السائل الأمنيوسي، ثم يطرح البول الناتج في السائل الأمنيوسي المحيط به، وبذلك تتكوّن دورة تساعد على إبقاء كمية السائل عند المستوى المطلوب باستمرار. والسائل الأمنيوسي سائل تتغير كميته وتركيبته بصورة متواصلة طوال الحمل. ففي الأسابيع الأولى من حملكِ، يحتوي على عناصر تمد طفلكِ بالغذاء والأكسجين، ويتكوّن من السوائل المترشحة من دمكِ. وفي الأسابيع التالية تتغير تركيبته، فيتكوّن من الماء والأملاح غير العضوية والبروتينات والدهون والكربوهيدرات والإنزيمات، بالإضافة إلى البول الذي يبدأ طفلكِ بإنتاجه اعتبارًا من الأسبوع 12. ولهذا السائل دور بالغ الأهمية في تكوّن منعكس المص لدى طفلكِ وتطور رئتيه. كما يتيح له أداء حركات مثل التمدد والدوران بسهولة، مما يدعم نمو جهازه الهيكلي والعضلي. ويحمي السائل الأمنيوسي طفلكِ أيضًا من الصدمات الخارجية. ويتجدد هذا السائل وتتغير تركيبته في المتوسط كل 3 ساعات، كما يسهم البول الذي ينتجه طفلكِ في هذا التغير المستمر.'), baby_message_ar = COALESCE(baby_message_ar, 'ما لون عينيّ؟ 👁️ في الوقت الحالي، عيناي زرقاوان داكنتان أو رماديتان، مثل عيون جميع الأطفال. وبعد ولادتي وتعرّضي للضوء، سيظهر لونهما الحقيقي، سواء كان بنيًا أو أخضر أو عسليًا. وقد يستغرق ذلك 6-9 أشهر. لكنني، مهما كان لونهما، سأنظر إليكِ بعينين جميلتين.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'يسبب تمدد الرحم شدًا في العضلات والأنسجة الرابطة المحيطة به، ما قد يؤدي إلى الشعور بألم في المهبل. كما أن تمدد الرحم بفعل نمو طفلكِ داخله يؤثر في مركز ثقل جسمكِ، وقد يسبب ألمًا في ظهركِ وأسفل بطنكِ. ومع ازدياد حجم البطن بوضوح خلال الثلث الثالث من الحمل، قد يؤدي شد الأربطة عند القيام بحركة مفاجئة إلى ألم في منطقة الأُربية يشبه الشد أو الطعن بالسكين. ويرجع ذلك إلى تمدد الرباط المستدير.;;;
غالبًا ما يُخلط بين ألم الرحم وألم المهبل أثناء الحمل. وفي الأسابيع الأخيرة من الحمل، قد يبدأ عنق الرحم باللين والانفتاح جزئيًا، وقد تبدأ هذه التغيرات قبل الولادة بعدة أسابيع. وقد تشعرين خلال هذا الانفتاح بألم شديد في المهبل يشبه الطعن بالسكين، لكن ذلك لا يعني بالضرورة أن تقلصات المخاض قد بدأت.'), daily_tip_ar = COALESCE(daily_tip_ar, 'إذا كنتِ تعانين من ألم العصب الوركي، فلا تنامي على الجانب المصاب. خذي حمامًا دافئًا أو ضعي كمادة دافئة على موضع الألم. وبعد استشارة طبيبتكِ، يمكنكِ الخضوع للعلاج الطبيعي أو التدليك المخصص للحوامل.') WHERE id = 'ef1f18bb-3c48-4a2a-96b2-7141d5fc2528';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'قد يظهر على فروة رأس طفلكِ تورم يُسمى ورم الولادة. ويُعد ذلك جزءًا من عملية تشكّل الرأس. وتشير قولبة الرأس إلى تغير مؤقت في شكل رأس طفلكِ، وإلى حد ما في حجمه، أثناء مروره بعملية الولادة. ففي أثناء الولادة، يجب أن يتكيف رأس طفلكِ مع شكل قناة الولادة وحجمها حتى يتمكن من المرور عبرها. وخلال عبوره قناة الولادة، يؤدي طفلكِ حركات مثل ثني الرأس إلى الأمام، والدوران إلى الداخل، ومد الرأس إلى الخلف، والدوران إلى الخارج. وأثناء هذه العملية، تتقارب عظام جمجمته وقد تتراكب فوق بعضها بفضل الأنسجة الغضروفية المرنة الموجودة بينها. وقد تظهر بعض الانحناءات المؤقتة في منطقة الرأس نتيجة التشكّل السريع للأنسجة الرخوة خلال المرور عبر قناة الولادة. ومن أسباب تغير شكل جمجمة الطفل حديث الولادة: وضعية الطفل داخل الرحم، وطول الولادة وصعوبتها، وبقاؤه في الحاضنة، أو قِصر بعض عضلات رقبته.'), baby_message_ar = COALESCE(baby_message_ar, 'هل أنا في وضعية الرأس إلى أسفل؟ 🙃 على الأرجح أنني أحاول الآن الانتقال إلى وضعية الرأس إلى أسفل، أي المجيء بالرأس. وهذه هي الوضعية الأنسب للولادة. لكن إذا لم أستدر بعد، فلا تقلقي، فلا يزال لدي وقت. أنا أحب الجاذبية؛ ولأن رأسي ثقيل، فمن السهل أن يتجه إلى أسفل.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'جوز الهند'), body_changes_ar = COALESCE(body_changes_ar, 'تُعد فترة الحمل من أسرع الفترات التي قد يزداد فيها وزن المرأة خلال حياتها. وقد تشعرين بالجوع كثيرًا خلال الحمل نتيجة ارتفاع مستويات الهرمونات وحاجة جسمكِ إلى دعم نمو طفلكِ. وإذا لم تتناولي وجبات خفيفة مناسبة عند الشعور بالجوع، فقد يدفعكِ ذلك إلى تناول وجبات كبيرة غنية بالسعرات الحرارية. وعادةً ما تزداد أوزان النساء اللواتي كان مؤشر كتلة أجسامهن طبيعيًا أو منخفضًا قبل الحمل بمعدل 10-12 كيلوغرامًا خلال هذه الفترة. أما النساء اللواتي كن يعانين من زيادة الوزن قبل الحمل، فقد يكنّ أكثر ميلًا إلى اكتساب وزن إضافي. ويرجع ذلك أساسًا إلى استمرار العادات الغذائية غير الصحية وتفاقمها خلال الحمل.;;;
وبدلًا من تناول الأطعمة غير الصحية ذات السعرات الحرارية الفارغة والقيمة الغذائية المنخفضة، احرصي على تناول 3 حصص من الفاكهة يوميًا، ووجبات رئيسية غنية بالبروتين، وإدراج الحليب ومنتجات الألبان ضمن وجباتكِ الخفيفة، وممارسة تمارين خفيفة بانتظام.'), daily_tip_ar = COALESCE(daily_tip_ar, 'توقفي عن تناول الطعام قبل النوم بـ2-3 ساعات. وقد يساعد شرب الحليب أو تناول حفنة من اللوز النيئ على معادلة حمض المعدة. وابتعدي عن الأطعمة الحمضية والحارة.') WHERE id = '805cdfb6-2608-4845-b4aa-f6272786a6f0';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'السائل الأمنيوسي هو سائل معقم وعديم اللون وواقٍ يحيط بطفلكِ. وعلى الرغم من أن جزءًا منه تنتجه «الخلايا الأمنيوسية» داخل الرحم، فإن مصدره الأساسي هو الأم. يتيح هذا السائل لطفلكِ التحرك براحة داخل الرحم، ويحميه في الوقت نفسه من الصدمات والعدوى وتغيرات درجة الحرارة. ويحافظ السائل الأمنيوسي على درجة حرارته ثابتة عند 37 درجة طوال فترة الحمل، ما يمنع تأثر طفلكِ ببرد الشتاء أو حر الصيف. خلال الثلث 2 من الحمل، تزداد كمية السائل الأمنيوسي بالتوازي مع زيادة وزن طفلكِ. وفي الأسبوع 32، تبلغ كمية هذا السائل 1 لتر، وهي أعلى كمية يصل إليها السائل الأمنيوسي. ولإتاحة المجال لطفلكِ لاكتساب المزيد من الوزن، تنخفض كمية السائل الأمنيوسي بدءًا من هذا الأسبوع وحتى الولادة بنحو 150-250 ml، وتستقر في المتوسط عند مستوى 750-800 ml.'), baby_message_ar = COALESCE(baby_message_ar, 'أظافري طويلة جدًا! 💅 لقد تجاوزت أظافري أطراف أصابعي. وأحيانًا أخدش وجهي من دون قصد. حضّري لي قفازات أو مقص أظافر عند ولادتي. فما زلت لا أعرف كيف أعتني بنفسي. ستساعدينني، أليس كذلك؟'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خس'), body_changes_ar = COALESCE(body_changes_ar, 'قد يرهقكِ ضيق التنفس. فالرحم على وشك بلوغ أعلى نقطة له، أي القوس الضلعي. وهذا يضغط على الحجاب الحاجز ويمنع الرئتين من التمدد بالكامل. وقد يصبح صعود الدرج أو المشي بسرعة أكثر صعوبة.;;;
قد تزداد إفرازات «اللبأ» من ثدييكِ. فجسمكِ يحضّر «السائل الذهبي» لأول رضعة بعد الولادة. وقد يصبح ثدياكِ أثقل وأكثر حساسية. كما أن جلد بطنكِ في أقصى درجات التمدد.'), daily_tip_ar = COALESCE(daily_tip_ar, 'قلّلي المشروبات المحتوية على الكافيين إلى أدنى حد لتخفيف الضغط على المثانة، لأنها مدرّة للبول. ولتخفيف آلام الظهر، ضعي وسائد صغيرة بين ساقيكِ وتحت بطنكِ عند النوم. واصلي تناول الكالسيوم والحديد، لأن طفلكِ يخزّن هذين العنصرين بسرعة في هذه المرحلة. لا ترهقي نفسكِ كثيرًا اليوم.') WHERE id = 'b016d6e4-baac-45d0-93bb-1a801a1ac462';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بدأ طفلكِ يسمع منذ الأسبوع 16، وبحلول نهاية هذا الأسبوع يصبح قادرًا على تذكّر ما يسمعه والاستجابة له. وعندما يبدأ بتمييز صوت والديه، يشعر بالحماس إذا تحدث إليه أحدهما، فتتسارع ضربات قلبه ويحاول الاستجابة. وهذا مؤشر على مدى سرعة تطور دماغ طفلكِ. وبحلول نهاية هذه المرحلة، تصبح الرئتان قادرتين على إجراء تبادل الغازات، لكنهما لا تزالان غير ناضجتين بما يكفي. وعندما يكتمل نمو الرئتين، تصبحان قادرتين على توفير الحماية من الكائنات الحية الدقيقة. كما تؤديان دورًا في تنظيم توازن السوائل والشوارد، وتنظمان توازن الهيدروجين واليود في الدم، وتساعدان على إنتاج بعض الأصوات الضرورية للكلام.'), baby_message_ar = COALESCE(baby_message_ar, '32 أسبوعًا! 🎃 أنا بحجم حبة خس! لقد أصبحت الآن من «الأوزان الثقيلة». ولم يعد الرحم واسعًا بما يكفي لي. لا أستطيع مد ساقيّ بالكامل، لذلك أبقى في «وضعية الجنين». هذه هي الوضعية الأكثر راحة لي.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خس'), body_changes_ar = COALESCE(body_changes_ar, 'يؤدي ارتفاع مستوى هرمون الإستروجين في دمكِ خلال الحمل إلى زيادة إفرازات الجسم. ونتيجة لذلك، قد تتسبب زيادة إنتاج المخاط مقارنة بما قبل الحمل في تورم الأوعية الدموية داخل الأنف. وهذا يؤدي إلى احتقان الأنف ويسبب شعورًا بالانزعاج لدى الحوامل. يساعد التدليك على زيادة تدفق الدم في الممرات الأنفية وتقليل كثافة المخاط، ما يجعل التنفس أسهل. ومن الحلول الأخرى لاحتقان الأنف الحرص على شرب الماء، والاستحمام بماء دافئ، ووضع كمادات دافئة حول الأنف، وإبقاء الرأس في وضع مرتفع.'), daily_tip_ar = COALESCE(daily_tip_ar, 'لا تفوّتي مواعيدكِ مع طبيبكِ. ففي هذه الأسابيع، يُعد قياس ضغط الدم وفحص البروتين في البول مهمين جدًا لتقييم خطر «تسمم الحمل». إذا كنتِ تعانين من صداع أو تشوش في الرؤية، فأخبري طبيبكِ فورًا.') WHERE id = '33dd2de9-c534-420c-8e3d-e027683ad6e9';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'بلغت طبقة الطلاء الجبني المتكوّنة على جلد طفلكِ كميتها المثلى. وتتمثل مهمة هذه الطبقة في تكوين غلاف خارجي واقٍ لطفلكِ وهو لا يزال داخل الرحم. وتتكون من 80% ماء و10% دهون و10% مركّبات بروتينية.;;;
أما أثناء الولادة، فتتمثل مهمتها في حماية الجلد من تأثير الهواء المجفف والكائنات الحية الدقيقة الضارة، والاحتفاظ برطوبة الجلد لمنع جفافه، والحفاظ على توازن درجة حموضة الجلد عند مستوى معين، وحماية طفلكِ من العدوى والإصابات المحتملة أثناء الولادة.'), baby_message_ar = COALESCE(baby_message_ar, 'أصبحت لديّ أحلام! 💤 تُظهر موجات دماغي أنني أمر بمراحل من النوم العميق والنوم الخفيف. أبتسم في نومي وأعبس، بل وأحرّك عينيّ أيضًا. لقد بدأ دماغي يعمل مثل دماغ شخص بالغ. أنا طفل حالم.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'خس'), body_changes_ar = COALESCE(body_changes_ar, 'قد يرهقكِ الأرق ليلًا وتشنجات الساقين. ويجعل حجم بطنكِ التقلب في السرير أكثر صعوبة. تحركي ببطء لأنكِ قد تواجهين مشكلة في التوازن. قد يجعلكِ الأرق سريعة الانفعال، لكن حاولي الحصول على قسط من الراحة بعد الظهر.;;;
قد يزداد الضغط على المثانة، لكن حرقة المعدة وضيق التنفس قد يخفّان قليلًا. فمع نزول رأس طفلكِ إلى أسفل، ترتاح الأعضاء الموجودة في الجزء العلوي، بينما يزداد الضغط على الأعضاء الموجودة في الأسفل، مثل المثانة وعظام الحوض. وقد تبدئين بالمشي على طريقة «مشية البطريق».'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي شرب الكثير من الماء وقلّلي تناول الملح إلى أدنى حد لتخفيف تورم ساقيكِ. حاولي إبقاء ظهركِ مستقيمًا عند الجلوس حتى تتمكن رئتاكِ من التمدد بسهولة أكبر. هذا الأسبوع هو أنسب وقت لوضع اللمسات الأخيرة على خطة الولادة، مثل اختيار المستشفى واستشارة الطبيب. دلّكي بطنكِ برفق في المساء، فقد أصبح طفلكِ يشعر بهذه اللمسات بوضوح شديد.') WHERE id = '7757d4d7-3e07-45ad-b80b-78b87e96663b';
UPDATE public.pregnancy_daily_content SET baby_development_ar = COALESCE(baby_development_ar, 'يواصل طفلكِ النمو بسرعة مذهلة! مع دخولكِ الثلث الثالث من الحمل، يزداد وزنكِ بمعدل يقارب 500 غرام أسبوعيًا. ويكتسب طفلكِ ما يقارب نصف هذه الزيادة في صورة أنسجة دهنية. والسبب الأهم وراء إنتاج طفلكِ للخلايا الدهنية بهذه السرعة هو مساعدته على الحفاظ على درجة حرارة جسمه بعد الولادة واستخدام هذه الدهون مصدرًا للطاقة عند الحاجة. في هذه المرحلة، يحتوي جسم طفلكِ على خلايا دهنية بنية وأخرى بيضاء. وتُعرف الخلايا الدهنية البنية طبيًا باسم النسيج الدهني الجنيني، وتوجد لدى الأطفال بنسبة أكبر مقارنة بالبالغين لأنها تساعد على الحفاظ على حرارة الجسم بكفاءة. وتؤدي الخلايا الدهنية البنية هذه الوظيفة بفضل بروتين يُسمى الثرموجينين، يوجد في الغشاء الخارجي لعضيات الميتوكوندريا المتوافرة بكثرة داخلها. ويساعد بروتين الثرموجينين على إنتاج الحرارة بكفاءة من خلال استهلاك الأكسجين الذي يصل إلى الخلايا عبر الأوعية الدموية.'), baby_message_ar = COALESCE(baby_message_ar, 'أُدير رأسي إلى الأسفل! ⬇️ تدفعني الجاذبية وغرائزي إلى اتخاذ وضعية الرأس إلى الأسفل. رأسي هو أثقل جزء من جسمي، لذلك من السهل أن يتجه إلى الأسفل. وهذه أفضل وضعية للولادة. وإذا لم أستدر بعد، فلا تقلقي، فبعض أصدقائي ينتظرون حتى اللحظة الأخيرة.'), baby_size_fruit_ar = COALESCE(baby_size_fruit_ar, 'أناناس'), body_changes_ar = COALESCE(body_changes_ar, 'قد تشعرين بضيق شديد في التنفس خلال الثلث الثالث من الحمل. فارتفاع مستوى هرمون البروجسترون في الدم أثناء الحمل يحفّز مركز التنفس في الدماغ، ما يجعلكِ تتنفسين بوتيرة أسرع وبعمق أكبر. ويحتاج جهازكِ التنفسي إلى كمية أكبر من الهواء حتى يتمكن الدم من نقل المزيد من الأكسجين إلى المشيمة والتخلص من كمية أكبر من ثاني أكسيد الكربون مقارنة بالمعتاد. ولهذه الأسباب، تستنشق رئتاكِ وتزفران هواءً أكثر بنسبة 30-40% مع كل نَفَس. وقد تؤدي هذه التغيرات إلى صعوبة التنفس والشعور بالحاجة إلى مزيد من الهواء. ويمكن أن يساعدكِ الاستلقاء على جانبكِ الأيسر، وتجنب الأعمال المجهدة، والجلوس باستقامة، والتنفس بطريقة صحيحة على تخفيف هذه المشكلة والشعور براحة أكبر.'), daily_tip_ar = COALESCE(daily_tip_ar, 'واصلي ممارسة تمارين كيغل. فتقوية عضلات قاع الحوض تساعد على التعامل مع الضغط الناتج عن نزول رأس طفلكِ إلى الأسفل، كما تساعد على الوقاية من سلس البول.') WHERE id = '7324ee36-63a7-4db4-bc5e-2444adb29718';